(()=>{const t=[{courseId:"call-center",unit:{id:"cc-u06",title:"الانتظار والتحويل والتصعيد",desc:"تستأذن قبل الانتظار وتحدد المدة، توضح لمين حتحوّل العميل وإيه اللي بينتقل، وتدير الانتظار الطويل بصراحة وبدائل.",cefr:"B1"},lessons:[{id:"cc-u06l01",courseId:"call-center",unitId:"cc-u06",sourceLessonId:"cc-u06l01",level:"B1",register:"usted",title:"استأذن قبل الانتظار",context:"محتاج دقيقة تراجع حاجة على النظام أثناء المكالمة. دورك: تستأذن العميل في انتظار قصير وتحدد المدة، وتشكره لما ترجع.",goal:"بعد الدرس ده حتقدر تطلب الانتظار بأدب مع مدة واضحة، وترجع للمكالمة بشكر بدل ما تكمل كأن مفيش حاجة حصلت.",targets:[{es:"Necesito un minuto para revisarlo.",ar:"محتاجة دقيقة أراجعه.",speaker:"luna"},{es:"¿Le puedo dejar en espera?",ar:"ممكن أحط حضرتك على الانتظار؟",speaker:"luna"},{es:"Sí, sin problema.",ar:"أيوه، مفيش مشكلة.",speaker:"paco"},{es:"Gracias por esperar.",ar:"شكرًا على الانتظار.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola, quiero saber por qué me llegó un cargo raro.",ar:"أهلًا، عايز أعرف ليه جالي خصم غريب."},{speaker:"luna",es:"Claro. Necesito un minuto para revisarlo. ¿Le puedo dejar en espera?",ar:"طبعًا. محتاجة دقيقة أراجعه. ممكن أحط حضرتك على الانتظار؟"},{speaker:"paco",es:"Sí, sin problema.",ar:"أيوه، مفيش مشكلة."},{speaker:"luna",es:"Gracias. Un minuto solo.",ar:"شكرًا. دقيقة واحدة بس."},{speaker:"paco",es:"Sí, dígame.",ar:"أيوه، اتفضلي."},{speaker:"luna",es:"Gracias por esperar. Ya vi el cargo y le explico.",ar:"شكرًا على الانتظار. شفت الخصم وحأشرح لحضرتك."}],questions:[{q:"الموظفة عملت إيه قبل ما تحط العميل على الانتظار؟",options:["استأذنته وشرحت ليه محتاجة دقيقة","حطته على الانتظار فورًا","قفلت المكالمة","حوّلته لقسم تاني"],answer:"استأذنته وشرحت ليه محتاجة دقيقة",rationale:"قالت: Necesito un minuto para revisarlo. ¿Le puedo dejar en espera? — سبب + استئذان + مدة. en espera = على الانتظار."},{q:"لما رجعت من الانتظار، أول حاجة قالت إيه؟",options:["اعتذرت عن التأخير","شكرته على الانتظار","سألته عن رقمه","بدأت تشرح على طول"],answer:"شكرته على الانتظار",rationale:"قالت: Gracias por esperar = شكرًا على الانتظار. الشكر بعد الرجوع بيحترم وقت العميل."},{q:"محتاج تراجع حاجة على النظام أثناء المكالمة. تعمل إيه؟",options:["تسكت وتشتغل لحد ما تخلص","تحط العميل على الانتظار من غير ما تقوله","تستأذن العميل في انتظار قصير وتحدد المدة","تقوله يتصل تاني"],answer:"تستأذن العميل في انتظار قصير وتحدد المدة",rationale:"الصمت على الخط بيخلي العميل يفتكر المكالمة اتقطعت. الاستئذان بمدة واضحة بيطمنه."}],responseTask:{prompt:"محتاج دقيقة تراجع حاجة على النظام. استأذن العميل بالإسباني في انتظار قصير وحدد المدة.",acceptable:["Necesito un minuto para revisarlo. ¿Le puedo dejar en espera?","¿Le puedo dejar en espera un minuto mientras lo reviso?","Un momento, por favor. ¿Le dejo en espera un minuto?","¿Le puedo poner en espera un minuto? Lo reviso y vuelvo."],modelEs:"Necesito un minuto para revisarlo. ¿Le puedo dejar en espera?",modelAr:"محتاجة دقيقة أراجعه. ممكن أحط حضرتك على الانتظار؟",checklistAr:"راجع إجابتك: ١) سبب الانتظار واضح، ٢) استئذان صريح (¿Le puedo…?)، ٣) مدة واضحة وقصيرة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"en espera = على الانتظار. dejar o poner en espera = يحط على الانتظار. un minuto solo = دقيقة واحدة بس. dígame = اتفضل احكيلي (بصيغة حضرتك)."}},{id:"cc-u06l02",courseId:"call-center",unitId:"cc-u06",sourceLessonId:"cc-u06l02",level:"B1",register:"usted",title:"ححوّلك لمين",context:"حالة العميلة بتخص قسم الحجوزات، مش قسمك. دورك: تقول لها حتتحوّل لمين بالظبط، وتطمنها إن ملفها واصل، وتقولها إيه اللي بيحصل لو الخط اتقطع.",goal:"بعد الدرس ده حتقدر تشرح التحويل بشكل كامل: القسم المقصود، إن الملف واصل، وسيناريو انقطاع الخط.",targets:[{es:"Su caso lo lleva el departamento de reservas.",ar:"حالة حضرتك بيتابعها قسم الحجوزات.",speaker:"paco"},{es:"Ellos ven su expediente completo.",ar:"هم شايفين ملف حضرتك كامل.",speaker:"paco"},{es:"Si se corta la llamada, le devuelven la llamada.",ar:"لو المكالمة اتقطعت، حيرنّوا على حضرتك.",speaker:"paco"},{es:"Que tenga buen día.",ar:"يومك سعيد.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Mire. Su caso lo lleva el departamento de reservas. Le paso con ellos ahora.",ar:"بصي حضرتك. حالة حضرتك بيتابعها قسم الحجوزات. ححوّلك لهم دلوقتي."},{speaker:"luna",es:"¿Con quién voy a hablar?",ar:"حتكلم مين؟"},{speaker:"paco",es:"Con el departamento de reservas. Ellos ven su expediente completo.",ar:"مع قسم الحجوزات. هم شايفين ملف حضرتك كامل."},{speaker:"luna",es:"¿Y cuánto tarda?",ar:"وحياخد وقت قد إيه؟"},{speaker:"paco",es:"Normalmente unos minutos. Si se corta la llamada, le devuelven la llamada.",ar:"عادي كام دقيقة. لو المكالمة اتقطعت، حيرنّوا على حضرتك."},{speaker:"luna",es:"Vale, gracias.",ar:"تمام، شكرًا."},{speaker:"paco",es:"Le paso ahora. Que tenga buen día.",ar:"ححوّلك دلوقتي. يومك سعيد."}],questions:[{q:"العميلة حتتحوّل لأنهي قسم؟",options:["المبيعات","القسم الفني","قسم الفواتير","قسم الحجوزات"],answer:"قسم الحجوزات",rationale:"قال: su caso lo lleva el departamento de reservas = حالتك بيتابعها قسم الحجوزات. reservas = حجوزات."},{q:"لو المكالمة اتقطعت أثناء التحويل، إيه اللي بيحصل؟",options:["القسم التاني حيرن عليها","تتصل من الأول","البلاغ بيتقفل","لازم تبعت إيميل"],answer:"القسم التاني حيرن عليها",rationale:"قال: Si se corta la llamada, le devuelven la llamada = لو المكالمة اتقطعت، حيرنّوا عليكي. devolver la llamada = يرن تاني."},{q:"ليه مهم تقول للعميل حيتحوّل لمين؟",options:["عشان يتأكد من راتب الموظف","عشان يعرف مين حيساعده وميحسش إنه اترمي في مكان مجهول","عشان يقفل هو","مش مهم"],answer:"عشان يعرف مين حيساعده وميحسش إنه اترمي في مكان مجهول",rationale:"التحويل المفاجئ من أكتر الحاجات اللي بتضايق العملاء. اسم القسم + طمأنة إن الملف واصل بيقلل الاحتكاك."}],responseTask:{prompt:"حتحوّل العميلة لقسم الحجوزات. وضح لها بالإسباني لمين حتتحوّل وإنهم شايفين ملفها كامل.",acceptable:["Su caso lo lleva el departamento de reservas. Le paso con ellos ahora.","Le paso con el departamento de reservas, que ve su expediente completo.","Ahora le paso con reservas. Ellos ven todo su expediente.","Le transfiero con el departamento de reservas, que tiene su expediente."],modelEs:"Su caso lo lleva el departamento de reservas. Le paso con ellos ahora.",modelAr:"حالة حضرتك بيتابعها قسم الحجوزات. ححوّلك لهم دلوقتي.",checklistAr:"راجع إجابتك: ١) اسم القسم واضح، ٢) طمأنة إن الملف واصل (expediente)، ٣) مفيش وعد بوقت انتظار مضمون. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"pasar con = يحوّل لـ. expediente = ملف. transferir = يحوّل (أكتر رسمية). ¿Cuánto tarda? = حياخد وقت قد إيه؟"}},{id:"cc-u06l03",courseId:"call-center",unitId:"cc-u06",sourceLessonId:"cc-u06l03",level:"B1",register:"usted",title:"انقل بس المسموح",context:"حتحوّل عميل لزميل في قسم تاني. دورك: تنقل بس البيانات الضرورية للحالة، وتوضح للعميل إن بيانات الدفع مش بتتنقل، وتعرض بديل الرنة الرجيعة.",goal:"بعد الدرس ده حتقدر توضح إيه اللي بينتقل في التحويل، وتحمي بيانات العميل، وتعرض بدائل الانتظار لو شركتك بتتيحها.",targets:[{es:"Le dejo una nota a mi compañero con su caso.",ar:"حسيب ملاحظة لزميلي بحالة حضرتك.",speaker:"luna"},{es:"Solo lo necesario para su caso.",ar:"الضروري بس لحالة حضرتك.",speaker:"luna"},{es:"Si prefiere, puede pedir que le devuelvan la llamada en vez de esperar.",ar:"لو تفضل، ممكن تطلب إنهم يرنّوا على حضرتك بدل الانتظار.",speaker:"luna"},{es:"Prefiero esperar.",ar:"أفضّل أستنى.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Antes de pasarle, un detalle. Le dejo una nota a mi compañero con su caso.",ar:"قبل ما أحوّلك، تفصيلة. حسيب ملاحظة لزميلي بحالة حضرتك."},{speaker:"paco",es:"¿Le va a contar todo?",ar:"حتحكي له كل حاجة؟"},{speaker:"luna",es:"Solo lo necesario para su caso. El número de pedido y lo que hemos revisado. Nada de datos de pago.",ar:"الضروري بس لحالة حضرتك. رقم الطلب واللي راجعناه. مفيش بيانات دفع خالص."},{speaker:"paco",es:"Me parece bien.",ar:"كده تمام."},{speaker:"luna",es:"Si prefiere, puede pedir que le devuelvan la llamada en vez de esperar.",ar:"لو تفضل، ممكن تطلب إنهم يرنّوا على حضرتك بدل الانتظار."},{speaker:"paco",es:"No. Prefiero esperar.",ar:"لأ. أفضّل أستنى."},{speaker:"luna",es:"Perfecto. Le paso ahora.",ar:"جميل. ححوّلك دلوقتي."}],questions:[{q:"الموظفة حتنقل للزميل إيه؟",options:["كل بيانات العميل","بيانات الكارت","رقم الطلب واللي اتراجع بس، من غير بيانات دفع","مش حتنقل أي حاجة"],answer:"رقم الطلب واللي اتراجع بس، من غير بيانات دفع",rationale:"قالت: Solo lo necesario para su caso. El número de pedido y lo que hemos revisado. Nada de datos de pago. lo necesario = الضروري."},{q:"إيه البديل اللي عرضته الموظفة بدل الانتظار؟",options:["مفيش بديل","رسالة نصية","إيميل","القسم يرن على العميل"],answer:"القسم يرن على العميل",rationale:"قالت: puede pedir que le devuelvan la llamada en vez de esperar = ممكن تطلب إنهم يرنّوا عليك بدل الانتظار. en vez de = بدل."},{q:"ليه بننقل بس البيانات الضرورية في التحويل؟",options:["عشان نحمي خصوصية العميل ونقلل مشاركة بياناته","عشان الزميل مشغول","عشان الشركة بتبخل","عشان الخط مش بيسمح"],answer:"عشان نحمي خصوصية العميل ونقلل مشاركة بياناته",rationale:"كل حد بيشوف البيانات بيزوّد مخاطرها. القاعدة: أقل بيانات تأدّي الغرض."}],responseTask:{prompt:"وضح للعميل بالإسباني إيه اللي حتنقله للزميل في التحويل، وإنك مش حتنقل بيانات دفع.",acceptable:["Le dejo una nota a mi compañero con su caso. Solo lo necesario para su caso. Nada de datos de pago.","Le paso una nota con lo necesario para su caso, sin datos de pago.","Mi compañero recibe solo lo necesario para su caso. Nada de datos de pago.","Le dejo una nota con su caso. Solo lo necesario, sin datos de pago."],modelEs:"Le dejo una nota a mi compañero con su caso. Solo lo necesario para su caso. Nada de datos de pago.",modelAr:"حسيب ملاحظة لزميلي بحالة حضرتك. الضروري بس. مفيش بيانات دفع خالص.",checklistAr:"راجع إجابتك: ١) تحديد اللي بينتقل (lo necesario)، ٢) استبعاد بيانات الدفع صراحة، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"lo necesario = الضروري. nada de = مفيش خالص. en vez de = بدل. Me parece bien = كده تمام / موافق."}},{id:"cc-u06l04",courseId:"call-center",unitId:"cc-u06",sourceLessonId:null,level:"B1",register:"usted",title:"انتظار طويل؟ قول الحقيقة",context:"طابور الانتظار طويل ومش قادر تأكد وقت. دورك: تقول الحقيقة باحترام وتعرض بديل عملي زي الرنة الرجيعة، من غير وعد بوقت مش مضمون.",goal:"بعد الدرس ده حتقدر تدير توقعات العميل لما الانتظار يطول: صراحة + بديل، بدل وقت متفائل بيوقعك في مشكلة أكبر.",targets:[{es:"No puedo darle un tiempo seguro.",ar:"مش قادر أديك وقت مضمون.",speaker:"paco"},{es:"Tiene dos opciones: espera en línea, o le devolvemos la llamada cuando le toque, sin perder su turno.",ar:"قدامك خيارين: تستني على الخط، أو نرّن عليك لما يجي دورك، من غير ما تخسري دورك.",speaker:"paco"},{es:"El sistema guarda su puesto.",ar:"النظام بيحفظ مكانك في الطابور.",speaker:"paco"},{es:"Prefiero que me devuelvan la llamada.",ar:"أفضّل إنكم ترنّوا عليّا.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Cuánto tengo que esperar?",ar:"لازم أستنى قد إيه؟"},{speaker:"paco",es:"Le soy sincero. Ahora mismo la espera está alta. No puedo darle un tiempo seguro.",ar:"حأكون صريح مع حضرتك. دلوقتي الانتظار عالي. مش قادر أديك وقت مضمون."},{speaker:"luna",es:"Uf, qué rabia.",ar:"أوف، يخربيت الضيق."},{speaker:"paco",es:"Lo entiendo. Tiene dos opciones: espera en línea, o le devolvemos la llamada cuando le toque, sin perder su turno.",ar:"فاهم حضرتك. قدامك خيارين: تستني على الخط، أو نرّن عليك لما يجي دورك، من غير ما تخسري دورك."},{speaker:"luna",es:"¿Y no pierdo mi turno seguro?",ar:"ومتأكد إني مش حخسر دوري؟"},{speaker:"paco",es:"No lo pierde. El sistema guarda su puesto.",ar:"مش حتخسريه. النظام بيحفظ مكانك في الطابور."},{speaker:"luna",es:"Entonces, vale. Prefiero que me devuelvan la llamada.",ar:"يبقى تمام. أفضّل إنكم ترنّوا عليّا."},{speaker:"paco",es:"Perfecto. Apuntado. Le llaman al mismo número.",ar:"جميل. اتسجل. حيرنّوا على نفس الرقم."}],questions:[{q:"ليه الموظف مداش وقت انتظار محدد؟",options:["عشان مش عارف يقرا النظام","عشان الانتظار عالي ومفيش وقت مضمون يقدر يقوله","عشان مش عايز يتكلم","عشان الخط بيفصل"],answer:"عشان الانتظار عالي ومفيش وقت مضمون يقدر يقوله",rationale:"قال: no puedo darle un tiempo seguro = مش قادر أديك وقت مضمون. الصراحة أحسن من وقت متفائل بيكذب."},{q:"إيه الخيارين اللي اتعرضوا على العميلة؟",options:["تستنى أو تبعت إيميل","تقفل أو تشتكي","تستنى على الخط أو يرنّوا عليها من غير ما تخسر دورها","تدفع أكتر أو تستنى"],answer:"تستنى على الخط أو يرنّوا عليها من غير ما تخسر دورها",rationale:"قال: espera en línea, o le devolvemos la llamada cuando le toque, sin perder su turno = استنى على الخط أو نرّن عليك من غير ما تخسر دورك. puesto = مكان في الطابور."},{q:"لو العميلة اختارت الرنة الرجيعة، حتخسر دورها؟",options:["أيوه","ممكن","حسب الحظ","لأ، النظام بيحفظ مكانها"],answer:"لأ، النظام بيحفظ مكانها",rationale:"قال: No lo pierde. El sistema guarda su puesto = مش حتخسريه، النظام بيحفظ مكانك."}],responseTask:{prompt:"الانتظار طويل ومش قادر تأكد وقت. قل للعميل الحقيقة بالإسباني واعرض الرنة الرجيعة كبديل.",acceptable:["Le soy sincero: la espera está alta y no puedo darle un tiempo seguro. Si quiere, le devolvemos la llamada sin perder su turno.","Ahora mismo la espera está alta. Puede esperar en línea o le devolvemos la llamada sin perder su turno.","No puedo darle un tiempo seguro. Le devolvemos la llamada cuando le toque, si prefiere.","La espera está alta, lo siento. Si quiere, le llamamos nosotros sin perder su turno."],modelEs:"Le soy sincero: la espera está alta y no puedo darle un tiempo seguro. Si quiere, le devolvemos la llamada sin perder su turno.",modelAr:"حأكون صريح مع حضرتك: دلوقتي الانتظار عالي ومش قادر أديك وقت مضمون. لو تحبي، نرّن عليك من غير ما تخسري دورك.",checklistAr:"راجع إجابتك: ١) صراحة (le soy sincero / no puedo darle un tiempo seguro)، ٢) بديل عملي (devolver la llamada)، ٣) مفيش وعد بوقت محدد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"le soy sincero = حأكون صريح مع حضرتك. seguro هنا معناها مضمون. sin perder su turno = من غير ما تخسر دورك. qué rabia = يخربيت الضيق."}},{id:"cc-u06l05",courseId:"call-center",unitId:"cc-u06",sourceLessonId:null,level:"B1",register:"usted",title:"مش عايز يتحوّل تاني",context:"عميل اتحوّل مرتين قبل كده ورفض يتحوّل تالت. دورك: تتفهم إحباطه وتعرض بديل (القسم يرن عليه هو) من غير ما تعد بموعد محدد.",goal:"بعد الدرس ده حتقدر تمتص رفض العميل للتحويل وتلاقي حل وسط يحترم وقته من غير ما تكسر قواعد الشغل.",targets:[{es:"¡Ya me pasaron dos veces!",ar:"أنا اتحوّلت مرتين خلاص!",speaker:"paco"},{es:"No quiero hacerle dar vueltas.",ar:"مش عايزة أخلّيك تتلفت.",speaker:"luna"},{es:"Le pido al técnico que le llame a usted.",ar:"حطلب من الفني إنه يرن على حضرتك.",speaker:"luna"},{es:"No le prometo una hora concreta, pero queda su número con la nota.",ar:"مش حوعدك بساعة محددة، بس رقمك حيفضل مع الملاحظة.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Otra vez a otro departamento? ¡Ya me pasaron dos veces!",ar:"تاني لقسم تاني؟ أنا اتحوّلت مرتين خلاص!"},{speaker:"luna",es:"Le entiendo. No quiero hacerle dar vueltas. Déjeme ver si puedo resolverlo yo desde aquí.",ar:"فاهمة حضرتك. مش عايزة أخلّيك تتلفت. اسمحلي أشوف لو أقدر أحلها أنا من هنا."},{speaker:"paco",es:"Eso quiero.",ar:"ده اللي أنا عايزه."},{speaker:"luna",es:"Vale… Su caso necesita una clave que solo tiene el técnico. Le pido al técnico que le llame a usted. Así no tiene que esperar en línea.",ar:"تمام… حالة حضرتك محتاجة رمز مفيش غير عند الفني. حطلب من الفني إنه يرن على حضرتك. كده مش حتستنى على الخط."},{speaker:"paco",es:"¿Y eso cuándo?",ar:"وده حيكون إمتى؟"},{speaker:"luna",es:"Queda registrado con prioridad hoy. No le prometo una hora concreta, pero queda su número con la nota.",ar:"بيتسجل بأولوية النهارده. مش حوعدك بساعة محددة، بس رقمك حيفضل مع الملاحظة."},{speaker:"paco",es:"Vale, me parece justo.",ar:"تمام، ده كلام عادل."},{speaker:"luna",es:"Gracias por su paciencia, de verdad.",ar:"شكرًا على صبرك، والله."}],questions:[{q:"العميل زعلان من إيه؟",options:["اتحوّل مرتين قبل كده","الانتظار طويل","الفاتورة غلط","الموقع مش شغال"],answer:"اتحوّل مرتين قبل كده",rationale:"قال: ¡Ya me pasaron dos veces! = اتحوّلت مرتين خلاص! التحويل المتكرر من غير حل بيكسر صبر العميل."},{q:"الموظفة قدرت تحل المشكلة بنفسها؟",options:["أيوه، وقفلت الحالة","لأ، محتاجة رمز مفيش غير عند الفني","مش واضح","أيوه جزئيًا"],answer:"لأ، محتاجة رمز مفيش غير عند الفني",rationale:"قالت: su caso necesita una clave que solo tiene el técnico = الحالة محتاجة رمز مفيش غير عند الفني. clave = رمز/كلمة سر."},{q:"إيه الحل الوسط اللي اقترحته الموظفة؟",options:["تحويله فورًا","تقفل المكالمة","الفني يرن على العميل بدل ما العميل يتحوّل","تقوله يجي الفرع"],answer:"الفني يرن على العميل بدل ما العميل يتحوّل",rationale:"قالت: le pido al técnico que le llame a usted = حطلب من الفني إنه يرن على حضرتك. بديل بيحترم رفض العميل للتحويل."}],responseTask:{prompt:"عميل مش عايز يتحوّل تاني. رد بالإسباني: تفهّم، واعرض بديل من غير ما تعد بموعد محدد.",acceptable:["Le entiendo. No quiero hacerle dar vueltas. Le pido al técnico que le llame a usted.","Tiene razón. No le paso otra vez: le pido al técnico que le llame.","Lo entiendo. En vez de pasarle otra vez, pido que le llamen a usted.","No quiero hacerle dar vueltas. Le pido al técnico que le llame a usted directamente."],modelEs:"Le entiendo. No quiero hacerle dar vueltas. Le pido al técnico que le llame a usted.",modelAr:"فاهمة حضرتك. مش عايزة أخلّيك تتلفت. حطلب من الفني إنه يرن على حضرتك.",checklistAr:"راجع إجابتك: ١) تفهّم (Le entiendo / Tiene razón)، ٢) بديل من غير تحويل (que le llame a usted)، ٣) مفيش وعد بساعة محددة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"dar vueltas = يتلفت/يلف. pasarle = يحوّل حضرتك. una hora concreta = ساعة محددة. queda registrado = بيتسجل."}},{id:"cc-u06l06",courseId:"call-center",unitId:"cc-u06",sourceLessonId:null,level:"B1",register:"usted",title:"انتظار وتحويل وتسليم",context:"مكالمة كاملة: تستأذن في انتظار، ترجع وتشكر، توضح القسم اللي حياخد الحالة، وتسيب ملاحظة للزميل من غير بيانات دفع. الدرس ده بيجمع كل اللي فات في الوحدة.",goal:"بعد الدرس ده حتقدر تنفذ دورة انتظار وتحويل كاملة وسليمة من أول الاستئذان لحد قفلة المكالمة.",targets:[{es:"¿Le puedo dejar en espera?",ar:"ممكن أحط حضرتك على الانتظار؟",speaker:"luna"},{es:"Gracias por esperar.",ar:"شكرًا على الانتظار.",speaker:"luna"},{es:"Su caso lo lleva el departamento de envíos.",ar:"حالة حضرتك بيتابعها قسم الشحن.",speaker:"luna"},{es:"Si se corta la llamada, le devuelven la llamada.",ar:"لو المكالمة اتقطعت، حيرنّوا على حضرتك.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Necesito un minuto para revisar su caso. ¿Le puedo dejar en espera?",ar:"محتاجة دقيقة أراجع حالة حضرتك. ممكن أحط حضرتك على الانتظار؟"},{speaker:"paco",es:"Sí, claro.",ar:"أيوه، طبعًا."},{speaker:"luna",es:"Gracias por esperar. Ya lo tengo. Su caso lo lleva el departamento de envíos.",ar:"شكرًا على الانتظار. لقيتها. حالة حضرتك بيتابعها قسم الشحن."},{speaker:"paco",es:"¿Y tengo que explicarlo todo otra vez?",ar:"ولازم أحكي كل حاجة من الأول؟"},{speaker:"luna",es:"No. Le dejo una nota a mi compañero con su pedido y lo que hemos revisado. Nada de datos de pago.",ar:"لأ. حسيب ملاحظة لزميلي بالطلب بتاعك واللي راجعناه. مفيش بيانات دفع خالص."},{speaker:"paco",es:"Perfecto.",ar:"جميل."},{speaker:"luna",es:"Le paso ahora. Si se corta la llamada, le devuelven la llamada.",ar:"ححوّلك دلوقتي. لو المكالمة اتقطعت، حيرنّوا على حضرتك."},{speaker:"paco",es:"Vale, gracias.",ar:"تمام، شكرًا."},{speaker:"luna",es:"Gracias a usted. Que tenga buen día.",ar:"وشكرًا لحضرتك. يومك سعيد."}],questions:[{q:"الموظفة عملت إيه أول ما رجعت من الانتظار؟",options:["حوّلته فورًا","بدأت تتكلم على طول","سألته يقفل","شكرت العميل على الانتظار وقالتله النتيجة"],answer:"شكرت العميل على الانتظار وقالتله النتيجة",rationale:"قالت: Gracias por esperar. Ya lo tengo. = شكرًا على الانتظار، لقيتها. الشكر بعد الرجوع جزء أساسي من الآداب."},{q:"إيه اللي حيتنقل للزميل في الملاحظة؟",options:["رقم الطلب واللي اتراجع، من غير بيانات دفع","كل حاجة بما فيها بيانات الدفع","مفيش حاجة","رقم الكارت بس"],answer:"رقم الطلب واللي اتراجع، من غير بيانات دفع",rationale:"قالت: una nota con su pedido y lo que hemos revisado. Nada de datos de pago. pedido = طلب."},{q:"لو الخط اتقطع أثناء التحويل، إيه اللي بيحصل؟",options:["العميل يتصل من الأول","القسم الجديد يرن على العميل","الحالة بتتلغى","مفيش حل"],answer:"القسم الجديد يرن على العميل",rationale:"قالت: Si se corta la llamada, le devuelven la llamada = لو المكالمة اتقطعت، حيرنّوا عليك."}],responseTask:{prompt:"لخّص بالإسباني خطوات التحويل الصح: استئذان للانتظار، شكر بعد الرجوع، توضيح القسم، وملاحظة للزميل من غير بيانات دفع.",acceptable:["¿Le puedo dejar en espera un minuto? …Gracias por esperar. Su caso lo lleva el departamento de envíos. Le dejo una nota a mi compañero, sin datos de pago.","¿Le dejo en espera un minuto? …Gracias por esperar. Le paso con envíos y le dejo una nota a mi compañero. Nada de datos de pago.","¿Le puedo dejar en espera? …Gracias por esperar. Le paso con el departamento de envíos, con una nota de su caso. Sin datos de pago.","¿Le dejo en espera un minuto? …Gracias por esperar. Su caso es de envíos. Mi compañero recibe una nota con lo necesario."],modelEs:"¿Le puedo dejar en espera un minuto? …Gracias por esperar. Su caso lo lleva el departamento de envíos. Le dejo una nota a mi compañero, sin datos de pago.",modelAr:"ممكن أحط حضرتك على الانتظار دقيقة؟ …شكرًا على الانتظار. حالة حضرتك بيتابعها قسم الشحن. حسيب ملاحظة لزميلي، من غير بيانات دفع.",checklistAr:"راجع إجابتك: ١) استئذان مع مدة، ٢) شكر بعد الرجوع، ٣) القسم + ملاحظة من غير بيانات دفع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Que tenga buen día = يومك سعيد (صيغة حضرتك). gracias a usted = وشكرًا لحضرتك. Nada de datos de pago = مفيش بيانات دفع خالص."}}]},{courseId:"call-center",unit:{id:"cc-u07",title:"الاعتذار والمكالمات الصعبة",desc:"تعتذر عن الإزعاج من غير لوم، ترفض الوعد الكاذب ببديل واقعي، وتدير العميل الغاضب والشكوى الرسمية.",cefr:"B1"},lessons:[{id:"cc-u07l01",courseId:"call-center",unitId:"cc-u07",sourceLessonId:"cc-u07l01",level:"B1",register:"usted",title:"اعتذر صح",context:"عميل متضايق من تأخير. دورك: تعتذر عن الإزعاج من غير ما ترمي اللوم عليه ولا على زمايلك، وتنتقل بسرعة للخطوة العملية.",goal:"بعد الدرس ده حتقدر تعتذر اعتذار مهني: يعترف بالإزعاج، ميلومش حد، وبيفتح الطريق للحل.",targets:[{es:"Siento mucho las molestias.",ar:"أنا متأسفة جدًا على الإزعاج.",speaker:"luna"},{es:"Tiene toda la razón.",ar:"مع حضرتك كل الحق.",speaker:"luna"},{es:"Vamos a arreglarlo ahora.",ar:"حنصلحها دلوقتي.",speaker:"luna"},{es:"Gracias por su paciencia.",ar:"شكرًا على صبر حضرتك.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¡Llevo tres días esperando una respuesta!",ar:"أنا ليّا تلات أيام مستني رد!"},{speaker:"luna",es:"Siento mucho las molestias. Tiene toda la razón.",ar:"أنا متأسفة جدًا على الإزعاج. مع حضرتك كل الحق."},{speaker:"paco",es:"Es que nadie me contesta.",ar:"المشكلة إن محدش بيرد عليّا."},{speaker:"luna",es:"Lo entiendo. Vamos a arreglarlo ahora. ¿Me da el número de su caso?",ar:"فاهمة حضرتك. حنصلحها دلوقتي. تديني رقم البلاغ بتاع حضرتك؟"},{speaker:"paco",es:"Es el cuarenta y cinco ochenta y nueve.",ar:"رقم ٤٥٨٩."},{speaker:"luna",es:"Gracias. Ya lo tengo delante.",ar:"شكرًا. هو قدامي خلاص."},{speaker:"paco",es:"A ver si esta vez pasa algo.",ar:"نشوف المرة دي هيحصل حاجة ولا لأ."},{speaker:"luna",es:"Gracias por su paciencia. Le digo exactamente lo que voy a hacer.",ar:"شكرًا على صبر حضرتك. حأقولك بالظبط حعمل إيه."}],questions:[{q:"الموظفة عملت إيه أول حاجة لما العميل اتنرفز؟",options:["اعتذرت عن الإزعاج واعترفت إنه معه حق","دافعت عن الشركة","سألته يهدى الأول","قالتله إن ده غلطه هو"],answer:"اعتذرت عن الإزعاج واعترفت إنه معه حق",rationale:"قالت: Siento mucho las molestias. Tiene toda la razón. — الاعتذار والاعتراف بيهدّوا المكالمة قبل أي خطوة عملية."},{q:"بعد الاعتذار، الموظفة انتقلت لإيه؟",options:["قفلت المكالمة","طلبت رقم البلاغ عشان تبدأ الحل","حوّلته لقسم تاني","وعدته بتعويض"],answer:"طلبت رقم البلاغ عشان تبدأ الحل",rationale:"قالت: ¿Me da el número de su caso? — الاعتذار لوحده مش كفاية، لازم خطوة عملية فورية."},{q:"ليه الاعتذار المهني مبيلومش زمايلك ولا العميل؟",options:["عشان اللوم بيطوّل المكالمة وبيحرق الثقة من غير ما يحل حاجة","عشان الشركة بتمنع الكلام","عشان العميل بيزعل","مفيش سبب"],answer:"عشان اللوم بيطوّل المكالمة وبيحرق الثقة من غير ما يحل حاجة",rationale:"اللوم، لأي حد، بيخلي العميل يدافع أو يهاجم. الاعتراف بالإزعاج + خطوة عملية هو اللي بيقدّم المكالمة."}],responseTask:{prompt:"عميل مستني رد من تلات أيام ومتضايق. اعتذر بالإسباني من غير لوم، وانتقل لخطوة عملية.",acceptable:["Siento mucho las molestias. Tiene toda la razón. Vamos a arreglarlo ahora.","Siento mucho las molestias. Lo entiendo. ¿Me da el número de su caso? Lo veo ahora.","Tiene razón, y siento las molestias. Vamos a arreglarlo ahora mismo.","Siento mucho las molestias. Gracias por su paciencia. Lo revisamos ahora."],modelEs:"Siento mucho las molestias. Tiene toda la razón. Vamos a arreglarlo ahora.",modelAr:"أنا متأسفة جدًا على الإزعاج. مع حضرتك كل الحق. حنصلحها دلوقتي.",checklistAr:"راجع إجابتك: ١) اعتذار صريح (Siento…)، ٢) اعتراف بحق العميل أو تفهّم، ٣) خطوة عملية فورية، ٤) مفيش لوم لأي حد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Siento mucho las molestias = أنا متأسف جدًا على الإزعاج (molestias = إزعاج). Tiene toda la razón = مع حضرتك كل الحق. arreglarlo = يصلحها. ahora mismo = دلوقتي حالًا."}},{id:"cc-u07l02",courseId:"call-center",unitId:"cc-u07",sourceLessonId:"cc-u07l02",level:"B1",register:"usted",title:"متوعدش بمش مضمون",context:"عميل عايز وعد بميعاد تسليم ورد فلوس. دورك: متوعدش بحاجة مش في صلاحيتك ولا متأكد منها؛ قول اللي تقدر تعمله فعلًا.",goal:"بعد الدرس ده حتقدر ترفض الوعد الكاذب بشكل مهني وتقدّم البديل الواقعي: اللي في إيدك + خطوة متابعة.",targets:[{es:"No le puedo prometer una fecha que no controlo.",ar:"مش أقدر أوعدك بميعاد مش في إيدي.",speaker:"paco"},{es:"Lo que sí puedo hacer es abrir una reclamación con prioridad.",ar:"اللي أقدر أعمله فعلًا إني أفتح شكوى بأولوية.",speaker:"paco"},{es:"Le doy la referencia y me comprometo a darle seguimiento.",ar:"حأديك رقم المرجع وألتزم إني أتابع الموضوع.",speaker:"paco"},{es:"No quiero decirle algo que no puedo cumplir.",ar:"مش عايز أقولك حاجة مش حقدر أنفذها.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Necesito que me prometa que llega el viernes.",ar:"محتاجاك توعدني إنه حيوصل الجمعة."},{speaker:"paco",es:"Le soy sincero. No le puedo prometer una fecha que no controlo.",ar:"حأكون صريح مع حضرتك. مش أقدر أوعدك بميعاد مش في إيدي."},{speaker:"luna",es:"Entonces, ¿qué hago?",ar:"طب أعمل إيه؟"},{speaker:"paco",es:"Lo que sí puedo hacer es abrir una reclamación con prioridad. Así su caso pasa delante.",ar:"اللي أقدر أعمله فعلًا إني أفتح شكوى بأولوية. كده حالة حضرتك حتتقدم."},{speaker:"luna",es:"¿Y me devuelven el dinero si no llega?",ar:"ولو موصلش، حيرجعولي فلوسي؟"},{speaker:"paco",es:"Eso lo decide el departamento de reembolsos, no yo. No quiero decirle algo que no puedo cumplir.",ar:"ده قرار قسم المرتجعات، مش قراري أنا. مش عايز أقولك حاجة مش حقدر أنفذها."},{speaker:"luna",es:"Vale, entiendo.",ar:"تمام، فاهمة."},{speaker:"paco",es:"Le doy la referencia y me comprometo a darle seguimiento. Si no hay noticias, llama con ella.",ar:"حأديك رقم المرجع وألتزم إني أتابع الموضوع. لو مفيش أخبار، اتصلي بيه."}],questions:[{q:"ليه الموظف رفض يوعد بميعاد الجمعة؟",options:["عشان مش عايز يشتغل","عشان الميعاد مش في صلاحيته ومش مضمون","عشان الشركة بتمنع الوعود الكلامية","عشان العميل مش مستاهل"],answer:"عشان الميعاد مش في صلاحيته ومش مضمون",rationale:"قال: No le puedo prometer una fecha que no controlo = مش أقدر أوعدك بميعاد مش في إيدي. الوعد الكاذب بيخلّي العميل يتصل تاني أكتر عصبية."},{q:"قرار رد الفلوس بتاع مين؟",options:["الموظف نفسه","قسم المرتجعات","الشحن","العميل"],answer:"قسم المرتجعات",rationale:"قال: Eso lo decide el departamento de reembolsos, no yo. reembolso = مرتجع/رد فلوس."},{q:"إيه اللي التزم بيه الموظف فعلًا؟",options:["ميعاد الجمعة","رد الفلوس","فتح شكوى بأولوية ورقم مرجع ومتابعة","خصم على الطلب الجاي"],answer:"فتح شكوى بأولوية ورقم مرجع ومتابعة",rationale:"قال: abrir una reclamación con prioridad… Le doy la referencia y me comprometo a darle seguimiento. reclamación = شكوى رسمية، seguimiento = متابعة."}],responseTask:{prompt:"عميلة بتطلب وعد بميعاد مش في إيدك. رد بالإسباني: صدق من غير وعد كاذب + بديل واقعي.",acceptable:["No le puedo prometer una fecha que no controlo. Lo que sí puedo hacer es abrir una reclamación con prioridad.","Le soy sincero: no puedo prometer una fecha que no controlo. Puedo abrir una reclamación con prioridad.","No quiero decirle algo que no puedo cumplir. Lo que sí puedo hacer es abrir una reclamación con prioridad.","No le puedo prometer eso. Lo que sí puedo hacer es abrir una reclamación con prioridad y darle seguimiento."],modelEs:"No le puedo prometer una fecha que no controlo. Lo que sí puedo hacer es abrir una reclamación con prioridad.",modelAr:"مش أقدر أوعدك بميعاد مش في إيدي. اللي أقدر أعمله فعلًا إني أفتح شكوى بأولوية.",checklistAr:"راجع إجابتك: ١) مفيش وعد بميعاد أو رد فلوس مش مضمون، ٢) بديل واقعي في صلاحيتك (reclamación con prioridad = شكوى رسمية)، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"prometer = يوعد. cumplir = ينفذ الوعد. me comprometo = أنا ملتزم. Lo que sí puedo hacer = اللي أقدر أعمله فعلًا (بتتقال كتير لما بترفض طلب)."}},{id:"cc-u07l03",courseId:"call-center",unitId:"cc-u07",sourceLessonId:"cc-u07l03",level:"B1",register:"usted",title:"الشكوى الرسمية",context:"عميل قرر يقدّم شكوى رسمية. دورك: تحترم قراره وتشرح له طريقة الشكوى ببساطة، من غير ما تحاول تثنيه ولا تضايقه.",goal:"بعد الدرس ده حتقدر تستقبل طلب الشكوى الرسمية باحترافية: تسجّلها، وتشرح القناة، وتدي رقم مرجع.",targets:[{es:"Tiene derecho a presentar una reclamación.",ar:"من حق حضرتك تقدّم شكوى رسمية.",speaker:"luna"},{es:"Le explico cómo hacerlo paso a paso.",ar:"حأشرح لحضرتك الطريقة خطوة خطوة.",speaker:"luna"},{es:"Le doy el número de registro de la reclamación.",ar:"حأديك رقم تسجيل الشكوى.",speaker:"luna"},{es:"Recibirá una respuesta por escrito.",ar:"حيوصلك رد مكتوب.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Mire, esto no puede seguir así. Quiero presentar una reclamación.",ar:"بصي حضرتك، كده مينفعش يفضل. عايز أقدّم شكوى رسمية."},{speaker:"luna",es:"Lo entiendo. Tiene derecho a presentar una reclamación.",ar:"فاهمة حضرتك. من حق حضرتك تقدّم شكوى رسمية."},{speaker:"paco",es:"¿Y cómo se hace?",ar:"وأعمل كده إزاي؟"},{speaker:"luna",es:"Le explico cómo hacerlo paso a paso. La registro ahora con usted y le llega un correo de confirmación.",ar:"حأشرح لحضرتك الطريقة خطوة خطوة. حسجّلها دلوقتي مع حضرتك وحيوصلك إيميل تأكيد."},{speaker:"paco",es:"¿Y quién la lee?",ar:"ومين حيقراها؟"},{speaker:"luna",es:"El equipo de reclamaciones. Recibirá una respuesta por escrito.",ar:"فريق الشكاوى. حيوصلك رد مكتوب."},{speaker:"paco",es:"Vale. ¿Tengo algún número para seguirla?",ar:"تمام. معايا رقم أتابع بيه؟"},{speaker:"luna",es:"Sí. Le doy el número de registro de la reclamación. Apúntelo, por favor.",ar:"أيوه. حأديك رقم تسجيل الشكوى. دوّنه لو سمحت."}],questions:[{q:"الموظفة ردّت إزاي على طلب الشكوى؟",options:["حاولت تقنعه يعدل","قالتله من حقه وساعدته يسجّلها","قالتله الشكاوى مش بتنفع","تجاهلت الطلب"],answer:"قالتله من حقه وساعدته يسجّلها",rationale:"قالت: Tiene derecho a presentar una reclamación = من حق حضرتك تقدّم شكوى رسمية. محاولة صد العميل عن حقه بتصعّد الموقف."},{q:"مين حيرد على الشكوى؟",options:["الموظفة نفسها","فريق الشكاوى، وبرد مكتوب","المبيعات","محدش"],answer:"فريق الشكاوى، وبرد مكتوب",rationale:"قالت: El equipo de reclamaciones. Recibirá una respuesta por escrito. por escrito = مكتوب."},{q:"ليه رقم تسجيل الشكوى مهم للعميل؟",options:["عشان يقدر يتابع الشكوى ويثبت إنها اتسجلت","عشان الديكور","مش مهم","عشان الموظف يفتكره"],answer:"عشان يقدر يتابع الشكوى ويثبت إنها اتسجلت",rationale:"رقم التسجيل هو الدليل إن الشكوى دخلت النظام، والعميل يتابع بيه في أي مكالمة جاية."}],responseTask:{prompt:"عميل عايز يقدّم شكوى رسمية. رد بالإسباني: اعترف بحقه واعرض تسجيلها مع رقم متابعة.",acceptable:["Tiene derecho a presentar una reclamación. La registro ahora y le doy el número de registro.","Tiene derecho a presentar una reclamación. Le explico cómo hacerlo paso a paso.","Por supuesto. Le registro la reclamación ahora y le doy el número.","Tiene derecho a presentar una reclamación. La registramos ahora y recibirá una respuesta por escrito."],modelEs:"Tiene derecho a presentar una reclamación. La registro ahora y le doy el número de registro.",modelAr:"من حق حضرتك تقدّم شكوى رسمية. حسجّلها دلوقتي وحأديك رقم التسجيل.",checklistAr:"راجع إجابتك: ١) اعتراف بالحق (tiene derecho)، ٢) تسجيل فوري أو شرح للطريقة، ٣) رقم مرجع أو رد مكتوب، ٤) مفيش محاولة صد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"reclamación = شكوى رسمية. registrar = يسجّل. por escrito = مكتوب. Apúntelo = دوّنه (صيغة حضرتك)."}},{id:"cc-u07l04",courseId:"call-center",unitId:"cc-u07",sourceLessonId:null,level:"B1",register:"usted",title:"عميل بيصرخ",context:"عميل بيصرخ وبيشتّم الخدمة. دورك: تمتص الغضب بثبات، تحط حد هادئ للأسلوب من غير ما تهاجم، وترجع الكلام للحل.",goal:"بعد الدرس ده حتقدر تتعامل مع الصوت العالي: هدوء + حد للأسلوب + رجوع للحل، من غير ما تنزل لنفس المستوى.",targets:[{es:"Le escucho y quiero ayudarle de verdad.",ar:"أنا سامع حضرتك وعايزة أساعدك بجد.",speaker:"luna"},{es:"Si hablamos con calma, lo resolvemos más rápido.",ar:"لو اتكلمنا بهدوء، حنحلها أسرع.",speaker:"luna"},{es:"Estoy aquí para resolverlo.",ar:"أنا هنا عشان أحلها.",speaker:"luna"},{es:"¿Me deja hacerle unas preguntas para empezar?",ar:"تسمحلي أسأل حضرتك كام سؤال عشان نبدأ؟",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¡Esto es una vergüenza! ¡Nada funciona nunca!",ar:"ده عيب! ولا حاجة بتشتغل أبدًا!"},{speaker:"luna",es:"Le escucho y quiero ayudarle de verdad.",ar:"أنا سامع حضرتك وعايزة أساعدك بجد."},{speaker:"paco",es:"¡Es que ya estoy harto!",ar:"أنا زهقت خلاص!"},{speaker:"luna",es:"Lo sé, y tiene motivos. Si hablamos con calma, lo resolvemos más rápido.",ar:"عارفة، ومع حضرتك أسباب. لو اتكلمنا بهدوء، حنحلها أسرع."},{speaker:"paco",es:"…Vale. Dígame.",ar:"…تمام. اتفضلي."},{speaker:"luna",es:"Gracias. Estoy aquí para resolverlo. ¿Me deja hacerle unas preguntas para empezar?",ar:"شكرًا. أنا هنا عشان أحلها. تسمحلي أسأل حضرتك كام سؤال عشان نبدأ؟"},{speaker:"paco",es:"Adelante.",ar:"اتفضلي."},{speaker:"luna",es:"Perfecto. ¿Me cuenta desde cuándo le pasa?",ar:"جميل. احكيلي من إمتى بيحصل مع حضرتك؟"}],questions:[{q:"الموظفة عملت إيه لما العميل صرخ؟",options:["هدّته من غير ما تهاجم وحطّت حد للأسلوب","صرخت زيه","قفلت فورًا","حوّلته للمدير"],answer:"هدّته من غير ما تهاجم وحطّت حد للأسلوب",rationale:"قالت: Si hablamos con calma, lo resolvemos más rápido = لو اتكلمنا بهدوء، حنحلها أسرع. حد هادئ للأسلوب + رجوع للحل."},{q:"إيه اللي خلّى العميل يهدى؟",options:["وعدته بتعويض","تجاهلته","اعترفت بأسبابه وربطت الهدوء بسرعة الحل","هدّدته بقفل الخط"],answer:"اعترفت بأسبابه وربطت الهدوء بسرعة الحل",rationale:"قالت: Lo sé, y tiene motivos = عارفة، ومع حضرتك أسباب. الاعتراف بالغضب + مصلحة العميل في الهدوء."},{q:"ليه مينفعش تصرخ في وش العميل اللي بيصرخ؟",options:["عشان التسجيل","عشان الزمايل حيسمعوك","عشان ده بيصعّد الموقف وبيكسر أي فرصة للحل","مينفع عادي"],answer:"عشان ده بيصعّد الموقف وبيكسر أي فرصة للحل",rationale:"الصوت العالي بيولّد صوت أعلى. ثباتك هو الأداة الوحيدة اللي بترجع المكالمة لسكة الحل."}],responseTask:{prompt:"عميل بيصرخ وبيشتّم الخدمة. رد بالإسباني بجملتين: تفهّم ثابت + رجوع للحل، من غير هجوم.",acceptable:["Le escucho y quiero ayudarle de verdad. Si hablamos con calma, lo resolvemos más rápido.","Tiene motivos para enfadarse. Estoy aquí para resolverlo.","Lo entiendo. Estoy aquí para resolverlo. ¿Me deja hacerle unas preguntas?","Le escucho. Quiero ayudarle de verdad, y con calma lo resolvemos más rápido."],modelEs:"Le escucho y quiero ayudarle de verdad. Si hablamos con calma, lo resolvemos más rápido.",modelAr:"أنا سامع حضرتك وعايزة أساعدك بجد. لو اتكلمنا بهدوء، حنحلها أسرع.",checklistAr:"راجع إجابتك: ١) تفهّم أو استماع (Le escucho / Lo entiendo)، ٢) حد هادئ للأسلوب أو ربط الهدوء بالحل، ٣) مفيش هجوم ولا تهديد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"harto = زهقان. con calma = بهدوء. una vergüenza = عيب/فضيحة. adelante = اتفضل/كمّل."}},{id:"cc-u07l05",courseId:"call-center",unitId:"cc-u07",sourceLessonId:null,level:"B1",register:"usted",title:"قول لأ ببديل",context:"عميلة طالبة خصم مش موجود في النظام. دورك: تقول لأ بوضوح وأدب، من غير أعذار ملتفة، وتقدّم اللي تقدر تعمله فعلًا.",goal:"بعد الدرس ده حتقدر ترفض طلب من غير ما تكسّر العميل: لأ واضحة + سبب حقيقي + بديل متاح.",targets:[{es:"Ese descuento no puedo aplicarlo, lo siento.",ar:"الخصم ده مش أقدر أطبقه، أنا آسف.",speaker:"paco"},{es:"No existe en el sistema para este servicio.",ar:"مش موجود في النظام للخدمة دي.",speaker:"paco"},{es:"Lo que sí puedo hacer es revisar si tiene una oferta activa.",ar:"اللي أقدر أعمله فعلًا إني أراجع لو عند حضرتك عرض شغال.",speaker:"paco"},{es:"Prefiero decírselo claro ahora.",ar:"أفضّل أقولهالك بوضوح دلوقتي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Quiero un descuento del cincuenta por ciento, como el de mi amiga.",ar:"عايزة خصم خمسين في المية، زي بتاع صاحبتي."},{speaker:"paco",es:"Lo entiendo. Ese descuento no puedo aplicarlo, lo siento. No existe en el sistema para este servicio.",ar:"فاهم حضرتك. الخصم ده مش أقدر أطبقه، أنا آسف. مش موجود في النظام للخدمة دي."},{speaker:"luna",es:"¿Ni un poquito?",ar:"ولا حتى شوية؟"},{speaker:"paco",es:"Prefiero decírselo claro ahora. Lo que sí puedo hacer es revisar si tiene una oferta activa.",ar:"أفضّل أقولهالك بوضوح دلوقتي. اللي أقدر أعمله فعلًا إني أراجع لو عند حضرتك عرض شغال."},{speaker:"luna",es:"Vale, mírelo.",ar:"تمام، بصّلي."},{speaker:"paco",es:"Mire. Tiene una oferta del quince por ciento durante tres meses.",ar:"بصي حضرتك. عندك عرض خمستاشر في المية لمدة تلات شهور."},{speaker:"luna",es:"Bueno, algo es algo. Vale.",ar:"ماشي، حاجة أحسن من لأ. تمام."},{speaker:"paco",es:"Se lo activo ahora mismo.",ar:"حفعّلهولك دلوقتي حالًا."}],questions:[{q:"الموظف رفض الطلب إزاي؟",options:["بأعذار طويلة ملتفة","وعده يشوف بعدين","لأ واضحة + سبب حقيقي + بديل","تجاهل الطلب"],answer:"لأ واضحة + سبب حقيقي + بديل",rationale:"قال: Ese descuento no puedo aplicarlo… No existe en el sistema… Lo que sí puedo hacer es… — الوضوح بيوفر على العميل سلسلة مكالمات."},{q:"إيه البديل اللي لقاه الموظف؟",options:["خصم خمسين في المية","مفيش بديل","شهر مجاني","عرض خمستاشر في المية لمدة تلات شهور"],answer:"عرض خمستاشر في المية لمدة تلات شهور",rationale:"قال: una oferta del quince por ciento durante tres meses = عرض ١٥٪ لمدة ٣ شهور. oferta = عرض."},{q:"ليه الوضوح في اللأ أحسن من الأعذار الملتفة؟",options:["عشان يخلص بسرعة","مفيش فرق","عشان النظام بيسجل","عشان العميل بيحترم الصراحة وبيبني عليها، والالتفاف بيخلّيه يحاول تاني وتالت"],answer:"عشان العميل بيحترم الصراحة وبيبني عليها، والالتفاف بيخلّيه يحاول تاني وتالت",rationale:"قالها بنفسه: Prefiero decírselo claro ahora = أفضّل أقولهالك بوضوح دلوقتي. اللأ الغامضة بتفتح باب للمفاوضة المستمرة."}],responseTask:{prompt:"عميل طالب خصم مش موجود. قول لأ بالإسباني مع سبب وبديل واقعي.",acceptable:["Ese descuento no puedo aplicarlo, lo siento. Lo que sí puedo hacer es revisar si tiene una oferta activa.","Lo siento, ese descuento no existe para este servicio. Puedo revisar qué ofertas tiene.","No puedo aplicar ese descuento. Lo que sí puedo hacer es revisar las ofertas que tiene.","Lo siento. Ese descuento no existe en el sistema. Miro qué oferta activa tiene."],modelEs:"Ese descuento no puedo aplicarlo, lo siento. Lo que sí puedo hacer es revisar si tiene una oferta activa.",modelAr:"الخصم ده مش أقدر أطبقه، أنا آسف. اللي أقدر أعمله فعلًا إني أراجع لو عند حضرتك عرض شغال.",checklistAr:"راجع إجابتك: ١) لأ واضحة (no puedo / no existe)، ٢) سبب حقيقي قصير، ٣) بديل في صلاحيتك (revisar ofertas). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"descuento = خصم. aplicar = يطبّق/يفعّل. oferta activa = عرض شغال. algo es algo = حاجة أحسن من لأ."}},{id:"cc-u07l06",courseId:"call-center",unitId:"cc-u07",sourceLessonId:null,level:"B1",register:"usted",title:"مكالمة صعبة من الأول للآخر",context:"مكالمة كاملة: عميل متضايق من غلطة متكررة، بيطلب تعويض مش في صلاحيتك. دورك: تعتذر، ترفض الوعد الكاذب، تعرض اللي في إيدك، وتسجّل اللي العميل طلبه. الدرس ده بيجمع الوحدة كلها.",goal:"بعد الدرس ده حتقدر تدير مكالمة صعبة كاملة: اعتذار + حدود صادقة + بديل واقعي + تسجيل، من غير ما المكالمة تتفجر.",targets:[{es:"Siento mucho que le pase otra vez.",ar:"متأسفة جدًا إن ده بيحصل مع حضرتك تاني.",speaker:"luna"},{es:"Esa compensación no está en mi mano.",ar:"التعويض ده مش في إيدي.",speaker:"luna"},{es:"Puedo registrar su petición y que la vea el equipo correspondiente.",ar:"أقدر أسجّل طلب حضرتك والفريق المختص يشوفه.",speaker:"luna"},{es:"Le dejo la referencia por escrito.",ar:"حسيب لحضرتك رقم المرجع مكتوب.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¡Otra vez lo mismo! ¡Es la segunda vez en un mes!",ar:"تاني نفس المشكلة! دي تاني مرة في الشهر!"},{speaker:"luna",es:"Siento mucho que le pase otra vez. Tiene toda la razón para estar enfadado.",ar:"متأسفة جدًا إن ده بيحصل مع حضرتك تاني. مع حضرتك كل الحق تكون متضايق."},{speaker:"paco",es:"Quiero una compensación. Un mes gratis, por lo menos.",ar:"عايز تعويض. شهر ببلاش، على الأقل."},{speaker:"luna",es:"Le entiendo. Esa compensación no está en mi mano. No quiero prometerle algo que no puedo cumplir.",ar:"فاهمة حضرتك. التعويض ده مش في إيدي. مش عايزة أوعدك بحاجة مش أقدر أنفذها."},{speaker:"paco",es:"¿Entonces nada?",ar:"يبقى ولا حاجة؟"},{speaker:"luna",es:"Puedo registrar su petición y que la vea el equipo correspondiente. Y reviso ahora mismo por qué se repite el problema.",ar:"أقدر أسجّل طلب حضرتك والفريق المختص يشوفه. وحراجع دلوقتي حالًا ليه المشكلة بتتكرر."},{speaker:"paco",es:"Vale. Pero que quede constancia.",ar:"تمام. بس عايز الموضوع يتسجل."},{speaker:"luna",es:"Queda registrado. Le dejo la referencia por escrito.",ar:"اتسجل. حسيب لحضرتك رقم المرجع مكتوب."}],questions:[{q:"الموظفة تعاملت إزاي مع غضب العميل في البداية؟",options:["اعتذرت واعترفت بحقه","قالتله اهدى","دافعت عن الشركة","حوّلته"],answer:"اعتذرت واعترفت بحقه",rationale:"قالت: Siento mucho que le pase otra vez. Tiene toda la razón para estar enfadado. enfadado = متضايق/زعلان."},{q:"ليه رفضت توعد بالشهر المجاني؟",options:["عشان مش عايزاه يستفيد","عشان مفيش تعويضات أصلًا","عشان العميل مش محتاجه","عشان مش في صلاحيتها ومش عايزة توعد بحاجة مش حتنفذها"],answer:"عشان مش في صلاحيتها ومش عايزة توعد بحاجة مش حتنفذها",rationale:"قالت: Esa compensación no está en mi mano. No quiero prometerle algo que no puedo cumplir. en mi mano = في إيدي."},{q:"إيه اللي العميل خرج بيه من المكالمة؟",options:["شهر مجاني","خصم فوري","ولا حاجة","طلبه اتسجل للفريق المختص + رقم مرجع مكتوب + مراجعة سبب التكرار"],answer:"طلبه اتسجل للفريق المختص + رقم مرجع مكتوب + مراجعة سبب التكرار",rationale:"قالت: Puedo registrar su petición… y reviso ahora mismo por qué se repite… Le dejo la referencia por escrito. quede constancia = الموضوع يتسجل رسميًا."}],responseTask:{prompt:"عميل متضايق من مشكلة متكررة وبيطلب تعويض مش في صلاحيتك. لخّص ردك بالإسباني: اعتذار + حدود + تسجيل الطلب للفريق المختص.",acceptable:["Siento mucho que le pase otra vez. Esa compensación no está en mi mano, pero puedo registrar su petición.","Siento mucho que le pase otra vez. No puedo prometer esa compensación. Puedo registrar su petición y darle seguimiento.","Tiene razón. Esa compensación no está en mi mano. Registro su petición ahora y le dejo la referencia.","Lo siento mucho. La compensación no la decido yo, pero registro su petición ahora mismo."],modelEs:"Siento mucho que le pase otra vez. Esa compensación no está en mi mano, pero puedo registrar su petición.",modelAr:"متأسفة جدًا إن ده بيحصل مع حضرتك تاني. التعويض ده مش في إيدي، بس أقدر أسجّل طلب حضرتك.",checklistAr:"راجع إجابتك: ١) اعتذار عن التكرار، ٢) حد صادق (no está en mi mano)، ٣) تسجيل الطلب أو متابعة، ٤) مفيش وعد كاذب. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"que le pase otra vez = إن ده يحصل مع حضرتك تاني (subjuntivo بعد siento). compensación = تعويض. que quede constancia = الموضوع يتسجل رسميًا. por lo menos = على الأقل."}}]},{courseId:"call-center",unit:{id:"cc-u08",title:"تلخيص وقفلة المكالمة",desc:"تلخّص اللي اتحل واللي لسه مفتوح بصدق، تتأكد إن العميل مش محتاج حاجة تانية، وتقفل بوداع مهني دافي.",cefr:"B1"},lessons:[{id:"cc-u08l01",courseId:"call-center",unitId:"cc-u08",sourceLessonId:"cc-u08l01",level:"B1",register:"usted",title:"لخّص بصدق",context:"في آخر المكالمة، دورك: تلخّص اللي اتحل فعلًا واللي لسه مفتوح، من غير ادعاء إن كل حاجة خلصت. التلخيص الصادق بيمنع مكالمات تكرار.",goal:"بعد الدرس ده حتقدر تلخّص نهاية مكالمة ببندين: اتعمل إيه + إيه اللي لسه مفتوح ومين حيعمله.",targets:[{es:"Le resumo lo que hemos hecho.",ar:"حلخّص لحضرتك اللي عملناه.",speaker:"luna"},{es:"Eso ya está resuelto.",ar:"ده اتحل خلاص.",speaker:"luna"},{es:"Esto queda pendiente.",ar:"ده لسه مفتوح.",speaker:"luna"},{es:"¿Le queda claro así?",ar:"كده واضح لحضرتك؟",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Bueno, ¿y entonces qué?",ar:"طيب، وإيه يعني؟"},{speaker:"luna",es:"Le resumo lo que hemos hecho. Cambiamos la contraseña y activamos el aviso por correo. Eso ya está resuelto.",ar:"حلخّص لحضرتك اللي عملناه. غيّرنا كلمة السر وفعّلنا التنبيه على الإيميل. ده اتحل خلاص."},{speaker:"paco",es:"¿Y el cargo raro?",ar:"والخصم الغريب؟"},{speaker:"luna",es:"Esto queda pendiente. Lo revisa el departamento de facturación y le contestan en este correo.",ar:"ده لسه مفتوح. قسم الفواتير حيراجعه وحيردّوا على حضرتك على الإيميل ده."},{speaker:"paco",es:"¿Cuándo?",ar:"إمتى؟"},{speaker:"luna",es:"No le puedo prometer un día concreto. Tiene la referencia para seguirlo.",ar:"مش أقدر أوعدك بيوم محدد. مع حضرتك رقم المرجع تتابع بيه."},{speaker:"paco",es:"Vale.",ar:"تمام."},{speaker:"luna",es:"¿Le queda claro así?",ar:"كده واضح لحضرتك؟"}],questions:[{q:"التلخيص اتقسم لإيه؟",options:["اللي اتحل + اللي لسه مفتوح ومين مسؤول عنه","المشاكل القديمة بس","وعود بالمستقبل","اللي العميل عمله غلط"],answer:"اللي اتحل + اللي لسه مفتوح ومين مسؤول عنه",rationale:"قالت: Eso ya está resuelto… Esto queda pendiente. Lo revisa el departamento de facturación. resuelto = اتحل، pendiente = لسه مفتوح."},{q:"لما العميل سأل عن الموعد، الموظفة عملت إيه؟",options:["وعدته بكرة","قالتله مش حتوعد بيوم محدد وأدته رقم مرجع للمتابعة","تجاهلت السؤال","قالتله استنى على الخط"],answer:"قالتله مش حتوعد بيوم محدد وأدته رقم مرجع للمتابعة",rationale:"قالت: No le puedo prometer un día concreto. Tiene la referencia para seguirlo. concreto = محدد."},{q:"ليه التلخيص الصادق مهم في آخر المكالمة؟",options:["عشان المكالمة تطول","عشان العميل يعرف بالظبط إيه اللي اتعمل وإيه اللي مستنيه، فميتصلش تاني بنفس السؤال","مش مهم","عشان التسجيل"],answer:"عشان العميل يعرف بالظبط إيه اللي اتعمل وإيه اللي مستنيه، فميتصلش تاني بنفس السؤال",rationale:"أغلب مكالمات التكرار سببها إن العميل مش عارف حالة طلبه. التلخيص الواضح بيقفل الباب ده."}],responseTask:{prompt:"اقفل مكالمة بتلخيص صادق بالإسباني: حاجة اتحلّت + حاجة لسه مفتوحة عند قسم تاني + رقم مرجع.",acceptable:["Le resumo lo que hemos hecho. Eso ya está resuelto. Esto queda pendiente y lo revisa el otro departamento. Tiene la referencia.","Le resumo: esto ya está resuelto, y esto queda pendiente con el otro departamento. Le doy la referencia.","Resumen: esta parte ya está resuelta. Esta otra queda pendiente y la revisan. Aquí tiene la referencia.","Eso ya está resuelto. Esto queda pendiente, lo revisa facturación, y tiene la referencia para seguirlo."],modelEs:"Le resumo lo que hemos hecho. Eso ya está resuelto. Esto queda pendiente y lo revisa el otro departamento. Tiene la referencia.",modelAr:"حلخّص لحضرتك اللي عملناه. ده اتحل خلاص. ده لسه مفتوح والقسم التاني حيراجعه. مع حضرتك رقم المرجع.",checklistAr:"راجع إجابتك: ١) بند اتحل (resuelto)، ٢) بند لسه مفتوح (pendiente) + مين حيعمله، ٣) رقم مرجع أو طريقة متابعة، ٤) مفيش ادعاء نجاح كامل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"resumir = يلخّص. resuelto = اتحل. pendiente = لسه مفتوح/معلّق. ¿Le queda claro? = كده واضح لحضرتك؟"}},{id:"cc-u08l02",courseId:"call-center",unitId:"cc-u08",sourceLessonId:"cc-u08l02",level:"B1",register:"usted",title:"محتاج حاجة تانية؟",context:"قبل ما تقفل، دورك: تتأكد إن العميلة مش محتاجة حاجة تانية، وتودعها بأدب من غير ما تستعجلها.",goal:"بعد الدرس ده حتقدر تقفل المكالمة بسؤال الاحتياج الأخير والوداع المهني.",targets:[{es:"¿Le puedo ayudar en algo más?",ar:"أقدر أساعد حضرتك في حاجة تانية؟",speaker:"paco"},{es:"No, eso es todo, gracias.",ar:"لأ، ده كل حاجة، شكرًا.",speaker:"luna"},{es:"Gracias por su llamada.",ar:"شكرًا لمكالمة حضرتك.",speaker:"paco"},{es:"Que tenga buena tarde.",ar:"مساءك سعيد.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Perfecto. ¿Le puedo ayudar en algo más?",ar:"جميل. أقدر أساعد حضرتك في حاجة تانية؟"},{speaker:"luna",es:"No, eso es todo, gracias.",ar:"لأ، ده كل حاجة، شكرًا."},{speaker:"paco",es:"Muy bien. Gracias por su llamada.",ar:"تمام جدًا. شكرًا لمكالمة حضرتك."},{speaker:"luna",es:"Gracias a usted por la ayuda.",ar:"وشكرًا لحضرتك على المساعدة."},{speaker:"paco",es:"Que tenga buena tarde.",ar:"مساءك سعيد."},{speaker:"luna",es:"Igualmente. Adiós.",ar:"وحضرتك كمان. مع السلامة."}],questions:[{q:"إيه آخر سؤال سأله الموظف قبل الوداع؟",options:["عايز تشترك في عرض؟","أقدر أساعد حضرتك في حاجة تانية؟","عندك شكوى؟","رقمك إيه؟"],answer:"أقدر أساعد حضرتك في حاجة تانية؟",rationale:"قال: ¿Le puedo ayudar en algo más? — سؤال الاحتياج الأخير بيمنع مكالمة تانية بعد دقيقة من القفلة."},{q:"العميلة ردّت إزاي؟",options:["طلبت خدمة جديدة","قالت ده كل حاجة وشكرت","اشتكت من الانتظار","قفلت من غير سلام"],answer:"قالت ده كل حاجة وشكرت",rationale:"قالت: No, eso es todo, gracias = لأ، ده كل حاجة، شكرًا. eso es todo = ده كل حاجة."},{q:"ليه منستعجلش العميل في القفلة؟",options:["عشان آخر انطباع هو اللي بيفتكره العميل عن الخدمة كلها","عشان الوقت مش مهم","عشان النظام بطيء","عشان نسجل أكتر"],answer:"عشان آخر انطباع هو اللي بيفتكره العميل عن الخدمة كلها",rationale:"القفلة المستعجلة بتهد أي شغل كويس اتعمل في المكالمة. سؤال أخير + وداع هادئ = قفلة محترمة."}],responseTask:{prompt:"اقفل المكالمة بالإسباني: سؤال الاحتياج الأخير + شكر على المكالمة + تمني طيب.",acceptable:["¿Le puedo ayudar en algo más? …Gracias por su llamada. Que tenga buena tarde.","¿Necesita algo más? …Gracias por su llamada. Que tenga buen día.","¿Le ayudo en algo más? …Gracias por llamar. Que tenga buena tarde.","¿Algo más en lo que pueda ayudarle? …Gracias por su llamada. Que tenga buena tarde."],modelEs:"¿Le puedo ayudar en algo más? …Gracias por su llamada. Que tenga buena tarde.",modelAr:"أقدر أساعد حضرتك في حاجة تانية؟ …شكرًا لمكالمة حضرتك. مساءك سعيد.",checklistAr:"راجع إجابتك: ١) سؤال احتياج أخير (¿…algo más?)، ٢) شكر على المكالمة، ٣) تمني طيب (Que tenga…)، ٤) مفيش استعجال. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"eso es todo = ده كل حاجة. Gracias por su llamada = شكرًا لمكالمة حضرتك. Que tenga buena tarde = مساءك سعيد (صيغة حضرتك). Igualmente = وحضرتك كمان."}},{id:"cc-u08l03",courseId:"call-center",unitId:"cc-u08",sourceLessonId:"cc-u08l03",level:"B1",register:"usted",title:"المتابعة بعد المكالمة",context:"في السيناريو ده، الشركة بتبعت ملخص بالإيميل وبتخلي العميل يتابع حالته من التطبيق. دورك: تشرح طرق المتابعة المتاحة هنا، من غير ما تعمّمها على أي شركة تانية.",goal:"بعد الدرس ده حتقدر تشرح خطوات المتابعة بعد المكالمة: إيميل ملخص + متابعة من التطبيق + رقم مرجع لو احتاج يكلمنا تاني.",targets:[{es:"Le llega un correo con el resumen de la llamada.",ar:"حيوصلك إيميل بملخص المكالمة.",speaker:"luna"},{es:"Puede seguir su caso desde la aplicación.",ar:"تقدر تتابع حالة حضرتك من التطبيق.",speaker:"luna"},{es:"Si nos llama otra vez, tenga a mano la referencia.",ar:"لو اتصلت بينا تاني، خلّي رقم المرجع قدامك.",speaker:"luna"},{es:"Así no tiene que repetirlo todo.",ar:"كده مش حتضطر تعيد كل حاجة.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Y cómo sé lo que pasa con mi caso después?",ar:"وأعرف إزاي بيحصل إيه في حالتي بعد كده؟"},{speaker:"luna",es:"Le llega un correo con el resumen de la llamada. Ahí tiene los pasos y la referencia.",ar:"حيوصلك إيميل بملخص المكالمة. فيه الخطوات ورقم المرجع."},{speaker:"paco",es:"¿Y si quiero mirarlo yo?",ar:"ولو عايز أبص بنفسي؟"},{speaker:"luna",es:"Puede seguir su caso desde la aplicación. Entra con su correo y lo ve al momento.",ar:"تقدر تتابع حالة حضرتك من التطبيق. تدخل بإيميلك وتشوفها أول بأول."},{speaker:"paco",es:"¿Y si hay algún problema?",ar:"ولو حصلت مشكلة؟"},{speaker:"luna",es:"Si nos llama otra vez, tenga a mano la referencia. Así no tiene que repetirlo todo.",ar:"لو اتصلت بينا تاني، خلّي رقم المرجع قدامك. كده مش حتضطر تعيد كل حاجة."},{speaker:"paco",es:"Perfecto, gracias.",ar:"جميل، شكرًا."}],questions:[{q:"العميل حيعرف أخبار حالته منين؟",options:["إيميل بالملخص + متابعة من التطبيق","رسالة صباحية يوميًا","مكالمة كل ساعة","مفيش طريقة"],answer:"إيميل بالملخص + متابعة من التطبيق",rationale:"قالت: Le llega un correo con el resumen… Puede seguir su caso desde la aplicación. seguir = يتابع."},{q:"ليه قالتله يخلي رقم المرجع قدامه لو اتصل تاني؟",options:["عشان ميضطرش يعيد حكاية كل حاجة من الأول","عشان الموظف يعرف مرتبه","عشان النظام مش بيحفظ","مفيش سبب"],answer:"عشان ميضطرش يعيد حكاية كل حاجة من الأول",rationale:"قالت: Así no tiene que repetirlo todo = كده مش حتضطر تعيد كل حاجة. a mano = قدامك/في المتناول."},{q:"في السيناريو ده، طرق المتابعة دي…",options:["موجودة في كل شركات العالم","مستحيلة","جزء من الخدمة عند الشركة دي تحديدًا، مش قاعدة عامة","للعملاء المميزين بس"],answer:"جزء من الخدمة عند الشركة دي تحديدًا، مش قاعدة عامة",rationale:"كل شركة ليها أدوات متابعة مختلفة. اللي بيتقال هنا بيوصف السيناريو ده بس."}],responseTask:{prompt:"اشرح للعميل بالإسباني طرق المتابعة بعد المكالمة: إيميل ملخص + التطبيق + رقم المرجع.",acceptable:["Le llega un correo con el resumen de la llamada. Puede seguir su caso desde la aplicación. Si nos llama otra vez, tenga a mano la referencia.","Le llega un correo con el resumen. También puede seguir su caso desde la aplicación. Tenga a mano la referencia si llama.","Le llega un correo con el resumen de la llamada, y puede seguir su caso desde la aplicación. Guarde la referencia.","Recibirá un correo con el resumen. Puede seguir el caso desde la aplicación con la referencia."],modelEs:"Le llega un correo con el resumen de la llamada. Puede seguir su caso desde la aplicación. Si nos llama otra vez, tenga a mano la referencia.",modelAr:"حيوصلك إيميل بملخص المكالمة. تقدر تتابع حالة حضرتك من التطبيق. لو اتصلت بينا تاني، خلّي رقم المرجع قدامك.",checklistAr:"راجع إجابتك: ١) إيميل الملخص، ٢) المتابعة من التطبيق، ٣) رقم المرجع عند الاتصال التاني، ٤) مفيش وعد بميزة مش موجودة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"seguir = يتابع. tenga a mano = خلّيه قدامك/في المتناول (صيغة حضرتك). guarde = احفظ. en el momento = أول بأول."}},{id:"cc-u08l04",courseId:"call-center",unitId:"cc-u08",sourceLessonId:null,level:"B1",register:"usted",title:"قفلة من غير حل كامل",context:"المشكلة مش اتحلّت النهارده: محتاجة مراجعة من قسم تاني. دورك: تقفل المكالمة بشكل يحافظ على ثقة العميلة: اللي اتعمل، اللي حيحصل بعدين، وإزاي تتابع.",goal:"بعد الدرس ده حتقدر تقفل مكالمة مفتوحة من غير ما العميل يحس إنه اتنسي أو اترمي.",targets:[{es:"Hoy no hemos podido resolverlo del todo.",ar:"النهارده مقدرناش نحلها بالكامل.",speaker:"paco"},{es:"Su caso queda abierto con el departamento técnico.",ar:"حالة حضرتك حتفضل مفتوحة مع القسم الفني.",speaker:"paco"},{es:"No tiene que empezar de cero si vuelve a llamar.",ar:"مش حتضطري تبدئي من الصفر لو اتصلتي تاني.",speaker:"paco"},{es:"Todo lo que hablamos queda apuntado.",ar:"كل اللي اتكلمنا فيه اتسجل.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Entonces se arregló o no?",ar:"يبقى اتحلّت ولا لأ؟"},{speaker:"paco",es:"Le soy sincero. Hoy no hemos podido resolverlo del todo.",ar:"حأكون صريح مع حضرتك. النهارده مقدرناش نحلها بالكامل."},{speaker:"luna",es:"Uf. ¿Y ahora qué?",ar:"أوف. ودلوقتي إيه؟"},{speaker:"paco",es:"Su caso queda abierto con el departamento técnico. Ellos prueban la línea y le avisan por correo.",ar:"حالة حضرتك حتفضل مفتوحة مع القسم الفني. هم حيجرّبوا الخط وحيقولولك النتيجة على الإيميل."},{speaker:"luna",es:"¿Y tengo que explicarlo todo otra vez?",ar:"ولازم أحكي كل حاجة من الأول تاني؟"},{speaker:"paco",es:"No. Todo lo que hablamos queda apuntado. No tiene que empezar de cero si vuelve a llamar.",ar:"لأ. كل اللي اتكلمنا فيه اتسجل. مش حتضطري تبدئي من الصفر لو اتصلتي تاني."},{speaker:"luna",es:"Vale, eso me quita un peso.",ar:"تمام، ده طمّنّي شوية."},{speaker:"paco",es:"Gracias por su paciencia. Le llega el resumen por correo.",ar:"شكرًا على صبر حضرتك. حيوصلك الملخص على الإيميل."}],questions:[{q:"الموظف قال الحقيقة عن حالة المشكلة إزاي؟",options:["ادعى إنها اتحلّت","غيّر الموضوع","قال بصراحة إنها منحلّتش بالكامل ووضح الخطوة الجاية","لوم العميلة"],answer:"قال بصراحة إنها منحلّتش بالكامل ووضح الخطوة الجاية",rationale:"قال: Hoy no hemos podido resolverlo del todo… Su caso queda abierto con el departamento técnico. del todo = بالكامل."},{q:"العميلة كانت خايفة من إيه؟",options:["إنها تدفع أكتر","إن المكالمة تتسجل","إنها تحكي كل حاجة من الأول لو اتصلت تاني","إن الخط يفصل"],answer:"إنها تحكي كل حاجة من الأول لو اتصلت تاني",rationale:"سألت: ¿Y tengo que explicarlo todo otra vez? — ورد الموظف: Todo lo que hablamos queda apuntado. de cero = من الصفر."},{q:"إيه عناصر القفلة الصح لمكالمة مفتوحة؟",options:["صدق عن الوضع + خطوة جاية واضحة + طمأنة إن الشغل متسجل + طريقة متابعة","وعد بكرة","قفلة سريعة","تحويل للمدير"],answer:"صدق عن الوضع + خطوة جاية واضحة + طمأنة إن الشغل متسجل + طريقة متابعة",rationale:"القفلة المفتوحة الصح بتسيب العميل عارف: إيه الوضع، مين شغال عليه، وإزاي يتابع."}],responseTask:{prompt:"اقفل مكالمة منحلّتش بالكامل بالإسباني: صدق + الحالة مفتوحة مع القسم المختص + طمأنة إن كل حاجة متسجلة.",acceptable:["Hoy no hemos podido resolverlo del todo. Su caso queda abierto con el departamento técnico. Todo lo que hablamos queda apuntado.","Le soy sincero: no lo hemos resuelto del todo. Queda abierto con el departamento técnico y todo queda apuntado.","No hemos podido resolverlo del todo hoy. Su caso queda abierto y todo lo que hablamos queda apuntado.","Hoy no se resolvió del todo. Queda abierto con el técnico. No tiene que empezar de cero: todo queda apuntado."],modelEs:"Hoy no hemos podido resolverlo del todo. Su caso queda abierto con el departamento técnico. Todo lo que hablamos queda apuntado.",modelAr:"النهارده مقدرناش نحلها بالكامل. حالة حضرتك حتفضل مفتوحة مع القسم الفني. كل اللي اتكلمنا فيه اتسجل.",checklistAr:"راجع إجابتك: ١) صدق (no…del todo)، ٢) الحالة مفتوحة + مين شغال عليها، ٣) طمأنة التسجيل (queda apuntado)، ٤) مفيش ادعاء حل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"del todo = بالكامل. queda abierto = حتفضل مفتوحة. queda apuntado = اتسجل. eso me quita un peso = ده طمّنّي (شال عني هم)."}},{id:"cc-u08l05",courseId:"call-center",unitId:"cc-u08",sourceLessonId:null,level:"B1",register:"usted",title:"وداع دافي من غير ضغط",context:"آخر لحظة في المكالمة. دورك: تسيب الباب مفتوح للعميل يرجع لو احتاج، وتودّع بشكل إنساني، من غير ما تبيعه حاجة ولا تضغط عليه.",goal:"بعد الدرس ده حتقدر تقفل بوداع مهني دافي: دعوة للرجوع + شكر + تمني طيب، من غير أي بيع إجباري.",targets:[{es:"Si le surge cualquier cosa, aquí estamos.",ar:"لو ظهر لحضرتك أي حاجة، إحنا هنا.",speaker:"luna"},{es:"Puede llamarnos cuando quiera.",ar:"ممكن تتصل بينا في أي وقت.",speaker:"luna"},{es:"Gracias por su tiempo hoy.",ar:"شكرًا على وقت حضرتك النهارده.",speaker:"luna"},{es:"Que descanse.",ar:"تتريح بقى / أمسية هادية.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Bueno, ya está todo claro.",ar:"طيب، كل حاجة بقت واضحة."},{speaker:"luna",es:"Me alegro. Si le surge cualquier cosa, aquí estamos.",ar:"حلو. لو ظهر لحضرتك أي حاجة، إحنا هنا."},{speaker:"paco",es:"¿Puedo llamar a esta misma línea?",ar:"أقدر أتصل على نفس الخط ده؟"},{speaker:"luna",es:"Sí, claro. Puede llamarnos cuando quiera. Con la referencia le atienden enseguida.",ar:"أيوه طبعًا. ممكن تتصل بينا في أي وقت. برقم المرجع حيردوا عليك بسرعة."},{speaker:"paco",es:"Muy amable.",ar:"لطيفة منك."},{speaker:"luna",es:"Gracias por su tiempo hoy. Que descanse.",ar:"شكرًا على وقت حضرتك النهارده. أمسية هادية."},{speaker:"paco",es:"Gracias, igualmente.",ar:"شكرًا، وحضرتك كمان."}],questions:[{q:"إزاي الموظفة سابت الباب مفتوح للعميل؟",options:["قالتله متتصلش تاني","قالتله ابعت إيميل بس","قالتله أي حاجة تظهر، إحنا هنا واتصل في أي وقت","مقالتش حاجة"],answer:"قالتله أي حاجة تظهر، إحنا هنا واتصل في أي وقت",rationale:"قالت: Si le surge cualquier cosa, aquí estamos. Puede llamarnos cuando quiera. surgir = يظهر/يحصل."},{q:"قالتله يجهز إيه عشان الرد يكون أسرع؟",options:["رقم كارته","عنوانه","كلمة السر","رقم المرجع"],answer:"رقم المرجع",rationale:"قالت: Con la referencia le atienden enseguida = برقم المرجع حيردوا عليك بسرعة. enseguida = بسرعة/حالًا."},{q:"ليه الوداع مبيعش حاجة ولا بيضغط؟",options:["عشان الشركة مش عايزة مبيعات","مش مهم","عشان الوقت خلص","عشان آخر انطباع مكانش فيه مصلحة، فالعميل يفكر يرجع بمزاجه"],answer:"عشان آخر انطباع مكانش فيه مصلحة، فالعميل يفكر يرجع بمزاجه",rationale:"البيع في لحظة الوداع بيحسّس العميل إن المكالمة كلها كانت لهدف تاني. الدفا من غير مصلحة هو اللي بيبني الولاء."}],responseTask:{prompt:"اقفل بوداع دافي بالإسباني: الباب مفتوح + شكر على الوقت + تمني طيب.",acceptable:["Si le surge cualquier cosa, aquí estamos. Gracias por su tiempo hoy. Que descanse.","Puede llamarnos cuando quiera. Gracias por su tiempo. Que descanse.","Si le surge cualquier cosa, llámenos. Gracias por su tiempo hoy. Que tenga buena tarde.","Aquí estamos para lo que necesite. Gracias por su tiempo. Que descanse."],modelEs:"Si le surge cualquier cosa, aquí estamos. Gracias por su tiempo hoy. Que descanse.",modelAr:"لو ظهر لحضرتك أي حاجة، إحنا هنا. شكرًا على وقت حضرتك النهارده. أمسية هادية.",checklistAr:"راجع إجابتك: ١) الباب مفتوح (aquí estamos / cuando quiera)، ٢) شكر على الوقت، ٣) تمني طيب، ٤) مفيش بيع ولا ضغط. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"surgir = يظهر/يطرأ. cuando quiera = في أي وقت (صيغة حضرتك). Muy amable = لطيفة منك (ولو المخاطَب راجل: لطيف منك). Que descanse = أمسية هادية/تتريح (بتتقال في وداع آخر اليوم)."}},{id:"cc-u08l06",courseId:"call-center",unitId:"cc-u08",sourceLessonId:null,level:"B1",register:"usted",title:"من أول التلخيص لآخر السلام",context:"مكالمة كاملة في قفلتها: تلخيص صادق، سؤال الاحتياج الأخير، طرق المتابعة، ووداع دافي. الدرس ده بيجمع كل الوحدة في قفلة واحدة متقنة.",goal:"بعد الدرس ده حتقدر تقفل أي مكالمة خدمة عملاء قفلة كاملة: ملخص + تأكيد + متابعة + وداع.",targets:[{es:"Le resumo en dos líneas.",ar:"حلخّص لحضرتك في سطرين.",speaker:"paco"},{es:"¿Hay algo más en lo que le pueda ayudar?",ar:"في حاجة تانية أقدر أساعد حضرتك فيها؟",speaker:"paco"},{es:"Le llega el resumen por correo y puede seguirlo en la aplicación.",ar:"حيوصلك الملخص على الإيميل وتقدري تتابعيه من التطبيق.",speaker:"paco"},{es:"Ha sido un placer ayudarle.",ar:"تشرفت بمساعدة حضرتك.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Bueno, creo que ya estamos.",ar:"طيب، أظن خلصنا."},{speaker:"paco",es:"Casi. Le resumo en dos líneas. El envío sale hoy y el cargo duplicado está en revisión.",ar:"تقريبًا. حلخّص لحضرتك في سطرين. الشحنة حتطلع النهارده والخصم المكرر تحت المراجعة."},{speaker:"luna",es:"Vale.",ar:"تمام."},{speaker:"paco",es:"Le llega el resumen por correo y puede seguirlo en la aplicación. ¿Hay algo más en lo que le pueda ayudar?",ar:"حيوصلك الملخص على الإيميل وتقدري تتابعيه من التطبيق. في حاجة تانية أقدر أساعد حضرتك فيها؟"},{speaker:"luna",es:"No, nada más.",ar:"لأ، مفيش حاجة تانية."},{speaker:"paco",es:"Perfecto. Si le surge cualquier cosa, llámenos con la referencia.",ar:"جميل. لو ظهر لحضرتك أي حاجة، اتصلي بينا برقم المرجع."},{speaker:"luna",es:"Así lo haré. Gracias.",ar:"حعمل كده. شكرًا."},{speaker:"paco",es:"Ha sido un placer ayudarle. Que tenga buena tarde.",ar:"تشرفت بمساعدة حضرتك. مساءك سعيد."}],questions:[{q:"الملخص جه في قالب إيه؟",options:["تفاصيل طويلة","أرقام بس","مفيش ملخص","سطرين: اللي حيحصل واللي تحت المراجعة"],answer:"سطرين: اللي حيحصل واللي تحت المراجعة",rationale:"قال: Le resumo en dos líneas. El envío sale hoy y el cargo duplicado está en revisión. en revisión = تحت المراجعة."},{q:"ترتيب القفلة الصح كان إيه؟",options:["وداع → ملخص → سؤال","بيع → ملخص","سؤال → قفل فوري","ملخص → متابعة → سؤال احتياج أخير → وداع"],answer:"ملخص → متابعة → سؤال احتياج أخير → وداع",rationale:"التسلسل في الحوار: ملخص، طرق متابعة، ¿Hay algo más…?، وبعدين الدعوة بالمرجع والوداع."},{q:"«Ha sido un placer ayudarle» بتتقال إمتى؟",options:["أول المكالمة","في قلب المشكلة","في الوداع كعبارة ختامية دافية","لما العميل يغلط"],answer:"في الوداع كعبارة ختامية دافية",rationale:"عبارة ختامية مهنية دافية: تشرفت بمساعدة حضرتك. مكانها الطبيعي آخر سطر قبل مع السلامة."}],responseTask:{prompt:"اقفل مكالمة كاملة بالإسباني: ملخص سطرين + سؤال احتياج أخير + متابعة + وداع دافي.",acceptable:["Le resumo en dos líneas: el envío sale hoy y el cargo duplicado está en revisión. ¿Hay algo más en lo que le pueda ayudar? Le llega el resumen por correo. Que tenga buena tarde.","Le resumo: el envío sale hoy y el cargo está en revisión. Puede seguirlo en la aplicación. ¿Algo más? Que tenga buena tarde.","Resumen: esto resuelto, esto en revisión. Le llega el correo y puede seguirlo en la aplicación. ¿Le ayudo en algo más? Ha sido un placer.","Le resumo en dos líneas. ¿Hay algo más en lo que le pueda ayudar? Si le surge cualquier cosa, llámenos con la referencia. Que tenga buena tarde."],modelEs:"Le resumo en dos líneas: el envío sale hoy y el cargo duplicado está en revisión. ¿Hay algo más en lo que le pueda ayudar? Le llega el resumen por correo. Que tenga buena tarde.",modelAr:"حلخّص لحضرتك في سطرين: الشحنة حتطلع النهارده والخصم المكرر تحت المراجعة. في حاجة تانية أقدر أساعد حضرتك فيها؟ حيوصلك الملخص على الإيميل. مساءك سعيد.",checklistAr:"راجع إجابتك: ١) ملخص قصير ببندين، ٢) سؤال احتياج أخير، ٣) طريقة متابعة (correo / aplicación / referencia)، ٤) وداع دافي. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"en dos líneas = في سطرين. en revisión = تحت المراجعة. Ha sido un placer ayudarle = تشرفت بمساعدة حضرتك. Así lo haré = حعمل كده."}}]},{courseId:"tourism-work",unit:{id:"tw-u01",title:"الترحيب بالضيوف",desc:"ترحّب بالضيف، تتفاهم على لغة الكلام، تطلب التوضيح من غير إحراج، وتستقبل أول طلب.",cefr:"A2"},lessons:[{id:"tw-u01l01",courseId:"tourism-work",unitId:"tw-u01",sourceLessonId:"tw-u01l01",level:"A2",register:"usted",title:"أهلًا بحضرتك",context:"ضيف وصل للاستقبال. دورك: ترحّب بيه بجمل قصيرة وتفتح الكلام بسؤال بسيط عن اللي محتاجه.",goal:"بعد الدرس ده حتقدر ترحّب بأي ضيف بجمل إسبانية قصيرة وواضحة وتسأله محتاج إيه.",targets:[{es:"Bienvenido al hotel.",ar:"أهلًا بحضرتك في الفندق.",speaker:"luna"},{es:"¿En qué puedo ayudarle?",ar:"أقدر أساعد حضرتك في إيه؟",speaker:"luna"},{es:"Tengo una reserva.",ar:"عندي حجز.",speaker:"paco"},{es:"Un momento, por favor.",ar:"لحظة واحدة، لو سمحت.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenas tardes. Bienvenido al hotel.",ar:"مساء الخير. أهلًا بحضرتك في الفندق."},{speaker:"paco",es:"Buenas tardes.",ar:"مساء الخير."},{speaker:"luna",es:"¿En qué puedo ayudarle?",ar:"أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola. Tengo una reserva.",ar:"أهلًا. عندي حجز."},{speaker:"luna",es:"Muy bien. Un momento, por favor.",ar:"تمام. لحظة واحدة، لو سمحت."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."}],questions:[{q:"الموظفة بدأت بإيه؟",options:["تحية وقت اليوم + ترحيب بالفندق","طلبت الباسبور فورًا","سألت عن الفلوس","قالتله استنى بس"],answer:"تحية وقت اليوم + ترحيب بالفندق",rationale:"قالت: Buenas tardes. Bienvenido al hotel. — bienvenido = أهلًا بحضرتك (لضيف راجل؛ لضيفة ست: bienvenida)."},{q:"الضيف قال إيه عشان يوضح سبب وقفته؟",options:["عايز منيو","عندي حجز","فقدت شنطتي","عايز تاكسي"],answer:"عندي حجز",rationale:"قال: Tengo una reserva = عندي حجز. reserva = حجز."},{q:"ليه قالت Un momento, por favor بدل ما تسكت وهي بتدور في النظام؟",options:["عشان الضيف يعرف إن في حد شغال على طلبه وميفتكرش إنه اتجاهل","عشان تريح","عشان تكلم زميلتها","مفيش سبب"],answer:"عشان الضيف يعرف إن في حد شغال على طلبه وميفتكرش إنه اتجاهل",rationale:"الجملة القصيرة دي بتحافظ على التواصل أثناء أي انتظار قصير."}],responseTask:{prompt:"ضيف واقف قدامك في الاستقبال. رحّب بيه بالإسباني واسأله محتاج إيه.",acceptable:["Buenas tardes. Bienvenido al hotel. ¿En qué puedo ayudarle?","Bienvenido al hotel. ¿En qué puedo ayudarle?","Buenos días. Bienvenido. ¿En qué puedo ayudarle?","Bienvenido al hotel. ¿Qué necesita?"],modelEs:"Buenas tardes. Bienvenido al hotel. ¿En qué puedo ayudarle?",modelAr:"مساء الخير. أهلًا بحضرتك في الفندق. أقدر أساعد حضرتك في إيه؟",checklistAr:"راجع إجابتك: ١) تحية مناسبة للوقت، ٢) ترحيب (Bienvenido)، ٣) سؤال عن الاحتياج بصيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"bienvenido = أهلًا بحضرتك (بتتظبط على حسب الضيف: bienvenido لراجل، bienvenida لست). reserva = حجز. Un momento, por favor = لحظة واحدة لو سمحت."}},{id:"tw-u01l02",courseId:"tourism-work",unitId:"tw-u01",sourceLessonId:"tw-u01l02",level:"A2",register:"usted",title:"اللغة المناسبة",context:"ضيف مش واضح إنه فاهم إسباني. دورك: تسأله عن اللغة اللي يفضّلها من غير ما تحرجه، وتكمّل باللغة المتفق عليها.",goal:"بعد الدرس ده حتقدر تسأل الضيف عن لغته المفضلة بأدب وتأكد إن التواصل ماشي صح.",targets:[{es:"¿Habla español?",ar:"بتتكلم إسباني؟",speaker:"luna"},{es:"¿Prefiere otro idioma?",ar:"تفضّل لغة تانية؟",speaker:"luna"},{es:"Un poco, pero mejor en inglés.",ar:"شوية، بس أحسن بالإنجليزي.",speaker:"paco"},{es:"Sin problema. Seguimos en inglés.",ar:"مفيش مشكلة. نكمل بالإنجليزي.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenas tardes. ¿En qué puedo ayudarle?",ar:"مساء الخير. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Erm… ¿Perdón?",ar:"آم… آسف؟"},{speaker:"luna",es:"¿Habla español? ¿Prefiere otro idioma?",ar:"بتتكلم إسباني؟ تفضّل لغة تانية؟"},{speaker:"paco",es:"Un poco, pero mejor en inglés.",ar:"شوية، بس أحسن بالإنجليزي."},{speaker:"luna",es:"Sin problema. Seguimos en inglés.",ar:"مفيش مشكلة. نكمل بالإنجليزي."},{speaker:"paco",es:"Gracias, muy amable.",ar:"شكرًا، لطيفة منك."}],questions:[{q:"إيه اللي خلّى الموظفة تسأل عن اللغة؟",options:["الضيف مردّش بوضوح وبدا مش فاهم","الضيف طلب مترجم","الضيف اتكلم بصوت عالي","عشان الفضول"],answer:"الضيف مردّش بوضوح وبدا مش فاهم",rationale:"الضيف قال ¿Perdón? — إشارة إنه مش لاحق. السؤال عن اللغة بيجهّز تواصل فعلي بدل التخمين."},{q:"الضيف فضّل إيه؟",options:["يكمل بالإسباني","يكمل بالإنجليزي","يكتب بس","يتكلم عربي"],answer:"يكمل بالإنجليزي",rationale:"قال: Un poco, pero mejor en inglés = شوية، بس أحسن بالإنجليزي. mejor = أحسن."},{q:"ليه السؤال عن اللغة المفضلة مش إهانة؟",options:["لأنه بيحترم وقت الضيف وبيمنع سوء فهم أسوأ بعدين","لأنه مطلوب قانونيًا","مفيش فرق","لأن الضيوف بيحبوه"],answer:"لأنه بيحترم وقت الضيف وبيمنع سوء فهم أسوأ بعدين",rationale:"أنك تسأل بدري أحسن بكتير من إنك تكمل بلغة الضيف مش فاهمها وتلخبط حجزه."}],responseTask:{prompt:"ضيف باين عليه مش فاهم إسباني كويس. اسأله بالإسباني عن اللغة اللي يفضّلها وطمّنه.",acceptable:["¿Habla español? ¿Prefiere otro idioma? Sin problema.","¿Prefiere otro idioma? Sin problema, seguimos como prefiera.","¿Habla español o prefiere otro idioma? Sin problema.","No se preocupe. ¿Prefiere otro idioma?"],modelEs:"¿Habla español? ¿Prefiere otro idioma? Sin problema.",modelAr:"بتتكلم إسباني؟ تفضّل لغة تانية؟ مفيش مشكلة.",checklistAr:"راجع إجابتك: ١) سؤال عن اللغة بصيغة حضرتك، ٢) طمأنة (Sin problema / No se preocupe)، ٣) مفيش تعليق مستخف بلغة الضيف. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Habla español? = بتتكلم إسباني؟ idioma = لغة. Sin problema = مفيش مشكلة. mejor = أحسن/يفضّل."}},{id:"tw-u01l03",courseId:"tourism-work",unitId:"tw-u01",sourceLessonId:"tw-u01l03",level:"A2",register:"usted",title:"نفهم بعض",context:"ضيفة بتتكلم بسرعة ومش فاهم طلبها. دورك: تطلب إعادة الكلام بأدب بدل ما تتظاهر إنك فاهم.",goal:"بعد الدرس ده حتقدر تطلب التوضيح والإعادة والكلام البطيء من غير ما تحسّس الضيف إنه غلطان.",targets:[{es:"Perdone, no le entendí bien.",ar:"لو سمحت، مش فاهم حضرتك كويس.",speaker:"paco"},{es:"¿Puede repetirlo, por favor?",ar:"ممكن تعيديها، لو سمحت؟",speaker:"paco"},{es:"Más despacio, por favor.",ar:"ببطء أكتر، لو سمحت.",speaker:"paco"},{es:"Ah, ahora sí. Gracias.",ar:"آه، دلوقتي فهمت. شكرًا.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"…y entonces quería preguntar si podemos dejar las maletas aquí antes de la entrada, porque llegamos temprano y…",ar:"…وكنت عايزة أسأل لو ممكن نسيب الشنط هنا قبل معاد الدخول، عشان إحنا واصلين بدري و…"},{speaker:"paco",es:"Perdone, no le entendí bien. ¿Puede repetirlo, por favor?",ar:"لو سمحت، مش فاهم حضرتك كويس. ممكن تعيديها، لو سمحت؟"},{speaker:"luna",es:"Claro. ¿Podemos dejar las maletas aquí?",ar:"طبعًا. ممكن نسيب الشنط هنا؟"},{speaker:"paco",es:"Más despacio, por favor.",ar:"ببطء أكتر، لو سمحت."},{speaker:"luna",es:"¿Dejar… las maletas… aquí?",ar:"نسيب… الشنط… هنا؟"},{speaker:"paco",es:"Ah, ahora sí. Gracias. Sí, puede dejarlas aquí conmigo.",ar:"آه، دلوقتي فهمت. شكرًا. أيوه، ممكن تسيبيها هنا معايا."}],questions:[{q:"الموظف عمل إيه لما مفهمهاش؟",options:["اتظاهر إنه فاهم","طلب الإعادة بأدب","نادى مديره","رد بالإنجليزي على طول"],answer:"طلب الإعادة بأدب",rationale:"قال: Perdone, no le entendí bien. ¿Puede repetirlo, por favor? — repetir = يعيد."},{q:"طلب منها تعمل إيه تاني حاجة؟",options:["تكتب الطلب","تتكلم ببطء أكتر","تتكلم بصوت أعلى","تترجم"],answer:"تتكلم ببطء أكتر",rationale:"قال: Más despacio, por favor = ببطء أكتر لو سمحت. despacio = ببطء."},{q:"ليه التظاهر بالفهم خطر في الشغل ده؟",options:["عشان ممكن تنفذ طلب غلط وتضيّع وقت الضيف والشغل يتوّل","مش خطر","عشان الضيف حيزعل","عشان الكاميرات"],answer:"عشان ممكن تنفذ طلب غلط وتضيّع وقت الضيف والشغل يتوّل",rationale:"لو اتظاهرت بالفهم ونفذت حاجة غلط، المشكلة بتتضاعف. طلب الإعادة مهنية مش ضعف."}],responseTask:{prompt:"ضيف بيتكلم بسرعة ومش فاهمه. اطلب منه بالإسباني يعيد وببطء، بأدب.",acceptable:["Perdone, no le entendí bien. ¿Puede repetirlo, por favor? Más despacio, por favor.","Perdone. ¿Puede repetirlo más despacio, por favor?","No le entendí bien. Más despacio, por favor.","Perdone, ¿lo repite más despacio, por favor?"],modelEs:"Perdone, no le entendí bien. ¿Puede repetirlo, por favor? Más despacio, por favor.",modelAr:"لو سمحت، مش فاهم حضرتك كويس. ممكن تعيدها، لو سمحت؟ ببطء أكتر، لو سمحت.",checklistAr:"راجع إجابتك: ١) اعتراف إنك مش فاهم (no le entendí)، ٢) طلب إعادة بأدب، ٣) طلب كلام أبطأ، ٤) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Perdone = لو سمحت/المعذرة (بصيغة حضرتك). repetir = يعيد. más despacio = ببطء أكتر. ahora sí = دلوقتي فهمت."}},{id:"tw-u01l04",courseId:"tourism-work",unitId:"tw-u01",sourceLessonId:null,level:"A2",register:"usted",title:"أول طلب للضيف",context:"بعد الترحيب، ضيفة عندها طلب سريع: عايزة مياه ومكان تسيب فيه شنطتها. دورك: تستقبل الطلب ببساطة، تؤكد فهمك، وتقول حتعمل إيه.",goal:"بعد الدرس ده حتقدر تستقبل طلبات الضيوف البسيطة الأولى وتأكدها بجملة واضحة.",targets:[{es:"¿Me trae un poco de agua, por favor?",ar:"ممكن تجيبلي شوية مياه، لو سمحت؟",speaker:"luna"},{es:"Claro, enseguida.",ar:"طبعًا، حالًا.",speaker:"paco"},{es:"¿Dónde puedo dejar la mochila?",ar:"أقدر أسيب الشنطة فين؟",speaker:"luna"},{es:"Se la guardo aquí detrás del mostrador.",ar:"ححفظهالك هنا ورا الكاونتر.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone. ¿Me trae un poco de agua, por favor?",ar:"لو سمحت. ممكن تجيبلي شوية مياه، لو سمحت؟"},{speaker:"paco",es:"Claro, enseguida.",ar:"طبعًا، حالًا."},{speaker:"luna",es:"Gracias. Y otra cosa. ¿Dónde puedo dejar la mochila?",ar:"شكرًا. وحاجة تانية. أقدر أسيب الشنطة فين؟"},{speaker:"paco",es:"Se la guardo aquí detrás del mostrador. ¿Le parece?",ar:"ححفظهالك هنا ورا الكاونتر. يناسبك كده؟"},{speaker:"luna",es:"Genial, gracias.",ar:"جميل، شكرًا."},{speaker:"paco",es:"De nada. Ahora le traigo el agua.",ar:"ولا يهمك. حأجيبلك المياه دلوقتي."}],questions:[{q:"أول طلب للضيفة كان إيه؟",options:["مفتاح الأوضة","مناديل","شوية مياه","واي فاي"],answer:"شوية مياه",rationale:"قالت: ¿Me trae un poco de agua, por favor? — traer = يجيب. enseguida = حالًا."},{q:"الموظف عرض يعمل إيه بالشنطة؟",options:["يرميها في أوضة بعيدة","يقولها تمسكها","يحفظها ورا الكاونتر","يديها لحد تاني"],answer:"يحفظها ورا الكاونتر",rationale:"قال: Se la guardo aquí detrás del mostrador. mostrador = كاونتر الاستقبال."},{q:"ليه الموظف أكّد كل طلب بجملة قصيرة؟",options:["عشان التدريب","عشان يطوّل الكلام","عشان الضيفة تتطمن إن طلبها اتفهم وحيتنفذ","مفيش سبب"],answer:"عشان الضيفة تتطمن إن طلبها اتفهم وحيتنفذ",rationale:"التأكيد القصير (Claro, enseguida) بيقفل حلقة الطلب: الضيف عارف إنك سامع وشغال."}],responseTask:{prompt:"ضيف طلب منك حاجة بسيطة. رد بالإسباني بتأكيد سريع إنك حتعملها حالًا.",acceptable:["Claro, enseguida.","Claro. Ahora mismo se lo traigo.","Por supuesto, enseguida.","Sí, claro. Un momento."],modelEs:"Claro, enseguida.",modelAr:"طبعًا، حالًا.",checklistAr:"راجع إجابتك: ١) قبول واضح (Claro / Por supuesto)، ٢) توقيت قريب (enseguida / ahora mismo)، ٣) مفيش تعقيد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"enseguida = حالًا/على طول. guardar = يحفظ/يخزّن. mostrador = كاونتر. De nada = ولا يهمك."}},{id:"tw-u01l05",courseId:"tourism-work",unitId:"tw-u01",sourceLessonId:null,level:"A2",register:"usted",title:"استقبال عيلة",context:"عيلة وصلت: أب بيتكلم وأطفال تعبانين من السفر. دورك: ترحّب بالمجموعة كلها، تبسّط كلامك، وتعرض مساعدة عملية للعيلة.",goal:"بعد الدرس ده حتقدر تستقبل مجموعة أو عيلة بترحيب جماعي وجمل بسيطة ومناسبة للموقف.",targets:[{es:"Bienvenidos. ¿Qué tal el viaje?",ar:"أهلًا بيكم. عاملين إيه السفر؟",speaker:"paco"},{es:"Largo, pero bien.",ar:"طويل، بس كويس.",speaker:"luna"},{es:"¿Quieren sentarse un momento?",ar:"تحبوا تقعدوا شوية؟",speaker:"paco"},{es:"Les preparo las llaves enseguida.",ar:"حجهّز لكم المفاتيح حالًا.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenas tardes. Bienvenidos. ¿Qué tal el viaje?",ar:"مساء الخير. أهلًا بيكم. عاملين إيه السفر؟"},{speaker:"luna",es:"Largo, pero bien. Los niños están cansados.",ar:"طويل، بس كويس. العيال تعبانين."},{speaker:"paco",es:"Lo entiendo. ¿Quieren sentarse un momento?",ar:"فاهم حضرتك. تحبوا تقعدوا شوية؟"},{speaker:"luna",es:"Sí, gracias. Sería perfecto.",ar:"أيوه، شكرًا. ده حيكون جميل."},{speaker:"paco",es:"Les preparo las llaves enseguida. Ustedes descansan.",ar:"حجهّز لكم المفاتيح حالًا. وانتوا ارتاحوا."},{speaker:"luna",es:"Muchas gracias, de verdad.",ar:"شكرًا جدًا، والله."}],questions:[{q:"الموظف خاطب العيلة بصيغة إيه؟",options:["مفرد","مؤنث بس","جمع (Bienvenidos / Quieren / Les)","رسمية زيادة"],answer:"جمع (Bienvenidos / Quieren / Les)",rationale:"Bienvenidos = أهلًا بيكم (جمع)، ¿Quieren…? = تحبوا…؟ (جمع). لما بترحّب بأكتر من شخص بتتكلم بصيغة الجمع."},{q:"الموظف عرض إيه على العيلة التعبانة؟",options:["جولة في المدينة","مشروبات مدفوعة","يقعدوا شوية وهو يجهّز المفاتيح","أوضة أغلى"],answer:"يقعدوا شوية وهو يجهّز المفاتيح",rationale:"قال: ¿Quieren sentarse un momento?… les preparo las llaves enseguida. mientras = في الوقت اللي."},{q:"ليه سأل عن السفر؟",options:["عشان التقرير","بيانات مطلوبة","عشان يملّي الوقت","سؤال بشري بسيط بيفتح الكلام وبيوريك حالة الضيوف المزاجية"],answer:"سؤال بشري بسيط بيفتح الكلام وبيوريك حالة الضيوف المزاجية",rationale:"¿Qué tal el viaje? سؤال خفيف بيدّيك معلومة عملية: العيلة تعبانة، فيحتاجوا سرعة وهدوء."}],responseTask:{prompt:"رحّب بعيلة وصلت الفندق بالإسباني واعرض عليهم يقعدوا لحد ما تجهّز الأوراق.",acceptable:["Bienvenidos. ¿Qué tal el viaje? ¿Quieren sentarse un momento?","Buenas tardes, bienvenidos. Siéntense un momento, por favor.","Bienvenidos. ¿Quieren sentarse mientras preparo las llaves?","Hola, bienvenidos. ¿Qué tal el viaje? Siéntense un momento."],modelEs:"Bienvenidos. ¿Qué tal el viaje? ¿Quieren sentarse un momento?",modelAr:"أهلًا بيكم. عاملين إيه السفر؟ تحبوا تقعدوا شوية؟",checklistAr:"راجع إجابتك: ١) ترحيب جمع (Bienvenidos)، ٢) سؤال خفيف أو عرض قعود، ٣) جمل قصيرة وبسيطة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"bienvenidos = أهلًا بيكم (جمع). ¿Qué tal…? = عاملين إيه…؟ (للجمع) / عامل إيه…؟ (لواحد) sentarse = يقعد. mientras = في الوقت اللي (زي mientras preparo las llaves)."}},{id:"tw-u01l06",courseId:"tourism-work",unitId:"tw-u01",sourceLessonId:null,level:"A2",register:"usted",title:"ترحيب كامل من أوله",context:"ضيف وصل، مش واضح إنه بيتكلم إسباني كويس، وعنده حجز. الدرس ده بيجمع الوحدة: ترحيب + سؤال عن اللغة + طلب إعادة بأدب + استقبال الطلب الأول.",goal:"بعد الدرس ده حتقدر تنفذ ترحيب كامل لأي ضيف: تحية، لغة، فهم، وأول خطوة.",targets:[{es:"Bienvenido. ¿En qué puedo ayudarle?",ar:"أهلًا بحضرتك. أقدر أساعد حضرتك في إيه؟",speaker:"luna"},{es:"¿Prefiere que hablemos en inglés?",ar:"تفضّل نتكلم بالإنجليزي؟",speaker:"luna"},{es:"¿Puede repetirlo más despacio?",ar:"ممكن تعيدها ببطء أكتر؟",speaker:"luna"},{es:"Perfecto, ya le busco la reserva.",ar:"جميل، حدور على الحجز بتاع حضرتك دلوقتي.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenas tardes. Bienvenido. ¿En qué puedo ayudarle?",ar:"مساء الخير. أهلًا بحضرتك. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola, tengo una reserva pero… mi español no es muy bueno.",ar:"أهلًا، عندي حجز بس… إسبانيّتي مش كويسة أوي."},{speaker:"luna",es:"No se preocupe. ¿Prefiere que hablemos en inglés?",ar:"متقلقش. تفضّل نتكلم بالإنجليزي؟"},{speaker:"paco",es:"No, no. Quiero practicar. Pero despacio, por favor.",ar:"لأ لأ. عايز أتمرن. بس ببطء، لو سمحت."},{speaker:"luna",es:"Perfecto. ¿Me dice su nombre, por favor?",ar:"جميل. تقوللي اسم حضرتك، لو سمحت؟"},{speaker:"paco",es:"¿Perdón?",ar:"آسف؟"},{speaker:"luna",es:"¿Puede repetirlo más despacio? Ah no, perdón. Le pregunto otra vez: ¿su nombre?",ar:"ممكن تعيدها ببطء أكتر؟ آه لأ، المعذرة. أسأل حضرتك تاني: اسمك؟"},{speaker:"paco",es:"Ah. Paco Martín.",ar:"آه. باكو مارتين."},{speaker:"luna",es:"Gracias. Perfecto, ya le busco la reserva.",ar:"شكرًا. جميل، حدور على الحجز بتاع حضرتك دلوقتي."}],questions:[{q:"الضيف طلب إيه بخصوص اللغة؟",options:["مترجم","يكمل بالإنجليزي","يكتب كل حاجة","يكمل بالإسباني بس ببطء عشان يتمرن"],answer:"يكمل بالإسباني بس ببطء عشان يتمرن",rationale:"قال: Quiero practicar. Pero despacio, por favor = عايز أتمرن، بس ببطء لو سمحت. practicar = يتمرن."},{q:"الموظفة غلطت في حاجة وصلحتها فورًا. إيه هي؟",options:["اتكلمت إنجليزي غلط","نسيت اسمها","قفلت الخط","ردّت على الضيف بطلب إنه يعيد الكلام، وهو اللي محتاجها هي تعيد، وبعدين اعتذرت وبسّطت السؤال"],answer:"ردّت على الضيف بطلب إنه يعيد الكلام، وهو اللي محتاجها هي تعيد، وبعدين اعتذرت وبسّطت السؤال",rationale:"لما الضيف قال ¿Perdón? ردّت بـ ¿Puede repetirlo más despacio? وهو طلب إعادة في الاتجاه الغلط: اللي مش فاهم هو الضيف، فالمفروض هي اللي تعيد. لحقت نفسها فورًا (Ah no, perdón) وقالت Le pregunto otra vez وبسّطتها لـ ¿su nombre?"},{q:"إيه تسلسل الترحيب الصح اللي حصل؟",options:["حجز → تحية → لغة","لغة → وداع","اسم → فلوس → مفتاح","تحية → سؤال عن اللغة/السرعة → الاسم → البحث عن الحجز"],answer:"تحية → سؤال عن اللغة/السرعة → الاسم → البحث عن الحجز",rationale:"الترحيب الصح بيبني: تحية، تظبيط التواصل، وبعدين بيانات الحجز."}],responseTask:{prompt:"ضيف إسبانيته ضعيفة وعايز يتمرن. رد بالإسباني: طمّنه وكمّل ببطء وبجمل قصيرة، وابدأ بسؤال الاسم.",acceptable:["No se preocupe. Hablamos despacio. ¿Me dice su nombre, por favor?","Tranquilo, hablamos despacio. ¿Su nombre, por favor?","No se preocupe. Vamos despacio. ¿Me dice su nombre?","Perfecto. Despacio y sin problema. ¿Su nombre, por favor?"],modelEs:"No se preocupe. Hablamos despacio. ¿Me dice su nombre, por favor?",modelAr:"متقلقش. حنتكلم ببطء. تقوللي اسم حضرتك، لو سمحت؟",checklistAr:"راجع إجابتك: ١) طمأنة (No se preocupe)، ٢) وعد بكلام بطيء وبسيط، ٣) سؤال الاسم بصيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"No se preocupe = متقلقش (صيغة حضرتك). despacio = ببطء. practicar = يتمرن. buscar la reserva = يدور على الحجز."}}]},{courseId:"tourism-work",unit:{id:"tw-u02",title:"استقبال الفندق",desc:"تلاقي حجز الضيف بالاسم والتهجية، تؤكد الليالي، تتحقق من المستند، وتسلّم المفتاح وتفاصيل الإقامة.",cefr:"A2–B1"},lessons:[{id:"tw-u02l01",courseId:"tourism-work",unitId:"tw-u02",sourceLessonId:"tw-u02l01",level:"A2",register:"usted",title:"الحجز باسم مين؟",context:"ضيفة وصلت الفندق وعندها حجز. دورك: تسأل الحجز باسم مين وتلاقيه في النظام بجمل بسيطة.",goal:"بعد الدرس ده حتقدر تسأل عن اسم الحجز وتأكد الحروف لو الاسم مش واضح.",targets:[{es:"¿A nombre de quién es la reserva?",ar:"الحجز باسم مين؟",speaker:"paco"},{es:"A nombre de Luna García.",ar:"باسم لونا جارسيا.",speaker:"luna"},{es:"¿Me lo deleta, por favor?",ar:"ممكن تهجّيهولي، لو سمحت؟",speaker:"paco"},{es:"Aquí está. García López, Luna.",ar:"أهو. جارسيا لوبيز، لونا.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenas tardes. ¿Tiene reserva?",ar:"مساء الخير. مع حضرتك حجز؟"},{speaker:"luna",es:"Sí, tengo una reserva.",ar:"أيوه، عندي حجز."},{speaker:"paco",es:"¿A nombre de quién es la reserva?",ar:"الحجز باسم مين؟"},{speaker:"luna",es:"A nombre de Luna García.",ar:"باسم لونا جارسيا."},{speaker:"paco",es:"¿Me lo deleta, por favor?",ar:"ممكن تهجّيهولي، لو سمحت؟"},{speaker:"luna",es:"Claro. Ge, a, ere, ce, i, a.",ar:"طبعًا. G-A-R-C-I-A."},{speaker:"paco",es:"Gracias. Aquí está. García López, Luna.",ar:"شكرًا. أهو. جارسيا لوبيز، لونا."}],questions:[{q:"إزاي الموظف سأل عن اسم الحجز؟",options:["¿A nombre de quién es la reserva?","¿Cómo se llama usted?","¿Su pasaporte?","¿De dónde viene?"],answer:"¿A nombre de quién es la reserva?",rationale:"a nombre de = باسم. السؤال عن اسم الحجز مش لازم يكون اسم الضيف نفسه (ممكن حاجز لحد تاني)."},{q:"ليه الموظف طلب تهجية الاسم؟",options:["عشان يلاقي الحجز صح في النظام من غير لخبطة في الحروف","عشان يتسلى","مطلوب قانونيًا","عشان الاسم طويل"],answer:"عشان يلاقي الحجز صح في النظام من غير لخبطة في الحروف",rationale:"¿Me lo deleta? = ممكن تهجّيهولي؟ deletrear = يهجّي. الأسماء المتشابهة كتير، والتهجية بتمنع فتح حجز غلط."},{q:"الضيفة هجّت اسمها إزاي؟",options:["بالأرقام","حرف حرف بالإسباني","رسمت الاسم","قالتله يكتبه هو"],answer:"حرف حرف بالإسباني",rationale:"قالت: Ge, a, ere, ce, i, a — دي أسماء الحروف بالإسباني لكلمة García."}],responseTask:{prompt:"ضيف عنده حجز. اسأله بالإسباني الحجز باسم مين واطلب تهجية الاسم.",acceptable:["¿A nombre de quién es la reserva? ¿Me lo deleta, por favor?","¿A nombre de quién? ¿Me lo deleta?","¿La reserva a nombre de quién es? ¿Me lo deleta, por favor?","¿A nombre de quién es la reserva? ¿Cómo se escribe?"],modelEs:"¿A nombre de quién es la reserva? ¿Me lo deleta, por favor?",modelAr:"الحجز باسم مين؟ ممكن تهجّيهولي، لو سمحت؟",checklistAr:"راجع إجابتك: ١) a nombre de في السؤال، ٢) طلب تهجية بأدب، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"a nombre de = باسم. deletrear = يهجّي حرف حرف. ¿Cómo se escribe? = بيتكتب إزاي؟ Aquí está = أهو/ده هو."}},{id:"tw-u02l02",courseId:"tourism-work",unitId:"tw-u02",sourceLessonId:"tw-u02l02",level:"A2",register:"usted",title:"مدة الإقامة والتحقق",context:"لقيت حجز الضيف. دورك: تؤكد عدد الليالي وتطلب منه يوريك مستند التحقق بالطريقة القانونية في مكان شغلك.",goal:"بعد الدرس ده حتقدر تؤكد تفاصيل الحجز الأساسية وتطلب إثبات الهوية بأدب ومن غير ما تاخد بيانات زيادة.",targets:[{es:"Son tres noches, ¿verdad?",ar:"تلات ليالي، صح؟",speaker:"luna"},{es:"Sí, del lunes al jueves.",ar:"أيوه، من الاتنين للخميس.",speaker:"paco"},{es:"¿Me enseña un documento de identidad, por favor?",ar:"ممكن توريني بطاقة تحقيق شخصية، لو سمحت؟",speaker:"luna"},{es:"Aquí tiene.",ar:"اتفضلي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perfecto, ya tengo su reserva. Son tres noches, ¿verdad?",ar:"جميل، لقيت الحجز بتاع حضرتك. تلات ليالي، صح؟"},{speaker:"paco",es:"Sí, del lunes al jueves.",ar:"أيوه، من الاتنين للخميس."},{speaker:"luna",es:"Muy bien. ¿Me enseña un documento de identidad, por favor?",ar:"تمام. ممكن توريني بطاقة تحقيق شخصية، لو سمحت؟"},{speaker:"paco",es:"Sí, claro. Aquí tiene.",ar:"أيوه طبعًا. اتفضلي."},{speaker:"luna",es:"Gracias. Un momento. …Listo, todo correcto.",ar:"شكرًا. لحظة واحدة. …تمام، كل حاجة سليمة."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."}],questions:[{q:"الموظفة أكدت تفصيلة إيه قبل ما تكمل؟",options:["عدد الليالي","نوع الأكل","اسم شركة الضيف","رقم الطيارة"],answer:"عدد الليالي",rationale:"قالت: Son tres noches, ¿verdad? = تلات ليالي، صح؟ noche = ليلة. تأكيد التفاصيل قبل التسليم بيمنع أخطاء الفوترة."},{q:"طلبت المستند إزاي؟",options:["خدته منه من غير كلام","طلبت يوريها إياه بأدب","طلبت تصوره بموبايلها","طلبت رقمه على ورقة"],answer:"طلبت يوريها إياه بأدب",rationale:"قالت: ¿Me enseña un documento de identidad? — enseñar = يوري. عرض المستند للتحقق، مش أخذ نسخة، والقواعد بتختلف حسب البلد والنظام."},{q:"«del lunes al jueves» معناها إيه؟",options:["من الاتنين للخميس","يوم الاتنين بس","كل الخميس","من الصبح لليل"],answer:"من الاتنين للخميس",rationale:"del… al… = من… لـ. lunes = اتنين، jueves = خميس."}],responseTask:{prompt:"أكد للضيف بالإسباني إن الحجز تلات ليالي واطلب منه يوريك مستند تحقق.",acceptable:["Son tres noches, ¿verdad? ¿Me enseña un documento de identidad, por favor?","Perfecto. Tres noches, ¿verdad? ¿Me enseña un documento, por favor?","Son tres noches. ¿Me enseña su documento de identidad?","Tres noches, ¿correcto? ¿Me enseña un documento de identidad, por favor?"],modelEs:"Son tres noches, ¿verdad? ¿Me enseña un documento de identidad, por favor?",modelAr:"تلات ليالي، صح؟ ممكن توريني بطاقة تحقيق شخصية، لو سمحت؟",checklistAr:"راجع إجابتك: ١) تأكيد المدة (¿verdad?)، ٢) طلب عرض المستند بأدب (enseña)، ٣) مفيش طلب نسخة أو بيانات زيادة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"noche = ليلة. ¿verdad? = صح؟ documento de identidad = بطاقة تحقيق شخصية. Aquí tiene = اتفضل (بتتقال وإنت بتدي حاجة، ولو لست: اتفضلي)."}},{id:"tw-u02l03",courseId:"tourism-work",unitId:"tw-u02",sourceLessonId:"tw-u02l03",level:"A2",register:"usted",title:"الأوضة والفطار",context:"الحجز اتأكد. دورك: تشرح للضيفة تفاصيل الإقامة الأساسية في الفندق ده: الأوضة والفطار والمواعيد.",goal:"بعد الدرس ده حتقدر تشرح مواعيد الفطار ومكان الأوضة بجمل بسيطة واضحة.",targets:[{es:"Su habitación está en la segunda planta.",ar:"أوضة حضرتك في الدور التاني.",speaker:"paco"},{es:"El desayuno es de siete a diez.",ar:"الفطار من الساعة سبعة لعشرة.",speaker:"paco"},{es:"¿Dónde se desayuna?",ar:"الفطار فين؟",speaker:"luna"},{es:"En el comedor de abajo.",ar:"في صالة الأكل اللي تحت.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Muy bien. Su habitación está en la segunda planta. La doscientos cuatro.",ar:"تمام. أوضة حضرتك في الدور التاني. رقم ٢٠٤."},{speaker:"luna",es:"¿Y el desayuno?",ar:"والفطار؟"},{speaker:"paco",es:"El desayuno es de siete a diez.",ar:"الفطار من الساعة سبعة لعشرة."},{speaker:"luna",es:"¿Dónde se desayuna?",ar:"الفطار فين؟"},{speaker:"paco",es:"En el comedor de abajo. Está junto a la recepción.",ar:"في صالة الأكل اللي تحت. جنب الاستقبال."},{speaker:"luna",es:"Perfecto. Muchas gracias.",ar:"جميل. شكرًا جدًا."}],questions:[{q:"الأوضة فين؟",options:["الدور التاني، أوضة ٢٠٤","الدور الأول","الدور التالت","تحت"],answer:"الدور التاني، أوضة ٢٠٤",rationale:"قال: en la segunda planta. La doscientos cuatro. planta = دور، habitación = أوضة."},{q:"مواعيد الفطار إيه؟",options:["طول اليوم","من تمانية لتسعة","من سبعة لعشرة","مفيش فطار"],answer:"من سبعة لعشرة",rationale:"قال: El desayuno es de siete a diez. desayuno = فطار. de… a… = من… لـ."},{q:"التفاصيل دي ثابتة في أي فندق؟",options:["أيوه، كل الفنادق زي بعض","لأ، دي تفاصيل الفندق في التدريب، وكل مكان شغل ليه مواعيده وخدماته","مفيش فنادق أصلًا","بس فنادق إسبانيا"],answer:"لأ، دي تفاصيل الفندق في التدريب، وكل مكان شغل ليه مواعيده وخدماته",rationale:"الجمل بتتعلم، بس المواعيد والأدوار بتتأكد في مكان الشغل الحقيقي."}],responseTask:{prompt:"اشرح لضيف بالإسباني: الأوضة في الدور التالت، والفطار من ٧:٣٠ لـ ١٠:٣٠.",acceptable:["Su habitación está en la tercera planta. El desayuno es de siete y media a diez y media.","La habitación está en la tercera planta. El desayuno, de siete y media a diez y media.","Su habitación está en la tercera planta. Desayuno de siete y media a diez y media.","Está en la tercera planta. El desayuno es de siete y media a diez y media."],modelEs:"Su habitación está en la tercera planta. El desayuno es de siete y media a diez y media.",modelAr:"أوضة حضرتك في الدور التالت. الفطار من ٧:٣٠ لـ ١٠:٣٠.",checklistAr:"راجع إجابتك: ١) الدور (planta)، ٢) مواعيد الفطار بصيغة de… a…، ٣) الساعات منطوقة صح (y media = ونص). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"planta = دور/طابق. desayuno = فطار. comedor = صالة أكل. y media = ونص (7:30 = siete y media). abajo = تحت."}},{id:"tw-u02l04",courseId:"tourism-work",unitId:"tw-u02",sourceLessonId:null,level:"A2",register:"usted",title:"المفتاح والواي فاي",context:"الضيف خلص تسجيل دخول. دورك: تسلّمه المفتاح، تقوله كلمة سر الواي فاي، وتعرض مساعدة في الشنط لو متاحة.",goal:"بعد الدرس ده حتقدر تسلّم تفاصيل الدخول العملية: مفتاح، واي فاي، وعرض مساعدة بسيط.",targets:[{es:"Aquí tiene su llave.",ar:"اتفضلي مفتاح حضرتك.",speaker:"paco"},{es:"La contraseña del wifi está en la tarjeta.",ar:"كلمة سر الواي فاي على الكارت.",speaker:"paco"},{es:"¿Le ayudo con las maletas?",ar:"أساعد حضرتك في الشنط؟",speaker:"paco"},{es:"El ascensor está a la derecha.",ar:"الأسانسير على اليمين.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Listo. Aquí tiene su llave.",ar:"خلاص. اتفضلي مفتاح حضرتك."},{speaker:"luna",es:"Gracias. ¿Y el wifi?",ar:"شكرًا. والواي فاي؟"},{speaker:"paco",es:"La contraseña del wifi está en la tarjeta. La tarjeta está junto a la llave.",ar:"كلمة سر الواي فاي على الكارت. الكارت جنب المفتاح."},{speaker:"luna",es:"Genial. ¿Dónde está el ascensor?",ar:"جميل. الأسانسير فين؟"},{speaker:"paco",es:"El ascensor está a la derecha. ¿Le ayudo con las maletas?",ar:"الأسانسير على اليمين. أساعد حضرتك في الشنط؟"},{speaker:"luna",es:"No, gracias, puedo yo.",ar:"لأ، شكرًا، أقدر لوحدي."},{speaker:"paco",es:"Perfecto. Que descanse.",ar:"جميل. ترتاحي."}],questions:[{q:"كلمة سر الواي فاي فين؟",options:["الموظف يقولها همسًا","في الإيميل","على الكارت اللي مع المفتاح","مفيش واي فاي"],answer:"على الكارت اللي مع المفتاح",rationale:"قال: La contraseña del wifi está en la tarjeta. contraseña = كلمة سر، tarjeta = كارت."},{q:"الموظف عرض إيه بعد تسليم المفتاح؟",options:["مشروب ترحيبي مدفوع","يساعد في الشنط","جولة إجبارية","ترقية أوضة"],answer:"يساعد في الشنط",rationale:"قال: ¿Le ayudo con las maletas? — عرض مساعدة بسيط، والضيفة رفضت بأدب: No, gracias, puedo yo."},{q:"الأسانسير فين؟",options:["على الشمال","قدام","على اليمين","بره"],answer:"على اليمين",rationale:"قال: a la derecha = على اليمين. المقابل: a la izquierda = على الشمال."}],responseTask:{prompt:"سلّم الضيف مفتاحه بالإسباني وقوله إن كلمة سر الواي فاي على الكارت، واعرض المساعدة في الشنط.",acceptable:["Aquí tiene su llave. La contraseña del wifi está en la tarjeta. ¿Le ayudo con las maletas?","Aquí tiene la llave. El wifi está en la tarjeta. ¿Le ayudo con las maletas?","Su llave. La contraseña del wifi está en la tarjeta. ¿Le ayudo con algo?","Aquí tiene su llave y la tarjeta con el wifi. ¿Le ayudo con las maletas?"],modelEs:"Aquí tiene su llave. La contraseña del wifi está en la tarjeta. ¿Le ayudo con las maletas?",modelAr:"اتفضلي مفتاح حضرتك. كلمة سر الواي فاي على الكارت. أساعد حضرتك في الشنط؟",checklistAr:"راجع إجابتك: ١) تسليم المفتاح (Aquí tiene)، ٢) مكان كلمة السر، ٣) عرض مساعدة من غير إصرار. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"llave = مفتاح. contraseña = كلمة سر. maletas = شنط. ascensor = أسانسير. a la derecha = على اليمين."}},{id:"tw-u02l05",courseId:"tourism-work",unitId:"tw-u02",sourceLessonId:null,level:"B1",register:"usted",title:"الحجز مش ظاهر",context:"ضيف واسمه مش طالع في النظام. دورك: متتظاهرش إن مفيش مشكلة ولا تتهمه؛ تهدّي الموقف وتجرّب طرق بحث تانية.",goal:"بعد الدرس ده حتقدر تدير لحظة 'الحجز مش موجود' بهدوء: طمأنة + بحث بديل + حل عملي.",targets:[{es:"No se preocupe, lo miramos juntos.",ar:"متقلقش، حنشوفها مع بعض.",speaker:"luna"},{es:"A veces está con otro nombre o con el correo.",ar:"ساعات بيكون باسم تاني أو بالإيميل.",speaker:"luna"},{es:"¿Tiene el correo de confirmación?",ar:"مع حضرتك إيميل التأكيد؟",speaker:"luna"},{es:"Ya lo tengo. Estaba con el segundo apellido.",ar:"لقيته. كان متسجل باللقب التاني.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Tengo una reserva. Paco Martín.",ar:"عندي حجز. باكو مارتين."},{speaker:"luna",es:"Veamos… No me sale ese nombre.",ar:"نشوف… الاسم ده مش طالع عندي."},{speaker:"paco",es:"¿Cómo que no? Lo reservé ayer.",ar:"إزاي يعني؟ أنا حاجز من إمبارح."},{speaker:"luna",es:"No se preocupe, lo miramos juntos. A veces está con otro nombre o con el correo.",ar:"متقلقش، حنشوفها مع بعض. ساعات بيكون باسم تاني أو بالإيميل."},{speaker:"paco",es:"¿Y ahora qué?",ar:"ودلوقتي نعمل إيه؟"},{speaker:"luna",es:"¿Tiene el correo de confirmación? Con el número lo encuentro seguro.",ar:"مع حضرتك إيميل التأكيد؟ برقمه حلاقيه أكيد."},{speaker:"paco",es:"Sí, aquí está.",ar:"أيوه، أهو."},{speaker:"luna",es:"Perfecto. Ya lo tengo. Estaba con el segundo apellido.",ar:"جميل. لقيته. كان متسجل باللقب التاني."}],questions:[{q:"الموظفة ردّت إزاي لما الاسم مظهرش؟",options:["قالتله مفيش حجز وخلاص","اتهمته إنه غلطان","طمّنته واقترحت طرق بحث تانية","قالتله تعالى بكرة"],answer:"طمّنته واقترحت طرق بحث تانية",rationale:"قالت: No se preocupe, lo miramos juntos. A veces está con otro nombre o con el correo. no me sale = مش طالع عندي."},{q:"الحجز اتلاقى إزاي في الآخر؟",options:["الضيف فتكر غلط","معجزة","برقم إيميل التأكيد، وكان متسجل باللقب التاني","الاتصال بالشركة"],answer:"برقم إيميل التأكيد، وكان متسجل باللقب التاني",rationale:"قالت: Estaba con el segundo apellido = كان متسجل باللقب التاني. الأسماء المركبة سبب شائع جدًا لمشاكل البحث."},{q:"ليه الطمأنة أول رد فعل؟",options:["عشان الكاميرات","عشان ده بروتوكول شكلي","مش مهمة","عشان الضيف بيتوتر لما يسمع مفيش حجز، والتوتر بيصعّب أي حل"],answer:"عشان الضيف بيتوتر لما يسمع مفيش حجز، والتوتر بيصعّب أي حل",rationale:"lo miramos juntos = حنشوفها مع بعض: بتحوّل الموقف من مواجهة لتعاون."}],responseTask:{prompt:"ضيف وحجزه مش ظاهر في النظام. رد بالإسباني: طمأنة + اقتراح بحث بالإيميل أو رقم التأكيد.",acceptable:["No se preocupe, lo miramos juntos. ¿Tiene el correo de confirmación?","No se preocupe. A veces está con otro nombre. ¿Tiene el correo de confirmación?","Tranquilo, lo miramos juntos. ¿Me enseña el correo de confirmación?","No se preocupe, lo encontramos. ¿Tiene el correo o el número de confirmación?"],modelEs:"No se preocupe, lo miramos juntos. ¿Tiene el correo de confirmación?",modelAr:"متقلقش، حنشوفها مع بعض. مع حضرتك إيميل التأكيد؟",checklistAr:"راجع إجابتك: ١) طمأنة، ٢) نبرة تعاون (lo miramos juntos)، ٣) طلب مرجع بديل (correo / número)، ٤) مفيش اتهام. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"no me sale = مش طالع عندي. a veces = ساعات. apellido = اللقب/اسم العيلة. seguro هنا = أكيد."}},{id:"tw-u02l06",courseId:"tourism-work",unitId:"tw-u02",sourceLessonId:null,level:"B1",register:"usted",title:"تسجيل دخول كامل",context:"تسجيل دخول كامل من أول الترحيب لتسليم المفتاح: اسم الحجز، تهجية، مدة الإقامة، مستند التحقق، تفاصيل الأوضة والفطار، والواي فاي. الدرس ده بيجمع الوحدة كلها.",goal:"بعد الدرس ده حتقدر تنفذ check-in كامل بجمل إسبانية بسيطة ومرتبة.",targets:[{es:"¿A nombre de quién es la reserva?",ar:"الحجز باسم مين؟",speaker:"luna"},{es:"Son dos noches, del viernes al domingo.",ar:"ليلتين، من الجمعة للحد.",speaker:"luna"},{es:"¿Me enseña un documento de identidad?",ar:"ممكن توريني بطاقة تحقيق شخصية؟",speaker:"luna"},{es:"Aquí tiene su llave. El desayuno es de ocho a once, en el comedor de abajo.",ar:"اتفضل مفتاح حضرتك. الفطار من تمانية لحداشر، في صالة الأكل اللي تحت.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenas tardes. ¿Tiene reserva?",ar:"مساء الخير. مع حضرتك حجز؟"},{speaker:"paco",es:"Sí, buenas tardes.",ar:"أيوه، مساء الخير."},{speaker:"luna",es:"¿A nombre de quién es la reserva?",ar:"الحجز باسم مين؟"},{speaker:"paco",es:"Paco Martín. ¿Se lo deleto?",ar:"باكو مارتين. أهجّيهولك؟"},{speaker:"luna",es:"Sí, por favor. …Perfecto. Son dos noches, del viernes al domingo. ¿Verdad?",ar:"أيوه، لو سمحت. …جميل. ليلتين، من الجمعة للحد. صح؟"},{speaker:"paco",es:"Correcto.",ar:"صح."},{speaker:"luna",es:"¿Me enseña un documento de identidad? …Gracias. Todo correcto.",ar:"ممكن توريني بطاقة تحقيق شخصية؟ …شكرًا. كل حاجة سليمة."},{speaker:"paco",es:"¿Y la habitación?",ar:"والأوضة؟"},{speaker:"luna",es:"En la primera planta. Aquí tiene su llave. El desayuno es de ocho a once, en el comedor de abajo.",ar:"في الدور الأول. اتفضل مفتاح حضرتك. الفطار من تمانية لحداشر، في صالة الأكل اللي تحت."},{speaker:"paco",es:"Muchas gracias.",ar:"شكرًا جدًا."}],questions:[{q:"الضيف عمل حاجة استباقية حلوة. إيه هي؟",options:["سأل عن الخصم","دفع مقدم","مدح الفندق","عرض يهجّي اسمه قبل ما يتسأل"],answer:"عرض يهجّي اسمه قبل ما يتسأل",rationale:"قال: ¿Se lo deleto? = أهجّيهولك؟ — وفي شغل الاستقبال، تشجيع الضيوف على ده بيسرّع كل حاجة."},{q:"ترتيب الـ check-in الصح اللي حصل؟",options:["مفتاح → اسم → مستند","واي فاي → مفتاح → اسم","فلوس → اسم → فطار","اسم الحجز → تأكيد المدة → مستند التحقق → تفاصيل الأوضة والفطار → تسليم المفتاح"],answer:"اسم الحجز → تأكيد المدة → مستند التحقق → تفاصيل الأوضة والفطار → تسليم المفتاح",rationale:"الترتيب بيمنع الأخطاء: الأول نلاقي الحجز، نأكده، نتحقق من الشخص، وبعدين نسلّم."},{q:"«de ocho a once» معناها؟",options:["نص الليل","من تسعة لعشرة","التمنية وربع","من تمانية لحداشر"],answer:"من تمانية لحداشر",rationale:"de… a… = من… لـ. ocho = ٨، once = ١١."}],responseTask:{prompt:"نفّذ قلب الـ check-in بالإسباني: اسأل عن اسم الحجز، أكد الليالي، اطلب المستند، وسلّم المفتاح مع مواعيد الفطار.",acceptable:["¿A nombre de quién es la reserva? …Son dos noches, ¿verdad? ¿Me enseña un documento de identidad? …Aquí tiene su llave. El desayuno es de ocho a once.","¿A nombre de quién? …Dos noches, ¿verdad? ¿Me enseña su documento? …Su llave. Desayuno de ocho a once.","¿La reserva a nombre de quién es? …Dos noches. ¿Me enseña un documento de identidad? …Aquí tiene su llave y el desayuno es de ocho a once.","¿A nombre de quién es la reserva? …Son dos noches. ¿Su documento, por favor? …Aquí tiene la llave. Desayuno: de ocho a once."],modelEs:"¿A nombre de quién es la reserva? …Son dos noches, ¿verdad? ¿Me enseña un documento de identidad? …Aquí tiene su llave. El desayuno es de ocho a once.",modelAr:"الحجز باسم مين؟ …ليلتين، صح؟ ممكن توريني بطاقة تحقيق شخصية؟ …اتفضل مفتاح حضرتك. الفطار من تمانية لحداشر.",checklistAr:"راجع إجابتك: ١) a nombre de، ٢) تأكيد المدة، ٣) طلب المستند بأدب، ٤) تسليم المفتاح + مواعيد الفطار. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Se lo deleto? = أهجّيهولك؟ correcto = صح. todo correcto = كل حاجة سليمة. la primera planta = الدور الأول."}}]},{courseId:"tourism-work",unit:{id:"tw-u03",title:"خدمة المطعم والكافيه",desc:"تستقبل الضيوف على الترابيزة، تاخد الطلبات، تتعامل مع الحساسية الغذائية بجدية، وترشّح وتدير الحساب بأمان.",cefr:"A2–B1"},lessons:[{id:"tw-u03l01",courseId:"tourism-work",unitId:"tw-u03",sourceLessonId:"tw-u03l01",level:"A2",register:"usted",title:"الترابيزة والطلب",context:"ضيف قاعد في المطعم. دورك: تقوله عدد الأماكن المتاحة، تجيب المنيو، وتاخد أول طلب بجمل بسيطة.",goal:"بعد الدرس ده حتقدر تستقبل ضيف في المطعم: ترابيزة، منيو، وسؤال الطلب الأول.",targets:[{es:"¿Una mesa para dos?",ar:"في ترابيزة لاتنين؟",speaker:"paco"},{es:"Aquí tienen la carta.",ar:"اتفضلوا المنيو.",speaker:"luna"},{es:"¿Qué van a tomar?",ar:"حتطلبوا إيه؟",speaker:"luna"},{es:"Para mí, el menú del día.",ar:"أنا حاخد منيو اليوم.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenas tardes. ¿Una mesa para dos?",ar:"مساء الخير. في ترابيزة لاتنين؟"},{speaker:"luna",es:"Sí, claro. Por aquí, por favor.",ar:"أيوه طبعًا. من هنا، اتفضلوا."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."},{speaker:"luna",es:"Aquí tienen la carta.",ar:"اتفضلوا المنيو."},{speaker:"paco",es:"Gracias. Un momento, por favor.",ar:"شكرًا. لحظة، لو سمحت."},{speaker:"luna",es:"Claro. …¿Qué van a tomar?",ar:"اتفضلوا. …حتطلبوا إيه؟"},{speaker:"paco",es:"Para mí, el menú del día. Y para ella, la ensalada.",ar:"أنا حاخد منيو اليوم. وهي حتاخد السلطة."}],questions:[{q:"كلمة carta هنا معناها إيه؟",options:["المنيو","جواب","كارت لعب","خريطة"],answer:"المنيو",rationale:"carta في المطعم = المنيو. الجواب اسمه carta كمان بس السياق بيحدد: Aquí tienen la carta = اتفضلوا المنيو."},{q:"الضيف طلب إيه؟",options:["منيو اليوم لنفسه وسلطة للي معاه","أكل لحد تالت","شرب بس","الحساب"],answer:"منيو اليوم لنفسه وسلطة للي معاه",rationale:"قال: Para mí, el menú del día. Y para ella, la ensalada. menú del día = منيو اليوم (وجبة اليوم بسعر ثابت)."},{q:"الموظفة خاطبت الضيوف بصيغة إيه؟",options:["مفرد","جمع (tienen / van)","مؤنث","رسمية زيادة"],answer:"جمع (tienen / van)",rationale:"Aquí tienen / ¿Qué van a tomar? — صيغة الجمع (ustedes) لأنهم اتنين."}],responseTask:{prompt:"استقبل اتنين ضيوف في المطعم بالإسباني: وجّههم لترابيزة وادّيهم المنيو واسأل عن الطلب.",acceptable:["Por aquí, por favor. Aquí tienen la carta. ¿Qué van a tomar?","Una mesa para dos, por aquí. Aquí tienen la carta. ¿Qué van a tomar?","Pasen, por favor. La carta. ¿Qué van a tomar?","Por aquí. Aquí tienen la carta. ¿Ya saben qué van a tomar?"],modelEs:"Por aquí, por favor. Aquí tienen la carta. ¿Qué van a tomar?",modelAr:"من هنا، اتفضلوا. اتفضلوا المنيو. حتطلبوا إيه؟",checklistAr:"راجع إجابتك: ١) توجيه للترابيزة، ٢) تقديم المنيو (la carta)، ٣) سؤال الطلب بصيغة الجمع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"por aquí = من هنا. tomar هنا = ياكل أو يشرب. menú del día = منيو اليوم. para ella = ليها/هي."}},{id:"tw-u03l02",courseId:"tourism-work",unitId:"tw-u03",sourceLessonId:"tw-u03l02",level:"B1",register:"usted",title:"الحساسية والمكونات",context:"ضيفة عندها حساسية من المكسرات. دورك: تسأل عن النوع بالتحديد، متأكدش من اسم المكوّن لوحدك، وتراجع مع المطبخ قبل أي وعد.",goal:"بعد الدرس ده حتقدر تتعامل مع الحساسية الغذائية بجدية: سؤال محدد + مراجعة مطبخ + مفيش تأكيد من غير تحقق.",targets:[{es:"¿A qué frutos secos es alérgica exactamente?",ar:"عند حضرتك حساسية من أنهي مكسرات بالظبط؟",speaker:"paco"},{es:"De los cacahuetes y de las nueces.",ar:"من الفول السوداني وعين الجمل.",speaker:"luna"},{es:"Lo confirmo con la cocina antes de pedir.",ar:"حأكد مع المطبخ قبل ما نطلب.",speaker:"paco"},{es:"Este plato lleva almendras. No se lo recomiendo.",ar:"الطبق ده فيه لوز. مش حنصحك بيه.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Tengo alergia a los frutos secos.",ar:"عندي حساسية من المكسرات."},{speaker:"paco",es:"Gracias por decírmelo. ¿A qué frutos secos es alérgica exactamente?",ar:"شكرًا إنك قولتيلي. عند حضرتك حساسية من أنهي مكسرات بالظبط؟"},{speaker:"luna",es:"De los cacahuetes y de las nueces.",ar:"من الفول السوداني وعين الجمل."},{speaker:"paco",es:"Entendido. Lo confirmo con la cocina antes de pedir.",ar:"فاهم. حأكد مع المطبخ قبل ما نطلب."},{speaker:"luna",es:"¿Y este plato?",ar:"والطبق ده؟"},{speaker:"paco",es:"Este plato lleva almendras. No se lo recomiendo.",ar:"الطبق ده فيه لوز. مش حنصحك بيه."},{speaker:"luna",es:"Gracias. Entonces, la trucha.",ar:"شكرًا. يبقى السمك ده."}],questions:[{q:"الموظف عمل إيه أول ما سمع عن الحساسية؟",options:["سأل عن النوع بالتحديد","قال كل الأكل أمان","تجاهل الموضوع","شال طبق واحد بس"],answer:"سأل عن النوع بالتحديد",rationale:"سأل: ¿A qué frutos secos es alérgica exactamente? — frutos secos = مكسرات، alergia = حساسية، exactamente = بالظبط."},{q:"الضيفة عندها حساسية من إيه؟",options:["الفول السوداني وعين الجمل","اللوز بس","السمك","اللبن"],answer:"الفول السوداني وعين الجمل",rationale:"قالت: cacahuetes y nueces = فول سوداني وعين جمل. cacahuete = فول سوداني (في إسبانيا)، nuez = عين جمل."},{q:"ليه الموظف أكد مع المطبخ قبل ما يوصي؟",options:["عشان اسم المكوّن لوحده مش ضمان، واحتمال التلامس مع مسببات الحساسية لازم يتراجع","عشان يضيع وقت","عشان المطبخ فاضي","مش مهم"],answer:"عشان اسم المكوّن لوحده مش ضمان، واحتمال التلامس مع مسببات الحساسية لازم يتراجع",rationale:"الحساسية مسألة سلامة. حتى لو الطبق مش مكتوب فيه المكوّن، التلامس في المطبخ ممكن يكون خطر."}],responseTask:{prompt:"ضيف قالك عنده حساسية مكسرات. رد بالإسباني: اشكره، اسأل عن النوع بالتحديد، وقول إنك حتراجع المطبخ.",acceptable:["Gracias por decírmelo. ¿A qué frutos secos es alérgico exactamente? Lo confirmo con la cocina.","Gracias por avisar. ¿A cuáles exactamente? Lo confirmo con la cocina antes de pedir.","¿A qué frutos secos es alérgico exactamente? Lo confirmo con la cocina.","Entendido. ¿A cuáles es alérgico? Lo consulto con la cocina."],modelEs:"Gracias por decírmelo. ¿A qué frutos secos es alérgico exactamente? Lo confirmo con la cocina.",modelAr:"شكرًا إنك قولتلي. عند حضرتك حساسية من أنهي مكسرات بالظبط؟ حأكد مع المطبخ.",checklistAr:"راجع إجابتك: ١) شكر على المعلومة، ٢) سؤال عن النوع بالتحديد، ٣) مراجعة المطبخ قبل الوعد، ٤) مفيش تأكيد أمان من راسك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"alergia = حساسية (alérgico لراجل، alérgica لست). frutos secos = مكسرات. llevar = يحتوي (الطبق فيه). cocina = مطبخ."}},{id:"tw-u03l03",courseId:"tourism-work",unitId:"tw-u03",sourceLessonId:"tw-u03l03",level:"A2",register:"usted",title:"الحساب",context:"الضيوف خلصوا أكل وعايزين يدفعوا. دورك: تجيب الحساب، تسأل عن طريقة الدفع من غير ما تطلب بيانات كارت، وتشكرهم.",goal:"بعد الدرس ده حتقدر تدير لحظة الحساب: la cuenta، سؤال طريقة الدفع، وشكر الوداع.",targets:[{es:"La cuenta, por favor.",ar:"الحساب، لو سمحت.",speaker:"paco"},{es:"Enseguida se la traigo.",ar:"حأجيبهولك حالًا.",speaker:"luna"},{es:"¿Van a pagar en efectivo o con tarjeta?",ar:"حتدفعوا كاش ولا كارت؟",speaker:"luna"},{es:"Con tarjeta. ¿Está todo correcto?",ar:"كارت. كل حاجة سليمة في الحساب؟",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Perdone. La cuenta, por favor.",ar:"لو سمحت. الحساب، لو سمحت."},{speaker:"luna",es:"Enseguida se la traigo.",ar:"حأجيبهولك حالًا."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."},{speaker:"luna",es:"Aquí la tienen. ¿Van a pagar en efectivo o con tarjeta?",ar:"اتفضلوا الحساب. حتدفعوا كاش ولا كارت؟"},{speaker:"paco",es:"Con tarjeta. ¿Está todo correcto?",ar:"كارت. كل حاجة سليمة في الحساب؟"},{speaker:"luna",es:"Sí, todo correcto. Les acerco el datáfono.",ar:"أيوه، كل حاجة سليمة. حقرّبلكم ماكينة الدفع."},{speaker:"paco",es:"Perfecto, gracias.",ar:"جميل، شكرًا."}],questions:[{q:"الضيف طلب الحساب إزاي؟",options:["Quiero irme","El dinero, por favor","La cuenta, por favor","La factura fiscal"],answer:"La cuenta, por favor",rationale:"la cuenta = الحساب في المطعم. دي أشهر جملة في أي مطعم إسباني."},{q:"الموظفة سألت عن إيه؟",options:["رقم الكارت","طريقة الدفع: كاش ولا كارت","الرقم السري","العنوان"],answer:"طريقة الدفع: كاش ولا كارت",rationale:"سألت: ¿en efectivo o con tarjeta? — efectivo = كاش. سؤال طريقة الدفع مش طلب بيانات الكارت أبدًا."},{q:"datáfono معناها إيه؟",options:["التليفون","الدرج","ماكينة الدفع بالكارت","المنيو"],answer:"ماكينة الدفع بالكارت",rationale:"datáfono = ماكينة الـ POS في إسبانيا. كلمة شغالة جدًا في المطاعم هناك."}],responseTask:{prompt:"ضيوف عايزين يدفعوا. رد بالإسباني: الحساب جاي، واسألهم كاش ولا كارت.",acceptable:["Enseguida se la traigo. ¿Van a pagar en efectivo o con tarjeta?","Ahora les traigo la cuenta. ¿En efectivo o con tarjeta?","La cuenta enseguida. ¿Pagan en efectivo o con tarjeta?","Se la traigo ahora. ¿Cómo van a pagar, en efectivo o con tarjeta?"],modelEs:"Enseguida se la traigo. ¿Van a pagar en efectivo o con tarjeta?",modelAr:"حأجيبهولك حالًا. حتدفعوا كاش ولا كارت؟",checklistAr:"راجع إجابتك: ١) تأكيد إن الحساب جاي، ٢) سؤال طريقة الدفع، ٣) مفيش طلب بيانات كارت. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"la cuenta = الحساب. en efectivo = كاش. con tarjeta = بالكارت. datáfono = ماكينة الدفع. acercar = يقرّب/يجيب لحد عندك."}},{id:"tw-u03l04",courseId:"tourism-work",unitId:"tw-u03",sourceLessonId:null,level:"A2",register:"usted",title:"ترشيح صادق",context:"ضيف محتار وسألك ترشّح إيه. دورك: تسأله عن ذوقه بسرعة وترشّح حاجة موجودة فعلًا في المنيو، وتقول ليه رشّحتها.",goal:"بعد الدرس ده حتقدر ترشّح طبق من المنيو بجمل بسيطة مع سبب، من غير مبالغة.",targets:[{es:"¿Qué le gusta más, carne o pescado?",ar:"بتحب أكتر إيه، لحمة ولا سمك؟",speaker:"luna"},{es:"Le recomiendo el pollo al horno.",ar:"برشّح لحضرتك الفراخ في الفرن.",speaker:"luna"},{es:"Es el plato que más piden.",ar:"ده أكتر طبق بيتطلب.",speaker:"luna"},{es:"Y de postre, la tarta de la casa.",ar:"وللحلو، تورتة البيت.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Qué me recomienda?",ar:"ترشّحيلي إيه؟"},{speaker:"luna",es:"¿Qué le gusta más, carne o pescado?",ar:"بتحب أكتر إيه، لحمة ولا سمك؟"},{speaker:"paco",es:"Más carne.",ar:"لحمة أكتر."},{speaker:"luna",es:"Entonces, vale. Le recomiendo el pollo al horno. Es el plato que más piden.",ar:"يبقى تمام. برشّح لحضرتك الفراخ في الفرن. ده أكتر طبق بيتطلب."},{speaker:"paco",es:"Vale, ese. ¿Y de postre?",ar:"تمام، ده. وللحلو؟"},{speaker:"luna",es:"Y de postre, la tarta de la casa.",ar:"وللحلو، تورتة البيت."},{speaker:"paco",es:"Perfecto. Así sea.",ar:"جميل. يبقى كده."}],questions:[{q:"الموظفة سألت سؤال إيه قبل الترشيح؟",options:["جعان قد إيه؟","عندك فلوس قد إيه؟","بتحب لحمة ولا سمك أكتر؟","جاي منين؟"],answer:"بتحب لحمة ولا سمك أكتر؟",rationale:"سألت: ¿Qué le gusta más, carne o pescado? — الترشيح من غير معرفة الذوق تخمين أعمى."},{q:"الموظفة برّرت ترشيحها بإيه؟",options:["إنه أغلى طبق","إنه أكتر طبق بيتطلب","إنه صورته حلوة","مقالتش سبب"],answer:"إنه أكتر طبق بيتطلب",rationale:"قالت: Es el plato que más piden = ده أكتر طبق بيتطلب. سبب حقيقي بسيط أقوى من المبالغة."},{q:"«tarta de la casa» معناها؟",options:["آيس كريم","تورتة التفاح","تورتة البيت","قهوة"],answer:"تورتة البيت",rationale:"de la casa = بتاع البيت/السبيشيال بتاع المكان. postre = حلو."}],responseTask:{prompt:"ضيف سألك ترشّح إيه. رد بالإسباني: اسأل عن ذوقه ورشّح طبق بسبب بسيط.",acceptable:["¿Qué le gusta más, carne o pescado? …Le recomiendo el pollo al horno. Es el plato que más piden.","¿Carne o pescado? Le recomiendo el pescado del día. Es muy fresco.","¿Qué le gusta más? Le recomiendo la paella. Es el plato que más piden.","¿Prefiere carne o pescado? Le recomiendo el pollo. Es de los que más piden."],modelEs:"¿Qué le gusta más, carne o pescado? …Le recomiendo el pollo al horno. Es el plato que más piden.",modelAr:"بتحب أكتر إيه، لحمة ولا سمك؟ …برشّح لحضرتك الفراخ في الفرن. ده أكتر طبق بيتطلب.",checklistAr:"راجع إجابتك: ١) سؤال عن الذوق، ٢) ترشيح بـ Le recomiendo، ٣) سبب بسيط وحقيقي، ٤) مفيش مبالغة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"recomendar = يرشّح (le recomiendo = برشّح لحضرتك). pescado = سمك (بعد ما يتصاد). postre = حلو. al horno = في الفرن."}},{id:"tw-u03l05",courseId:"tourism-work",unitId:"tw-u03",sourceLessonId:null,level:"B1",register:"usted",title:"الطبق مش هو",context:"الضيفة استلمت طبق غلط: طلبت سمك وجالها فراخ. دورك: تعتذر، تؤكد الطلب الأصلي، وتصلّح الغلط بسرعة من غير جدال.",goal:"بعد الدرس ده حتقدر تدير غلطة طلب بسيطة: اعتذار + تأكيد + تصحيح فوري.",targets:[{es:"Lo siento mucho, este no es su plato.",ar:"أنا متأسف جدًا، ده مش طبق حضرتك.",speaker:"paco"},{es:"Usted pidió la trucha, ¿verdad?",ar:"حضرتك طلبتي السمك ده، صح؟",speaker:"paco"},{es:"Se lo cambio ahora mismo.",ar:"حغيّرهولك دلوقتي حالًا.",speaker:"paco"},{es:"El pollo vuelve a la cocina.",ar:"الفراخ حترجع المطبخ.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone. Yo pedí la trucha y esto es pollo.",ar:"لو سمحت. أنا طلبت السمك ده وده فراخ."},{speaker:"paco",es:"Lo siento mucho, este no es su plato. Usted pidió la trucha, ¿verdad?",ar:"أنا متأسف جدًا، ده مش طبق حضرتك. حضرتك طلبتي السمك ده، صح؟"},{speaker:"luna",es:"Sí, la trucha.",ar:"أيوه، السمك ده."},{speaker:"paco",es:"Perfecto. Se lo cambio ahora mismo. El pollo vuelve a la cocina.",ar:"جميل. حغيّرهولك دلوقتي حالًا. الفراخ حترجع المطبخ."},{speaker:"luna",es:"Gracias.",ar:"شكرًا."},{speaker:"paco",es:"En unos minutos tiene su trucha. Disculpe las molestias.",ar:"في كام دقيقة حيكون عند حضرتك طبقك. المعذرة على الإزعاج."}],questions:[{q:"الغلطة كانت إيه؟",options:["الحساب غلط","الأكل ساقع","الضيفة طلبت سمك وجالها فراخ","الترابيزة محجوزة"],answer:"الضيفة طلبت سمك وجالها فراخ",rationale:"قالت: Yo pedí la trucha y esto es pollo. trucha = نوع سمك، pollo = فراخ."},{q:"الموظف عمل إيه بالترتيب؟",options:["جدال → اعتذار","اعتذار → تأكيد الطلب الأصلي → تصحيح فوري","تجاهل → مشي","لوم المطبخ بصوت عالي"],answer:"اعتذار → تأكيد الطلب الأصلي → تصحيح فوري",rationale:"Lo siento mucho… Usted pidió la trucha, ¿verdad?… Se lo cambio ahora mismo. ahora mismo = دلوقتي حالًا."},{q:"ليه أكد الطلب الأصلي قبل التغيير؟",options:["مش مهم","عشان يضيع وقت","عشان يكتب تقرير","عشان يتأكد إنه بيصلّح للطبق الصح ومتتعملش غلطة تانية"],answer:"عشان يتأكد إنه بيصلّح للطبق الصح ومتتعملش غلطة تانية",rationale:"التأكيد بجملة واحدة بيمنع سيناريو الطبق التالت الغلط."}],responseTask:{prompt:"ضيف جاله طبق غلط. رد بالإسباني: اعتذر، أكد طلبه الأصلي، وقول إنك حتغيّره فورًا.",acceptable:["Lo siento mucho, este no es su plato. Usted pidió la trucha, ¿verdad? Se lo cambio ahora mismo.","Disculpe. Este no es su plato. Se lo cambio ahora mismo.","Lo siento mucho, este no es su plato. Se lo cambio ahora mismo.","Disculpe las molestias. Usted pidió la trucha. Ahora mismo se lo cambio."],modelEs:"Lo siento mucho, este no es su plato. Usted pidió la trucha, ¿verdad? Se lo cambio ahora mismo.",modelAr:"أنا متأسف جدًا، ده مش طبق حضرتك. حضرتك طلبتي السمك ده، صح؟ حغيّرهولك دلوقتي حالًا.",checklistAr:"راجع إجابتك: ١) اعتذار، ٢) تأكيد الطلب الأصلي، ٣) تصحيح فوري (ahora mismo)، ٤) مفيش جدال. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cambiar = يغيّر. volver a la cocina = يرجع المطبخ. Disculpe las molestias = المعذرة على الإزعاج (أخف شوية من Lo siento mucho)."}},{id:"tw-u03l06",courseId:"tourism-work",unitId:"tw-u03",sourceLessonId:null,level:"B1",register:"usted",title:"خدمة ترابيزة كاملة",context:"خدمة كاملة من أول القعود للحساب: منيو، سؤال حساسية، ترشيح، تأكيد الطلب، وحساب بطريقة الدفع. الدرس ده بيجمع الوحدة كلها في تسلسل واحد.",goal:"بعد الدرس ده حتقدر تخدم ترابيزة من أولها لآخرها بجمل إسبانية مرتبة وآمنة.",targets:[{es:"Aquí tiene la carta.",ar:"اتفضل المنيو.",speaker:"luna"},{es:"¿Tiene alguna alergia que deba saber?",ar:"عند حضرتك أي حساسية لازم أعرفها؟",speaker:"luna"},{es:"Entonces, le recomiendo la lubina.",ar:"يبقى برشّح لحضرتك السمك ده.",speaker:"luna"},{es:"¿En efectivo o con tarjeta?",ar:"كاش ولا كارت؟",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenas tardes. Aquí tiene la carta.",ar:"مساء الخير. اتفضل المنيو."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."},{speaker:"luna",es:"Antes de pedir, una pregunta. ¿Tiene alguna alergia que deba saber?",ar:"قبل ما نطلب، سؤال. عند حضرتك أي حساسية لازم أعرفها؟"},{speaker:"paco",es:"Sí, de los mariscos.",ar:"أيوه، من المحار والجمبري وده."},{speaker:"luna",es:"Gracias por decírmelo. ¿Le gusta el pescado?",ar:"شكرًا إنك قولتلي. بتحب السمك؟"},{speaker:"paco",es:"Sí, mucho.",ar:"أيوه، جدًا."},{speaker:"luna",es:"Entonces, le recomiendo la lubina. No lleva marisco. Lo confirmo con la cocina.",ar:"يبقى برشّح لحضرتك السمك ده. مفيهوش محار. حأكد مع المطبخ."},{speaker:"paco",es:"Perfecto. Ese.",ar:"جميل. ده."},{speaker:"paco",es:"…Y luego, la cuenta, por favor.",ar:"…وبعدين، الحساب لو سمحت."},{speaker:"luna",es:"Enseguida. ¿En efectivo o con tarjeta?",ar:"حالًا. كاش ولا كارت؟"}],questions:[{q:"الموظفة سألت عن الحساسية إمتى؟",options:["مسألتش","بعد ما الأكل جه","مع الحساب","قبل أخذ الطلب"],answer:"قبل أخذ الطلب",rationale:"سألت قبل أخذ الطلب: ¿Tiene alguna alergia que deba saber? — السؤال الاستباقي بيمنع مشكلة قبل ما تحصل."},{q:"الضيف عنده حساسية من إيه؟",options:["البيض","السمك","المكسرات","المحار والقشريات البحرية"],answer:"المحار والقشريات البحرية",rationale:"قال: de los mariscos = من المحار والجمبري وده. marisco = المأكولات البحرية القشرية، ودي من أشهر الحساسيات في إسبانيا."},{q:"ليه رشّحت له lubina بالذات؟",options:["أغلى طبق","الشيف قالها","عشان تخلّصه","بيحب السمك والطبق مفيهوش محار، مع مراجعة المطبخ"],answer:"بيحب السمك والطبق مفيهوش محار، مع مراجعة المطبخ",rationale:"جمعت ذوق الضيف مع قيد الحساسية، وقالت Lo confirmo con la cocina — الترشيح الأمن بيعدّي من المطبخ الأول."}],responseTask:{prompt:"افتح خدمة ترابيزة بالإسباني: منيو + سؤال حساسية استباقي.",acceptable:["Buenas tardes. Aquí tiene la carta. Antes de pedir: ¿tiene alguna alergia que deba saber?","Buenas tardes. La carta. ¿Tiene alguna alergia?","Aquí tiene la carta. ¿Tiene alguna alergia que deba saber?","Buenas tardes. Aquí tiene la carta. ¿Alguna alergia que deba saber?"],modelEs:"Buenas tardes. Aquí tiene la carta. Antes de pedir: ¿tiene alguna alergia que deba saber?",modelAr:"مساء الخير. اتفضل المنيو. قبل ما نطلب: عند حضرتك أي حساسية لازم أعرفها؟",checklistAr:"راجع إجابتك: ١) تحية + منيو، ٢) سؤال حساسية قبل الطلب، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"alguna alergia = أي حساسية. marisco = المأكولات البحرية القشرية (جمبري، محار…)."}}]},{courseId:"tourism-work",unit:{id:"tw-u04",title:"الاتجاهات والمواصلات",desc:"توصف الطريق بأوامر مهذبة، تقترح وسيلة المواصلات المناسبة، وتوجّه الضيف لمصدر المعلومة المضمون.",cefr:"A2–B1"},lessons:[{id:"tw-u04l01",courseId:"tourism-work",unitId:"tw-u04",sourceLessonId:"tw-u04l01",level:"A2",register:"usted",title:"يمين وشمال",context:"ضيفة سألت عن مكان قريب. دورك: توصف الطريق بأوامر مهذبة بصيغة حضرتك: كمّل على طول، خد يمين، خد شمال.",goal:"بعد الدرس ده حتقدر توصف طريق بسيط بثلاث جمل أساسية: siga، gire، y cruce.",targets:[{es:"Siga todo recto.",ar:"كمّلي على طول.",speaker:"paco"},{es:"Gire a la derecha.",ar:"خدي يمين.",speaker:"paco"},{es:"Gire a la izquierda.",ar:"خدي شمال.",speaker:"paco"},{es:"Está enfrente, al lado del banco.",ar:"هي قدّامك، جنب البنك.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone, ¿la farmacia?",ar:"لو سمحت، الصيدلية فين؟"},{speaker:"paco",es:"Sí, claro. Siga todo recto.",ar:"أيوه طبعًا. كمّلي على طول."},{speaker:"luna",es:"¿Recto?",ar:"على طول؟"},{speaker:"paco",es:"Sí, claro. Gire a la derecha.",ar:"أيوه طبعًا. خدي يمين."},{speaker:"luna",es:"Vale.",ar:"تمام."},{speaker:"paco",es:"Cruce la calle. Gire a la izquierda. Está enfrente, al lado del banco.",ar:"عدّي الشارع. خدي شمال. هي قدّامك، جنب البنك."},{speaker:"luna",es:"Muchas gracias.",ar:"شكرًا جدًا."}],questions:[{q:"أول اتجاه قاله الموظف؟",options:["كمّلي على طول","خدي يمين","ارجعي ورا","اطلعي فوق"],answer:"كمّلي على طول",rationale:"قال: Siga todo recto. siga = كمّل/امشي (أمر مهذب بصيغة حضرتك)، recto = على طول."},{q:"الصيدلية فين في الآخر؟",options:["قدّام الشارع، جنب البنك","جواه","في الدور التاني","بعيدة أوي"],answer:"قدّام الشارع، جنب البنك",rationale:"قال: está enfrente, al lado del banco. enfrente = قدّام، al lado de = جنب."},{q:"ليه بنستخدم siga و gire مش sigue و gira؟",options:["عشان دي صيغة الأمر المهذب بـ حضرتك المناسبة للضيوف","عشان أسرع في النطق","مفيش فرق","عشان دي عامية"],answer:"عشان دي صيغة الأمر المهذب بـ حضرتك المناسبة للضيوف",rationale:"siga/gire/cruce = أوامر usted الرسمية المهذبة. الصيغة دي هي اللي بتتقال لأي ضيف."}],responseTask:{prompt:"ضيف سأل عن مكان قريب. صف الطريق بالإسباني: على طول، وبعدين يمين، وبعدين الشارع قدّامك.",acceptable:["Siga todo recto. Luego gire a la derecha. Cruce la calle y está enfrente.","Todo recto, gire a la derecha, y está enfrente.","Siga recto. Gire a la derecha. Está enfrente.","Siga todo recto y luego gire a la derecha. Lo verá enfrente."],modelEs:"Siga todo recto. Luego gire a la derecha. Cruce la calle y está enfrente.",modelAr:"كمّل على طول. وبعدين خد يمين. عدّ الشارع وهو قدّامك.",checklistAr:"راجع إجابتك: ١) siga recto، ٢) gire + اتجاه، ٣) علامة نهاية (enfrente / al lado de)، ٤) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"recto = على طول. a la derecha = يمين، a la izquierda = شمال. cruzar = يعدّي (الشارع). enfrente = قدّام. al lado de = جنب."}},{id:"tw-u04l02",courseId:"tourism-work",unitId:"tw-u04",sourceLessonId:"tw-u04l02",level:"A2",register:"usted",title:"محطة قريبة",context:"ضيف عايز يروح محطة القطر. دورك: توصف له الطريق وتقوله المسافة تقريبًا، من غير ما تدّعي إنك خريطة (السيناريو ده خيالي).",goal:"بعد الدرس ده حتقدر توصف طريق لمحطة مواصلات مع تقدير المسافة والزمان.",targets:[{es:"La estación de tren está a diez minutos andando.",ar:"محطة القطر على بعد عشر دقايق مشي.",speaker:"luna"},{es:"¿Es fácil llegar?",ar:"سهل أوصل ليها؟",speaker:"paco"},{es:"Sí, es todo recto por esta calle.",ar:"أيوه، على طول في الشارع ده.",speaker:"luna"},{es:"Al final de la calle, gire a la izquierda.",ar:"في آخر الشارع، خد شمال.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Perdone, ¿cómo llego a la estación de tren?",ar:"لو سمحت، أروح محطة القطر إزاي؟"},{speaker:"luna",es:"La estación de tren está a diez minutos andando.",ar:"محطة القطر على بعد عشر دقايق مشي."},{speaker:"paco",es:"¿Es fácil llegar?",ar:"سهل أوصل ليها؟"},{speaker:"luna",es:"Sí, es todo recto por esta calle. Al final de la calle, gire a la izquierda.",ar:"أيوه، على طول في الشارع ده. في آخر الشارع، خد شمال."},{speaker:"paco",es:"¿Y la estación está a la izquierda?",ar:"والمحطة على الشمال؟"},{speaker:"luna",es:"No, a la derecha. La verá, es un edificio grande.",ar:"لأ، على اليمين. حتشوفها، مبنى كبير."},{speaker:"paco",es:"Perfecto, gracias.",ar:"جميل، شكرًا."}],questions:[{q:"المحطة على بعد قد إيه؟",options:["عشر دقايق مشي","نص ساعة عربية","دقيقتين","ساعة"],answer:"عشر دقايق مشي",rationale:"قالت: a diez minutos andando = على بعد عشر دقايق مشي. andando = مشي."},{q:"الطريق وصفه إيه؟",options:["معقد","على طول في الشارع ده، وفي آخره شمال","لف كتير","فوق كوبري"],answer:"على طول في الشارع ده، وفي آخره شمال",rationale:"قالت: todo recto por esta calle. Al final de la calle, gire a la izquierda. al final de = في آخر."},{q:"المحطة نفسها على أنهي ناحية؟",options:["الشمال","اليمين","ورا","جوّا"],answer:"اليمين",rationale:"قالت: a la derecha. La verá = حتشوفها (المحطة، ver = يشوف)."}],responseTask:{prompt:"ضيف سأل عن محطة قريبة. صف له الطريق بالإسباني مع المسافة مشي.",acceptable:["Está a diez minutos andando. Es todo recto por esta calle. Al final, gire a la izquierda.","A diez minutos andando. Siga recto por esta calle y gire a la izquierda al final.","Está cerca, a diez minutos andando. Todo recto y a la izquierda al final.","A unos diez minutos andando. Siga todo recto por esta calle y al final gire a la izquierda."],modelEs:"Está a diez minutos andando. Es todo recto por esta calle. Al final, gire a la izquierda.",modelAr:"على بعد عشر دقايق مشي. على طول في الشارع ده. في الآخر، خد شمال.",checklistAr:"راجع إجابتك: ١) المسافة (a … minutos andando)، ٢) وصف الطريق (recto / gire)، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"la estación de tren = محطة القطر. andando = مشي. al final de = في آخر. edificio = مبنى. La verá = حتشوفها."}},{id:"tw-u04l03",courseId:"tourism-work",unitId:"tw-u04",sourceLessonId:"tw-u04l03",level:"B1",register:"usted",title:"نختار وسيلة مناسبة",context:"ضيفة محتارة بين المشي والتاكسي والمترو. دورك: تساعدها تختار بمعلومات بسيطة، ومتوعدش بسعر تاكسي من غير ما تتأكد.",goal:"بعد الدرس ده حتقدر تقارن وسائل مواصلات للضيف وتوجّهه لمصدر السعر الصح.",targets:[{es:"¿Quiere ir andando o prefiere un taxi?",ar:"تحبي تمشي ولا تفضّلي تاكسي؟",speaker:"paco"},{es:"¿Cuánto cuesta un taxi más o menos?",ar:"التاكسي بيكلف كام تقريبًا؟",speaker:"luna"},{es:"No le puedo dar un precio seguro.",ar:"مش أقدر أديك سعر مضمون.",speaker:"paco"},{es:"El taxista le dice el precio antes de salir.",ar:"السواق حيقولك السعر قبل ما يتحرك.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Quiere ir andando o prefiere un taxi?",ar:"تحبي تمشي ولا تفضّلي تاكسي؟"},{speaker:"luna",es:"No sé. ¿Está lejos?",ar:"مش عارفة. بعيدة؟"},{speaker:"paco",es:"A veinte minutos andando. En taxi, unos cinco minutos.",ar:"عشرين دقيقة مشي. بالتاكسي، حوالي خمس دقايق."},{speaker:"luna",es:"¿Cuánto cuesta un taxi más o menos?",ar:"التاكسي بيكلف كام تقريبًا؟"},{speaker:"paco",es:"No le puedo dar un precio seguro. Depende del tráfico. El taxista le dice el precio antes de salir.",ar:"مش أقدر أديك سعر مضمون. بيختلف حسب الزحمة. السواق حيقولك السعر قبل ما يتحرك."},{speaker:"luna",es:"Vale. Entonces voy andando, que hace buen día.",ar:"تمام. يبقى حمشي، الجو حلو."},{speaker:"paco",es:"Buena idea. Le doy un plano de la zona.",ar:"فكرة حلوة. حأديك خريطة للمنطقة."}],questions:[{q:"الموظف رفض يعمل إيه؟",options:["تدّي سعر تاكسي مضمون من غير تأكيد","توصف الطريق","تدّي خريطة","تتكلم إسباني"],answer:"تدّي سعر تاكسي مضمون من غير تأكيد",rationale:"قال: No le puedo dar un precio seguro. Depende del tráfico. tráfico = زحمة. السعر الغلط بيعمل مشكلة عند الدفع."},{q:"الضيفة اختارت إيه في الآخر وليه؟",options:["التاكسي","تمشي عشان الجو حلو","المترو","تفضل في الفندق"],answer:"تمشي عشان الجو حلو",rationale:"قالت: voy andando, que hace buen día = حمشي، الجو حلو. hace buen día = الجو حلو."},{q:"إيه البديل اللي الموظف قدّمه مع المشي؟",options:["تاكسي مجاني","خريطة للمنطقة","مرافقة شخصية","مظلة"],answer:"خريطة للمنطقة",rationale:"قال: Le doy un plano de la zona = حأديك خريطة للمنطقة. plano = خريطة، zona = منطقة."}],responseTask:{prompt:"ضيف سألك سعر التاكسي وأنت مش متأكد. رد بالإسباني: مفيش سعر مضمون + مين يقوله السعر الصح.",acceptable:["No le puedo dar un precio seguro. El taxista le dice el precio antes de salir.","No puedo darle un precio seguro, depende del tráfico. Pregunte al taxista antes de salir.","No lo sé seguro. El taxista le dice el precio antes de salir.","No le puedo dar un precio exacto. Lo confirma el taxista."],modelEs:"No le puedo dar un precio seguro. El taxista le dice el precio antes de salir.",modelAr:"مش أقدر أديك سعر مضمون. السواق حيقولك السعر قبل ما يتحرك.",checklistAr:"راجع إجابتك: ١) مفيش سعر مخترع (no…seguro)، ٢) سبب بسيط أو بديل (taxista)، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"más o menos = تقريبًا. depender de = يعتمد على. antes de salir = قبل ما يتحرك. hace buen día = الجو حلو."}},{id:"tw-u04l04",courseId:"tourism-work",unitId:"tw-u04",sourceLessonId:null,level:"A2",register:"usted",title:"فين أقرب…؟",context:"ضيف بيسأل عن أماكن أساسية: حمّام، سوبرماركت، صراف آلي. دورك: تجاوب بمكان واضح مع علامة معروفة.",goal:"بعد الدرس ده حتقدر تجاوب على أسئلة «فين أقرب…؟» بعلامات واضحة: جنب، قدّام، ورا، في نفس الشارع.",targets:[{es:"¿Dónde está el baño?",ar:"فين الحمّام؟",speaker:"paco"},{es:"Está al fondo, a la derecha.",ar:"في الآخر، على اليمين.",speaker:"luna"},{es:"Hay un supermercado en esta misma calle.",ar:"فيه سوبرماركت في نفس الشارع ده.",speaker:"luna"},{es:"¿Hay un cajero cerca?",ar:"فيه صراف آلي قريب؟",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Perdone, una pregunta. ¿Dónde está el baño?",ar:"لو سمحت، سؤال. فين الحمّام؟"},{speaker:"luna",es:"Está al fondo, a la derecha. Junto a las escaleras.",ar:"في الآخر، على اليمين. جنب السلم."},{speaker:"paco",es:"Gracias. ¿Y hay un supermercado cerca?",ar:"شكرًا. وفيه سوبرماركت قريب؟"},{speaker:"luna",es:"Sí. Hay un supermercado en esta misma calle. Enfrente de la farmacia.",ar:"أيوه. فيه سوبرماركت في نفس الشارع ده. قدّام الصيدلية."},{speaker:"paco",es:"¿Hay un cajero cerca?",ar:"فيه صراف آلي قريب؟"},{speaker:"luna",es:"Hay uno dentro del supermercado.",ar:"فيه واحد جوّا السوبرماركت."},{speaker:"paco",es:"Perfecto.",ar:"جميل."}],questions:[{q:"الحمّام فين؟",options:["برّه المكان","في الدور التاني","في الآخر على اليمين، جنب السلم","جنب الباب"],answer:"في الآخر على اليمين، جنب السلم",rationale:"قالت: al fondo, a la derecha, junto a las escaleras. al fondo = في الآخر، escaleras = سلم."},{q:"السوبرماركت فين بالظبط؟",options:["في المحطة","بعيد أوي","في نفس الشارع، قدّام الصيدلية","فوق الفندق"],answer:"في نفس الشارع، قدّام الصيدلية",rationale:"قالت: en esta misma calle, enfrente de la farmacia. misma = نفسها، enfrente de = قدّام."},{q:"الصراف الآلي فين؟",options:["مفيش","في البنك بس","جوّا السوبرماركت","في الشارع التالت"],answer:"جوّا السوبرماركت",rationale:"قالت: Hay uno dentro del supermercado. dentro de = جوّا."}],responseTask:{prompt:"ضيف سأل: فين الحمّام؟ وفيه صراف آلي قريب؟ جاوب بالإسباني بعلامات واضحة.",acceptable:["El baño está al fondo, a la derecha. Y hay un cajero dentro del supermercado, enfrente de la farmacia.","El baño está al fondo a la derecha, junto a las escaleras. El cajero está dentro del supermercado de enfrente.","Al fondo, a la derecha. Y hay un cajero en el supermercado de esta calle.","El baño está al fondo, a la derecha. Hay un cajero cerca, dentro del supermercado."],modelEs:"El baño está al fondo, a la derecha. Y hay un cajero dentro del supermercado, enfrente de la farmacia.",modelAr:"الحمّام في الآخر، على اليمين. وفيه صراف آلي جوّا السوبرماركت، قدّام الصيدلية.",checklistAr:"راجع إجابتك: ١) مكان الحمّام بعلامة (al fondo / junto a)، ٢) مكان الصراف (hay un cajero + مكان)، ٣) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"al fondo = في الآخر. junto a = جنب. dentro de = جوّا. enfrente de = قدّام. hay = فيه/يوجد. cajero = صراف آلي."}},{id:"tw-u04l05",courseId:"tourism-work",unitId:"tw-u04",sourceLessonId:null,level:"B1",register:"usted",title:"التذاكر والمواصلات العامة",context:"ضيفة عايزة تستعمل الأوتوبيس أو المترو. دورك: تقولها فين تشتري التذكرة وتوجّهها لمصدر المعلومة الرسمي لو مش متأكد من التفاصيل.",goal:"بعد الدرس ده حتقدر تشرح أساسيات المواصلات العامة وتوجّه الضيف لمصدر المعلومة المضمون.",targets:[{es:"¿Dónde puedo comprar el billete?",ar:"أقدر أشتري التذكرة منين؟",speaker:"luna"},{es:"El billete se compra en la máquina de la parada.",ar:"التذكرة بتتشترى من الماكينة اللي عند الموقف.",speaker:"paco"},{es:"No sé el precio exacto.",ar:"مش عارف السعر بالظبط.",speaker:"paco"},{es:"Lo puede confirmar en la web oficial de transporte.",ar:"تقدري تتأكدي منه على الموقع الرسمي للمواصلات.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone, quiero ir al centro en autobús. ¿Dónde puedo comprar el billete?",ar:"لو سمحت، عايزة أروح وسط البلد بالأوتوبيس. أقدر أشتري التذكرة منين؟"},{speaker:"paco",es:"El billete se compra en la máquina de la parada. La parada está a dos minutos, saliendo a la derecha.",ar:"التذكرة بتتشترى من الماكينة اللي عند الموقف. الموقف على بعد دقيقتين، خدي يمين وأنتي طالعة."},{speaker:"luna",es:"¿Cuánto cuesta el billete?",ar:"التذكرة بكام؟"},{speaker:"paco",es:"No sé el precio exacto. Lo puede confirmar en la web oficial de transporte. O en la propia máquina.",ar:"مش عارف السعر بالظبط. تقدري تتأكدي منه على الموقع الرسمي للمواصلات. أو في الماكينة نفسها."},{speaker:"luna",es:"Vale. ¿Y qué línea cojo?",ar:"تمام. وأخد خط أنهي؟"},{speaker:"paco",es:"El doce. Pregunte al conductor si tiene dudas.",ar:"اتناشر. واسألي السواق لو عندك شك."},{speaker:"luna",es:"Muchas gracias.",ar:"شكرًا جدًا."}],questions:[{q:"التذكرة بتتشترى منين؟",options:["من السواق بس","من الفندق","من ماكينة عند الموقف","من الصيدلية"],answer:"من ماكينة عند الموقف",rationale:"قال: en la máquina de la parada. máquina = ماكينة، parada = موقف."},{q:"ليه الموظف مقالش سعر التذكرة؟",options:["عشان مش فاهمة السؤال","عشان السعر سر","عشان مش متأكدة ووجّهت للموقع الرسمي والماكينة","عشان التذكرة ببلاش"],answer:"عشان مش متأكدة ووجّهت للموقع الرسمي والماكينة",rationale:"قال: No sé el precio exacto ووجّه للـ web oficial والماكينة. السعر بيتغير، والمصدر الرسمي أضمن."},{q:"الخط المطلوب رقمه كام؟",options:["٧","٢","٢٠","١٢"],answer:"١٢",rationale:"قال: El doce = اتناشر. conductor = سواق."}],responseTask:{prompt:"ضيف سألك: أشتري تذكرة الأوتوبيس منين وبكام؟ وأنت عارف المكان بس مش متأكد من السعر. جاوب بالإسباني.",acceptable:["El billete se compra en la máquina de la parada. No sé el precio exacto, lo puede confirmar en la web oficial o en la máquina.","Se compra en la máquina de la parada. Del precio exacto no estoy seguro; confírmelo en la máquina o en la web oficial.","En la máquina de la parada. No sé el precio exacto; lo confirma en la web oficial de transporte.","El billete se compra en la máquina de la parada. El precio exacto no lo sé, pero la máquina lo muestra."],modelEs:"El billete se compra en la máquina de la parada. No sé el precio exacto, lo puede confirmar en la web oficial o en la máquina.",modelAr:"التذكرة بتتشترى من ماكينة الموقف. مش عارف السعر بالظبط، تقدر تتأكد منه من الموقع الرسمي أو من الماكينة.",checklistAr:"راجع إجابتك: ١) مكان الشراء (máquina / parada)، ٢) اعتراف بحدود معلوماتك (no sé exacto)، ٣) توجيه لمصدر مضمون (web oficial / máquina). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"billete = تذكرة. parada = موقف. máquina = ماكينة. conductor = سواق. propio = نفسه (في الماكينة نفسها)."}},{id:"tw-u04l06",courseId:"tourism-work",unitId:"tw-u04",sourceLessonId:null,level:"B1",register:"usted",title:"طريق كامل من الأول للآخر",context:"ضيف عايز يروح المتحف من الفندق. دورك: توصف الطريق كامل: اخرج من الفندق، امشي، اعمل تحويلة، ووصّله لحد الباب.",goal:"بعد الدرس ده حتقدر تدي وصف طريق كامل متسلسل بثقة، من أول خطوة لحد الوصول.",targets:[{es:"Saliendo del hotel, gire a la derecha.",ar:"وأنت طالع من الفندق، خد يمين.",speaker:"luna"},{es:"Siga recto hasta el semáforo.",ar:"كمّل على طول لحد الإشارة.",speaker:"luna"},{es:"En el semáforo, cruce y gire a la izquierda.",ar:"عند الإشارة، عدّ وخد شمال.",speaker:"luna"},{es:"El museo está a cinco minutos de aquí.",ar:"المتحف على بعد خمس دقايق من هنا.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Perdone, ¿cómo llego al museo?",ar:"لو سمحت، أروح المتحف إزاي؟"},{speaker:"luna",es:"Muy fácil. El museo está a cinco minutos de aquí. Saliendo del hotel, gire a la derecha.",ar:"سهل جدًا. المتحف على بعد خمس دقايق من هنا. وأنت طالع من الفندق، خد يمين."},{speaker:"paco",es:"A la derecha. Vale.",ar:"يمين. تمام."},{speaker:"luna",es:"Siga recto hasta el semáforo.",ar:"كمّل على طول لحد الإشارة."},{speaker:"paco",es:"¿Hasta el semáforo?",ar:"لحد الإشارة؟"},{speaker:"luna",es:"Sí. En el semáforo, cruce y gire a la izquierda. El museo es el edificio blanco de la esquina.",ar:"أيوه. عند الإشارة، عدّ وخد شمال. المتحف هو المبنى الأبيض اللي على الناصية."},{speaker:"paco",es:"Perfecto. Derecha, recto hasta el semáforo, cruzo y a la izquierda.",ar:"جميل. يمين، على طول لحد الإشارة، أعدّي وشمال."},{speaker:"luna",es:"Eso es. No tiene pérdida.",ar:"بالظبط. الطريق مش هيتلخبط."}],questions:[{q:"أول خطوة في الطريق؟",options:["تنزل تحت","تركب أوتوبيس","تعدّ الإشارة الأول","تاخد يمين وأنت طالع من الفندق"],answer:"تاخد يمين وأنت طالع من الفندق",rationale:"قالت: Saliendo del hotel, gire a la derecha. saliendo = وأنت طالع."},{q:"المتحف شكله إيه؟",options:["محطة قديمة","مبنى أحمر كبير","برج عالي","المبنى الأبيض اللي على الناصية"],answer:"المبنى الأبيض اللي على الناصية",rationale:"قالت: el edificio blanco de la esquina. blanco = أبيض، esquina = ناصية."},{q:"إيه معنى No tiene pérdida؟",options:["ممنوع الضحك","مفيش خسارة فلوس","المتحف مقفول","الطريق مش هيتلخبط / سهل تلاقيه"],answer:"الطريق مش هيتلخبط / سهل تلاقيه",rationale:"تعبير شائع معناه إنك مستحيل تتوه في الطريق ده. جملة طمأنة لطيفة في آخر أي وصف طريق."}],responseTask:{prompt:"ضيف سأل عن طريق مكان قريب. ادي له وصف كامل بالإسباني: أول خطوة + تحويلة + علامة الوصول.",acceptable:["Saliendo del hotel, gire a la derecha. Siga recto hasta el semáforo. En el semáforo, cruce y gire a la izquierda. Es el edificio blanco de la esquina.","Gire a la derecha al salir. Siga recto hasta el semáforo, cruce y gire a la izquierda. Allí está, el edificio blanco.","Saliendo, a la derecha. Todo recto hasta el semáforo. Cruce, gire a la izquierda y lo verá.","Saliendo del hotel, gire a la derecha, siga recto hasta el semáforo, cruce y gire a la izquierda."],modelEs:"Saliendo del hotel, gire a la derecha. Siga recto hasta el semáforo. En el semáforo, cruce y gire a la izquierda. Es el edificio blanco de la esquina.",modelAr:"وأنت طالع من الفندق، خد يمين. كمّل على طول لحد الإشارة. عند الإشارة، عدّ وخد شمال. هو المبنى الأبيض اللي على الناصية.",checklistAr:"راجع إجابتك: ١) بداية واضحة (saliendo / gire)، ٢) نقطة وسطى (hasta el semáforo)، ٣) علامة وصول (edificio / esquina)، ٤) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"hasta = لحد. semáforo = إشارة مرور. esquina = ناصية. No tiene pérdida = الطريق مش هيتلخبط (تعبير شائع للطمأنة)."}}]},{courseId:"tourism-work",unit:{id:"tw-u05",title:"المعالم وجدول الرحلة",desc:"توصف معلم بجمل بسيطة، تقول وقت البداية والمدة، وتدير تجمع المجموعة وإحاطة الجولة من الأول للآخر.",cefr:"A2–B1"},lessons:[{id:"tw-u05l01",courseId:"tourism-work",unitId:"tw-u05",sourceLessonId:"tw-u05l01",level:"A2",register:"usted",title:"نشرح المكان ببساطة",context:"ضيفة سألت عن معلم من معالم المدينة. دورك: توصفه بجمل بسيطة، ولو مش متأكد من معلومة، تقول إنك حتراجعها بدل ما تخترعها.",goal:"بعد الدرس ده حتقدر توصف معلم سياحي بجمل قصيرة واضحة، وتتعامل بأمانة مع سؤال مش عارف إجابته.",targets:[{es:"Es un palacio muy antiguo.",ar:"ده قصر قديم جدًا.",speaker:"paco"},{es:"Es el edificio más famoso de la ciudad.",ar:"ده أشهر مبنى في المدينة.",speaker:"paco"},{es:"¿De qué siglo es?",ar:"من قرن كام؟",speaker:"luna"},{es:"No estoy seguro. Lo confirmo ahora.",ar:"مش متأكد. حأكدها دلوقتي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone, ¿qué es este edificio?",ar:"لو سمحت، المبنى ده إيه؟"},{speaker:"paco",es:"Es un palacio muy antiguo. Es el edificio más famoso de la ciudad.",ar:"ده قصر قديم جدًا. ده أشهر مبنى في المدينة."},{speaker:"luna",es:"¡Qué bonito! ¿De qué siglo es?",ar:"جميل أوي! من قرن كام؟"},{speaker:"paco",es:"No estoy seguro. Lo confirmo ahora.",ar:"مش متأكد. حأكدها دلوقتي."},{speaker:"luna",es:"Gracias.",ar:"شكرًا."},{speaker:"paco",es:"Del siglo dieciséis. Tiene casi quinientos años.",ar:"من القرن السادس عشر. عمره حوالي خمسمية سنة."},{speaker:"luna",es:"¡Increíble!",ar:"مش معقول!"}],questions:[{q:"الموظف وصف المبنى بإيه؟",options:["قصر قديم وأشهر مبنى في المدينة","متحف حديث اتفتح من سنة","كنيسة صغيرة من القرن اللي فات","سوق قديم للحاجات التقليدية"],answer:"قصر قديم وأشهر مبنى في المدينة",rationale:"قال: un palacio muy antiguo… el edificio más famoso de la ciudad. palacio = قصر، famoso = مشهور."},{q:"لما اتسأل عن القرن، عمل إيه؟",options:["قال مش متأكد وأكّد المعلومة","اخترع رقم قرن من دماغه","غيّر الموضوع لحاجة تانية","قال للضيفة تدور على المعلومة بنفسها"],answer:"قال مش متأكد وأكّد المعلومة",rationale:"قال: No estoy seguro. Lo confirmo ahora. siglo = قرن. التخمين في معلومة تاريخية بيضيّع ثقة الضيف."},{q:"القصر عمره قد إيه تقريبًا؟",options:["حوالي خمسمية سنة","حوالي مية سنة","حوالي خمسين سنة","حوالي ألف سنة"],answer:"حوالي خمسمية سنة",rationale:"قال: Del siglo dieciséis. Tiene casi quinientos años. siglo = قرن، casi = حوالي."}],responseTask:{prompt:"ضيف سألك عن عمر مبنى وأنت مش متأكد. رد بالإسباني: اعترف + قول إنك حتأكد + ارجع بالمعلومة.",acceptable:["No estoy seguro. Lo confirmo ahora con mi compañero. … Es del siglo dieciséis.","No estoy seguro, lo confirmo con mi compañero. Es del siglo dieciséis.","No lo sé seguro. Lo confirmo ahora. Tiene casi quinientos años.","No estoy seguro. Un momento, lo confirmo. … Es del siglo dieciséis."],modelEs:"No estoy seguro. Lo confirmo ahora con mi compañero. … Es del siglo dieciséis.",modelAr:"مش متأكد. حأكدها دلوقتي مع زميلي. … من القرن السادس عشر.",checklistAr:"راجع إجابتك: ١) اعتراف (no estoy seguro)، ٢) وعد مراجعة (lo confirmo)، ٣) رجوع بالمعلومة المؤكدة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"siglo = قرن. antiguo = قديم. famoso = مشهور. casi = حوالي. tener…años = عمره…سنة."}},{id:"tw-u05l02",courseId:"tourism-work",unitId:"tw-u05",sourceLessonId:"tw-u05l02",level:"A2",register:"usted",title:"وقت البداية والمدة",context:"ضيف حابب يعرف الرحلة بتبدأ امتى وبتاخد قد إيه. دورك: تجاوب بوقت واضح ومدة واضحة: بتبدأ الساعة عشرة، ومدتها ساعة ونص.",goal:"بعد الدرس ده حتقدر تقول وقت البداية والمدة بالإسباني من غير لخبطة: a las diez، dura una hora y media.",targets:[{es:"¿A qué hora empieza la visita?",ar:"الزيارة بتبدأ الساعة كام؟",speaker:"paco"},{es:"Empieza a las diez.",ar:"بتبدأ الساعة عشرة.",speaker:"luna"},{es:"¿Cuánto dura?",ar:"بتاخد قد إيه؟",speaker:"paco"},{es:"Dura una hora y media.",ar:"مدتها ساعة ونص.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Perdone, una pregunta. ¿A qué hora empieza la visita?",ar:"لو سمحت، سؤال. الزيارة بتبدأ الساعة كام؟"},{speaker:"luna",es:"Empieza a las diez.",ar:"بتبدأ الساعة عشرة."},{speaker:"paco",es:"¿Cuánto dura?",ar:"بتاخد قد إيه؟"},{speaker:"luna",es:"Dura una hora y media.",ar:"مدتها ساعة ونص."},{speaker:"paco",es:"¿Entonces termina a las once y media?",ar:"يبقى بتخلص الساعة حداشر ونص؟"},{speaker:"luna",es:"Eso es. Y hay otra visita a las doce.",ar:"بالظبط. وفيه زيارة تانية الساعة اتناشر."},{speaker:"paco",es:"Vale, gracias.",ar:"تمام، شكرًا."}],questions:[{q:"الزيارة بتبدأ امتى؟",options:["الساعة عشرة","الساعة اتناشر","الساعة تسعة","الساعة حداشر ونص"],answer:"الساعة عشرة",rationale:"قالت: Empieza a las diez. empezar = يبدأ."},{q:"مدة الزيارة قد إيه؟",options:["ساعة ونص","ساعتين","نص ساعة","تلات ساعات"],answer:"ساعة ونص",rationale:"قالت: Dura una hora y media. durar = يستغرق، y media = ونص."},{q:"الضيف عمل إيه عشان يتأكد؟",options:["مشى من غير ما يسأل عن حاجة","حسب وقت النهاية بنفسه وسأل للتأكيد","سأل عن سعر التذكرة مرة تانية","طلب يلغي الزيارة خالص"],answer:"حسب وقت النهاية بنفسه وسأل للتأكيد",rationale:"قال: ¿Entonces termina a las once y media? terminar = يخلص. التأكيد بالتكرار بيمنع سوء الفهم."}],responseTask:{prompt:"ضيف سأل: الرحلة بتبدأ امتى وبتاخد قد إيه؟ جاوب بالإسباني بوقت ومدة واضحين (أي وقت ومدة منطقيين).",acceptable:["Empieza a las diez y dura una hora y media.","La visita empieza a las diez. Dura una hora y media.","Empieza a las diez y dura dos horas.","Empieza a las nueve y dura una hora."],modelEs:"Empieza a las diez y dura una hora y media.",modelAr:"بتبدأ الساعة عشرة ومدتها ساعة ونص.",checklistAr:"راجع إجابتك: ١) وقت بداية (a las…)، ٢) مدة (dura…)، ٣) أرقام إسبانية صحيحة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"empezar = يبدأ. terminar = يخلص. durar = يستغرق. y media = ونص. y cuarto = وربع."}},{id:"tw-u05l03",courseId:"tourism-work",unitId:"tw-u05",sourceLessonId:"tw-u05l03",level:"B1",register:"usted",title:"التجمّع والتعليمات",context:"قبل بدء الجولة، دورك: تقول للمجموعة مكان التجمع ووقته وتدّي تعليمات بسيطة (التعليمات دي للتدريب — كل مكان ليه قواعده).",goal:"بعد الدرس ده حتقدر تعلن مكان ووقت التجمع وتدّي تعليمات المجموعة بصيغة الجمع المهذبة.",targets:[{es:"Nos reunimos aquí a las nueve y media.",ar:"بنتجمّع هنا الساعة تسعة ونص.",speaker:"paco"},{es:"Por favor, lleguen cinco minutos antes.",ar:"لو سمحت، تعالوا قبلها بخمس دقايق.",speaker:"paco"},{es:"No se separen del grupo.",ar:"متبعدوش عن المجموعة.",speaker:"paco"},{es:"¿Alguna pregunta antes de empezar?",ar:"أي سؤال قبل ما نبدأ؟",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días a todos. Nos reunimos aquí a las nueve y media.",ar:"صباح الخير للكل. بنتجمّع هنا الساعة تسعة ونص."},{speaker:"luna",es:"¿Aquí, enfrente de la entrada?",ar:"هنا، قدّام المدخل؟"},{speaker:"paco",es:"Eso es. Por favor, lleguen cinco minutos antes.",ar:"بالظبط. لو سمحت، تعالوا قبلها بخمس دقايق."},{speaker:"luna",es:"¿Podemos hacer fotos dentro?",ar:"ممكن نصوّر جوّا؟"},{speaker:"paco",es:"En esta visita de práctica, sí. Y una cosa más. No se separen del grupo.",ar:"في الزيارة التدريبية دي، أيوه. وحاجة كمان. متبعدوش عن المجموعة."},{speaker:"luna",es:"Entendido.",ar:"فاهمين."},{speaker:"paco",es:"¿Alguna pregunta antes de empezar?",ar:"أي سؤال قبل ما نبدأ؟"},{speaker:"luna",es:"No, todo claro.",ar:"لأ، كل حاجة واضحة."}],questions:[{q:"التجمع امتى وفين؟",options:["الساعة عشرة، في المحطة","الساعة تسعة ونص، قدّام المدخل","الساعة تسعة بالظبط، جوّا المتحف","الساعة تمنية، في الفندق"],answer:"الساعة تسعة ونص، قدّام المدخل",rationale:"قال: aquí a las nueve y media وأكّد enfrente de la entrada. entrada = مدخل."},{q:"التعليمات الأساسية كانت إيه؟",options:["ممنوع الكلام خالص جوّا قاعات المتحف كلها بالمرة","تعالوا قبلها بخمس دقايق ومتبعدوش عن المجموعة","الحقوني بسرعة على الباب","مفيش أي تعليمات مهمة"],answer:"تعالوا قبلها بخمس دقايق ومتبعدوش عن المجموعة",rationale:"قال: lleguen cinco minutos antes و no se separen del grupo. separarse = يبعد."},{q:"ليه قال «في الزيارة التدريبية دي، أيوه» عن التصوير؟",options:["عشان التصوير ممنوع في كل الأماكن السياحية من غير أي استثناء خالص","عشان قواعد التصوير بتختلف من مكان لمكان وده سيناريو تدريب","عشانه مش فاهم السؤال أصلًا ومحتاج حد يترجمهوله","عشان كاميرا المكان مكسورة"],answer:"عشان قواعد التصوير بتختلف من مكان لمكان وده سيناريو تدريب",rationale:"قال: En esta visita de práctica, sí. قواعد التصوير ملهاش قاعدة عامة — كل معلم ليه نظامه."}],responseTask:{prompt:"قول لمجموعة سياح بالإسباني: التجمع هنا الساعة تسعة ونص + تعالوا قبلها بخمس دقايق + متبعدوش عن المجموعة.",acceptable:["Nos reunimos aquí a las nueve y media. Por favor, lleguen cinco minutos antes. Y no se separen del grupo.","Nos reunimos aquí a las nueve y media. Lleguen cinco minutos antes, por favor, y no se separen del grupo.","Aquí a las nueve y media. Lleguen cinco minutos antes. No se separen del grupo.","Nos reunimos aquí a las nueve y media, lleguen cinco minutos antes y no se separen del grupo."],modelEs:"Nos reunimos aquí a las nueve y media. Por favor, lleguen cinco minutos antes. Y no se separen del grupo.",modelAr:"بنتجمّع هنا الساعة تسعة ونص. لو سمحت، تعالوا قبلها بخمس دقايق. ومتبعدوش عن المجموعة.",checklistAr:"راجع إجابتك: ١) مكان ووقت التجمع (nos reunimos + a las…)، ٢) طلب الحضور بدري (lleguen…antes)، ٣) تعليمة المجموعة (no se separen)، ٤) صيغة جمع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"reunirse = يتجمّع. lleguen = تعالوا (أمر جمع مهذب). antes = قبل. separarse = يبعد. entrada = مدخل."}},{id:"tw-u05l04",courseId:"tourism-work",unitId:"tw-u05",sourceLessonId:null,level:"A2",register:"usted",title:"إيه اللي حنشوفه؟",context:"ضيفة عايزة تعرف الجولة بتشمل إيه. دورك: تعدّد أهم المحطات بجمل بسيطة من غير مبالغة.",goal:"بعد الدرس ده حتقدر تلخص برنامج جولة: بنزور كذا، وبعدين كذا، وفي الآخر كذا.",targets:[{es:"¿Qué vamos a ver?",ar:"حنشوف إيه؟",speaker:"luna"},{es:"Primero visitamos el casco antiguo.",ar:"الأول بنزور المدينة القديمة.",speaker:"paco"},{es:"Después vemos la catedral.",ar:"وبعدين بنشوف الكاتدرائية.",speaker:"paco"},{es:"Al final, tiempo libre en la plaza.",ar:"في الآخر، وقت حر في الميدان.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone, una pregunta. ¿Qué vamos a ver?",ar:"لو سمحت، سؤال. حنشوف إيه؟"},{speaker:"paco",es:"Primero visitamos el casco antiguo.",ar:"الأول بنزور المدينة القديمة."},{speaker:"luna",es:"¿Y después?",ar:"وبعدين؟"},{speaker:"paco",es:"Después vemos la catedral. Es el punto más importante de la ruta.",ar:"وبعدين بنشوف الكاتدرائية. دي أهم محطة في الجولة."},{speaker:"luna",es:"¿Y al final?",ar:"وفي الآخر؟"},{speaker:"paco",es:"Al final, tiempo libre en la plaza. Unos veinte minutos.",ar:"في الآخر، وقت حر في الميدان. حوالي عشرين دقيقة."},{speaker:"luna",es:"Perfecto.",ar:"جميل."}],questions:[{q:"أول محطة في الجولة؟",options:["الميدان","الكاتدرائية الكبيرة","المدينة القديمة","المتحف"],answer:"المدينة القديمة",rationale:"قال: Primero visitamos el casco antiguo. casco antiguo = المدينة القديمة (تعبير ثابت في إسبانيا)."},{q:"أهم محطة في الجولة؟",options:["السوق","الميدان","الكاتدرائية","الفندق الكبير"],answer:"الكاتدرائية",rationale:"قال: la catedral. Es el punto más importante de la ruta. ruta = جولة/مسار."},{q:"الجولة بتنتهي بإيه؟",options:["رجوع فوري للفندق بالأوتوبيس","غدا جماعي كامل في مطعم المدينة القديمة","وقت حر في الميدان حوالي عشرين دقيقة","تسوق إجباري في السوق"],answer:"وقت حر في الميدان حوالي عشرين دقيقة",rationale:"قال: Al final, tiempo libre en la plaza. Unos veinte minutos. tiempo libre = وقت حر."}],responseTask:{prompt:"ضيف سأل: حنشوف إيه في الجولة؟ لخّص برنامج من تلات محطات بالإسباني (أي محطات منطقية).",acceptable:["Primero visitamos el casco antiguo. Después vemos la catedral. Al final, tiempo libre en la plaza.","Primero el casco antiguo, después la catedral, y al final tiempo libre en la plaza.","Vamos a ver primero el casco antiguo, después la catedral y al final la plaza.","Primero visitamos la catedral. Después vemos el museo. Al final, tiempo libre."],modelEs:"Primero visitamos el casco antiguo. Después vemos la catedral. Al final, tiempo libre en la plaza.",modelAr:"الأول بنزور المدينة القديمة. وبعدين بنشوف الكاتدرائية. في الآخر، وقت حر في الميدان.",checklistAr:"راجع إجابتك: ١) ترتيب واضح (primero / después / al final)، ٢) تلات محطات، ٣) أفعال الجمع (visitamos / vemos). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"primero = الأول. después = بعدين. al final = في الآخر. casco antiguo = المدينة القديمة. tiempo libre = وقت حر."}},{id:"tw-u05l05",courseId:"tourism-work",unitId:"tw-u05",sourceLessonId:null,level:"B1",register:"usted",title:"أسئلة الزيارة العملية",context:"ضيف بيسأل أسئلة عملية قبل الزيارة: في سلالم كتير؟ ينفع مع عربية أطفال؟ فيه دورة مياه؟ دورك: تجاوب بصدق وتقترح بديل لو في مانع.",goal:"بعد الدرس ده حتقدر تجاوب على أسئلة الوصول والراحة، وتقترح حل عملي لما تكون الإجابة لأ.",targets:[{es:"¿Hay muchas escaleras?",ar:"فيه سلالم كتير؟",speaker:"luna"},{es:"La subida es un poco dura.",ar:"الطلعة شاقة شوية.",speaker:"paco"},{es:"Hay un ascensor para quien lo necesite.",ar:"فيه أسانسير للي محتاجه.",speaker:"paco"},{es:"¿Puedo ir con el carrito del bebé?",ar:"ينفع أدخل بعربية البيبي؟",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Perdone, una pregunta. ¿Hay muchas escaleras? Mi madre viene con nosotros.",ar:"لو سمحت، سؤال. فيه سلالم كتير؟ ماما جاية معانا."},{speaker:"paco",es:"La subida es un poco dura. Pero tranquila. Hay un ascensor para quien lo necesite.",ar:"الطلعة شاقة شوية. بس متقلقيش. فيه أسانسير للي محتاجه."},{speaker:"luna",es:"Ah, bien. ¿Puedo ir con el carrito del bebé?",ar:"آه، تمام. ينفع أدخل بعربية البيبي؟"},{speaker:"paco",es:"Sí, en esta ruta sí. Es llana.",ar:"أيوه، في المسار ده ينفع. هو مستوي."},{speaker:"luna",es:"¿Y hay baños dentro?",ar:"وفيه حمّامات جوّا؟"},{speaker:"paco",es:"Sí, junto a la entrada.",ar:"أيوه، جنب المدخل."},{speaker:"luna",es:"Genial, gracias.",ar:"برافو، شكرًا."}],questions:[{q:"الضيفة سألت عن السلالم ليه؟",options:["عشان خايفة من العلالي","عشان بتحب الرياضة","عشان ماما جاية معاها","عشان رجليها بتوجعها"],answer:"عشان ماما جاية معاها",rationale:"قالت: Mi madre viene con nosotros. السؤال العملي وراه سبب إنساني — لازم إجابة صادقة مش مجاملة."},{q:"إيه الحل اللي الموظف اقترحه للطلعة الشاقة؟",options:["تتشجع وتطلع على رجليها","تلغي الزيارة خالص أحسن","فيه أسانسير للي محتاجه","مفيش أي حل متاح"],answer:"فيه أسانسير للي محتاجه",rationale:"قال: hay un ascensor para quien lo necesite. ascensor = أسانسير. الإجابة الصادقة + البديل أحسن من «لا سهلة» الكاذبة."},{q:"عربية البيبي تنفع ليه؟",options:["عشان المكان ضيق","عشان ممنوعة","عشان فيه سلالم كتير","عشان المسار مستوي"],answer:"عشان المسار مستوي",rationale:"قال: en esta ruta sí. Es llana. llano = مستوي (مفيهوش مطالع)."}],responseTask:{prompt:"ضيف سأل: فيه سلالم كتير؟ جاوب بالإسباني بصدق + اقترح بديل عملي.",acceptable:["La subida es un poco dura, pero hay un ascensor para quien lo necesite.","Hay algunas escaleras, pero hay un ascensor para quien lo necesite.","Sí, la subida es dura. Hay un ascensor para quien lo necesite.","La subida es un poco dura. Hay un ascensor y también un banco para descansar."],modelEs:"La subida es un poco dura, pero hay un ascensor para quien lo necesite.",modelAr:"الطلعة شاقة شوية، بس فيه أسانسير للي محتاجه.",checklistAr:"راجع إجابتك: ١) إجابة صادقة (dura / escaleras)، ٢) بديل عملي (ascensor)، ٣) نبرة مطمئنة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"escaleras = سلالم. subida = طلعة. duro = شاق. ascensor = أسانسير. carrito del bebé = عربية البيبي. llano = مستوي."}},{id:"tw-u05l06",courseId:"tourism-work",unitId:"tw-u05",sourceLessonId:null,level:"B1",register:"usted",title:"إحاطة جولة كاملة",context:"قبل ما الجولة تبدأ، دورك: تدّي إحاطة كاملة: الترحيب، البرنامج، الوقت، والتعليمات — في دقيقة واحدة.",goal:"بعد الدرس ده حتقدر تفتتح جولة بإحاطة متكاملة ومنظمة، وتختم بسؤال مفتوح للمجموعة.",targets:[{es:"Bienvenidos a la visita del casco antiguo.",ar:"أهلًا بيكم في جولة المدينة القديمة.",speaker:"paco"},{es:"La visita dura unas dos horas.",ar:"الجولة حوالي ساعتين.",speaker:"paco"},{es:"Haremos tres paradas principales.",ar:"حنعمل تلات وقفات أساسية.",speaker:"paco"},{es:"Si tienen alguna pregunta, me la hacen en cualquier momento.",ar:"لو عندكم أي سؤال، اسألوني في أي وقت.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días. Bienvenidos a la visita del casco antiguo.",ar:"صباح الخير. أهلًا بيكم في جولة المدينة القديمة."},{speaker:"paco",es:"La visita dura unas dos horas. Haremos tres paradas principales. La muralla, la catedral y la plaza.",ar:"الجولة حوالي ساعتين. حنعمل تلات وقفات أساسية. السور، والكاتدرائية، والميدان."},{speaker:"luna",es:"¿Hay tiempo para fotos?",ar:"فيه وقت للتصوير؟"},{speaker:"paco",es:"Sí, en cada parada hay unos minutos libres.",ar:"أيوه، في كل وقفة فيه دقايق حرة."},{speaker:"luna",es:"¿Y dónde terminamos?",ar:"وبنخلّص فين؟"},{speaker:"paco",es:"Aquí mismo, en esta plaza. Si tienen alguna pregunta, me la hacen en cualquier momento.",ar:"هنا بالظبط، في الميدان ده. لو عندكم أي سؤال، اسألوني في أي وقت."},{speaker:"luna",es:"Perfecto, empecemos.",ar:"جميل، يلا نبدأ."}],questions:[{q:"وقفات الجولة التلاتة؟",options:["المحطة، والفندق، والمطعم","المتحف، والسوق، والميناء","القصر، والحديقة، والبرج","السور، والكاتدرائية، والميدان"],answer:"السور، والكاتدرائية، والميدان",rationale:"قال: la muralla, la catedral y la plaza. muralla = سور، parada = وقفة."},{q:"وقت التصوير إزاي متظبط؟",options:["التصوير مسموح في الآخر بس","ممنوع التصوير نهائي","ساعة كاملة مخصصة للتصوير","دقايق حرة في كل وقفة"],answer:"دقايق حرة في كل وقفة",rationale:"قال: en cada parada hay unos minutos libres. cada = كل."},{q:"الجولة بتخلص فين؟",options:["قدّام باب الكاتدرائية","في الفندق اللي نازلين فيه","عند محطة القطر المركزية","في نفس الميدان اللي بدأوا منه"],answer:"في نفس الميدان اللي بدأوا منه",rationale:"قال: Aquí mismo, en esta plaza. mismo = نفسه."}],responseTask:{prompt:"افتتح جولة بإحاطة قصيرة بالإسباني: ترحيب + المدة + عدد الوقفات + دعوة للأسئلة.",acceptable:["Bienvenidos a la visita del casco antiguo. La visita dura unas dos horas. Haremos tres paradas principales. Si tienen alguna pregunta, me la hacen en cualquier momento.","Buenos días y bienvenidos. La visita dura unas dos horas, con tres paradas principales. Si tienen preguntas, me las hacen en cualquier momento.","Bienvenidos. Dura unas dos horas y haremos tres paradas. Cualquier pregunta, me la hacen en cualquier momento.","Bienvenidos a la visita. Son unas dos horas y haremos tres paradas principales. Si tienen alguna pregunta, aquí estoy."],modelEs:"Bienvenidos a la visita del casco antiguo. La visita dura unas dos horas. Haremos tres paradas principales. Si tienen alguna pregunta, me la hacen en cualquier momento.",modelAr:"أهلًا بيكم في جولة المدينة القديمة. الجولة حوالي ساعتين. حنعمل تلات وقفات أساسية. لو عندكم أي سؤال، اسألوني في أي وقت.",checklistAr:"راجع إجابتك: ١) ترحيب (bienvenidos)، ٢) المدة (dura…)، ٣) الوقفات (paradas)، ٤) دعوة للأسئلة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"parada = وقفة. muralla = سور. en cualquier momento = في أي وقت. haremos = حنعمل (مستقبل بصيغة الجمع)."}}]},{courseId:"tourism-work",unit:{id:"tw-u06",title:"الحجوزات والتذاكر والأسعار",desc:"تاخد بيانات الحجز، تقول السعر والشامل بصدق، ومتقولش اتأكد غير لما يتثبت فعلًا.",cefr:"A2–B1"},lessons:[{id:"tw-u06l01",courseId:"tourism-work",unitId:"tw-u06",sourceLessonId:"tw-u06l01",level:"A2",register:"usted",title:"تفاصيل الحجز",context:"ضيفة عايزة تحجز تذاكر لمعرض. دورك: تسأل عن اليوم وعدد الأشخاص، وتفتكر إن السؤال عن التوفر مش حجز مؤكد.",goal:"بعد الدرس ده حتقدر تاخد بيانات حجز أساسية: اليوم، العدد، والاسم.",targets:[{es:"¿Para qué día lo quiere?",ar:"لأنهي يوم؟",speaker:"paco"},{es:"¿Para cuántas personas?",ar:"لعدد كام شخص؟",speaker:"paco"},{es:"Para dos personas.",ar:"لشخصين.",speaker:"luna"},{es:"¿Me dice su nombre, por favor?",ar:"ممكن تقوليلي اسمك، لو سمحت؟",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenos días. Quiero entradas para la exposición.",ar:"صباح الخير. عايزة تذاكر للمعرض."},{speaker:"paco",es:"Claro. ¿Para qué día lo quiere?",ar:"طبعًا. لأنهي يوم؟"},{speaker:"luna",es:"Para el jueves.",ar:"ليوم الخميس."},{speaker:"paco",es:"¿Para cuántas personas?",ar:"لعدد كام شخص؟"},{speaker:"luna",es:"Para dos personas.",ar:"لشخصين."},{speaker:"paco",es:"Muy bien. ¿Me dice su nombre, por favor?",ar:"تمام. ممكن تقوليلي اسمك، لو سمحت؟"},{speaker:"luna",es:"Luna García.",ar:"لونا جارسيا."}],questions:[{q:"الضيفة عايزة تذاكر لأنهي يوم؟",options:["الخميس","الجمعة","النهارده","السبت"],answer:"الخميس",rationale:"قالت: Para el jueves. jueves = الخميس."},{q:"عدد التذاكر المطلوب؟",options:["اتنين","تلاتة","واحدة","أربعة"],answer:"اتنين",rationale:"قالت: Para dos personas. personas = أشخاص."},{q:"ليه السؤال عن اليوم والعدد مهم قبل أي وعد؟",options:["عشان السؤال عن التوفر مش معناه إن الحجز اتأكد","عشان البروتوكول الشكلي بس","عشان نملّي وقت المكالمة","مش مهم، السؤال كفاية"],answer:"عشان السؤال عن التوفر مش معناه إن الحجز اتأكد",rationale:"بيانات الحجز (اليوم والعدد والاسم) هي اللي بيبني عليها التأكيد. من غيرها مفيش حجز أصلًا."}],responseTask:{prompt:"ضيف عايز يحجز تذاكر. اسأله بالإسباني عن اليوم والعدد والاسم.",acceptable:["¿Para qué día lo quiere? ¿Para cuántas personas? ¿Me dice su nombre, por favor?","¿Para qué día? ¿Cuántas personas son? ¿Su nombre, por favor?","¿Para qué día lo quiere y para cuántas personas? ¿Me dice su nombre?","¿Qué día le viene bien? ¿Para cuántas personas? ¿Su nombre, por favor?"],modelEs:"¿Para qué día lo quiere? ¿Para cuántas personas? ¿Me dice su nombre, por favor?",modelAr:"لأنهي يوم؟ لعدد كام شخص؟ ممكن تقولي اسمك، لو سمحت؟",checklistAr:"راجع إجابتك: ١) سؤال اليوم (para qué día)، ٢) سؤال العدد (cuántas personas)، ٣) سؤال الاسم بأدب، ٤) صيغة حضرتك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"entrada = تذكرة. exposición = معرض. jueves = الخميس. para + عدد + personas = لعدد… أشخاص."}},{id:"tw-u06l02",courseId:"tourism-work",unitId:"tw-u06",sourceLessonId:"tw-u06l02",level:"A2",register:"usted",title:"السعر والشامل",context:"ضيف سأل عن سعر التذكرة وإيه اللي شاملها. دورك: تقول السعر بوضوح (الأسعار هنا للتدريب) وتشرح الشامل والمش شامل.",goal:"بعد الدرس ده حتقدر تقول سعر وتفصّل اللي بيشمله: la entrada incluye…، no incluye…",targets:[{es:"¿Cuánto cuesta la entrada?",ar:"التذكرة بكام؟",speaker:"paco"},{es:"La entrada cuesta doce euros.",ar:"التذكرة باتناشر يورو.",speaker:"luna"},{es:"¿Qué incluye?",ar:"شاملة إيه؟",speaker:"paco"},{es:"Incluye la visita guiada.",ar:"شاملة الجولة مع مرشد.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Perdone, una pregunta. ¿Cuánto cuesta la entrada?",ar:"لو سمحت، سؤال. التذكرة بكام؟"},{speaker:"luna",es:"La entrada cuesta doce euros.",ar:"التذكرة باتناشر يورو."},{speaker:"paco",es:"¿Qué incluye?",ar:"شاملة إيه؟"},{speaker:"luna",es:"Incluye la visita guiada. No incluye la audioguía, que son tres euros más.",ar:"شاملة الجولة مع مرشد. مش شاملة السماعة، دي تلاتة يورو زيادة."},{speaker:"paco",es:"¿Y para los niños?",ar:"وللأطفال؟"},{speaker:"luna",es:"Menores de doce años, gratis.",ar:"أقل من اتناشر سنة، ببلاش."},{speaker:"paco",es:"Vale. Dos entradas, por favor.",ar:"تمام. تذكرتين لو سمحت."}],questions:[{q:"سعر التذكرة؟",options:["اتناشر يورو","عشرة يورو","تلاتة يورو","عشرين يورو"],answer:"اتناشر يورو",rationale:"قالت: cuesta doce euros. doce = اتناشر."},{q:"التذكرة مش شاملة إيه؟",options:["السماعة، دي تلاتة يورو زيادة","الجولة مع المرشد نفسها","دخول الأطفال الصغيرين","الضريبة المحلية على التذكرة"],answer:"السماعة، دي تلاتة يورو زيادة",rationale:"قالت: No incluye la audioguía, que son tres euros más. audioguía = سماعة الشرح، más = زيادة."},{q:"الأطفال أقل من اتناشر سنة بيدفعوا كام؟",options:["نص السعر","ببلاش","السعر كامل","تلاتة يورو"],answer:"ببلاش",rationale:"قالت: Menores de doce años, gratis. menores = أقل من السن، gratis = ببلاش."}],responseTask:{prompt:"ضيف سأل عن السعر والشامل. جاوب بالإسباني: سعر + حاجة شاملة + حاجة مش شاملة (أي أرقام منطقية).",acceptable:["La entrada cuesta doce euros. Incluye la visita guiada. No incluye la audioguía.","Cuesta doce euros. Incluye la visita guiada, pero no incluye la audioguía.","Son doce euros. Incluye la visita guiada. La audioguía no está incluida.","La entrada cuesta quince euros. Incluye la visita guiada. No incluye la comida."],modelEs:"La entrada cuesta doce euros. Incluye la visita guiada. No incluye la audioguía.",modelAr:"التذكرة باتناشر يورو. شاملة الجولة مع مرشد. مش شاملة السماعة.",checklistAr:"راجع إجابتك: ١) السعر (cuesta…euros)، ٢) الشامل (incluye)، ٣) المش شامل (no incluye). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"costar = يكلّف. incluir = يشمل. visita guiada = جولة مع مرشد. audioguía = سماعة الشرح. gratis = ببلاش. menores = الأقل من السن."}},{id:"tw-u06l03",courseId:"tourism-work",unitId:"tw-u06",sourceLessonId:"tw-u06l03",level:"B1",register:"usted",title:"التوفر والتأكيد",context:"ضيف عايز يتأكد إن حجزه ثابت. دورك: متقولش «اتأكد» غير لما النظام يثبته فعلًا، ولو لسه، قوله الخطوة الجاية بوضوح.",goal:"بعد الدرس ده حتقدر تفرّق بين «هراجع التوفر» و«الحجز مؤكد»، وتقول كل واحدة في وقتها.",targets:[{es:"Déjeme comprobar la disponibilidad.",ar:"استنى أراجع التوفر.",speaker:"luna"},{es:"¿Está confirmado?",ar:"اتأكد؟",speaker:"paco"},{es:"Todavía no. Estoy comprobándolo.",ar:"لسه. براجعه دلوقتي.",speaker:"luna"},{es:"Listo. Su reserva está confirmada.",ar:"خلاص. حجز حضرتك اتأكد.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Quiero una mesa para cuatro, mañana a las nueve.",ar:"عايز ترابيزة لأربعة، بكرة الساعة تسعة."},{speaker:"luna",es:"Déjeme comprobar la disponibilidad.",ar:"استنى أراجع التوفر."},{speaker:"paco",es:"¿Está confirmado?",ar:"اتأكد؟"},{speaker:"luna",es:"Todavía no. Estoy comprobándolo.",ar:"لسه. براجعه دلوقتي."},{speaker:"paco",es:"Vale, espero.",ar:"تمام، حستنى."},{speaker:"luna",es:"Listo. Su reserva está confirmada. Mesa para cuatro, mañana a las nueve.",ar:"خلاص. حجز حضرتك اتأكد. ترابيزة لأربعة، بكرة الساعة تسعة."},{speaker:"paco",es:"Perfecto, gracias.",ar:"جميل، شكرًا."}],questions:[{q:"الضيف سأل «اتأكد؟» بدري، والموظفة ردت بإيه؟",options:["أيوه، أكيد اتأكد من زمان","لسه. براجعه دلوقتي","مش عارفة أي حاجة عنه","بكرة حنعرف النتيجة"],answer:"لسه. براجعه دلوقتي",rationale:"قالت: Todavía no. Estoy comprobándolo. todavía no = لسه. كلمة «اتأكد» ليها معنى: ماتتقالش قبل ما النظام يثبت."},{q:"التأكيد النهائي اتقال إزاي؟",options:["ماشي تقريبًا كده تمام","خلاص. حجز حضرتك اتأكد + تكرار التفاصيل","المفروض يبقى كل حاجة تمام","اتفقنا شفوي وبس"],answer:"خلاص. حجز حضرتك اتأكد + تكرار التفاصيل",rationale:"قالت: Listo. Su reserva está confirmada وكررت التفاصيل (أربعة، بكرة، تسعة). التكرار بيقفل سوء الفهم."},{q:"إيه الفرق بين comprobar و confirmar؟",options:["الاتنين نفس المعنى بالظبط","comprobar = يراجع، confirmar = يؤكد — المراجعة قبل التأكيد","comprobar = يدفع الحساب","confirmar = يلغي الحجز"],answer:"comprobar = يراجع، confirmar = يؤكد — المراجعة قبل التأكيد",rationale:"comprobar la disponibilidad = يراجع التوفر. estar confirmada = يكون مؤكد. الترتيب مهم: مراجعة، بعدين تأكيد."}],responseTask:{prompt:"ضيف ضاغط: اتأكد الحجز؟ وانت لسه بتراجع. رد بالإسباني: لسه + براجع + استنى لحظة.",acceptable:["Todavía no. Estoy comprobándolo. Un momento, por favor.","Todavía no, estoy comprobando la disponibilidad. Un momento.","No todavía. Lo estoy comprobando ahora. Un momento, por favor.","Todavía no. Estoy comprobándolo y enseguida le confirmo."],modelEs:"Todavía no. Estoy comprobándolo. Un momento, por favor.",modelAr:"لسه. براجعه دلوقتي. لحظة لو سمحت.",checklistAr:"راجع إجابتك: ١) «لسه» (todavía no) من غير كذبة، ٢) المراجعة جارية (estoy comprobando)، ٣) طلب انتظار مهذب. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"todavía no = لسه. comprobar = يراجع/يتأكد من. disponibilidad = توفر. reserva = حجز. listo = خلاص/جاهز."}},{id:"tw-u06l04",courseId:"tourism-work",unitId:"tw-u06",sourceLessonId:null,level:"A2",register:"usted",title:"تغيير حجز",context:"ضيفة عندها حجز وعايزة تغيّره من الخميس للجمعة. دورك: تاخد بيانات الحجز الحالي، تراجع المتاح، وتأكد التغيير الجديد.",goal:"بعد الدرس ده حتقدر تدير تغيير حجز قائم: مراجعة البيانات القديمة، اقتراح البديل، وتأكيد الجديد.",targets:[{es:"¿Puedo cambiar mi reserva?",ar:"ينفع أغيّر حجزي؟",speaker:"luna"},{es:"¿Para qué día lo tiene ahora?",ar:"حجزك دلوقتي لأنهي يوم؟",speaker:"paco"},{es:"Lo cambio al viernes.",ar:"حغيّره ليوم الجمعة.",speaker:"paco"},{es:"Su reserva queda para el viernes.",ar:"حجزك بقى يوم الجمعة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenas. ¿Puedo cambiar mi reserva?",ar:"صباح الخير. ينفع أغيّر حجزي؟"},{speaker:"paco",es:"Claro. ¿Para qué día lo tiene ahora?",ar:"طبعًا. حجزك دلوقتي لأنهي يوم؟"},{speaker:"luna",es:"Para el jueves, a nombre de Luna García.",ar:"ليوم الخميس، باسم لونا جارسيا."},{speaker:"paco",es:"Vale, lo tengo. ¿Qué día le viene mejor?",ar:"تمام، لاقيه. أنهي يوم يناسبك أكتر؟"},{speaker:"luna",es:"El viernes, si es posible.",ar:"الجمعة، لو ينفع."},{speaker:"paco",es:"Hay sitio. Lo cambio al viernes. Su reserva queda para el viernes. A la misma hora.",ar:"فيه مكان. حغيّره ليوم الجمعة. حجزك بقى يوم الجمعة. نفس المعاد."},{speaker:"luna",es:"Muchas gracias.",ar:"شكرًا جدًا."}],questions:[{q:"الحجز الأصلي كان لأنهي يوم؟",options:["الأربعاء","الجمعة","الخميس","السبت"],answer:"الخميس",rationale:"قالت: Para el jueves, a nombre de Luna García."},{q:"التغيير تم لأنهي يوم وبأنهي شرط؟",options:["الخميس، من غير تغيير","السبت، بمعاد مختلف","الجمعة، بنفس المعاد","أي يوم"],answer:"الجمعة، بنفس المعاد",rationale:"قال: Su reserva queda para el viernes, a la misma hora. quedar = يستقر/يبقى."},{q:"إيه أول حاجة الموظف عملها؟",options:["رفض التغيير من الأساس","غيّر اليوم على طول من غير سؤال","أكّد بيانات الحجز الحالي قبل التغيير","طلب رسوم زيادة على التغيير"],answer:"أكّد بيانات الحجز الحالي قبل التغيير",rationale:"قال: ¿Para qué día lo tiene ahora? وVale, lo tengo. لازم تلاقي الحجز القديم قبل ما تغيّره."}],responseTask:{prompt:"ضيف عايز يغيّر حجزه ليوم تاني. دير المحادثة من جهتك بالإسباني: تأكيد الحجز الحالي + التغيير + تأكيد الجديد.",acceptable:["¿Para qué día lo tiene ahora? … Vale, lo tengo. Lo cambio al viernes. Su reserva queda para el viernes.","¿Qué día tiene ahora? … Lo cambio al viernes. Su reserva queda para el viernes.","¿Me dice su nombre? … Lo tengo. Lo cambio al viernes, queda para el viernes.","¿Para qué día lo tiene? … Hay sitio. Lo cambio al viernes. Queda para el viernes."],modelEs:"¿Para qué día lo tiene ahora? … Vale, lo tengo. Lo cambio al viernes. Su reserva queda para el viernes.",modelAr:"حجزك دلوقتي لأنهي يوم؟ … تمام، لاقيه. حغيّره ليوم الجمعة. حجزك بقى يوم الجمعة.",checklistAr:"راجع إجابتك: ١) تثبّت من الحجز الحالي، ٢) تنفيذ التغيير (lo cambio)، ٣) تأكيد الحالة الجديدة (queda para…). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cambiar = يغيّر. a nombre de = باسم. quedar = يستقر/يبقى (queda para el viernes = بقى يوم الجمعة). si es posible = لو ينفع."}},{id:"tw-u06l05",courseId:"tourism-work",unitId:"tw-u06",sourceLessonId:null,level:"B1",register:"usted",title:"إلغاء مهذب",context:"ضيف عايز يلغي حجزه. دورك: تتم الإلغاء باحتراف من غير ضغط، وتسأل لو حابب يحجز معاد تاني، وتتجنب أي وعد بفلوس مش من صلاحيتك.",goal:"بعد الدرس ده حتقدر تدير إلغاء حجز بلباقة وتعرض البدائل المتاحة بس.",targets:[{es:"¿Quiere cancelar la reserva?",ar:"عايز تلغي الحجز؟",speaker:"paco"},{es:"Sí, no podemos venir.",ar:"أيوه، مش حنقدر نيجي.",speaker:"luna"},{es:"Queda cancelada.",ar:"اتلغى.",speaker:"paco"},{es:"¿Quiere que le busque otra fecha?",ar:"تحبي أدورلك على معاد تاني؟",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días, ¿en qué le ayudo?",ar:"صباح الخير، أساعدك في إيه؟"},{speaker:"luna",es:"Tengo una reserva para mañana y quiero cancelarla.",ar:"عندي حجز لبكرة وعايزة ألغيه."},{speaker:"paco",es:"Entendido. ¿Quiere cancelar la reserva? ¿Me dice su nombre?",ar:"فاهم. عايزة تلغي الحجز؟ ممكن تقوليلي اسمك؟"},{speaker:"luna",es:"Luna García. Sí, no podemos venir.",ar:"لونا جارسيا. أيوه، مش حنقدر نيجي."},{speaker:"paco",es:"No pasa nada. Queda cancelada.",ar:"ولا يهمك. اتلغى."},{speaker:"luna",es:"¿Me llega alguna confirmación?",ar:"حيوصلني تأكيد؟"},{speaker:"paco",es:"Sí, le llega un correo. ¿Quiere que le busque otra fecha?",ar:"أيوه، حيوصلك إيميل. تحبي أدورلك على معاد تاني؟"},{speaker:"luna",es:"No, gracias. Ya llamaré.",ar:"لأ، شكرًا. حتصل أنا."}],questions:[{q:"سبب الإلغاء؟",options:["المكان بعيد جدًا عنهم","السعر غالي","مش حيقدروا ييجوا","الحجز غلط"],answer:"مش حيقدروا ييجوا",rationale:"قالت: no podemos venir. الموظف مسألش ليه — الإلغاء حق، مش محتاج تبرير."},{q:"الموظف أكّد الإلغاء بإيه؟",options:["حنشوف الموضوع بعدين","ممكن نلغي، مش متأكد","Queda cancelada — جملة قصيرة حاسمة","اتفضلي املي فورم الإلغاء الأول وبعدين نتكلم"],answer:"Queda cancelada — جملة قصيرة حاسمة",rationale:"قال: No pasa nada. Queda cancelada. طمأنة + تأكيد رسمي في سطرين."},{q:"العرض الإضافي اللي قدمه الموظف؟",options:["فلوس ترجع فورًا","خصم خمسين في المية","ترقية مجانية","يدور على معاد تاني"],answer:"يدور على معاد تاني",rationale:"قال: ¿Quiere que le busque otra fecha? عرض معاد بديل خدمة كويسة؛ وعد استرداد فلوس مش من صلاحيته فمتعاهش."}],responseTask:{prompt:"ضيف ألغى حجزه. رد بالإسباني: طمأنة + تأكيد الإلغاء + عرض معاد بديل.",acceptable:["No pasa nada. Queda cancelada. ¿Quiere que le busque otra fecha?","No se preocupe. Queda cancelada. ¿Le busco otra fecha?","No pasa nada. Su reserva queda cancelada. ¿Quiere otra fecha?","Entendido. Queda cancelada. Si quiere, le busco otra fecha."],modelEs:"No pasa nada. Queda cancelada. ¿Quiere que le busque otra fecha?",modelAr:"ولا يهمك. اتلغى. تحب أدورلك على معاد تاني؟",checklistAr:"راجع إجابتك: ١) طمأنة (no pasa nada)، ٢) تأكيد الإلغاء (queda cancelada)، ٣) عرض بديل (otra fecha)، ٤) من غير وعود فلوس. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cancelar = يلغي. No pasa nada = ولا يهمك. fecha = معاد/تاريخ. ya llamaré = حتصل (بعدين)."}},{id:"tw-u06l06",courseId:"tourism-work",unitId:"tw-u06",sourceLessonId:null,level:"B1",register:"usted",title:"حجز كامل من التليفون",context:"مكالمة حجز كاملة: الضيفة عايزة ترابيزة، وأنت بتاخد اليوم والعدد والساعة والاسم، بتراجع التوفر، وبتأكد في الآخر.",goal:"بعد الدرس ده حتقدر تدير مكالمة حجز كاملة بترتيب صح: بيانات، مراجعة، تأكيد، ختام.",targets:[{es:"Quisiera reservar una mesa para el sábado.",ar:"عايزة أحجز ترابيزة ليوم السبت.",speaker:"luna"},{es:"¿A qué hora lo prefiere?",ar:"الساعة كام تفضّليه؟",speaker:"paco"},{es:"Le apunto para las dos.",ar:"حسجّلك الساعة اتنين.",speaker:"paco"},{es:"Queda reservado a su nombre.",ar:"اتحجز باسمك.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Restaurante Miraflores, buenos días.",ar:"مطعم ميرافلوريس، صباح الخير."},{speaker:"luna",es:"Buenos días. Quisiera reservar una mesa para el sábado.",ar:"صباح الخير. عايزة أحجز ترابيزة ليوم السبت."},{speaker:"paco",es:"Con mucho gusto. ¿Para cuántas personas?",ar:"بكل سرور. لعدد كام شخص؟"},{speaker:"luna",es:"Para cinco.",ar:"لخمسة."},{speaker:"paco",es:"¿A qué hora lo prefiere?",ar:"الساعة كام تفضّليه؟"},{speaker:"luna",es:"Sobre las dos, si hay sitio.",ar:"حوالي الساعة اتنين، لو فيه مكان."},{speaker:"paco",es:"Déjeme mirar… Sí, hay sitio. Le apunto para las dos. ¿A nombre de quién?",ar:"استني أبص… أيوه، فيه مكان. حسجّلك الساعة اتنين. باسم مين؟"},{speaker:"luna",es:"A nombre de Luna García.",ar:"باسم لونا جارسيا."},{speaker:"paco",es:"Queda reservado a su nombre. Cinco personas, el sábado a las dos.",ar:"اتحجز باسمك. خمسة أفراد، السبت الساعة اتنين."},{speaker:"luna",es:"Perfecto. Muchas gracias.",ar:"جميل. شكرًا جدًا."}],questions:[{q:"الحجز: كام فرد، أنهي يوم، والساعة كام؟",options:["تنين، السبت، الساعة اتناشر","أربعة، الجمعة، الساعة تسعة","خمسة، الحد، الساعة تلاتة","خمسة، السبت، الساعة اتنين"],answer:"خمسة، السبت، الساعة اتنين",rationale:"قال في التأكيد: Cinco personas, el sábado a las dos. التأكيد النهائي بيعيد كل التفاصيل."},{q:"الموظف أكّد التوفر امتى؟",options:["في مكالمة تانية بكرة","قبل ما يسمع الطلب كله","من غير أي مراجعة","بعد ما راجع («استني أبص… فيه مكان»)، مش قبلها"],answer:"بعد ما راجع («استني أبص… فيه مكان»)، مش قبلها",rationale:"قال: Déjeme mirar… Sí, hay sitio. الوعد جه بعد المراجعة — زي قاعدة الوحدة كلها."},{q:"«Quisiera reservar» أدبها في إيه؟",options:["زمن ماضي بعيد","صيغة أمر مباشر للموظف","غلطة نحوية شائعة","صيغة طلب مهذبة أرقى من quiero في مكالمات الحجز"],answer:"صيغة طلب مهذبة أرقى من quiero في مكالمات الحجز",rationale:"quisiera = عايز بصيغة مهذبة (زي «كنت حابب»). مناسبة جدًا للتليفون والحجوزات."}],responseTask:{prompt:"مكالمة حجز: خد الطلب كامل بالإسباني — العدد، الساعة، الاسم — وراجع التوفر قبل التأكيد.",acceptable:["¿Para cuántas personas? ¿A qué hora lo prefiere? … Sí, hay sitio. Le apunto para las dos. ¿A nombre de quién? … Queda reservado a su nombre.","¿Cuántas personas son? ¿A qué hora? … Hay sitio. ¿Su nombre? … Queda reservado.","¿Para cuántas personas y a qué hora? … Déjeme mirar… hay sitio. ¿A nombre de quién? … Queda reservado a su nombre.","¿Cuántas personas? ¿A qué hora lo prefiere? … Hay sitio, le apunto. ¿Su nombre? … Reservado a su nombre."],modelEs:"¿Para cuántas personas? ¿A qué hora lo prefiere? … Sí, hay sitio. Le apunto para las dos. ¿A nombre de quién? … Queda reservado a su nombre.",modelAr:"لعدد كام شخص؟ الساعة كام تفضّليه؟ … أيوه، فيه مكان. حسجّلك الساعة اتنين. باسم مين؟ … اتحجز باسمك.",checklistAr:"راجع إجابتك: ١) سؤال العدد والساعة، ٢) مراجعة قبل الوعد (hay sitio بعد mirar)، ٣) الاسم (a nombre de quién)، ٤) تأكيد نهائي بالتفاصيل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"quisiera = عايز بأدب. apuntar = يسجّل. sobre las dos = حوالي الساعة اتنين. hay sitio = فيه مكان. queda reservado = اتحجز."}}]},{courseId:"tourism-work",unit:{id:"tw-u07",title:"الشكاوى والمفقودات",desc:"تستقبل الشكوى باعتذار صادق من غير وعود، تسجل بلاغ مفقودات بدقة، وتقفل بخطوة عملية بزمن محدد.",cefr:"B1"},lessons:[{id:"tw-u07l01",courseId:"tourism-work",unitId:"tw-u07",sourceLessonId:"tw-u07l01",level:"B1",register:"usted",title:"اعتذار وفهم المشكلة",context:"ضيف زعلان لأن أوضته مش جاهزة. دورك: تعتذر وتفهم المشكلة من غير وعود — التعاطف مش وعد بحل.",goal:"بعد الدرس ده حتقدر تعتذر بصدق وتلخص مشكلة الضيف بكلماتك من غير ما تلزم نفسك بحل مش في إيدك.",targets:[{es:"Lo siento mucho.",ar:"أنا آسف جدًا.",speaker:"paco"},{es:"Entiendo que esto es un problema para usted.",ar:"فاهم إن ده مشكل لحضرتك.",speaker:"paco"},{es:"A ver si lo entiendo bien.",ar:"خليني أتأكد إني فاهم صح.",speaker:"paco"},{es:"La habitación no está lista todavía.",ar:"الأوضة لسه مش جاهزة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Llevo media hora esperando y mi habitación no está lista.",ar:"لي نص ساعة مستنية وأوضتي لسه مش جاهزة."},{speaker:"paco",es:"Lo siento mucho. Entiendo que esto es un problema para usted.",ar:"أنا آسف جدًا. فاهم إن ده مشكل لحضرتك."},{speaker:"luna",es:"Es que estoy muy cansada del viaje.",ar:"أنا تعبانة أوي من السفر."},{speaker:"paco",es:"Lo entiendo. A ver si lo entiendo bien. La habitación no está lista todavía. Y usted lleva esperando media hora.",ar:"فاهمك. خليني أتأكد إني فاهم صح. الأوضة لسه مش جاهزة. وحضرتك مستنياها من نص ساعة."},{speaker:"luna",es:"Eso es.",ar:"بالظبط."},{speaker:"paco",es:"Voy a ver qué puedo hacer. Un momento, por favor.",ar:"حشوف أقدر أعمل إيه. لحظة لو سمحت."},{speaker:"luna",es:"Vale, gracias.",ar:"تمام، شكرًا."}],questions:[{q:"شكوى الضيفة؟",options:["مستنية من نص ساعة والأوضة مش جاهزة","الأوضة وسخة ومش متنضفة","السعر طالع غلط في الفاتورة","الواي فاي مش شغال من الصبح"],answer:"مستنية من نص ساعة والأوضة مش جاهزة",rationale:"قالت: Llevo media hora esperando y mi habitación no está lista. llevar + زمن = لي/ليها مدة بيعمل حاجة."},{q:"الموظف لخّص المشكلة ليه؟",options:["عشان يتأكد إنه فاهم صح قبل ما يتصرف","عشان يضيّع وقت لحد ما الأوضة تجهز","عشان يلوم الضيفة على التأخير","عشان يتجنب الاعتذار الرسمي"],answer:"عشان يتأكد إنه فاهم صح قبل ما يتصرف",rationale:"قال: A ver si lo entiendo bien وكرر المشكلة. التلخيص بيمنع حل المشكلة الغلط."},{q:"الموظف وعد بإيه في الآخر؟",options:["حيشوف يقدر يعمل إيه — من غير وعد محدد","أوضة جديدة حتجهز في الحال","فلوس الليلة دي حترجع أكيد","ترقية مجانية لأوضة أكبر وأحسن"],answer:"حيشوف يقدر يعمل إيه — من غير وعد محدد",rationale:"قال: Voy a ver qué puedo hacer. التعاطف والمراجعة مسموحين؛ الوعد المحدد لازم يكون مضمون."}],responseTask:{prompt:"ضيف زعلان من مشكلة. رد بالإسباني: اعتذار + تفهّم + تلخيص للمشكلة من غير وعد.",acceptable:["Lo siento mucho. Entiendo que esto es un problema para usted. A ver si lo entiendo bien: la habitación no está lista todavía.","Lo siento mucho. Lo entiendo. La habitación no está lista todavía, ¿verdad? Voy a ver qué puedo hacer.","Lo siento. Entiendo el problema. A ver: usted lleva media hora esperando y la habitación no está lista.","Lo siento mucho. Entiendo que es un problema. A ver si lo entiendo bien: lleva media hora esperando."],modelEs:"Lo siento mucho. Entiendo que esto es un problema para usted. A ver si lo entiendo bien: la habitación no está lista todavía.",modelAr:"أنا آسف جدًا. فاهم إن ده مشكل لحضرتك. خليني أتأكد إني فاهم صح: الأوضة لسه مش جاهزة.",checklistAr:"راجع إجابتك: ١) اعتذار (lo siento)، ٢) تفهّم (entiendo)، ٣) تلخيص المشكلة بكلماتك، ٤) من غير وعد بحل محدد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"entender = يفهم. todavía no = لسه مش. llevar + وقت = بقاله/بقاها مدة. cansado = تعبان. a ver = خلينا نشوف."}},{id:"tw-u07l02",courseId:"tourism-work",unitId:"tw-u07",sourceLessonId:"tw-u07l02",level:"B1",register:"usted",title:"حاجة ضاعت",context:"ضيف ضاع منه شنطته في المطار. دورك: تاخد وصف دقيق وآخر مكان شافه فيه، وتسجل البيانات من غير ما توعد بلقاها.",goal:"بعد الدرس ده حتقدر تسجل بلاغ مفقودات: وصف، مكان، وقت، وبيانات تواصل.",targets:[{es:"¿Me describe la maleta?",ar:"ممكن توصفيلي الشنطة؟",speaker:"paco"},{es:"Es negra, grande, con una etiqueta azul.",ar:"سودا، كبيرة، عليها بطاقة زرقا.",speaker:"luna"},{es:"¿Dónde la vio por última vez?",ar:"آخر مرة شفتها فين؟",speaker:"paco"},{es:"Anoto sus datos y le avisamos.",ar:"حسجّل بياناتك وحنبلّغك.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone, no encuentro mi maleta.",ar:"لو سمحت، شنطتي مش لاقيها."},{speaker:"paco",es:"Lo siento. ¿Me describe la maleta?",ar:"آسف. ممكن توصفيلي الشنطة؟"},{speaker:"luna",es:"Es negra, grande, con una etiqueta azul.",ar:"سودا، كبيرة، عليها بطاقة زرقا."},{speaker:"paco",es:"¿Dónde la vio por última vez?",ar:"آخر مرة شفتها فين؟"},{speaker:"luna",es:"En la cinta de equipaje, hace veinte minutos.",ar:"على سير الشنط، من عشرين دقيقة."},{speaker:"paco",es:"Vale. Anoto sus datos y le avisamos. En cuanto sepamos algo, claro.",ar:"تمام. حسجّل بياناتك وحنبلّغك. أول ما نعرف حاجة طبعًا."},{speaker:"luna",es:"Gracias. Es que están mis medicinas dentro.",ar:"شكرًا. أدويتي جواها."},{speaker:"paco",es:"Lo entiendo. Lo marco como urgente.",ar:"فاهمك. حعلّمها كعاجلة."}],questions:[{q:"وصف الشنطة؟",options:["سودا، كبيرة، عليها بطاقة زرقا","حمرا، صغيرة، من غير بطاقة","زرقا، متوسطة، بعجلات","شنطة ظهر رياضية"],answer:"سودا، كبيرة، عليها بطاقة زرقا",rationale:"قالت: negra, grande, con una etiqueta azul. etiqueta = بطاقة/ليبل."},{q:"آخر مكان ووقت؟",options:["سير الشنط، من عشرين دقيقة","على الأوتوبيس، من ساعة كاملة","في الفندق، من امبارح بالليل","في الكافيه، من خمس دقايق بس"],answer:"سير الشنط، من عشرين دقيقة",rationale:"قالت: En la cinta de equipaje, hace veinte minutos. cinta de equipaje = سير الشنط، hace = من (زمن فات)."},{q:"الموظف وعد بيلاقي الشنطة؟",options:["أيوه، متقلقيش حتلاقيها بكرة الصبح","لأ — سجّل البيانات ووعد بالإبلاغ أول ما يعرف","أيوه، حتلاقيها موجودة دلوقتي حالًا","قال مستحيل الشنطة دي تتلاقى"],answer:"لأ — سجّل البيانات ووعد بالإبلاغ أول ما يعرف",rationale:"قال: Anoto sus datos y le avisamos. En cuanto sepamos algo, claro. en cuanto = أول ما. الوعد هنا على المتابعة، مش على النتيجة."}],responseTask:{prompt:"ضيف فقد حاجة. خد بلاغ كامل بالإسباني: وصف + آخر مكان + طمأنة إنك حتبلّغه.",acceptable:["¿Me describe la maleta? … ¿Dónde la vio por última vez? … Anoto sus datos y le avisamos en cuanto sepamos algo.","Descríbala, por favor. ¿Dónde la vio por última vez? Anoto sus datos y le avisamos.","¿Cómo es la maleta? ¿Dónde la vio por última vez? Anoto sus datos y le avisamos en cuanto sepamos algo.","¿Me la describe? ¿Cuándo la vio por última vez? Le avisamos en cuanto sepamos algo."],modelEs:"¿Me describe la maleta? … ¿Dónde la vio por última vez? … Anoto sus datos y le avisamos en cuanto sepamos algo.",modelAr:"ممكن توصفيلي الشنطة؟ … آخر مرة شفتها فين؟ … حسجّل بياناتك وحنبلّغك أول ما نعرف حاجة.",checklistAr:"راجع إجابتك: ١) طلب وصف (describe)، ٢) آخر مكان/وقت (última vez)، ٣) تسجيل + إبلاغ (anoto / avisamos)، ٤) من غير وعد بلقاها. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"maleta = شنطة سفر. equipaje = شنط. etiqueta = بطاقة/ليبل. por última vez = آخر مرة. en cuanto = أول ما. urgente = عاجل/مستعجل."}},{id:"tw-u07l03",courseId:"tourism-work",unitId:"tw-u07",sourceLessonId:"tw-u07l03",level:"B1",register:"usted",title:"الخطوة اللي جاية",context:"ضيفة عندها مشكلة في الفطار محتاجة حل. دورك: تقول إيه اللي حيحصل دلوقتي بالظبط — خطوة واقعية بعد مراجعة، مش وعد فاضي.",goal:"بعد الدرس ده حتقدر تقفل أي شكوى بخطوة عملية واضحة: مين، يعمل إيه، وامتى.",targets:[{es:"Voy a comprobarlo con el departamento.",ar:"حراجعها مع القسم المختص.",speaker:"paco"},{es:"Le doy una respuesta en diez minutos.",ar:"حرد عليكي خلال عشر دقايق.",speaker:"paco"},{es:"¿Qué va a pasar ahora?",ar:"حيحصل إيه دلوقتي؟",speaker:"luna"},{es:"Primero lo compruebo y luego le aviso.",ar:"الأول حراجع وبعدين حبلّغك.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Mi reserva incluye desayuno y me dicen que no.",ar:"حجزي شامل الفطار وبيقولولي لأ."},{speaker:"paco",es:"Lo siento. Voy a comprobarlo con el departamento. El de reservas.",ar:"آسف. حراجعها مع القسم المختص. قسم الحجوزات."},{speaker:"luna",es:"¿Qué va a pasar ahora?",ar:"حيحصل إيه دلوقتي؟"},{speaker:"paco",es:"Primero lo compruebo y luego le aviso. Le doy una respuesta en diez minutos.",ar:"الأول حراجع وبعدين حبلّغك. حرد عليكي خلال عشر دقايق."},{speaker:"luna",es:"¿Aquí la espero?",ar:"أستناها هنا؟"},{speaker:"paco",es:"Como prefiera. Aquí o en su habitación, la llamo.",ar:"زي ما تحبي. هنا أو في أوضتك، حكلمك."},{speaker:"luna",es:"En la habitación, por favor.",ar:"في الأوضة، لو سمحت."}],questions:[{q:"مشكلة الضيفة؟",options:["الفطار وحش ومش مستاهل","حجزها شامل الفطار وبيتقالها لأ","الأوضة صغيرة أوي عن الحجز","الفاتورة فيها بنود غلط"],answer:"حجزها شامل الفطار وبيتقالها لأ",rationale:"قالت: Mi reserva incluye desayuno y me dicen que no. incluir = يشمل."},{q:"الخطوة الجاية بالظبط؟",options:["يتجاهل الموضوع خالص","يراجع مع قسم الحجوزات ويرد خلال عشر دقايق","يحوّلها لقسم تاني ويخلص منها","يديها قسيمة خصم ويسكت"],answer:"يراجع مع قسم الحجوزات ويرد خلال عشر دقايق",rationale:"قال: Voy a comprobarlo con el departamento. El de reservas. وقال: Le doy una respuesta en diez minutos. خطوة محددة بزمن محدد."},{q:"الضيفة اختارت تستنى فين؟",options:["في الاستقبال","في الأوضة","في المطعم","برّه"],answer:"في الأوضة",rationale:"قالت: En la habitación, por favor والموظف عرض الاتنين: Como prefiera. como prefiera = زي ما تحبي."}],responseTask:{prompt:"ضيف سأل: حيحصل إيه دلوقتي؟ اشرح خطوتك الجاية بالإسباني بزمن محدد.",acceptable:["Primero lo compruebo con el departamento y luego le aviso. Le doy una respuesta en diez minutos.","Voy a comprobarlo con el departamento. Le doy una respuesta en diez minutos.","Lo compruebo ahora y le doy una respuesta en diez minutos.","Primero lo compruebo, luego le aviso. En diez minutos tiene una respuesta."],modelEs:"Primero lo compruebo con el departamento y luego le aviso. Le doy una respuesta en diez minutos.",modelAr:"الأول حراجعها مع القسم وبعدين حبلّغك. حرد عليك خلال عشر دقايق.",checklistAr:"راجع إجابتك: ١) الخطوة (compruebo con…)، ٢) زمن محدد (en diez minutos)، ٣) ترتيب واضح (primero / luego). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"comprobar = يراجع. departamento = قسم. avisar = يبلّغ. respuesta = رد. en diez minutos = خلال عشر دقايق."}},{id:"tw-u07l04",courseId:"tourism-work",unitId:"tw-u07",sourceLessonId:null,level:"B1",register:"usted",title:"تصعيد للمدير",context:"مشكلة أكبر من صلاحيتك: ضيفة عايزة تعويض. دورك: تصعّد للمدير باحتراف من غير ما تاخد قرار مش قرارك، وتقول للضيفة مين حيتابع وامتى.",goal:"بعد الدرس ده حتقدر تقول «ده قرار المدير» بشكل مهني، وتحدد خطوة التصعيد بوضوح.",targets:[{es:"Esto lo decide el director.",ar:"ده قرار المدير.",speaker:"paco"},{es:"Lo aviso ahora mismo.",ar:"حبلّغه حالًا.",speaker:"paco"},{es:"Quiero hablar con el responsable.",ar:"عايزة أكلم المسؤول.",speaker:"luna"},{es:"El director la atiende en cinco minutos.",ar:"المدير حيقابلك خلال خمس دقايق.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Quiero una compensación por lo de ayer.",ar:"عايزة تعويض عن اللي حصل امبارح."},{speaker:"paco",es:"Lo entiendo. Esto lo decide el director. Lo aviso ahora mismo.",ar:"فاهمك. ده قرار المدير. حبلّغه حالًا."},{speaker:"luna",es:"Quiero hablar con el responsable.",ar:"عايزة أكلم المسؤول."},{speaker:"paco",es:"Claro. El director la atiende en cinco minutos. ¿Le traigo un agua mientras?",ar:"طبعًا. المدير حيقابلك خلال خمس دقايق. أجيبلك مية في الوقت ده؟"},{speaker:"luna",es:"Sí, gracias.",ar:"أيوه، شكرًا."},{speaker:"paco",es:"El director ya conoce su caso. Le cuento los detalles.",ar:"المدير عارف موضوعك. ححكيله التفاصيل."},{speaker:"luna",es:"Vale, espero aquí.",ar:"تمام، حستنى هنا."}],questions:[{q:"الضيفة طلبت إيه؟",options:["تغيير الأوضة فورًا","خصم على حجزها الجاي","تعويض عن مشكلة امبارح","نسخة من الفاتورة"],answer:"تعويض عن مشكلة امبارح",rationale:"قالت: Quiero una compensación. compensación = تعويض. القرارات المالية مش قرار الموظف."},{q:"الموظف عمل إيه مع الطلب؟",options:["رفض الطلب تمامًا","وعد بالتعويض على طول","صعّد للمدير وحدد وقت المقابلة","قالها كلمي الشركة بنفسك"],answer:"صعّد للمدير وحدد وقت المقابلة",rationale:"قال: Esto lo decide el director و la atiende en cinco minutos. تصعيد واضح + زمن محدد = احتراف."},{q:"اللمسة الإضافية اللي الموظف عرضها؟",options:["ترقية للأوضة","قهوة ببلاش من الكافيه","مية وقت الانتظار","خريطة للمدينة"],answer:"مية وقت الانتظار",rationale:"قال: ¿Le traigo un agua mientras? mientras = في الوقت ده. لفتة صغيرة بتهدّي الانتظار."}],responseTask:{prompt:"ضيف طلب قرار أكبر من صلاحيتك. رد بالإسباني: القرار للمدير + حبلّغه دلوقتي + حيقابلك خلال خمس دقايق.",acceptable:["Esto lo decide el director. Lo aviso ahora mismo. El director la atiende en cinco minutos.","Esto lo decide el director. Lo aviso ahora mismo. Le atiende en cinco minutos.","Es decisión del director. Lo aviso ahora y le atiende en cinco minutos.","Esto lo decide el director. Le aviso ahora mismo y en cinco minutos la atiende."],modelEs:"Esto lo decide el director. Lo aviso ahora mismo. El director la atiende en cinco minutos.",modelAr:"ده قرار المدير. حبلّغه حالًا. المدير حيقابلك خلال خمس دقايق.",checklistAr:"راجع إجابتك: ١) صلاحية القرار (lo decide el director)، ٢) إبلاغ فوري (ahora mismo)، ٣) زمن مقابلة محدد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"decidir = يقرر. director = مدير. responsable = مسؤول. atender = يقابل/يخدم. ahora mismo = حالًا."}},{id:"tw-u07l05",courseId:"tourism-work",unitId:"tw-u07",sourceLessonId:null,level:"B1",register:"usted",title:"مشكلة في الأوضة",context:"ضيف بيبلّغ إن التكييف مش شغال. دورك: تاخد البلاغ، تعتذر، وتقول إيه الحل العملي المتاح — من غير وعود بمواعيد مش في إيدك.",goal:"بعد الدرس ده حتقدر تستقبل بلاغ عطل وتحوّله لإجراء: فني، أو تغيير أوضة، حسب المتاح.",targets:[{es:"El aire acondicionado no funciona.",ar:"التكييف مش شغال.",speaker:"luna"},{es:"Mando al técnico ahora.",ar:"حبعت الفني دلوقتي.",speaker:"paco"},{es:"Si no se arregla, le cambiamos de habitación.",ar:"لو مااتصلحش، حنغيّرلك الأوضة.",speaker:"paco"},{es:"¿Cuánto tarda el técnico?",ar:"الفني حياخد قد إيه؟",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Perdone. El aire acondicionado no funciona.",ar:"لو سمحت. التكييف مش شغال."},{speaker:"paco",es:"Lo siento mucho. Mando al técnico ahora.",ar:"آسف جدًا. حبعت الفني دلوقتي."},{speaker:"luna",es:"¿Cuánto tarda el técnico?",ar:"الفني حياخد قد إيه؟"},{speaker:"paco",es:"No le puedo dar una hora exacta. Le aviso en cuanto salga.",ar:"مش أقدر أديك معاد بالظبط. حبلّغك أول ما يتحرك."},{speaker:"luna",es:"¿Y si no lo arregla?",ar:"ولو مااتصلحش؟"},{speaker:"paco",es:"Si no se arregla, le cambiamos de habitación.",ar:"لو مااتصلحش، حنغيّرلك الأوضة."},{speaker:"luna",es:"Vale, me quedo en la habitación.",ar:"تمام، حفضل في الأوضة."}],questions:[{q:"البلاغ؟",options:["المية سخنة مش فيها","التليفزيون بايظ","التكييف مش شغال","النور مش شغال"],answer:"التكييف مش شغال",rationale:"قالت: El aire acondicionado no funciona. funcionar = يشتغل (للأجهزة)."},{q:"ليه الموظف مداش معاد محدد للفني؟",options:["عشان الفني واخد أجازة النهارده","عشان الموضوع مش مهم عنده خالص","عشان مش في إيده — ووعد بالإبلاغ أول ما الفني يتحرك","عشان نسي يسأل الفني عن معاده"],answer:"عشان مش في إيده — ووعد بالإبلاغ أول ما الفني يتحرك",rationale:"قال: No le puedo dar una hora exacta. Le aviso en cuanto salga. الوعد الصادق على المتابعة أحسن من معاد مخترع."},{q:"الخطة البديلة لو العطل مااتصلحش؟",options:["تصليح بكرة الصبح","إلغاء الحجز كله","تعويض فوري بالفلوس","تغيير الأوضة"],answer:"تغيير الأوضة",rationale:"قال: le cambiamos de habitación. cambiar de = يغيّر (حاجة)."}],responseTask:{prompt:"ضيف بلّغ عن عطل. رد بالإسباني: اعتذار + إرسال الفني + الخطة البديلة.",acceptable:["Lo siento mucho. Mando al técnico ahora. Si no se arregla, le cambiamos de habitación.","Lo siento. Mando al técnico ahora y si no se arregla, le cambiamos de habitación.","Lo siento mucho. Ahora mando al técnico. Si no lo arregla, le cambio de habitación.","Lo siento. Mando al técnico. Si no se arregla, hay otra habitación para usted."],modelEs:"Lo siento mucho. Mando al técnico ahora. Si no se arregla, le cambiamos de habitación.",modelAr:"آسف جدًا. حبعت الفني دلوقتي. لو مااتصلحش، حنغيّرلك الأوضة.",checklistAr:"راجع إجابتك: ١) اعتذار، ٢) إجراء فوري (mando al técnico)، ٣) خطة بديلة (si no se arregla…)، ٤) من غير معاد مخترع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"aire acondicionado = تكييف. funcionar = يشتغل. técnico = فني. tardar = ياخد وقت. arreglar = يصلّح."}},{id:"tw-u07l06",courseId:"tourism-work",unitId:"tw-u07",sourceLessonId:null,level:"B1",register:"usted",title:"شكوى من الأول للآخر",context:"ضيفة جاية بشكوى كاملة: مفيش مية سخنة من الصبح. دورك: اعتذر، افهم، لخّص، ادي خطوة بزمن، وتابع.",goal:"بعد الدرس ده حتقدر تدير شكوى كاملة بالترتيب المهني اللي اتدربت عليه في الوحدة.",targets:[{es:"No hay agua caliente desde esta mañana.",ar:"مفيش مية سخنة من الصبح.",speaker:"luna"},{es:"Lo siento mucho, no es aceptable.",ar:"آسف جدًا، ده مش مقبول.",speaker:"paco"},{es:"Aviso a mantenimiento ya.",ar:"حبلّغ الصيانة دلوقتي حالًا.",speaker:"paco"},{es:"Le llamo en cuanto tenga noticias.",ar:"حكلمك أول ما يوصلني خبر.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días, ¿en qué la ayudo?",ar:"صباح الخير، أساعدك في إيه؟"},{speaker:"luna",es:"No hay agua caliente desde esta mañana. Me quiero duchar.",ar:"مفيش مية سخنة من الصبح. عايزة أستحمى."},{speaker:"paco",es:"Lo siento mucho, no es aceptable. Aviso a mantenimiento ya.",ar:"آسف جدًا، ده مش مقبول. حبلّغ الصيانة دلوقتي حالًا."},{speaker:"luna",es:"¿Cuánto tarda?",ar:"حياخد قد إيه؟"},{speaker:"paco",es:"Le llamo en cuanto tenga noticias. Mientras, ¿le preparo algo para el desayuno?",ar:"حكلمك أول ما يوصلني خبر. في الوقت ده، أجهّزلك حاجة للفطار؟"},{speaker:"luna",es:"Sí, gracias. Y avíseme pronto, por favor.",ar:"أيوه، شكرًا. وبلّغني بسرعة، لو سمحت."},{speaker:"paco",es:"Cuenta con ello.",ar:"متقلقيش، حبلّغك."}],questions:[{q:"الشكوى؟",options:["الصوت عالي من الشارع","الأوضة سخنة أوي","الفطار اتأخر ساعة","مفيش مية سخنة من الصبح"],answer:"مفيش مية سخنة من الصبح",rationale:"قالت: No hay agua caliente desde esta mañana. desde = من (زمن). ducharse = يستحمى."},{q:"ردة فعل الموظف الأولى؟",options:["لوم الضيفة على الاستخدام","تبرير طويل للموقف","تجاهل كامل للشكوى","اعتذار صريح + إبلاغ الصيانة فورًا"],answer:"اعتذار صريح + إبلاغ الصيانة فورًا",rationale:"قال: Lo siento mucho, no es aceptable. Aviso a mantenimiento ya. الاعتراف بالمشكلة بيهدّي الضيف أكتر من التبرير."},{q:"«Cuenta con ello» معناها؟",options:["مفيش مشكلة كبيرة أصلًا","احسبي الحساب كويس","عدّي عليا بكرة الصبح","متقلقيش / اعتمدي على كده"],answer:"متقلقيش / اعتمدي على كده",rationale:"تعبير ثابت معناه طمأنة شخصية: اعتمد على كده. مناسب كختام لوعد متابعة."}],responseTask:{prompt:"شكوى كاملة: رد بالإسباني باعتذار + إجراء فوري + وعد متابعة + عرض راحة مؤقتة.",acceptable:["Lo siento mucho, no es aceptable. Aviso a mantenimiento ya. Le llamo en cuanto tenga noticias.","Lo siento mucho. Aviso a mantenimiento ahora. Le llamo en cuanto tenga noticias. Mientras, ¿le preparo algo?","Lo siento, no es aceptable. Aviso a mantenimiento ya y le llamo en cuanto tenga noticias.","Lo siento mucho. Lo aviso a mantenimiento ya. Le aviso en cuanto sepa algo."],modelEs:"Lo siento mucho, no es aceptable. Aviso a mantenimiento ya. Le llamo en cuanto tenga noticias.",modelAr:"آسف جدًا، ده مش مقبول. حبلّغ الصيانة دلوقتي حالًا. حكلمك أول ما يوصلني خبر.",checklistAr:"راجع إجابتك: ١) اعتذار واعتراف، ٢) إجراء فوري (mantenimiento)، ٣) وعد متابعة (en cuanto tenga noticias). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"agua caliente = مية سخنة. mantenimiento = صيانة. noticias = أخبار. ducharse = يستحمى. Cuenta con ello = اعتمد على كده."}}]},{courseId:"tourism-work",unit:{id:"tw-u08",title:"المغادرة والتوصيات",desc:"تراجع الفاتورة باحترام من غير افتراض إن الضيف غلط، تنظم يوم المغادرة، وتدي توصية مبنية على تفضيلاته وتودّع بود.",cefr:"A2–B1"},lessons:[{id:"tw-u08l01",courseId:"tourism-work",unitId:"tw-u08",sourceLessonId:"tw-u08l01",level:"B1",register:"usted",title:"مراجعة الحساب",context:"ضيف لاقى بند في الفاتورة مش فاهمه. دورك: تراجع الحساب معاه باحترام — الاختلاف يتراجع، مش افتراض إن الضيف غلط.",goal:"بعد الدرس ده حتقدر تشرح بنود الفاتورة وتتعامل مع اعتراض بمراجعة حقيقية من غير ما تتجادل.",targets:[{es:"¿Puedo revisar la cuenta?",ar:"ينفع أراجع الفاتورة؟",speaker:"paco"},{es:"Claro, la miramos juntos.",ar:"طبعًا، نشوفها مع بعض.",speaker:"luna"},{es:"Este cargo no lo entiendo.",ar:"البند ده مش فاهمه.",speaker:"paco"},{es:"Lo compruebo ahora mismo.",ar:"حراجعه حالًا.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Buenos días. ¿Puedo revisar la cuenta?",ar:"صباح الخير. ينفع أراجع الفاتورة؟"},{speaker:"luna",es:"Claro, la miramos juntos.",ar:"طبعًا، نشوفها مع بعض."},{speaker:"paco",es:"Este cargo no lo entiendo. ¿Qué es?",ar:"البند ده مش فاهمه. ده إيه؟"},{speaker:"luna",es:"Es del minibar de ayer. ¿No lo pidió usted?",ar:"ده من الميني بار بتاع امبارح. حضرتك ما طلبتوهوش؟"},{speaker:"paco",es:"No, no pedí nada del minibar.",ar:"لأ، ما طلبتش أي حاجة من الميني بار."},{speaker:"luna",es:"Entonces. Lo compruebo ahora mismo. Si es un error, lo quito de la cuenta.",ar:"يبقى كده. حراجعه حالًا. لو غلط، حشيله من الفاتورة."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."}],questions:[{q:"اعتراض الضيف؟",options:["بند في الفاتورة مش فاهمه","الفاتورة غالية أوي","مش عايز يدفع خالص","الإيصال بتاعه ضاع"],answer:"بند في الفاتورة مش فاهمه",rationale:"قال: Este cargo no lo entiendo. cargo = بند/رسوم. revisar = يراجع."},{q:"البند كان منين؟",options:["من الميني بار بتاع امبارح","من المطعم بتاع امبارح","من خدمة الغسيل","من الواي فاي المدفوع"],answer:"من الميني بار بتاع امبارح",rationale:"قالت: Es del minibar de ayer. minibar = ميني بار، ayer = امبارح."},{q:"الموظفة تعاملت مع الاعتراض إزاي؟",options:["وعدت بمراجعة وحذف البند لو اتثبت إنه غلط","افترضت إن الضيف هو اللي غلط وقالته كده","رفضت تتناقش في الموضوع خالص","شالت البند فورًا من غير مراجعة"],answer:"وعدت بمراجعة وحذف البند لو اتثبت إنه غلط",rationale:"قالت: lo compruebo ahora mismo. Si es un error, lo quito. si es un error = لو غلط. المراجعة الأول، مش الافتراض ولا الحذف العشوائي."}],responseTask:{prompt:"ضيف معترض على بند في فاتورته. رد بالإسباني: راجع معاه + لو غلط حيتشال.",acceptable:["Claro, la miramos juntos. Lo compruebo ahora mismo. Si es un error, lo quito de la cuenta.","Vamos a mirarlo juntos. Lo compruebo ahora y si es un error, lo quito.","Claro. Lo compruebo ahora mismo. Si es un error, lo quito de la cuenta.","La miramos juntos. Lo compruebo y si es un error, lo quito de la cuenta."],modelEs:"Claro, la miramos juntos. Lo compruebo ahora mismo. Si es un error, lo quito de la cuenta.",modelAr:"طبعًا، نشوفها مع بعض. حراجعه حالًا. لو غلط، حشيله من الفاتورة.",checklistAr:"راجع إجابتك: ١) مراجعة مشتركة (miramos juntos)، ٢) تحقق (lo compruebo)، ٣) شرط واضح (si es un error…). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cuenta = فاتورة/حساب. cargo = بند/رسوم. error = غلط. quitar = يشيل. pedir = يطلب."}},{id:"tw-u08l02",courseId:"tourism-work",unitId:"tw-u08",sourceLessonId:"tw-u08l02",level:"A2",register:"usted",title:"وقت المغادرة",context:"ضيفة بتسأل عن معاد المغادرة. دورك: تقول المعاد وتسأل عن احتياجها من غير ما تحجز أو توعد بحاجة تلقائيًا.",goal:"بعد الدرس ده حتقدر تشرح معاد المغادرة وتعرض مساعدة عملية: شنط، تاكسي، وقت إضافي — بالسؤال مش بالافتراض.",targets:[{es:"¿A qué hora es la salida?",ar:"معاد المغادرة الساعة كام؟",speaker:"luna"},{es:"La salida es a las doce.",ar:"المغادرة الساعة اتناشر.",speaker:"paco"},{es:"¿Necesita algo más?",ar:"محتاجة أي حاجة تانية؟",speaker:"paco"},{es:"¿Le guardo las maletas?",ar:"أحفظلك الشنط؟",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Perdone, una pregunta. ¿A qué hora es la salida?",ar:"لو سمحت، سؤال. معاد المغادرة الساعة كام؟"},{speaker:"paco",es:"La salida es a las doce.",ar:"المغادرة الساعة اتناشر."},{speaker:"luna",es:"Mi tren sale a las cinco.",ar:"قطري الساعة خمسة."},{speaker:"paco",es:"Entiendo. ¿Necesita algo más? ¿Le guardo las maletas? Hasta que salga su tren.",ar:"فاهم. محتاجة أي حاجة تانية؟ أحفظلك الشنط؟ لحد ما ييجي معاد قطرك."},{speaker:"luna",es:"Sí, por favor. ¿Y puedo pedir un taxi para las cuatro?",ar:"أيوه، لو سمحت. وينفع أطلب تاكسي الساعة أربعة؟"},{speaker:"paco",es:"Claro. ¿Quiere que lo pida ahora?",ar:"طبعًا. تحبي أطلبه من دلوقتي؟"},{speaker:"luna",es:"Sí, perfecto.",ar:"أيوه، جميل."}],questions:[{q:"معاد المغادرة؟",options:["الساعة اتناشر","الساعة أربعة العصر","الساعة خمسة المغرب","الساعة عشرة الصبح"],answer:"الساعة اتناشر",rationale:"قال: La salida es a las doce. salida = مغادرة/خروج."},{q:"مشكلة الضيفة العملية؟",options:["قطارها الساعة خمسة، يعني في فترة فاضية بعد المغادرة","عايزة تلغي الليلة اللي فاضلة خالص","القطار بتاعها اتأجل لبكرة الصبح","الشنطة تقيلة أوي ومش قادرة تشيلها"],answer:"قطارها الساعة خمسة، يعني في فترة فاضية بعد المغادرة",rationale:"قالت: Mi tren sale a las cinco. الفرق بين اتناشر وخمسة هو سبب عرض حفظ الشنط."},{q:"التاكسي اتطلب إزاي؟",options:["اتحجز على طول من غير ما يسألها","الموظف سأل الأول لو تطلبه من دلوقتي — مش حجز تلقائي","الضيفة طلبت التاكسي أونلاين بنفسها","مفيش أي تاكسي اتطلب في الموضوع"],answer:"الموظف سأل الأول لو تطلبه من دلوقتي — مش حجز تلقائي",rationale:"قال: ¿Quiere que lo pida ahora? الحجز باسم الضيف محتاج موافقته الصريحة."}],responseTask:{prompt:"ضيفة قطارها متأخر بعد معاد المغادرة. رد بالإسباني: معاد المغادرة + عرض حفظ الشنط + سؤال عن التاكسي.",acceptable:["La salida es a las doce. ¿Le guardo las maletas hasta entonces? ¿Quiere que pida un taxi?","La salida es a las doce. ¿Le guardo las maletas? ¿Quiere que le pida un taxi para las cuatro?","La salida es a las doce. Le guardo las maletas hasta entonces y le pido un taxi si quiere.","La salida es a las doce. ¿Necesita algo más? ¿Le guardo las maletas o le pido un taxi?"],modelEs:"La salida es a las doce. ¿Le guardo las maletas hasta entonces? ¿Quiere que pida un taxi?",modelAr:"المغادرة الساعة اتناشر. أحفظلك الشنط لحد المعاد؟ تحبي أطلبلك تاكسي؟",checklistAr:"راجع إجابتك: ١) المعاد (a las doce)، ٢) عرض الشنط (guardo las maletas)، ٣) سؤال مش افتراض (¿quiere que…?). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"salida = مغادرة. guardar = يحفظ. hasta entonces = لحد المعاد. pedir un taxi = يطلب تاكسي. tren = قطر."}},{id:"tw-u08l03",courseId:"tourism-work",unitId:"tw-u08",sourceLessonId:"tw-u08l03",level:"B1",register:"usted",title:"توصية ووداع",context:"آخر يوم للضيف، وطلب توصية مطعم قبل ما يمشي. دورك: تسأل عن تفضيلاته وتراجع التفاصيل قبل الترشيح، وتودّع بود.",goal:"بعد الدرس ده حتقدر تدي توصية مبنية على تفضيلات الضيف، وتقفل الإقامة بوداع دافي.",targets:[{es:"¿Qué tipo de comida le gusta?",ar:"بتحب أنهي نوع أكل؟",speaker:"luna"},{es:"Le recomiendo un sitio de marisco.",ar:"برشّح لحضرتك مطعم مأكولات بحرية.",speaker:"luna"},{es:"Está a cinco minutos andando.",ar:"على بعد خمس دقايق مشي.",speaker:"luna"},{es:"Que tenga un buen viaje de vuelta.",ar:"رحلة رجوع سالمة إن شاء الله.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Me voy mañana. ¿Me recomienda un restaurante para hoy?",ar:"مسافر بكرة. ممكن ترشّحيلي مطعم للنهارده؟"},{speaker:"luna",es:"Con mucho gusto. ¿Qué tipo de comida le gusta?",ar:"بكل سرور. بتحب أنهي نوع أكل؟"},{speaker:"paco",es:"Me gusta el marisco.",ar:"بحب المأكولات البحرية."},{speaker:"luna",es:"Entonces. Le recomiendo un sitio de marisco. Está junto al puerto. Está a cinco minutos andando.",ar:"يبقى كده. برشّح لحضرتك مطعم مأكولات بحرية. جنب الميناء. على بعد خمس دقايق مشي."},{speaker:"paco",es:"¿Necesita reserva?",ar:"محتاج حجز؟"},{speaker:"luna",es:"Mejor sí. ¿Quiere que llame por usted?",ar:"الأفضل أيوه. تحب أكلم لحضرتك؟"},{speaker:"paco",es:"Sí, por favor.",ar:"أيوه، لو سمحت."},{speaker:"luna",es:"Hecho. Que tenga un buen viaje de vuelta.",ar:"تم. رحلة رجوع سالمة إن شاء الله."}],questions:[{q:"الموظفة سألت إيه قبل الترشيح؟",options:["عن الميزانية المتاحة","عن نوع الأكل المفضل","عن الفندق اللي نازل فيه","ماسألتش أي سؤال"],answer:"عن نوع الأكل المفضل",rationale:"قالت: ¿Qué tipo de comida le gusta? التوصية الكويسة بتبدأ بسؤال، مش باسم جاهز."},{q:"المطعم المرشح فين؟",options:["في وسط البلد، بالتاكسي","جنب الميناء، خمس دقايق مشي","في الفندق نفسه","بعيد، ساعة بالأوتوبيس"],answer:"جنب الميناء، خمس دقايق مشي",rationale:"قالت: junto al puerto. Está a cinco minutos andando. puerto = ميناء."},{q:"بخصوص الحجز، الموظفة عملت إيه؟",options:["حجزت على طول من غير ما تسأله","نصحت بالحجز وعرضت تكلم هي بعد موافقته","قالت مفيش داعي للحجز","قالتله يحجز أونلاين بنفسه"],answer:"نصحت بالحجز وعرضت تكلم هي بعد موافقته",rationale:"قالت: Mejor sí. ¿Quiere que llame por usted? وبعد موافقته: Hecho = تم."}],responseTask:{prompt:"ضيف طلب توصية مطعم وودّعك. رد بالإسباني: سؤال تفضيل + ترشيح بمكان + وداع.",acceptable:["¿Qué tipo de comida le gusta? … Le recomiendo un sitio de marisco junto al puerto. Que tenga un buen viaje de vuelta.","¿Qué le gusta comer? … Le recomiendo un sitio de marisco a cinco minutos. Que tenga un buen viaje.","¿Qué tipo de comida le gusta? … Hay un sitio de marisco muy bueno junto al puerto. Buen viaje de vuelta.","¿Qué le gusta? … Le recomiendo un sitio de marisco junto al puerto, a cinco minutos andando. Que tenga un buen viaje."],modelEs:"¿Qué tipo de comida le gusta? … Le recomiendo un sitio de marisco junto al puerto. Que tenga un buen viaje de vuelta.",modelAr:"بتحب أنهي نوع أكل؟ … برشّح لحضرتك مطعم مأكولات بحرية جنب الميناء. رحلة رجوع سالمة إن شاء الله.",checklistAr:"راجع إجابتك: ١) سؤال تفضيل (qué tipo de comida)، ٢) ترشيح بمكان (recomiendo + مكان)، ٣) وداع (que tenga un buen viaje). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"recomendar = يرشّح. sitio = مكان/مطعم. puerto = ميناء. viaje de vuelta = رحلة الرجوع. hecho = تم."}},{id:"tw-u08l04",courseId:"tourism-work",unitId:"tw-u08",sourceLessonId:null,level:"B1",register:"usted",title:"مغادرة متأخرة",context:"ضيفة عايزة تفضل في الأوضة بعد معاد المغادرة. دورك: تراجع المتاح وتقول الإمكانية الحقيقية، من غير وعد قبل المراجعة.",goal:"بعد الدرس ده حتقدر تدير طلب late checkout: مراجعة، إمكانية، وبديل لو مش متاح.",targets:[{es:"¿Puedo salir más tarde?",ar:"ينفع أمشي متأخر شوية؟",speaker:"luna"},{es:"¿Hasta qué hora lo necesita?",ar:"لحد الساعة كام محتاجاه؟",speaker:"paco"},{es:"Déjeme ver si es posible.",ar:"استني أشوف لو ينفع.",speaker:"paco"},{es:"Puede quedarse hasta las dos.",ar:"تقدري تفضلي لحد الساعة اتنين.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenas. ¿Puedo salir más tarde? Mi vuelo es por la noche.",ar:"صباح الخير. ينفع أمشي متأخر شوية؟ طيارتي بالليل."},{speaker:"paco",es:"¿Hasta qué hora lo necesita?",ar:"لحد الساعة كام محتاجاه؟"},{speaker:"luna",es:"Hasta las dos o las tres, si se puede.",ar:"لحد الساعة اتنين أو تلاتة، لو ينفع."},{speaker:"paco",es:"Déjeme ver si es posible.",ar:"استني أشوف لو ينفع."},{speaker:"luna",es:"Gracias.",ar:"شكرًا."},{speaker:"paco",es:"Puede quedarse hasta las dos. A las tres ya no, que entra la limpieza.",ar:"تقدري تفضلي لحد الساعة اتنين. تلاتة لأ، عشان بيدخل التنضيف."},{speaker:"luna",es:"Perfecto, hasta las dos.",ar:"جميل، لحد الساعة اتنين."}],questions:[{q:"الضيفة طلبت إيه وليه؟",options:["تغيّر الأوضة لواحدة أكبر منها","تمدد الإقامة يوم كامل زيادة","تفضل في الأوضة متأخر عشان طيارتها بالليل","تدخل الأوضة بدري عن معادها"],answer:"تفضل في الأوضة متأخر عشان طيارتها بالليل",rationale:"قالت: ¿Puedo salir más tarde? Mi vuelo es por la noche. vuelo = طيارة، por la noche = بالليل."},{q:"الموظف رد بإيه قبل المراجعة؟",options:["لأ، مستحيل خالص","أيوه، أكيد على طول","استنى أشوف لو ينفع","اتفضلي امضي الورق ده الأول"],answer:"استنى أشوف لو ينفع",rationale:"قال: Déjeme ver si es posible. المراجعة قبل الوعد — نفس قاعدة الوحدة كلها."},{q:"النتيجة؟",options:["مش متاح خالص في اليوم ده","متاح لحد الساعة خمسة العصر","متاح لحد الساعة اتنين بس، عشان التنضيف","متاح بس برسوم إضافية عليه"],answer:"متاح لحد الساعة اتنين بس، عشان التنضيف",rationale:"قال: hasta las dos. A las tres ya no, que entra la limpieza. limpieza = تنضيف."}],responseTask:{prompt:"ضيف طلب مغادرة متأخرة. رد بالإسباني: سؤال عن المعاد المطلوب + مراجعة + إمكانية واضحة.",acceptable:["¿Hasta qué hora lo necesita? … Déjeme ver si es posible. … Puede quedarse hasta las dos.","¿Hasta qué hora? … Déjeme ver. … Puede quedarse hasta las dos.","¿Hasta qué hora lo necesita? … Un momento, lo miro. … Hasta las dos puede quedarse.","¿Hasta qué hora lo necesita? … Déjeme ver si es posible. … Sí, hasta las dos."],modelEs:"¿Hasta qué hora lo necesita? … Déjeme ver si es posible. … Puede quedarse hasta las dos.",modelAr:"لحد الساعة كام محتاجاه؟ … استنى أشوف لو ينفع. … تقدر تفضل لحد الساعة اتنين.",checklistAr:"راجع إجابتك: ١) سؤال المعاد (hasta qué hora)، ٢) مراجعة (déjeme ver)، ٣) إمكانية واضحة (puede quedarse hasta…). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"salir más tarde = يمشي متأخر. quedarse = يفضل. vuelo = طيارة. limpieza = تنضيف. si se puede = لو ينفع."}},{id:"tw-u08l05",courseId:"tourism-work",unitId:"tw-u08",sourceLessonId:null,level:"A2",register:"usted",title:"الشنط والتاكسي",context:"يوم المغادرة: ضيف سايب شنطه ومحتاج تاكسي للمطار. دورك: تنظم استلام الشنط برقم، وتسأل عن التفاصيل قبل طلب التاكسي.",goal:"بعد الدرس ده حتقدر تدير خدمات يوم المغادرة العملية: تذكرة شنط، وتاكسي بتفاصيل مؤكدة.",targets:[{es:"Aquí están, dos maletas.",ar:"اتفضل، شنطتين.",speaker:"luna"},{es:"¿Para cuántas personas es el taxi?",ar:"التاكسي لعدد كام شخص؟",speaker:"luna"},{es:"¿A qué hora lo quiere?",ar:"عايزه الساعة كام؟",speaker:"luna"},{es:"El taxi llega en diez minutos.",ar:"التاكسي حيوصل خلال عشر دقايق.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Buenas, vengo a recoger las maletas.",ar:"صباح الخير، جاي أستلم الشنط."},{speaker:"luna",es:"¿Tiene el ticket?",ar:"معاك التذكرة؟"},{speaker:"paco",es:"Sí, aquí está.",ar:"أيوه، اتفضلي."},{speaker:"luna",es:"Perfecto. Un momento.",ar:"تمام. لحظة واحدة."},{speaker:"paco",es:"Sin prisa.",ar:"على مهلك."},{speaker:"luna",es:"Aquí están, dos maletas. ¿Le pido un taxi al aeropuerto?",ar:"اتفضل، شنطتين. أطلبلك تاكسي للمطار؟"},{speaker:"paco",es:"Sí, por favor.",ar:"أيوه، لو سمحت."},{speaker:"luna",es:"¿Para cuántas personas es el taxi? ¿A qué hora lo quiere?",ar:"التاكسي لعدد كام شخص؟ وعايزه الساعة كام؟"},{speaker:"paco",es:"Para dos, ahora mismo.",ar:"لشخصين، دلوقتي حالًا."},{speaker:"luna",es:"El taxi llega en diez minutos.",ar:"التاكسي حيوصل خلال عشر دقايق."}],questions:[{q:"استلام الشنط تم بإيه؟",options:["بكلمة سر متفق عليها","بصورة البطاقة الشخصية","بتذكرة الأمانات","من غير أي تحقق خالص"],answer:"بتذكرة الأمانات",rationale:"قالت: ¿Tiene el ticket? ticket de consigna = تذكرة الأمانات. التذكرة هي دليل الاستلام."},{q:"الموظفة سألت عن إيه قبل طلب التاكسي؟",options:["نوع العربية المطلوبة","اللون المفضل للعربية","عدد الأشخاص والمعاد","شركة تاكسي معينة"],answer:"عدد الأشخاص والمعاد",rationale:"قالت: ¿Para cuántas personas? ¿A qué hora lo quiere? التفاصيل دي اللي بيتحتاجها الطلب فعلًا."},{q:"«Sin prisa» معناها؟",options:["استنى برّه","بسرعة","ممنوع","على مهلك"],answer:"على مهلك",rationale:"prisa = عجلة. sin prisa = من غير عجلة، على مهلك — رد مهذب لما حد بيعتذر عن تأخير بسيط."}],responseTask:{prompt:"ضيف مستلم شنطه وعايز تاكسي. رد بالإسباني: تسليم الشنط + سؤال عدد ومعاد التاكسي.",acceptable:["Aquí tiene sus maletas. ¿Le pido un taxi? ¿Para cuántas personas y a qué hora lo quiere?","Aquí están sus maletas. ¿Para cuántas personas es el taxi y a qué hora lo quiere?","Aquí tiene las maletas. ¿Quiere un taxi? ¿Para cuántas personas? ¿A qué hora?","Aquí tiene sus maletas. ¿Le pido un taxi? ¿Para cuántas personas es?"],modelEs:"Aquí tiene sus maletas. ¿Le pido un taxi? ¿Para cuántas personas y a qué hora lo quiere?",modelAr:"اتفضل شنطك. أطلبلك تاكسي؟ لعدد كام شخص وعايزه الساعة كام؟",checklistAr:"راجع إجابتك: ١) تسليم (aquí tiene)، ٢) عرض التاكسي، ٣) عدد + معاد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"recoger = يستلم. consigna = أمانات. sin prisa = على مهلك. llegar = يوصل. ahora mismo = حالًا."}},{id:"tw-u08l06",courseId:"tourism-work",unitId:"tw-u08",sourceLessonId:null,level:"B1",register:"usted",title:"مغادرة كاملة",context:"ضيفة بتعمل مغادرة كاملة: فاتورة، شنط، تاكسي، ووداع. دورك: تقفل كل حاجة بالترتيب، من الحساب لحد آخر كلمة.",goal:"بعد الدرس ده حتقدر تدير مغادرة كاملة من غير ما تنسى خطوة: حساب، شنط، مواصلات، وداع.",targets:[{es:"¿Cómo fue su estancia?",ar:"إقامتك كانت عاملة إزاي؟",speaker:"paco"},{es:"La cuenta está correcta.",ar:"الفاتورة سليمة.",speaker:"paco"},{es:"¿Le bajo las maletas?",ar:"أنزّللك الشنط؟",speaker:"paco"},{es:"Esperamos verle pronto.",ar:"مستنيين نشوفك تاني قريب.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días. ¿Cómo fue su estancia?",ar:"صباح الخير. إقامتك كانت عاملة إزاي؟"},{speaker:"luna",es:"Muy bien, gracias. Quiero hacer la salida.",ar:"كويسة جدًا، شكرًا. عايزة أعمل المغادرة."},{speaker:"paco",es:"Claro. La miramos juntos… La cuenta está correcta. ¿Cómo paga?",ar:"طبعًا. نشوفها مع بعض… الفاتورة سليمة. حتدفعي إزاي؟"},{speaker:"luna",es:"Con tarjeta.",ar:"بالكارت."},{speaker:"paco",es:"Hecho. ¿Le bajo las maletas? ¿Y le pido un taxi?",ar:"تم. أنزّللك الشنط؟ وأطلبلك تاكسي؟"},{speaker:"luna",es:"Las maletas sí. El taxi no, viene mi hermano.",ar:"الشنط أيوه. التاكسي لأ، أخويا جاي."},{speaker:"paco",es:"Perfecto. Esperamos verle pronto.",ar:"جميل. مستنيين نشوفك تاني قريب."},{speaker:"luna",es:"Gracias por todo. Hasta la próxima.",ar:"شكرًا على كل حاجة. للمرة الجاية."}],questions:[{q:"الضيفة دفعت إزاي؟",options:["لسه مدفعتش","كاش","تحويل","بالكارت"],answer:"بالكارت",rationale:"قالت: Con tarjeta."},{q:"الموظف عرض الشنط والتاكسي، والضيفة وافقت على إيه؟",options:["التاكسي بس هو اللي قبلته","الاتنين قبلتهم مع بعض","ولا واحد فيهم قبلته","الشنط بس — أخوها جاي ياخدها"],answer:"الشنط بس — أخوها جاي ياخدها",rationale:"قالت: Las maletas sí. El taxi no, viene mi hermano. العرض مفصول، والضيف يختار كل حاجة لوحدها."},{q:"الوداع كان بإيه؟",options:["سلميلي على البيت","مع السلامة وبس من غير زيادة","مفيش وداع خالص","مستنيين نشوفك تاني قريب + للمرة الجاية"],answer:"مستنيين نشوفك تاني قريب + للمرة الجاية",rationale:"قال: Esperamos verle pronto وقالت: Hasta la próxima. وداع مهني دافي بيفتح باب لزيارة جاية."}],responseTask:{prompt:"مغادرة كاملة: رد بالإسباني بسؤال عن الإقامة + تأكيد الحساب + عرض الشنط والتاكسي + وداع.",acceptable:["¿Cómo fue su estancia? … La cuenta está correcta. ¿Le bajo las maletas? ¿Le pido un taxi? … Esperamos verle pronto.","¿Cómo fue su estancia? … La cuenta está correcta. ¿Le bajo las maletas o le pido un taxi? Esperamos verle pronto.","¿Qué tal su estancia? … La cuenta está correcta. ¿Le bajo las maletas? Esperamos verle pronto.","¿Cómo fue su estancia? … Todo correcto. ¿Le bajo las maletas y le pido un taxi? … Hasta la próxima."],modelEs:"¿Cómo fue su estancia? … La cuenta está correcta. ¿Le bajo las maletas? ¿Le pido un taxi? … Esperamos verle pronto.",modelAr:"إقامتك كانت عاملة إزاي؟ … الفاتورة سليمة. أنزّللك الشنط؟ أطلبلك تاكسي؟ … مستنيين نشوفك تاني قريب.",checklistAr:"راجع إجابتك: ١) سؤال الإقامة (cómo fue)، ٢) تأكيد الحساب، ٣) عرض الشنط/التاكسي كأسئلة، ٤) وداع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"estancia = إقامة. hacer la salida = يعمل مغادرة (check-out). bajar = ينزّل. Hasta la próxima = للمرة الجاية."}}]},{courseId:"job-interview",unit:{id:"iv-u01",title:"دخول المقابلة والتعريف",desc:"تبدأ المقابلة بأدب من لحظة الوصول، وتطلب توضيح لو السؤال مش واضح.",cefr:"A2–B1"},lessons:[{id:"iv-u01l01",courseId:"job-interview",unitId:"iv-u01",sourceLessonId:"iv-u01l01",level:"A2",register:"usted",title:"السلام والاسم",context:"أول لحظة في المقابلة: بتدخل، بتسلّم، وبتعرّف بنفسك. الاسم هنا مثال، غيّره لاسمك لما تتدرّب. المتقدم راجل ومسؤولة التوظيف ست.",goal:"بعد الدرس ده حتقدر تفتتح المقابلة بسلام مهذب وتقول اسمك بجملة كاملة.",targets:[{es:"Buenos días. Gracias por recibirme.",ar:"صباح الخير. شكرًا على استقبال حضرتك ليا.",speaker:"paco"},{es:"Me llamo Omar.",ar:"اسمي عمر.",speaker:"paco"},{es:"Encantado de conocerla.",ar:"اتشرّفت بمعرفة حضرتك.",speaker:"paco"},{es:"Pase, por favor. Tome asiento.",ar:"اتفضل. اقعد.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, adelante.",ar:"صباح الخير، اتفضل."},{speaker:"paco",es:"Buenos días. Gracias por recibirme.",ar:"صباح الخير. شكرًا على استقبال حضرتك ليا."},{speaker:"luna",es:"¿Usted es?",ar:"حضرتك مين؟"},{speaker:"paco",es:"Me llamo Omar. Tengo una entrevista a las diez.",ar:"اسمي عمر. عندي مقابلة الساعة عشرة."},{speaker:"luna",es:"Sí, Omar. Pase, por favor. Tome asiento.",ar:"أيوه يا عمر. اتفضل. اقعد."},{speaker:"paco",es:"Gracias. Encantado de conocerla.",ar:"شكرًا. اتشرّفت بمعرفة حضرتك."}],questions:[{q:"المتقدم فتّح بإيه؟",options:["صباح الخير وشكر على الاستقبال","سلام عليكم ودخل قاعد","قال اسمه وبس","سأل عن المرتب"],answer:"صباح الخير وشكر على الاستقبال",rationale:"قال: Buenos días. Gracias por recibirme. recibir = يستقبل. الانطباع الأول بيبدأ من السلام."},{q:"ليه Encantado مش Encantada؟",options:["عشان المتقدم راجل — ولو كانت ست حتقول Encantada","عشان مسؤولة التوظيف هي الست","عشان دي الصيغة الوحيدة الموجودة","عشان الجملة صيغتها رسمية"],answer:"عشان المتقدم راجل — ولو كانت ست حتقول Encantada",rationale:"Encantado بتوصف اللي بيتكلم، مش اللي بيتكلم معاه. المتقدم راجل يبقى Encantado؛ لو ست، Encantada. ولو الكلام لراجل: conocerlo."},{q:"Tome asiento معناها؟",options:["اقعد (بصيغة حضرتك)","خد نفس عميق","اتفضل من غير ميعاد","قول اسمك الأول"],answer:"اقعد (بصيغة حضرتك)",rationale:"tomar asiento = يقعد. دي الصيغة المهذبة اللي مسؤولة التوظيف بتقولها للمتقدم."}],responseTask:{prompt:"انت داخل على مقابلة شغل. افتتح بالإسباني: سلام + شكر على الاستقبال + اسمك.",acceptable:["Buenos días. Gracias por recibirme. Me llamo Omar.","Buenos días, gracias por recibirme. Me llamo Omar.","Buenos días. Gracias por recibirme. Soy Omar.","Buenos días, gracias. Me llamo Omar. Encantado de conocerla."],modelEs:"Buenos días. Gracias por recibirme. Me llamo Omar.",modelAr:"صباح الخير. شكرًا على استقبال حضرتك ليا. اسمي عمر.",checklistAr:"راجع إجابتك: ١) سلام (buenos días)، ٢) شكر (gracias por recibirme)، ٣) الاسم (me llamo + اسمك الحقيقي). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"recibir = يستقبل. me llamo = اسمي. Encantado de conocerla = اتشرّفت بمعرفتك (لست؛ للراجل conocerlo). entrevista = مقابلة."}},{id:"iv-u01l02",courseId:"job-interview",unitId:"iv-u01",sourceLessonId:"iv-u01l02",level:"A2",register:"usted",title:"احكي عن نفسك",context:"مسؤولة التوظيف بتقولك Háblame de ti (بصيغة tú) أو ممكن تسمع Hábleme de usted (بصيغة usted). الاتنين طلب إنك تحكي عن نفسك في سطرين: بتوصل لإيه وإيه اللي يهمك.",goal:"بعد الدرس ده حتقدر ترد على «احكيلي عن نفسك» بجملتين مركزين: هدفك واهتمامك.",targets:[{es:"Háblame de ti.",ar:"احكيلي عن نفسك.",speaker:"luna"},{es:"Busco un puesto de atención al cliente.",ar:"بدوّر على وظيفة خدمة عملاء.",speaker:"paco"},{es:"Me interesa trabajar con personas.",ar:"مهتم أشتغل مع الناس.",speaker:"paco"},{es:"Soy una persona organizada.",ar:"أنا شخص منظم.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Empecemos. Háblame de ti.",ar:"يلا نبدأ. احكيلي عن نفسك."},{speaker:"paco",es:"Soy una persona organizada. Me interesa trabajar con personas.",ar:"أنا شخص منظم. مهتم أشتغل مع الناس."},{speaker:"luna",es:"¿Qué buscas exactamente?",ar:"بتدوّر على إيه بالظبط؟"},{speaker:"paco",es:"Busco un puesto de atención al cliente.",ar:"بدوّر على وظيفة خدمة عملاء."},{speaker:"luna",es:"¿Por qué atención al cliente?",ar:"ليه خدمة العملاء؟"},{speaker:"paco",es:"Porque me gusta ayudar y resolver problemas.",ar:"عشان بحب أساعد وأحل المشاكل."},{speaker:"luna",es:"Muy bien.",ar:"جميل."}],questions:[{q:"المتقدم لخّص نفسه في إيه؟",options:["شخص منظم ومهتم يشتغل مع الناس","قائمة صفات طويلة محفوظة","تاريخه العائلي","مرتبه القديم"],answer:"شخص منظم ومهتم يشتغل مع الناس",rationale:"قال: Soy una persona organizada. Me interesa trabajar con personas. سطرين مركزين أحسن من سيرة كاملة."},{q:"الوظيفة اللي بيدوّر عليها؟",options:["خدمة العملاء","المحاسبة","السكرتارية","المبيعات"],answer:"خدمة العملاء",rationale:"قال: Busco un puesto de atención al cliente. puesto = وظيفة، atención al cliente = خدمة العملاء."},{q:"ليه اختار خدمة العملاء؟",options:["عشان المرتب فيها كبير","عشان بيحب يساعد ويحل المشاكل","عشان الشركة قريبة من بيته","عشان مفيش وظيفة تانية"],answer:"عشان بيحب يساعد ويحل المشاكل",rationale:"قال: Porque me gusta ayudar y resolver problemas. ayudar = يساعد، resolver = يحل."}],responseTask:{prompt:"مسؤولة التوظيف قالتلك: احكيلي عن نفسك. رد بالإسباني بجملتين: صفة + هدف وظيفي.",acceptable:["Soy una persona organizada. Busco un puesto de atención al cliente.","Soy una persona organizada y me interesa trabajar con personas. Busco un puesto de atención al cliente.","Me interesa trabajar con personas. Busco un puesto de atención al cliente.","Soy organizado. Busco un puesto de atención al cliente y me gusta ayudar."],modelEs:"Soy una persona organizada. Busco un puesto de atención al cliente.",modelAr:"أنا شخص منظم. بدوّر على وظيفة خدمة عملاء.",checklistAr:"راجع إجابتك: ١) صفة حقيقية (soy…)، ٢) هدف وظيفي (busco un puesto de…). متخترعش خبرات. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"háblame de ti = احكيلي عن نفسك (tú) / hábleme de usted (صيغة حضرتك). puesto = وظيفة. buscar = يدوّر. ayudar = يساعد."}},{id:"iv-u01l03",courseId:"job-interview",unitId:"iv-u01",sourceLessonId:"iv-u01l03",level:"A2",register:"usted",title:"لو السؤال مش واضح",context:"مسؤولة التوظيف سألت سؤال مش واضح. تقدر تطلب تكرار أو توضيح — ده أحسن بكتير من إجابة على سؤال مفهمتوش.",goal:"بعد الدرس ده حتقدر تطلب إعادة أو توضيح أو مثال بأدب، من غير ما تتلخبط.",targets:[{es:"¿Podría repetir la pregunta, por favor?",ar:"ممكن حضرتك تعيدي السؤال، لو سمحتي؟",speaker:"paco"},{es:"¿Se refiere a mi experiencia laboral?",ar:"حضرتك تقصدي خبرتي في الشغل؟",speaker:"paco"},{es:"¿Podría darme un ejemplo?",ar:"ممكن حضرتك تدّيني مثال؟",speaker:"paco"},{es:"Claro, se lo repito.",ar:"طبعًا، حعيدهولك.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Cómo gestionas la polivalencia en contextos cambiantes?",ar:"بتدير إزاي تعدد المهام في بيئات متغيرة؟"},{speaker:"paco",es:"¿Podría repetir la pregunta, por favor?",ar:"ممكن حضرتك تعيدي السؤال، لو سمحتي؟"},{speaker:"luna",es:"Claro, se lo repito. ¿Cómo organizas varias tareas a la vez?",ar:"طبعًا، حعيدهولك. بتنظّم إزاي كذا مهمة في نفس الوقت؟"},{speaker:"paco",es:"¿Se refiere a mi experiencia laboral?",ar:"حضرتك تقصدي خبرتي في الشغل؟"},{speaker:"luna",es:"Sí, en el trabajo o en los estudios.",ar:"أيوه، في الشغل أو في الدراسة."},{speaker:"paco",es:"¿Podría darme un ejemplo?",ar:"ممكن حضرتك تدّيني مثال؟"},{speaker:"luna",es:"Por ejemplo, contestar correos y atender llamadas al mismo tiempo.",ar:"مثلا، ترد على الإيميلات وترد على التليفون في نفس الوقت."}],questions:[{q:"المتقدم عمل إيه لما السؤال ماكانش واضح؟",options:["جاوب أي إجابة","طلب إعادة السؤال بأدب","سكت","قال مش فاهم وخلاص"],answer:"طلب إعادة السؤال بأدب",rationale:"قال: ¿Podría repetir la pregunta, por favor? repetir = يعيد. طلب التوضيح علامة احتراف، مش ضعف."},{q:"تأكد من المقصود إزاي؟",options:["خمّن المقصود وجاوب على طول","سأل: تقصدي خبرتي في الشغل؟","غيّر الموضوع لحاجة تانية","سأل عن المرتب بدلها"],answer:"سأل: تقصدي خبرتي في الشغل؟",rationale:"قال: ¿Se refiere a mi experiencia laboral? referirse a = يقصد. التأكد من القصد بيمنع إجابة غلط."},{q:"طلب إيه في الآخر عشان يفهم أكتر؟",options:["استراحة","مثال عملي","ترجمة عربي","سؤال أسهل"],answer:"مثال عملي",rationale:"قال: ¿Podría darme un ejemplo? المثال بيوضّح السؤال المجرد. والمسؤولة ردت بمثال: إيميلات وتليفونات في نفس الوقت."}],responseTask:{prompt:"سؤال في المقابلة مش واضح. اطلب توضيح بالإسباني بطريقتين: إعادة + تأكيد القصد.",acceptable:["¿Podría repetir la pregunta, por favor? ¿Se refiere a mi experiencia laboral?","¿Podría repetir la pregunta, por favor? ¿Se refiere a mi experiencia o a mis estudios?","¿Podría repetirla, por favor? ¿Se refiere a mi experiencia laboral?","¿Podría repetir la pregunta? ¿Se refiere a mi experiencia laboral o a mi formación?"],modelEs:"¿Podría repetir la pregunta, por favor? ¿Se refiere a mi experiencia laboral?",modelAr:"ممكن حضرتك تعيدي السؤال، لو سمحتي؟ حضرتك تقصدي خبرتي في الشغل؟",checklistAr:"راجع إجابتك: ١) طلب إعادة (podría repetir)، ٢) تأكيد القصد (se refiere a…)، ٣) أدب (por favor / صيغة مهذبة). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"repetir = يعيد. referirse a = يقصد. experiencia laboral = خبرة الشغل. a la vez = في نفس الوقت. al mismo tiempo = في نفس الوقت."}},{id:"iv-u01l04",courseId:"job-interview",unitId:"iv-u01",sourceLessonId:null,level:"A2",register:"usted",title:"توصل في معادك",context:"وصلت الشركة قبل المقابلة. دورك: تعرّف بنفسك في الاستقبال وتقول معادك، من غير ما تدخل متأخر ولا متوتر.",goal:"بعد الدرس ده حتقدر تعلن وصولك للمقابلة في الاستقبال: اسمك، معادك، ومين اللي مستنيك.",targets:[{es:"Tengo una entrevista a las diez.",ar:"عندي مقابلة الساعة عشرة.",speaker:"paco"},{es:"Me espera la señora García.",ar:"الست جارسيا مستنياي.",speaker:"paco"},{es:"He llegado un poco antes.",ar:"وصلت بدري شوية.",speaker:"paco"},{es:"Espere un momento, por favor.",ar:"استنى لحظة، لو سمحت.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, ¿en qué puedo ayudarle?",ar:"صباح الخير، أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Buenos días. Tengo una entrevista a las diez.",ar:"صباح الخير. عندي مقابلة الساعة عشرة."},{speaker:"luna",es:"¿Con quién es la entrevista?",ar:"المقابلة مع مين؟"},{speaker:"paco",es:"Me espera la señora García.",ar:"الست جارسيا مستنياي."},{speaker:"luna",es:"Vale. Espere un momento, por favor. La aviso.",ar:"تمام. استنى لحظة، لو سمحت. حبلّغها."},{speaker:"paco",es:"Sí. He llegado un poco antes. Sin problema, espero aquí.",ar:"أيوه. وصلت بدري شوية. مفيش مشكلة، حستنى هنا."}],questions:[{q:"المتقدم أعلن وصوله بإيه؟",options:["إنه ضيعان ومش لاقي عنوان الشركة","قال اسمه بس ومشى من غير تفاصيل","عنده مقابلة الساعة عشرة والست جارسيا مستنياه","إنه بيعرف المدير شخصيًا من زمان"],answer:"عنده مقابلة الساعة عشرة والست جارسيا مستنياه",rationale:"قال: Tengo una entrevista a las diez. Me espera la señora García. المعلومتين دول بيسهّلوا على الاستقبال شغلهم."},{q:"وصل بدري ولا متأخر؟",options:["في المعاد بالظبط","متأخر ربع ساعة","بدري شوية","قبل المعاد بيوم"],answer:"بدري شوية",rationale:"قال: He llegado un poco antes. un poco antes = بدري شوية. الوصول البدري شوية علامة تنظيم."},{q:"«Sin problema, espero aquí» ليه جملة كويسة؟",options:["بتلغي المقابلة من غير سبب","بتستعجل الموظفة وتدوس على الوقت","بتهدّي الموقف وتقبل الانتظار من غير ضغط","بتطلب قهوة ومعجنات من الاستقبال"],answer:"بتهدّي الموقف وتقبل الانتظار من غير ضغط",rationale:"esperar = يستنى. القبول الهادي للانتظار بيسيب انطباع كويس قبل المقابلة أصلًا."}],responseTask:{prompt:"في استقبال شركة: عرّف بنفسك بالإسباني — مقابلة + معاد + اسم الشخص اللي مستنيك.",acceptable:["Buenos días. Tengo una entrevista a las diez. Me espera la señora García.","Tengo una entrevista a las diez con la señora García.","Buenos días, tengo una entrevista a las diez. Me espera la señora García.","Tengo una entrevista a las diez. La señora García me espera."],modelEs:"Buenos días. Tengo una entrevista a las diez. Me espera la señora García.",modelAr:"صباح الخير. عندي مقابلة الساعة عشرة. الست جارسيا مستنياي.",checklistAr:"راجع إجابتك: ١) سلام، ٢) المقابلة ومعادها (tengo una entrevista a las…)، ٣) الشخص المسؤول (me espera…). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"entrevista = مقابلة. esperar = يستنى. un poco antes = بدري شوية. sin problema = مفيش مشكلة."}},{id:"iv-u01l05",courseId:"job-interview",unitId:"iv-u01",sourceLessonId:null,level:"A2",register:"usted",title:"لحظات الانتظار",context:"قبل ما المقابلة تبدأ فيه لحظات صغيرة: يسألوك عايز تشرب حاجة، وتستنى، وتشكر. الكلمات الصغيرة هنا بتفرق في الانطباع.",goal:"بعد الدرس ده حتقدر تتعامل بأدب مع عروض الاستقبال: تقبل أو تعتذر بجملة قصيرة لطيفة.",targets:[{es:"¿Quiere un vaso de agua?",ar:"تحب كوباية مية؟",speaker:"luna"},{es:"Sí, por favor. Muchas gracias.",ar:"أيوه، لو سمحتي. شكرًا جدًا.",speaker:"paco"},{es:"No, gracias. Estoy bien.",ar:"لأ، شكرًا. أنا كويس.",speaker:"paco"},{es:"Perdone la espera.",ar:"المعذرة على الانتظار.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Quiere un vaso de agua?",ar:"تحب كوباية مية؟"},{speaker:"paco",es:"Sí, por favor. Muchas gracias.",ar:"أيوه، لو سمحتي. شكرًا جدًا."},{speaker:"luna",es:"Aquí tiene. La señora García llega en cinco minutos.",ar:"اتفضل. الست جارسيا حتيجي خلال خمس دقايق."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."},{speaker:"luna",es:"¿Un café mientras tanto?",ar:"قهوة في الوقت ده؟"},{speaker:"paco",es:"No, gracias. Estoy bien.",ar:"لأ، شكرًا. أنا كويس."},{speaker:"luna",es:"Perdone la espera. Ya viene.",ar:"المعذرة على الانتظار. جاية دلوقتي."},{speaker:"paco",es:"No pasa nada. Gracias.",ar:"ولا يهمك. شكرًا."}],questions:[{q:"المتقدم قبل إيه ورفض إيه؟",options:["رفض الاتنين بوقاحة","قبل القهوة ورفض المية","قبل المية ورفض القهوة","قبل الاتنين"],answer:"قبل المية ورفض القهوة",rationale:"قال: Sí, por favor للمية، وNo, gracias. Estoy bien للقهوة. القبول والرفض بأدب الاتنين طبيعيين."},{q:"مسؤولة الاستقبال اعتذرت عن إيه؟",options:["عن المكان","عن القهوة","عن الانتظار","عن الزحمة"],answer:"عن الانتظار",rationale:"قالت: Perdone la espera. la espera = الانتظار. اعتذار بسيط بيهدّي الدقايق اللي قبل المقابلة."},{q:"رد المتقدم على الاعتذار؟",options:["أنا مش فاضي للانتظار","عيب عليكي التأخير ده","طيب خلّصي بسرعة","ولا يهمك. شكرًا"],answer:"ولا يهمك. شكرًا",rationale:"قال: No pasa nada. Gracias. قبول الاعتذار بهدوء بيكمّل الصورة المهنية."}],responseTask:{prompt:"في الانتظار قبل المقابلة، عرضوا عليك قهوة وانت مش عايز. اعتذر بأدب بالإسباني.",acceptable:["No, gracias. Estoy bien.","No, gracias, estoy bien.","No, muchas gracias. Estoy bien.","No, gracias. Ahora mismo estoy bien."],modelEs:"No, gracias. Estoy bien.",modelAr:"لأ، شكرًا. أنا كويس.",checklistAr:"راجع إجابتك: ١) رفض مهذب (no, gracias)، ٢) جملة قصيرة مطمئنة (estoy bien). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"vaso de agua = كوباية مية. mientras tanto = في الوقت ده. la espera = الانتظار. ya viene = جاي/جاية دلوقتي."}},{id:"iv-u01l06",courseId:"job-interview",unitId:"iv-u01",sourceLessonId:null,level:"B1",register:"usted",title:"افتتاحية مقابلة كاملة",context:"من لحظة الوصول لحد أول سؤال: تستقبل، تسلّم، تعرّف، تقعد، وتسمع أول سؤال. المشهد كامل هنا.",goal:"بعد الدرس ده حتقدر تعدّي بافتتاحية مقابلة كاملة بثقة: وصول، تعريف، جلوس، وأول سؤال.",targets:[{es:"Soy Omar. Tengo una entrevista a las diez.",ar:"أنا عمر. عندي مقابلة الساعة عشرة.",speaker:"paco"},{es:"Sígame, por favor.",ar:"اتبعني، لو سمحت.",speaker:"luna"},{es:"Cuénteme un poco de usted.",ar:"احكيلي شوية عن حضرتك.",speaker:"luna"},{es:"Con mucho gusto.",ar:"بكل سرور.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenos días.",ar:"صباح الخير."},{speaker:"paco",es:"Buenos días. Soy Omar. Tengo una entrevista a las diez.",ar:"صباح الخير. أنا عمر. عندي مقابلة الساعة عشرة."},{speaker:"luna",es:"Sí, le esperábamos. Sígame, por favor.",ar:"أيوه، كنا مستنيينك. اتبعني، لو سمحت."},{speaker:"paco",es:"Gracias.",ar:"شكرًا."},{speaker:"luna",es:"Tome asiento. ¿Está cómodo?",ar:"اقعد. مرتاح؟"},{speaker:"paco",es:"Sí, gracias. Encantado de conocerla.",ar:"أيوه، شكرًا. اتشرّفت بمعرفة حضرتك."},{speaker:"luna",es:"Igualmente. Cuénteme un poco de usted.",ar:"وأنا كمان. احكيلي شوية عن حضرتك."},{speaker:"paco",es:"Con mucho gusto. Soy una persona organizada y me interesa la atención al cliente.",ar:"بكل سرور. أنا شخص منظم ومهتم بخدمة العملاء."}],questions:[{q:"ترتيب الافتتاحية الصح؟",options:["تعريف سريع، وقهوة، وبعدين رحيل","أول سؤال، وبعدين سلام، وبعدين جلوس","جلوس، وسؤال عن المرتب، وبعدين سلام","سلام، تعريف بالمقابلة، جلوس، أول سؤال"],answer:"سلام، تعريف بالمقابلة، جلوس، أول سؤال",rationale:"الحوار مشي كده: Buenos días → Soy Omar. Tengo una entrevista → Tome asiento → Cuénteme un poco de usted."},{q:"مسؤولة التوظيف سألت أول سؤال بأنهي صيغة؟",options:["Cállate y escucha","Háblame de ti (دي صيغة tú)","Dime tu nombre y apellido","Cuénteme un poco de usted (صيغة حضرتك)"],answer:"Cuénteme un poco de usted (صيغة حضرتك)",rationale:"قالت: Cuénteme un poco de usted. contar = يحكي. زي Háblame de ti — الاتنين طلب تحكي عن نفسك، بصيغتين مختلفتين."},{q:"رد المتقدم على أول سؤال افتتح بإيه؟",options:["سؤال عن المرتب مباشرة","سكوت طويل ومحرج","قصة حياته كاملة من الأول","Con mucho gusto + جملة تعريف مركزة"],answer:"Con mucho gusto + جملة تعريف مركزة",rationale:"قال: Con mucho gusto. Soy una persona organizada… con mucho gusto = بكل سرور. البداية الإيجابية + التركيز = افتتاحية قوية."}],responseTask:{prompt:"افتتاحية مقابلة من جهتك: عرّف بنفسك ومقابلتك في الاستقبال بالإسباني، وبعدين رد على «احكيلي عن نفسك» بجملة.",acceptable:["Soy Omar. Tengo una entrevista a las diez. … Con mucho gusto. Soy una persona organizada y me interesa la atención al cliente.","Buenos días, soy Omar. Tengo una entrevista a las diez. … Con mucho gusto, soy organizado y me interesa la atención al cliente.","Soy Omar, tengo una entrevista a las diez. … Con mucho gusto. Me interesa la atención al cliente.","Buenos días. Soy Omar y tengo una entrevista a las diez. … Con mucho gusto: soy una persona organizada."],modelEs:"Soy Omar. Tengo una entrevista a las diez. … Con mucho gusto. Soy una persona organizada y me interesa la atención al cliente.",modelAr:"أنا عمر. عندي مقابلة الساعة عشرة. … بكل سرور. أنا شخص منظم ومهتم بخدمة العملاء.",checklistAr:"راجع إجابتك: ١) اسم + مقابلة + معاد، ٢) قبول مهذب (con mucho gusto)، ٣) جملة تعريف مركزة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"seguir = يتبع. cómodo = مرتاح. igualmente = وأنا كمان. contar = يحكي. con mucho gusto = بكل سرور."}}]},{courseId:"job-interview",unit:{id:"iv-u02",title:"الدراسة والخبرة وأول شغل",desc:"تحكي عن دراستك وخبرتك بصدق حتى لو لسه مشتغلتش، وتشرح التغيير وفترات الفراغ من غير اختلاق.",cefr:"A2–B1"},lessons:[{id:"iv-u02l01",courseId:"job-interview",unitId:"iv-u02",sourceLessonId:"iv-u02l01",level:"A2",register:"usted",title:"درست إيه؟",context:"مسؤولة التوظيف بتسأل عن دراستك. قول اللي درسته فعلًا: He estudiado جملة مفيدة عن الدراسة، مش شهادة بتتضاف لوحدها.",goal:"بعد الدرس ده حتقدر تجاوب على سؤال الدراسة بجملة صادقة ومباشرة، وتضيف كورس أو تدريب لو عملته.",targets:[{es:"¿Qué has estudiado?",ar:"إنت درست إيه؟",speaker:"luna"},{es:"He estudiado turismo.",ar:"درست سياحة.",speaker:"paco"},{es:"He hecho un curso de atención al cliente.",ar:"أخدت كورس خدمة عملاء.",speaker:"paco"},{es:"¿Dónde lo has estudiado?",ar:"درسته فين؟",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Qué has estudiado?",ar:"إنت درست إيه؟"},{speaker:"paco",es:"He estudiado turismo.",ar:"درست سياحة."},{speaker:"luna",es:"¿Dónde lo has estudiado?",ar:"درسته فين؟"},{speaker:"paco",es:"En la universidad, aquí en Madrid.",ar:"في الجامعة، هنا في مدريد."},{speaker:"luna",es:"¿Algo más?",ar:"أي حاجة تانية؟"},{speaker:"paco",es:"Sí. He hecho un curso de atención al cliente.",ar:"أيوه. أخدت كورس خدمة عملاء."},{speaker:"luna",es:"Muy bien.",ar:"جميل."}],questions:[{q:"المتقدم درس إيه؟",options:["سياحة، ومعاه كورس خدمة عملاء","محاسبة، ومعاه كورس إدارة أعمال","لغات، ومعاه كورس ترجمة","هندسة، ومعاه كورس تصميم"],answer:"سياحة، ومعاه كورس خدمة عملاء",rationale:"قال: He estudiado turismo و He hecho un curso de atención al cliente. curso = كورس."},{q:"درس فين؟",options:["أونلاين، من البيت","في الجامعة، في مدريد","في الجامعة، في برشلونة","في الثانوي، في البلد"],answer:"في الجامعة، في مدريد",rationale:"قال: En la universidad, aquí en Madrid. universidad = جامعة."},{q:"ليه He estudiado turismo إجابة كافية؟",options:["عشان فيها أرقام وتواريخ دقيقة عن كل سنة دراسة","عشانها جملة طويلة ومتدربة وبتبان ذكية قدّام الناس","عشانها جملة صادقة ومباشرة عن الدراسة الفعلية","عشانها جملة صعبة لغويًا ومحدش بيقولها في العادي"],answer:"عشانها جملة صادقة ومباشرة عن الدراسة الفعلية",rationale:"المطلوب دراستك الفعلية بجملة واضحة. المبالغة في الشهادات مش مطلوبة وممكن تتكشف."}],responseTask:{prompt:"اتسألت: درست إيه؟ جاوب بالإسباني بدراستك الحقيقية + كورس لو عملته (أي مجال منطقي).",acceptable:["He estudiado turismo. He hecho un curso de atención al cliente.","He estudiado turismo y he hecho un curso de atención al cliente.","He estudiado comercio. He hecho un curso de informática.","He estudiado hostelería. También he hecho un curso de idiomas."],modelEs:"He estudiado turismo. He hecho un curso de atención al cliente.",modelAr:"درست سياحة. أخدت كورس خدمة عملاء.",checklistAr:"راجع إجابتك: ١) دراسة حقيقية (he estudiado)، ٢) كورس لو فيه (he hecho un curso de…)، ٣) من غير مبالغة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"estudiar = يدرس. he estudiado = درست. he hecho = أخدت/عملت. curso = كورس. universidad = جامعة."}},{id:"iv-u02l02",courseId:"job-interview",unitId:"iv-u02",sourceLessonId:"iv-u02l02",level:"B1",register:"usted",title:"خبرة أو أول فرصة",context:"سؤال الخبرة. عندك بديلين حسب واقعك: عندك خبرة تقولها، أو لسه معندكش — وده مش نهاية المقابلة. مهم تصدق في الحالتين.",goal:"بعد الدرس ده حتقدر تقدّم خبرتك لو موجودة، أو تقدّم استعدادك بثقة لو دي أول فرصة.",targets:[{es:"He trabajado en atención al cliente.",ar:"اشتغلت في خدمة العملاء.",speaker:"paco"},{es:"Todavía no tengo experiencia laboral.",ar:"لسه معنديش خبرة شغل.",speaker:"paco"},{es:"En mis estudios he aprendido a trabajar en equipo.",ar:"في دراستي اتعلّمت أشتغل ضمن فريق.",speaker:"paco"},{es:"¿Tienes experiencia previa?",ar:"عندك خبرة سابقة؟",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Tienes experiencia previa?",ar:"عندك خبرة سابقة؟"},{speaker:"paco",es:"He trabajado en atención al cliente. Un año en una tienda.",ar:"اشتغلت في خدمة العملاء. سنة في محل."},{speaker:"luna",es:"¿Y qué hacías allí?",ar:"وكنت بتعمل إيه هناك؟"},{speaker:"paco",es:"Atendía a los clientes y resolvía sus dudas.",ar:"كنت بخدم العملاء وبرد على استفساراتهم."},{speaker:"luna",es:"Bien. ¿Y si no tuvieras experiencia?",ar:"تمام. ولو ماكانش عندك خبرة؟"},{speaker:"paco",es:"Diría la verdad. Todavía no tengo experiencia laboral. En mis estudios he aprendido a trabajar en equipo.",ar:"حأقول الحقيقة. لسه معنديش خبرة شغل. في دراستي اتعلّمت أشتغل ضمن فريق."},{speaker:"luna",es:"Esa honestidad también vale.",ar:"الصدق ده كمان ليه قيمة."}],questions:[{q:"خبرة المتقدم الفعلية؟",options:["خمس سنين بنك","سنتين كول سنتر","مفيش أي خبرة","سنة خدمة عملاء في محل"],answer:"سنة خدمة عملاء في محل",rationale:"قال: He trabajado en atención al cliente. Un año en una tienda. tienda = محل."},{q:"كان بيعمل إيه في المحل؟",options:["بيحاسب على الكاشير بس","بيسوّق منتجات المحل أونلاين بس","بيخدم العملاء ويرد على استفساراتهم","بينضّف المحل ويرتّب البضاعة"],answer:"بيخدم العملاء ويرد على استفساراتهم",rationale:"قال: Atendía a los clientes y resolvía sus dudas. dudas = استفسارات. atender = يخدم."},{q:"ليه مسؤولة التوظيف قالت «الصدق ده كمان ليه قيمة»؟",options:["عشان المقابلة خلصت وعايزة تقفل الكلام بشكل لطيف","عشان الخبرة مش مهمة خالص في أي وظيفة من الوظايف","عشانها بتمزح ومش بتاخد أسئلة المقابلة بجدية أصلًا","عشان الصدق عن نقص الخبرة مع استعداد للتعلم مقبول ومهم"],answer:"عشان الصدق عن نقص الخبرة مع استعداد للتعلم مقبول ومهم",rationale:"قالت: Esa honestidad también vale. honestidad = صدق. اختراع خبرة أخطر بكتير من الاعتراف بالبداية."}],responseTask:{prompt:"اتسألت عن خبرتك. جاوب بالإسباني بالصيغة اللي تنطبق عليك: خبرة فعلية أو أول فرصة + استعداد.",acceptable:["He trabajado en atención al cliente. Un año en una tienda.","Todavía no tengo experiencia laboral. En mis estudios he aprendido a trabajar en equipo.","Todavía no tengo experiencia laboral, pero en mis estudios he aprendido a trabajar en equipo.","He trabajado un año en atención al cliente, en una tienda."],modelEs:"Todavía no tengo experiencia laboral. En mis estudios he aprendido a trabajar en equipo.",modelAr:"لسه معنديش خبرة شغل. في دراستي اتعلّمت أشتغل ضمن فريق.",checklistAr:"راجع إجابتك: ١) صدق كامل (خبرة أو لسه)، ٢) نقطة قوة بديلة (trabajar en equipo). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"experiencia previa = خبرة سابقة. todavía no = لسه. trabajar en equipo = يشتغل ضمن فريق. dudas = استفسارات. honestidad = صدق."}},{id:"iv-u02l03",courseId:"job-interview",unitId:"iv-u02",sourceLessonId:"iv-u02l03",level:"B1",register:"usted",title:"التغيير وفترة من غير شغل",context:"سؤالين صعبين: ليه بتغيّر شغلك؟ وإيه الفترة الفاضية في سيرتك؟ استخدم سبب صادق، من غير اختلاق تبرير ومن غير نقد شغلك القديم.",goal:"بعد الدرس ده حتقدر تشرح سبب التغيير وفترة الفراغ بصدق ومن غير سلبية.",targets:[{es:"¿Por qué quieres cambiar de trabajo?",ar:"إنت عايز تغيّر شغلك ليه؟",speaker:"luna"},{es:"Busco nuevas oportunidades para aprender.",ar:"بدوّر على فرص جديدة أتعلّم فيها.",speaker:"paco"},{es:"Durante ese periodo me dediqué a estudiar.",ar:"في الفترة دي ركّزت على الدراسة.",speaker:"paco"},{es:"Veo un hueco de seis meses aquí.",ar:"شايفة فترة فراغ ست شهور هنا.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Por qué quieres cambiar de trabajo?",ar:"إنت عايز تغيّر شغلك ليه؟"},{speaker:"paco",es:"Busco nuevas oportunidades para aprender.",ar:"بدوّر على فرص جديدة أتعلّم فيها."},{speaker:"luna",es:"¿Algo no te gusta de tu trabajo actual?",ar:"في حاجة مش عاجباك في شغلك الحالي؟"},{speaker:"paco",es:"No, es un buen trabajo. Pero quiero crecer en otro sector.",ar:"لأ، ده شغل كويس. بس عايز أكبر في مجال تاني."},{speaker:"luna",es:"Veo un hueco de seis meses aquí.",ar:"شايفة فترة فراغ ست شهور هنا."},{speaker:"paco",es:"Sí. Durante ese periodo me dediqué a estudiar.",ar:"أيوه. في الفترة دي ركّزت على الدراسة."},{speaker:"luna",es:"Entendido.",ar:"فاهمة."}],questions:[{q:"سبب التغيير اللي قاله؟",options:["بيدوّر على فرص جديدة يتعلّم فيها","عشان شغله القديم كان وحش جدًا","عشان زمايله كانوا وحشين معاه","عشان المرتب كان قليل ومش كفاية"],answer:"بيدوّر على فرص جديدة يتعلّم فيها",rationale:"قال: Busco nuevas oportunidades para aprender. سبب إيجابي من غير نقد لأي حد."},{q:"رد على سؤال «في حاجة مش عاجباك؟» إزاي؟",options:["أيوه، المدير كان سيء ومش بيحترم حد","لأ، شغل كويس، بس عايز أكبر في مجال تاني","أيوه، كل حاجة كانت غلط من الأول للآخر","ماردش وقال إن الموضوع مش مهم"],answer:"لأ، شغل كويس، بس عايز أكبر في مجال تاني",rationale:"قال: No, es un buen trabajo. Pero quiero crecer en otro sector. crecer = يكبر. نقد الشغل القديم بيحسب عليك، مش ليه."},{q:"فترة الفراغ شرحها بإيه؟",options:["كان مسافر برّه البلد للسياحة","مفيش سبب، كانش عايز يشتغل","كان مريض وقاعد في البيت","ركّز على الدراسة في الفترة دي"],answer:"ركّز على الدراسة في الفترة دي",rationale:"قال: Durante ese periodo me dediqué a estudiar. hueco = فراغ. dedicarse a = يركّز على. سبب صادق ومنتج."}],responseTask:{prompt:"اتسألت ليه بتغيّر شغلك. جاوب بالإسباني بسبب إيجابي صادق من غير نقد.",acceptable:["Busco nuevas oportunidades para aprender. Quiero crecer en otro sector.","Busco nuevas oportunidades para aprender.","Busco crecer profesionalmente en este sector.","Busco nuevas oportunidades para aprender y crecer."],modelEs:"Busco nuevas oportunidades para aprender. Quiero crecer en otro sector.",modelAr:"بدوّر على فرص جديدة أتعلّم فيها. عايز أكبر في مجال تاني.",checklistAr:"راجع إجابتك: ١) سبب إيجابي (oportunidades / aprender / crecer)، ٢) من غير نقد للشغل القديم. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cambiar de trabajo = يغيّر شغله. hueco = فراغ. dedicarse a = يركّز على. crecer = يكبر. sector = مجال."}},{id:"iv-u02l04",courseId:"job-interview",unitId:"iv-u02",sourceLessonId:null,level:"B1",register:"usted",title:"اتعلّمت إيه من دراستك",context:"مسؤولة التوظيف عايزة تعرف دراستك سابتلك إيه عملي. دورك: تربط الدراسة بمهارة حقيقية تخص الوظيفة.",goal:"بعد الدرس ده حتقدر تقول اتعلّمت إيه من دراستك بجملة تربطها بالشغل.",targets:[{es:"¿Qué aprendiste en tus estudios?",ar:"اتعلّمت إيه من دراستك؟",speaker:"luna"},{es:"Aprendí a organizar mi tiempo.",ar:"اتعلّمت أنظّم وقتي.",speaker:"paco"},{es:"Aprendí a hablar en público.",ar:"اتعلّمت أتكلم قدّام ناس.",speaker:"paco"},{es:"Eso es muy útil para este puesto.",ar:"ده مفيد جدًا للوظيفة دي.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Qué aprendiste en tus estudios?",ar:"اتعلّمت إيه من دراستك؟"},{speaker:"paco",es:"Aprendí a organizar mi tiempo. Teníamos muchos trabajos con fechas límite.",ar:"اتعلّمت أنظّم وقتي. كان عندنا شغل كتير بمواعيد تسليم."},{speaker:"luna",es:"¿Algo más?",ar:"حاجة تانية؟"},{speaker:"paco",es:"Sí. Aprendí a hablar en público. Hacíamos presentaciones cada mes.",ar:"أيوه. اتعلّمت أتكلم قدّام ناس. كنا بنعمل عروض كل شهر."},{speaker:"luna",es:"Eso es muy útil para este puesto.",ar:"ده مفيد جدًا للوظيفة دي."},{speaker:"paco",es:"Gracias. Creo que sí.",ar:"شكرًا. أنا كمان شايف كده."}],questions:[{q:"أول مهارة قالها وسببها؟",options:["تنظيم الوقت، عشان كان فيه شغل كتير بمواعيد تسليم","الطبخ، عشان بيحب يجرب وصفات جديدة كل أسبوع","السواقة، عشان مهارة مفيدة في المواصلات اليومية","الرسم، عشان هوايته المفضلة من أيام المدرسة"],answer:"تنظيم الوقت، عشان كان فيه شغل كتير بمواعيد تسليم",rationale:"قال: Aprendí a organizar mi tiempo وعلّلها بـ trabajos con fechas límite. fecha límite = ميعاد تسليم."},{q:"تاني مهارة ودليلها؟",options:["التصوير، عشان خد كورس فيه مرة في الصيف","الكلام قدّام ناس، عشان كانوا بيعملوا عروض كل شهر","السباحة، عشان بيروح النادي بشكل أسبوعي منتظم","الترجمة، عشان شغل سابق كان محتاجها بشكل يومي"],answer:"الكلام قدّام ناس، عشان كانوا بيعملوا عروض كل شهر",rationale:"قال: Aprendí a hablar en público. Hacíamos presentaciones cada mes. presentaciones = عروض."},{q:"ليه كل مهارة معاها سبب؟",options:["عشان دي قاعدة لغوية مشهورة مش هدفها الإقناع","عشان نملّي وقت المقابلة بكلام كتير ومكرر","عشان المهارة من غير دليل تبقى كلام عام ومش مقنع","مفيش سبب حقيقي وراها، دي مجرد عادة شكلية"],answer:"عشان المهارة من غير دليل تبقى كلام عام ومش مقنع",rationale:"كل مهارة اتبعت بجملة واقعية بتوضح منين جهت. ده اللي بيخلي مسؤولة التوظيف تصدّق."}],responseTask:{prompt:"اتسألت: اتعلّمت إيه من دراستك؟ جاوب بالإسباني بمهارة واحدة + منين جهت.",acceptable:["Aprendí a organizar mi tiempo. Teníamos muchos trabajos con fechas límite.","Aprendí a hablar en público. Hacíamos presentaciones cada mes.","Aprendí a trabajar en equipo. Hacíamos proyectos en grupo.","Aprendí a organizar mi tiempo con los trabajos de la universidad."],modelEs:"Aprendí a organizar mi tiempo. Teníamos muchos trabajos con fechas límite.",modelAr:"اتعلّمت أنظّم وقتي. كان عندنا شغل كتير بمواعيد تسليم.",checklistAr:"راجع إجابتك: ١) مهارة (aprendí a…)، ٢) مصدرها (trabajos / proyectos / presentaciones). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"aprender = يتعلّم. organizar = ينظّم. fecha límite = ميعاد تسليم. en público = قدّام ناس. útil = مفيد."}},{id:"iv-u02l05",courseId:"job-interview",unitId:"iv-u02",sourceLessonId:null,level:"B1",register:"usted",title:"الشغل التطوعي بيحسب",context:"معندكش خبرة مدفوعة، بس عندك تطوع أو تنظيم فعاليات. دورك: تقدّمه كخبرة حقيقية من غير مبالغة.",goal:"بعد الدرس ده حتقدر تحكي عن تطوعك أو نشاطك كدليل مهارة، بلفظ صادق (تطوع، مش وظيفة).",targets:[{es:"¿Tienes alguna experiencia relacionada?",ar:"عندك أي خبرة ليها علاقة؟",speaker:"luna"},{es:"Hice voluntariado en un evento deportivo.",ar:"عملت تطوع في فعالية رياضية.",speaker:"paco"},{es:"Ayudaba a la gente y contestaba sus preguntas.",ar:"كنت بساعد الناس وبرد على أسئلتهم.",speaker:"paco"},{es:"No era un trabajo pagado, era voluntariado.",ar:"مكانش شغل مدفوع، كان تطوع.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Tienes alguna experiencia relacionada?",ar:"عندك أي خبرة ليها علاقة؟"},{speaker:"paco",es:"Hice voluntariado en un evento deportivo.",ar:"عملت تطوع في فعالية رياضية."},{speaker:"luna",es:"¿Qué hacías exactamente?",ar:"كنت بتعمل إيه بالظبط؟"},{speaker:"paco",es:"Ayudaba a la gente y contestaba sus preguntas.",ar:"كنت بساعد الناس وبرد على أسئلتهم."},{speaker:"luna",es:"¿Era un trabajo pagado?",ar:"كان شغل مدفوع؟"},{speaker:"paco",es:"No era un trabajo pagado, era voluntariado. Pero aprendí mucho.",ar:"مكانش شغل مدفوع، كان تطوع. بس اتعلّمت كتير."},{speaker:"luna",es:"Es válido. Cuenta como experiencia.",ar:"ده مقبول. بيتحسب كخبرة."}],questions:[{q:"النشاط اللي حكاه؟",options:["وظيفة مؤقتة في بنك محلي","تطوع في فعالية رياضية","كابتن فريق كورة في الحارة","مدرّس خصوصي في الإنجليزي"],answer:"تطوع في فعالية رياضية",rationale:"قال: Hice voluntariado en un evento deportivo. voluntariado = تطوع، evento = فعالية."},{q:"كان بيعمل إيه في التطوع؟",options:["بيبيع تذاكر الدخول عند البوابة","بيدرّب الفريق على التمرينات","بيساعد الناس ويرد على أسئلتهم","بينضّف الملعب بعد الماتشات"],answer:"بيساعد الناس ويرد على أسئلتهم",rationale:"قال: Ayudaba a la gente y contestaba sus preguntas. contestar = يرد."},{q:"ليه وضّح إنه «مش شغل مدفوع»؟",options:["عشانها قاعدة قانونية ثابتة في كل مقابلات الشغل","عشان التطوع مش مهم أصلًا ومش بيتحسب خبرة حقيقية","عشان مش عايز الشغل ده أصلًا وبيضيّع وقت الناس","عشان الصدق في طبيعة النشاط بيحميك لو اتسألت تفاصيل"],answer:"عشان الصدق في طبيعة النشاط بيحميك لو اتسألت تفاصيل",rationale:"قال: No era un trabajo pagado, era voluntariado. لو قلت «وظيفة» على تطوع، أول سؤال تفصيلي حيكشفك."}],responseTask:{prompt:"احكي بالإسباني عن تطوع أو نشاط عملته: ماهيته + كنت بتعمل إيه + إنه تطوع.",acceptable:["Hice voluntariado en un evento deportivo. Ayudaba a la gente y contestaba sus preguntas. No era un trabajo pagado, era voluntariado.","Hice voluntariado en una ONG. Ayudaba a organizar actividades. No era pagado, era voluntariado.","Hice voluntariado en un evento. Ayudaba a la gente. Era voluntariado, no un trabajo pagado.","Hice voluntariado en un evento deportivo y ayudaba a la gente con sus preguntas."],modelEs:"Hice voluntariado en un evento deportivo. Ayudaba a la gente y contestaba sus preguntas. No era un trabajo pagado, era voluntariado.",modelAr:"عملت تطوع في فعالية رياضية. كنت بساعد الناس وبرد على أسئلتهم. مكانش شغل مدفوع، كان تطوع.",checklistAr:"راجع إجابتك: ١) النشاط (hice voluntariado)، ٢) المهام (ayudaba / contestaba)، ٣) صدق عن طبيعته (no era pagado). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"voluntariado = تطوع. evento = فعالية. pagado = مدفوع. contestar = يرد. es válido = ده مقبول/صالح."}},{id:"iv-u02l06",courseId:"job-interview",unitId:"iv-u02",sourceLessonId:null,level:"B1",register:"usted",title:"دراسة وخبرة في إجابة واحدة",context:"سؤال شامل: احكيلي عن دراستك وخبرتك. دورك: ترتّب الإجابة — دراسة، خبرة أو تطوع، وربط بالوظيفة — في تلات جمل.",goal:"بعد الدرس ده حتقدر تدي ملخص دراسة وخبرة متكامل ومرتب في أقل من دقيقة.",targets:[{es:"Estudié turismo en la universidad.",ar:"درست سياحة في الجامعة.",speaker:"paco"},{es:"Trabajé un año en una tienda.",ar:"اشتغلت سنة في محل.",speaker:"paco"},{es:"Por eso me interesa este puesto.",ar:"عشان كده مهتم بالوظيفة دي.",speaker:"paco"},{es:"Háblame de tu formación y experiencia.",ar:"احكيلي عن دراستك وخبرتك.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Háblame de tu formación y experiencia.",ar:"احكيلي عن دراستك وخبرتك."},{speaker:"paco",es:"Con mucho gusto. Estudié turismo en la universidad.",ar:"بكل سرور. درست سياحة في الجامعة."},{speaker:"luna",es:"¿Y después?",ar:"وبعد كده؟"},{speaker:"paco",es:"Trabajé un año en una tienda. Atendía a los clientes cada día.",ar:"اشتغلت سنة في محل. كنت بخدم العملاء كل يوم."},{speaker:"luna",es:"¿Por qué te interesa este puesto, entonces?",ar:"يبقى ليه مهتم بالوظيفة دي؟"},{speaker:"paco",es:"Por eso me interesa este puesto. Me gusta el trato con la gente.",ar:"عشان كده مهتم بالوظيفة دي. بحب التعامل مع الناس."},{speaker:"luna",es:"Muy claro, gracias.",ar:"واضح جدًا، شكرًا."}],questions:[{q:"ترتيب إجابة المتقدم؟",options:["دراسة، خبرة، ربط بالوظيفة","ربط بالوظيفة، دراسة، خبرة","خبرة، مرتب متوقع، دراسة","دراسة بس وخلاص على كده"],answer:"دراسة، خبرة، ربط بالوظيفة",rationale:"مشي: Estudié turismo → Trabajé un año → Por eso me interesa este puesto. الترتيب الزمني بيخلّي الإجابة سهلة التتبع."},{q:"الربط بالوظيفة اتقال بجملة إيه؟",options:["Por eso me interesa este puesto","Quiero mucho dinero y ya","No sé la verdad ahora","Porque sí y nada más"],answer:"Por eso me interesa este puesto",rationale:"por eso = عشان كده. الجملة دي بتوصّل الماضي بالوظيفة اللي قدّامك — ده قفل الإجابة."},{q:"تقييم مسؤولة التوظيف؟",options:["مش فاهمة حاجة","واضح جدًا، شكرًا","طويل أوي وممل","مش مقنع خالص"],answer:"واضح جدًا، شكرًا",rationale:"قالت: Muy claro, gracias. claro = واضح. الإجابة المرتبة بتاخد التقييم ده."}],responseTask:{prompt:"اتسألت عن دراستك وخبرتك مع بعض. جاوب بالإسباني في تلات جمل: دراسة + خبرة + ربط بالوظيفة.",acceptable:["Estudié turismo en la universidad. Trabajé un año en una tienda. Por eso me interesa este puesto.","Estudié turismo. Trabajé un año en una tienda, atendiendo a los clientes. Por eso me interesa este puesto.","Estudié comercio. Trabajé un año en una tienda. Por eso me interesa este puesto.","Estudié turismo en la universidad y trabajé un año en atención al cliente. Por eso me interesa este puesto."],modelEs:"Estudié turismo en la universidad. Trabajé un año en una tienda. Por eso me interesa este puesto.",modelAr:"درست سياحة في الجامعة. اشتغلت سنة في محل. عشان كده مهتم بالوظيفة دي.",checklistAr:"راجع إجابتك: ١) دراسة (estudié)، ٢) خبرة (trabajé)، ٣) ربط (por eso me interesa). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"formación = دراسة/تعليم. estudié = درست (ماضي). trabajé = اشتغلت (ماضي). por eso = عشان كده. trato = تعامل."}}]},{courseId:"job-interview",unit:{id:"iv-u03",title:"ليه الوظيفة دي؟",desc:"تشرح سبب اهتمامك الحقيقي بالشغل، وإيه اللي هتضيفه للفريق، وهدفك الواقعي بعد كام سنة.",cefr:"A2–B1"},lessons:[{id:"iv-u03l01",courseId:"job-interview",unitId:"iv-u03",sourceLessonId:"iv-u03l01",level:"A2",register:"usted",title:"سبب التقديم",context:"أول سؤال جاد في المقابلة: ليه مهتم بالوظيفة دي؟ دورك: تربط السبب بالشغل نفسه وباهتمام حقيقي عندك.",goal:"ترد على ¿Por qué te interesa este puesto? بسبب صادق ومحدد.",targets:[{es:"Me interesa porque disfruto ayudando a los clientes.",ar:"مهتم بيها عشان بحب أساعد العملاء.",speaker:"paco"},{es:"Porque me gusta hablar con la gente y resolver problemas.",ar:"عشان بحب أكلم الناس وأحل مشاكلهم.",speaker:"paco"},{es:"Sé que atienden a clientes de varios países.",ar:"عارف إنكم بتردّوا على عملاء من كذا دولة.",speaker:"paco"},{es:"También quiero desarrollar mis habilidades de comunicación.",ar:"كمان عايز أطوّر مهارات التواصل عندي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Gracias por venir, Omar. ¿Por qué te interesa este puesto?",ar:"شكرًا إنك جيت يا عمر. إنت مهتم بالوظيفة دي ليه؟"},{speaker:"paco",es:"Me interesa porque disfruto ayudando a los clientes.",ar:"مهتم بيها عشان بحب أساعد العملاء."},{speaker:"luna",es:"¿Y por qué en un call center?",ar:"وليه في كول سنتر بالذات؟"},{speaker:"paco",es:"Porque me gusta hablar con la gente y resolver problemas.",ar:"عشان بحب أكلم الناس وأحل مشاكلهم."},{speaker:"luna",es:"¿Qué sabes de nosotros?",ar:"إنت عارف إيه عنّا؟"},{speaker:"paco",es:"Sé que atienden a clientes de varios países.",ar:"عارف إنكم بتردّوا على عملاء من كذا دولة."},{speaker:"luna",es:"Exacto. ¿Qué más?",ar:"بالظبط. إيه كمان؟"},{speaker:"paco",es:"También quiero desarrollar mis habilidades de comunicación.",ar:"كمان عايز أطوّر مهارات التواصل عندي."}],questions:[{q:"ليه عمر مهتم بالوظيفة؟",options:["عشان بحب أساعد العملاء","عشان المرتب عالي جدًا","عشان قريب من بيته","عشان مفيش بديل"],answer:"عشان بحب أساعد العملاء",rationale:"قال حرفيًا: Me interesa porque disfruto ayudando a los clientes — مهتم بيها عشان بحب أساعد العملاء."},{q:"عمر عارف إيه عن الشركة؟",options:["إنها شركة طيران دولية كبيرة","إنها بترد على عملاء من كذا دولة","إنها لسه فاتحة من شهر واحد بس","إنها شركة عائلية صغيرة ومعروفة"],answer:"إنها بترد على عملاء من كذا دولة",rationale:"قال: Sé que atienden a clientes de varios países — عارف إنكم بتردّوا على عملاء من كذا دولة."},{q:"إيه أحسن سبب تقوله لما تتسأل «ليه الوظيفة دي»؟",options:["مجاملة طويلة للشركة من غير أي سبب شخصي","سبب عام زي إن المرتب كويس ومفيش كلام تاني","سبب حقيقي مربوط بالشغل نفسه زي حب مساعدة العملاء","أي إجابة سريعة، المحتوى مش مهم خالص"],answer:"سبب حقيقي مربوط بالشغل نفسه زي حب مساعدة العملاء",rationale:"هدف الدرس: اربط السبب بالشغل نفسه وباهتمام حقيقي عندك، زي ما عمل عمر لما قال إنه بيستمتع بمساعدة العملاء."}],responseTask:{prompt:"اتسألت: ¿Por qué te interesa este puesto? اربط السبب بالشغل نفسه وباهتمام حقيقي عندك، وزوّد حاجة عارفها عن الشركة.",acceptable:["Me interesa porque disfruto ayudando a los clientes.","Me interesa porque me gusta hablar con la gente y resolver problemas.","Me interesa porque quiero desarrollar mis habilidades de comunicación."],modelEs:"Me interesa porque disfruto ayudando a los clientes.",modelAr:"مهتم بيها عشان بحب أساعد العملاء.",checklistAr:"راجع إجابتك: ١) السبب مربوط بالشغل نفسه مش بحاجة عامة، ٢) اهتمام حقيقي عندك (disfruto / me gusta)، ٣) ممكن تزوّد حاجة عارفها عن الشركة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Me interesa porque... = مهتم عشان... disfruto + مصدر = بستمتع بـ. puesto = وظيفة/منصب. habilidades = مهارات. بلاش أسباب عامة زي المرتب بس؛ السبب الشخصي المربوط بالشغل أقوى."}},{id:"iv-u03l02",courseId:"job-interview",unitId:"iv-u03",sourceLessonId:"iv-u03l02",level:"A2",register:"usted",title:"هتضيف إيه؟",context:"مسؤولة التوظيف بتسأل: تقدر تضيف إيه للفريق؟ دورك: تختار مهارة عندك فعلًا وتجهّز مثال حقيقي يوضحها.",goal:"تجاوب على ¿Qué puedes aportar? بمهارة + مثال.",targets:[{es:"Puedo aportar paciencia y capacidad de escucha.",ar:"أقدر أفيد الفريق بصبري وبإني بعرف أسمع الناس كويس.",speaker:"paco"},{es:"Sí, puedo dar un ejemplo de mis estudios.",ar:"أيوه، أقدر أدي مثال من دراستي.",speaker:"paco"},{es:"En la universidad escuchaba las dudas de mis compañeros antes de responder.",ar:"في الجامعة كنت بسمع استفسارات زمايلي الأول قبل ما أرد.",speaker:"paco"},{es:"Porque el cliente quiere sentirse comprendido.",ar:"عشان العميل عايز يحس إنه مفهوم.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Ahora cuéntame, ¿qué puedes aportar al equipo?",ar:"طب قوللي، تقدر تضيف إيه للفريق؟"},{speaker:"paco",es:"Puedo aportar paciencia y capacidad de escucha.",ar:"أقدر أفيد الفريق بصبري وبإني بعرف أسمع الناس كويس."},{speaker:"luna",es:"¿Puedes dar un ejemplo?",ar:"تقدر تدي مثال؟"},{speaker:"paco",es:"Sí, puedo dar un ejemplo de mis estudios.",ar:"أيوه، أقدر أدي مثال من دراستي."},{speaker:"paco",es:"En la universidad escuchaba las dudas de mis compañeros antes de responder.",ar:"في الجامعة كنت بسمع استفسارات زمايلي الأول قبل ما أرد."},{speaker:"luna",es:"Bien. ¿Y por qué es importante escuchar aquí?",ar:"كويس. وليه السمع مهم هنا؟"},{speaker:"paco",es:"Porque el cliente quiere sentirse comprendido.",ar:"عشان العميل عايز يحس إنه مفهوم."},{speaker:"luna",es:"Muy buena respuesta.",ar:"إجابة كويسة جدًا."}],questions:[{q:"عمر قال إنه هيضيف إيه للفريق؟",options:["طلاقة في خمس لغات","سرعة في الكتابة على الكيبورد","خبرة عشر سنين في المجال","صبر وقدرة على السمع الكويس"],answer:"صبر وقدرة على السمع الكويس",rationale:"قال: Puedo aportar paciencia y capacidad de escucha — أقدر أفيد الفريق بصبري وبإني بعرف أسمع الناس كويس."},{q:"المثال اللي قدّمه عمر كان عن إيه؟",options:["إنه كان بيسمع استفسارات زمايله في الجامعة قبل ما يرد","إنه كسب مسابقة في الإلقاء على مستوى الجامعة كلها","إنه اشتغل في محل ملابس وهو لسه طالب في الجامعة","إنه سافر لوحده برّه واتعلّم يعتمد على نفسه"],answer:"إنه كان بيسمع استفسارات زمايله في الجامعة قبل ما يرد",rationale:"قال: En la universidad escuchaba las dudas de mis compañeros antes de responder — في الجامعة كنت بسمع أسئلة زمايلي الأول قبل ما أرد."},{q:"ليه السمع مهم في شغل الكول سنتر؟",options:["عشان الشيفت طويل وممل","عشان المكالمات بتتسجل للجودة","عشان السماعة صوتها واطي أحيانًا","عشان العميل عايز يحس إنه مفهوم"],answer:"عشان العميل عايز يحس إنه مفهوم",rationale:"قال: Porque el cliente quiere sentirse comprendido — عشان العميل عايز يحس إنه مفهوم."}],responseTask:{prompt:"اتسألت: ¿Qué puedes aportar al equipo? اختار مهارة عندك فعلًا وجهّز مثال حقيقي يوضحها.",acceptable:["Puedo aportar paciencia y capacidad de escucha.","Puedo aportar organización y ganas de aprender.","Puedo aportar calma bajo presión y trabajo en equipo."],modelEs:"Puedo aportar paciencia y capacidad de escucha.",modelAr:"أقدر أفيد الفريق بصبري وبإني بعرف أسمع الناس كويس.",checklistAr:"راجع إجابتك: ١) مهارة عندك فعلًا مش مثالية، ٢) جاهز بمثال حقيقي لو اتسألت، ٣) اربطها بشغل الوظيفة (العميل/الفريق). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Puedo aportar + اسم = أقدر أضيف/أفيد بـ. capacidad de escucha = قدرة على السمع. escuchaba = كنت بسمع (ماضي مستمر). اختار مهارة حقيقية: لو اتسألت عن مثال وهتتلخبط، يبقى السؤال الجاي هيكشفك."}},{id:"iv-u03l03",courseId:"job-interview",unitId:"iv-u03",sourceLessonId:"iv-u03l03",level:"A2",register:"usted",title:"هدفك الجاي",context:"سؤال كلاسيكي: شايف نفسك فين بعد كام سنة؟ دورك: خطة واقعية، من غير وعود بترقيات ولا أهداف مش بتاعتك.",goal:"تجاوب على ¿Dónde te ves dentro de unos años? بهدف واقعي.",targets:[{es:"Me gustaría asumir más responsabilidad con el tiempo.",ar:"نفسي أتحمّل مسؤولية أكتر مع الوقت.",speaker:"paco"},{es:"Quizás coordinar a un equipo pequeño.",ar:"يمكن أدير فريق صغير.",speaker:"paco"},{es:"Quiero seguir aprendiendo en este sector.",ar:"عايز أفضل أتعلّم في المجال ده.",speaker:"paco"},{es:"Prefiero metas que pueda cumplir.",ar:"بفضّل أهداف أقدر أوصلها.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Dónde te ves dentro de unos años, Omar?",ar:"شايف نفسك فين بعد كام سنة يا عمر؟"},{speaker:"paco",es:"Me gustaría asumir más responsabilidad con el tiempo.",ar:"نفسي أتحمّل مسؤولية أكتر مع الوقت."},{speaker:"luna",es:"¿Por ejemplo?",ar:"مثلًا إيه؟"},{speaker:"paco",es:"Quizás coordinar a un equipo pequeño.",ar:"يمكن أدير فريق صغير."},{speaker:"luna",es:"¿Y cómo piensas llegar ahí?",ar:"وعايز توصل لده إزاي؟"},{speaker:"paco",es:"Quiero seguir aprendiendo en este sector.",ar:"عايز أفضل أتعلّم في المجال ده."},{speaker:"luna",es:"Es un plan realista.",ar:"دي خطة واقعية."},{speaker:"paco",es:"Gracias. Prefiero metas que pueda cumplir.",ar:"شكرًا. بفضّل أهداف أقدر أوصلها."}],questions:[{q:"هدف عمر بعد كام سنة؟",options:["يتحمّل مسؤولية أكتر مع الوقت","يفتح شركته الخاصة فورًا","يسيب المجال خالص ويسافر","يبقى مدير الشركة في سنة"],answer:"يتحمّل مسؤولية أكتر مع الوقت",rationale:"قال: Me gustaría asumir más responsabilidad con el tiempo — نفسي أتحمّل مسؤولية أكتر مع الوقت."},{q:"المثال اللي ذكره على المسؤولية؟",options:["تدريب الموظفين الجدد","إدارة فريق صغير","فتح فرع جديد للشركة","توقيع عقود مع العملاء"],answer:"إدارة فريق صغير",rationale:"قال: Quizás coordinar a un equipo pequeño — يمكن أدير فريق صغير."},{q:"ليه مسؤولة التوظيف شافت الخطة واقعية؟",options:["عشانه جايب خطة مكتوبة ومفصلة لخمس سنين","عشانه قال إنه عايز يبقى مدير في أقرب وقت ممكن","عشانه اتكلم بثقة عالية ومرددش في أي سؤال","عشانه ما وعدش بترقية مضمونة واختار هدف ممكن التحقيق"],answer:"عشانه ما وعدش بترقية مضمونة واختار هدف ممكن التحقيق",rationale:"قال في الآخر: Prefiero metas que pueda cumplir — بفضّل أهداف أقدر أوصلها. الواقعية هنا إنه ما وعدش بحاجة مش في إيده."}],responseTask:{prompt:"اتسألت: ¿Dónde te ves dentro de unos años? اختار خطة واقعية: مسؤولية أكتر أو تعلم مستمر، من غير وعود بترقيات.",acceptable:["Me gustaría asumir más responsabilidad con el tiempo.","Quiero seguir aprendiendo en este sector.","Me gustaría crecer dentro de la empresa."],modelEs:"Me gustaría asumir más responsabilidad con el tiempo.",modelAr:"نفسي أتحمّل مسؤولية أكتر مع الوقت.",checklistAr:"راجع إجابتك: ١) هدف واقعي وممكن التحقيق، ٢) مربوط بالمجال أو الشركة، ٣) من غير وعود بترقية أو أرقام. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Me gustaría + مصدر = نفسي/حابب (صيغة مهذبة). seguir + اسم/مصدر = أفضل/أستمر في. dentro de unos años = بعد كام سنة. بلاش «هبقى مدير في سنة»: وعد مش في إيدك وبيبان مبالغة."}},{id:"iv-u03l04",courseId:"job-interview",unitId:"iv-u03",sourceLessonId:null,level:"A2",register:"usted",title:"ليه الشركة دي بالذات؟",context:"سؤال أصعب: في شركات كتير، ليه إحنا؟ دورك: سبب محدد وحقيقي عن الشركة نفسها، مش مجاملة فاضية.",goal:"تجاوب على ¿Por qué esta empresa? بسبب محدد.",targets:[{es:"Porque escuché cosas buenas sobre su formación.",ar:"عشان سمعت كلام كويس عن التدريب عندكم.",speaker:"paco"},{es:"Un amigo trabajó aquí y aprendió mucho.",ar:"صاحبي اشتغل هنا واتعلّم كتير.",speaker:"paco"},{es:"También me interesa el horario flexible que ofrecen.",ar:"كمان مهتم بالمواعيد المرنة اللي بتقدّموها.",speaker:"paco"},{es:"Por eso elegí esta empresa y no otra.",ar:"عشان كده اخترت الشركة دي مش غيرها.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hay muchas empresas. ¿Por qué esta?",ar:"في شركات كتير. ليه الشركة دي بالذات؟"},{speaker:"paco",es:"Porque escuché cosas buenas sobre su formación.",ar:"عشان سمعت كلام كويس عن التدريب عندكم."},{speaker:"luna",es:"¿Quién te lo dijo?",ar:"مين قالك كده؟"},{speaker:"paco",es:"Un amigo trabajó aquí y aprendió mucho.",ar:"صاحبي اشتغل هنا واتعلّم كتير."},{speaker:"luna",es:"Ya veo. ¿Algo más?",ar:"فهمت. في حاجة تانية؟"},{speaker:"paco",es:"También me interesa el horario flexible que ofrecen.",ar:"كمان مهتم بالمواعيد المرنة اللي بتقدّموها."},{speaker:"luna",es:"Es verdad que lo ofrecemos.",ar:"صحيح إحنا بنقدّم ده."},{speaker:"paco",es:"Por eso elegí esta empresa y no otra.",ar:"عشان كده اخترت الشركة دي مش غيرها."}],questions:[{q:"ليه عمر اختار الشركة دي بالذات؟",options:["عشان سمع كلام كويس عن التدريب ومهتم بالمواعيد المرنة","عشان إعلان الوظيفة كان أول إعلان شافه على النت","عشان الشركة قريبة من بيته ومش هياخد مواصلات","عشان مفيش شركة تانية قبلت الطلب بتاعه"],answer:"عشان سمع كلام كويس عن التدريب ومهتم بالمواعيد المرنة",rationale:"قال: Porque escuché cosas buenas sobre su formación وبعدين También me interesa el horario flexible que ofrecen — سمع كلام كويس عن التدريب ومهتم بالمواعيد المرنة."},{q:"مصدر كلام عمر عن التدريب في الشركة؟",options:["إعلان مدفوع شافه على التلفزيون","صاحبه اللي اشتغل هنا قبل كده","موقع الشركة الرسمي بس","قراها في جريدة قديمة"],answer:"صاحبه اللي اشتغل هنا قبل كده",rationale:"قال: Un amigo trabajó aquí y aprendió mucho — صاحبي اشتغل هنا واتعلّم كتير."},{q:"إيه أحسن طريقة تجاوب على «ليه الشركة دي»؟",options:["القول إن مفيش اختيارات تانية قدامك دلوقتي","مجاملة عامة من غير أي تفاصيل ملموسة عن الشركة","سبب محدد وحقيقي عن الشركة نفسها زي التدريب أو النظام","تجاهل السؤال وتحويل الكلام للمرتب فورًا"],answer:"سبب محدد وحقيقي عن الشركة نفسها زي التدريب أو النظام",rationale:"عمر ربط اختياره بحاجتين محددتين: التدريب اللي سمع عنه من صاحبه، والمواعيد المرنة. السبب المحدد بيبين إنك بحثت فعلًا."}],responseTask:{prompt:"اتسألت: ¿Por qué esta empresa? ادي سبب محدد وحقيقي عن الشركة نفسها (تدريب، نظام، سمعة)، مش مجاملة عامة.",acceptable:["Porque escuché cosas buenas sobre su formación.","Porque me interesa el horario flexible que ofrecen.","Porque quiero trabajar en una empresa seria como esta."],modelEs:"Porque escuché cosas buenas sobre su formación.",modelAr:"عشان سمعت كلام كويس عن التدريب عندكم.",checklistAr:"راجع إجابتك: ١) سبب محدد مش مجاملة عامة، ٢) مصدر معلوماتك واضح لو اتسألت، ٣) تربط السبب بالشركة نفسها. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"escuché = سمعت (ماضي بسيط). formación = تدريب/تأهيل. elegí = اخترت. «سمعت كلام كويس» سبب مقبول لو عندك مصدر؛ المجاملة من غير تفاصيل بتبان فاضية."}},{id:"iv-u03l05",courseId:"job-interview",unitId:"iv-u03",sourceLessonId:null,level:"B1",register:"usted",title:"ليه نختارك؟",context:"سؤال الحسم: لو هتلخّصها، ليه المفروض نختارك؟ دورك: تلخّص اهتمامك وإضافتك بصدق، من غير وعود خيالية.",goal:"تلخّص قيمتك: اهتمام + إضافة + وعد واقعي بالمجهود.",targets:[{es:"Porque me interesa el trabajo y puedo aportar paciencia.",ar:"عشان مهتم بالشغل وأقدر أفيد بصبري.",speaker:"paco"},{es:"No, también ganas de aprender y compromiso.",ar:"لأ، كمان رغبة في التعلم والتزام.",speaker:"paco"},{es:"Por eso prometo esfuerzo, no resultados mágicos.",ar:"عشان كده بوعد بمجهود، مش بنتايج سحرية.",speaker:"paco"},{es:"Creo que la honestidad vale más.",ar:"شايف إن الصراحة أحسن.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Si tuvieras que resumirlo, ¿por qué deberíamos elegirte?",ar:"لو هتلخّصها، ليه المفروض نختارك؟"},{speaker:"paco",es:"Porque me interesa el trabajo y puedo aportar paciencia.",ar:"عشان مهتم بالشغل وأقدر أفيد بصبري."},{speaker:"luna",es:"¿Solo paciencia?",ar:"صبر بس؟"},{speaker:"paco",es:"No, también ganas de aprender y compromiso.",ar:"لأ، كمان رغبة في التعلم والتزام."},{speaker:"luna",es:"El compromiso es importante.",ar:"الالتزام مهم فعلًا."},{speaker:"paco",es:"Por eso prometo esfuerzo, no resultados mágicos.",ar:"عشان كده بوعد بمجهود، مش بنتايج سحرية."},{speaker:"luna",es:"Me gusta esa sinceridad.",ar:"الصدق ده عاجبني."},{speaker:"paco",es:"Gracias. Creo que la honestidad vale más.",ar:"شكرًا. شايف إن الصراحة أحسن."}],questions:[{q:"عمر وعد بإيه في الآخر؟",options:["بمضاعفة مبيعات الشركة في شهر","بمجهود حقيقي مش بنتايج سحرية","بعدم طلب أي إجازات في السنة","بتعلم اللغة كاملة في أسبوعين"],answer:"بمجهود حقيقي مش بنتايج سحرية",rationale:"قال: Por eso prometo esfuerzo, no resultados mágicos — عشان كده بوعد بمجهود، مش بنتايج سحرية."},{q:"الصفات اللي ذكرها عمر غير الصبر؟",options:["قوة شخصية وصوت عالي","سرعة بديهة وخفة دم","رغبة في التعلم والتزام","شهادات كتير وخبرة طويلة"],answer:"رغبة في التعلم والتزام",rationale:"قال: No, también ganas de aprender y compromiso — لأ، كمان رغبة في التعلم والتزام."},{q:"ليه إجابة «بوعد بمجهود» أقوى من «هحقق أرقام خيالية»؟",options:["عشان الوعود الكبيرة محظورة قانونيًا","عشانها أقصر وبتخلّص المقابلة بسرعة","عشان مسؤولة التوظيف مش بتفهم في الأرقام","عشانها صادقة ومبنية على حاجة في إيدك فعلًا"],answer:"عشانها صادقة ومبنية على حاجة في إيدك فعلًا",rationale:"المجهود في إيدك، النتايج مش كله في إيدك. مسؤولة التوظيف نفسها قالت: Me gusta esa sinceridad — الصدق ده عاجبني."}],responseTask:{prompt:"اتسألت: ¿Por qué deberíamos elegirte? لخّص اهتمامك وإضافتك، واختم بوعد واقعي بالمجهود مش بمعجزات.",acceptable:["Porque me interesa el trabajo y puedo aportar paciencia.","Porque tengo ganas de aprender y compromiso.","Porque prometo esfuerzo y honestidad, no resultados mágicos."],modelEs:"Porque me interesa el trabajo y puedo aportar paciencia.",modelAr:"عشان مهتم بالشغل وأقدر أفيد بصبري.",checklistAr:"راجع إجابتك: ١) تلخّص اهتمامك بالشغل، ٢) تذكر إضافة حقيقية عندك، ٣) وعد بالمجهود مش بنتايج مضمونة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"deberíamos elegirte = المفروض نختارك (شرطي مهذب). ganas de aprender = رغبة في التعلم. compromiso = التزام. prometo = بوعد. الوعد بالمجهود صادق؛ الوعد بنتايج مضمونة مبالغة هتترفض."}},{id:"iv-u03l06",courseId:"job-interview",unitId:"iv-u03",sourceLessonId:null,level:"B1",register:"usted",title:"الإجابة المتكاملة",context:"تدريب قفلة للوحدة: سؤالين ورا بعض، وإجابة واحدة متكاملة تجمع السبب والإضافة والهدف.",goal:"تجاوب على سؤالين متتاليين بإجابة مترابطة: اهتمام، إضافة، هدف.",targets:[{es:"Me interesa porque disfruto ayudando a los clientes.",ar:"مهتم بيها عشان بحب أساعد العملاء.",speaker:"paco"},{es:"Puedo aportar paciencia y capacidad de escucha.",ar:"أقدر أفيد بصبري وبسمعي الكويس.",speaker:"paco"},{es:"Quiero seguir aprendiendo y asumir más responsabilidad.",ar:"عايز أفضل أتعلّم وأتحمّل مسؤولية أكتر.",speaker:"paco"},{es:"Gracias a usted por escucharme.",ar:"وأنا شكرًا لحضرتك إنك سمعتيني.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Última pregunta de esta parte, Omar.",ar:"آخر سؤال في الجزء ده يا عمر."},{speaker:"luna",es:"¿Por qué este puesto y qué puedes aportar?",ar:"ليه الوظيفة دي وتقدر تضيف إيه؟"},{speaker:"paco",es:"Me interesa porque disfruto ayudando a los clientes.",ar:"مهتم بيها عشان بحب أساعد العملاء."},{speaker:"paco",es:"Puedo aportar paciencia y capacidad de escucha.",ar:"أقدر أفيد بصبري وبسمعي الكويس."},{speaker:"luna",es:"¿Y dónde te ves dentro de unos años?",ar:"وشايف نفسك فين بعد كام سنة؟"},{speaker:"paco",es:"Quiero seguir aprendiendo y asumir más responsabilidad.",ar:"عايز أفضل أتعلّم وأتحمّل مسؤولية أكتر."},{speaker:"luna",es:"Muy completo. Gracias.",ar:"إجابة متكاملة. شكرًا."},{speaker:"paco",es:"Gracias a usted por escucharme.",ar:"وأنا شكرًا لحضرتك إنك سمعتيني."}],questions:[{q:"الإجابة المتكاملة لعمر جمعت إيه؟",options:["سبب الاهتمام والإضافة والهدف المستقبلي","الدراسة والمرتب المتوقع والإجازات","اسم الشركة وعنوانها وتاريخ تأسيسها","الهوايات والعيلة والسفر"],answer:"سبب الاهتمام والإضافة والهدف المستقبلي",rationale:"جاوب على ليه الوظيفة (Me interesa porque disfruto ayudando a los clientes)، وإضافته (Puedo aportar paciencia)، وهدفه (Quiero seguir aprendiendo)."},{q:"عمر شكر مسؤولة التوظيف على إيه في الآخر؟",options:["إنها سمعته","إنها قبلته في الشغل","إنها عرضت عليه قهوة","إنها وصلته للباب"],answer:"إنها سمعته",rationale:"قال: Gracias a usted por escucharme — وأنا شكرًا لحضرتك إنك سمعتني."},{q:"الترتيب الصح لإجابة «ليه الوظيفة دي» الكاملة؟",options:["هدف بعيد، بعدين مرتب، بعدين شكر وسلام","اهتمام حقيقي، بعدين إضافة، بعدين هدف واقعي","إضافة، بعدين اعتذار، بعدين سؤال عن الإجازات","مجاملة، بعدين صمت، بعدين اتفاق على الميعاد"],answer:"اهتمام حقيقي، بعدين إضافة، بعدين هدف واقعي",rationale:"ده بالظبط اللي عمله عمر: اهتمام (disfruto ayudando)، إضافة (puedo aportar)، هدف (quiero seguir aprendiendo)."}],responseTask:{prompt:"اتسألت سؤالين ورا بعض: ليه الوظيفة دي وتقدر تضيف إيه؟ وبعدين شايف نفسك فين؟ جاوب إجابة متكاملة تجمع التلاتة.",acceptable:["Me interesa porque disfruto ayudando a los clientes. Puedo aportar paciencia y capacidad de escucha. Quiero seguir aprendiendo en este sector.","Me interesa el trabajo, puedo aportar compromiso, y quiero crecer con el tiempo.","Me interesa ayudar a los clientes, aporto calma y escucha, y quiero asumir más responsabilidad."],modelEs:"Me interesa porque disfruto ayudando a los clientes. Puedo aportar paciencia y capacidad de escucha. Quiero seguir aprendiendo en este sector.",modelAr:"مهتم بيها عشان بحب أساعد العملاء. أقدر أفيد بصبري وبسمعي الكويس. عايز أفضل أتعلّم في المجال ده.",checklistAr:"راجع إجابتك: ١) سبب اهتمام حقيقي، ٢) إضافة محددة عندك، ٣) هدف واقعي من غير وعود. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"دي قفلة الوحدة: interés + aporte + objetivo. حافظ على نفس ترتيب عمر وربّط الجمل ببعض بشكل طبيعي. Gracias a usted por escucharme قفلة مهذبة بصيغة usted."}}]},{courseId:"job-interview",unit:{id:"iv-u04",title:"نقاط القوة والتحسين",desc:"تقول نقطة قوة محددة مع دليل حقيقي، ونقطة تحسين صادقة مع خطوة بتعملها فعلًا.",cefr:"A2–B1"},lessons:[{id:"iv-u04l01",courseId:"job-interview",unitId:"iv-u04",sourceLessonId:"iv-u04l01",level:"A2",register:"usted",title:"نقطة قوة محددة",context:"سؤال متوقع: إيه نقاط قوتك؟ دورك: مهارة واحدة مرتبطة بالوظيفة، مش قائمة صفات محفوظة.",goal:"تجاوب على ¿Cuáles son tus puntos fuertes? بنقطة محددة مرتبطة بالشغل.",targets:[{es:"Mi punto fuerte es escuchar con atención.",ar:"نقطة قوتي إني بسمع بانتباه.",speaker:"paco"},{es:"También me organizo bien cuando tengo varias tareas.",ar:"بعرف أنظّم نفسي لما يبقى عندي كذا مهمة.",speaker:"paco"},{es:"No es una lista, es mi punto fuerte de verdad.",ar:"دي مش قائمة محفوظة، دي نقطة قوتي بجد.",speaker:"paco"},{es:"En este trabajo escuchar es lo primero.",ar:"في الشغل ده السمع هو الأول.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Vamos con una pregunta clásica. ¿Cuáles son tus puntos fuertes?",ar:"هنسأل سؤال كلاسيكي. إيه نقاط قوتك؟"},{speaker:"paco",es:"Mi punto fuerte es escuchar con atención.",ar:"نقطة قوتي إني بسمع بانتباه."},{speaker:"luna",es:"¿Solo uno? La mayoría dice una lista.",ar:"واحدة بس؟ أغلب الناس بتقول قائمة."},{speaker:"paco",es:"No es una lista, es mi punto fuerte de verdad.",ar:"دي مش قائمة محفوظة، دي نقطة قوتي بجد."},{speaker:"paco",es:"También me organizo bien cuando tengo varias tareas.",ar:"وكمان بعرف أنظّم نفسي لما يبقى عندي كذا مهمة."},{speaker:"luna",es:"¿Por qué mencionas escuchar primero?",ar:"ليه ذكرت السمع الأول؟"},{speaker:"paco",es:"En este trabajo escuchar es lo primero.",ar:"في الشغل ده السمع هو الأول."},{speaker:"luna",es:"Buena conexión con el puesto.",ar:"ربط كويس بالوظيفة."}],questions:[{q:"أول نقطة قوة قالها عمر؟",options:["إنه بيسمع بانتباه","إنه بيتكلم بسرعة","إنه بيحفظ بسرعة","إنه بيشتغل لوحده"],answer:"إنه بيسمع بانتباه",rationale:"قال: Mi punto fuerte es escuchar con atención — نقطة قوتي إني بسمع بانتباه."},{q:"نقطة القوة التانية اللي ذكرها؟",options:["إنه بييجي قبل المعاد بساعة","إنه بينظّم نفسه مع كذا مهمة","إنه بيعرف لغات كتير","إنه بيحب الشغل تحت ضغط"],answer:"إنه بينظّم نفسه مع كذا مهمة",rationale:"قال: También me organizo bien cuando tengo varias tareas — وكمان بعرف أنظّم نفسي لما يبقى عندي كذا مهمة."},{q:"ليه عمر قال نقطة واحدة واضحة مش قائمة؟",options:["عشان مسؤولة التوظيف طلبت نقطة واحدة بالظبط منه","عشان ميعرفش يعدّد صفات كتير باللغة الإسبانية","عشان نقطة محددة مرتبطة بالوظيفة أقوى من قائمة محفوظة","عشان القوائم الطويلة ممنوعة في المقابلات الرسمية"],answer:"عشان نقطة محددة مرتبطة بالوظيفة أقوى من قائمة محفوظة",rationale:"قال: No es una lista, es mi punto fuerte de verdad وربطها بالشغل: En este trabajo escuchar es lo primero."}],responseTask:{prompt:"اتسألت: ¿Cuáles son tus puntos fuertes? اختار نقطة قوة واحدة مرتبطة بالوظيفة وقولها بثقة.",acceptable:["Mi punto fuerte es escuchar con atención.","Mi punto fuerte es organizarme bien con varias tareas.","Mi punto fuerte es mantener la calma con los clientes."],modelEs:"Mi punto fuerte es escuchar con atención.",modelAr:"نقطة قوتي إني بسمع بانتباه.",checklistAr:"راجع إجابتك: ١) نقطة واحدة محددة مش قائمة، ٢) مرتبطة بالوظيفة اللي بتقدم عليها، ٣) قولها بثقة من غير مبالغة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"punto fuerte = نقطة قوة. escuchar con atención = يسمع بانتباه. organizarse = ينظّم نفسه. varias tareas = كذا مهمة. بلاش «نقاط قوتي إني شاطر ومجتهد وملتزم» — دي قائمة محفوظة محدش بيصدقها."}},{id:"iv-u04l02",courseId:"job-interview",unitId:"iv-u04",sourceLessonId:"iv-u04l02",level:"A2",register:"usted",title:"دليل مش وصف بس",context:"مسؤولة التوظيف عايزة دليل على نقطة القوة. دورك: مثال حقيقي من الدراسة أو التطوع، مناسب للسؤال.",goal:"تدعم نقطة القوة بمثال حقيقي بنتيجة واضحة.",targets:[{es:"Por ejemplo, organicé las tareas de un proyecto de clase.",ar:"مثلًا، نظّمت مهام مشروع في الدراسة.",speaker:"paco"},{es:"Primero escucho y después confirmo lo que he entendido.",ar:"الأول بسمع، وبعد كده بتأكد إني فهمت صح.",speaker:"paco"},{es:"Eso nos ayudó a terminar a tiempo.",ar:"وده ساعدنا نخلّص في المعاد.",speaker:"paco"},{es:"El ejemplo es real, de mi universidad.",ar:"المثال ده حقيقي، من جامعتي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Dices que escuchas con atención. ¿Tienes un ejemplo?",ar:"بتقول إنك بتسمع بانتباه. عندك مثال؟"},{speaker:"paco",es:"Por ejemplo, organicé las tareas de un proyecto de clase.",ar:"مثلًا، نظّمت مهام مشروع في الدراسة."},{speaker:"luna",es:"¿Y qué hacías exactamente?",ar:"وكنت بتعمل إيه بالظبط؟"},{speaker:"paco",es:"Primero escucho y después confirmo lo que he entendido.",ar:"الأول بسمع، وبعد كده بتأكد إني فهمت صح."},{speaker:"luna",es:"¿Y el resultado?",ar:"والنتيجة كانت إيه؟"},{speaker:"paco",es:"Eso nos ayudó a terminar a tiempo.",ar:"وده ساعدنا نخلّص في المعاد."},{speaker:"luna",es:"¿Es un ejemplo real o preparado?",ar:"ده مثال حقيقي ولا متحضّر؟"},{speaker:"paco",es:"El ejemplo es real, de mi universidad.",ar:"المثال ده حقيقي، من جامعتي."}],questions:[{q:"مثال عمر على نقطة قوته؟",options:["إنه ساعد في تنظيم حفل تخرج","إنه كسب جائزة في الخطابة","إنه اشتغل في مكتبة الجامعة","إنه نظّم مهام مشروع في الدراسة"],answer:"إنه نظّم مهام مشروع في الدراسة",rationale:"قال: Por ejemplo, organicé las tareas de un proyecto de clase — مثلًا، نظّمت مهام مشروع في الدراسة."},{q:"طريقته في التأكد من الفهم؟",options:["بيسأل نفس السؤال مرتين ورا بعض","بيكتب كل كلمة ورا المتكلم في ورقة","بيسمع الأول وبعدين بيتأكد إنه فهم صح","بيطلب من الناس تتكلم ببطء شديد"],answer:"بيسمع الأول وبعدين بيتأكد إنه فهم صح",rationale:"قال: Primero escucho y después confirmo lo que he entendido — الأول بسمع، وبعد كده بتأكد إني فهمت صح."},{q:"نتيجة المثال اللي حكاه؟",options:["المشروع اتنشر في مجلة علمية","الفريق كسب أعلى درجة في الجامعة","الدكتور عيّنه قائد دائم للمشاريع","الفريق خلّص الشغل في المعاد"],answer:"الفريق خلّص الشغل في المعاد",rationale:"قال: Eso nos ayudó a terminar a tiempo — وده ساعدنا نخلّص في المعاد."}],responseTask:{prompt:"اتسألت عن مثال يثبت نقطة قوتك. احكِ مثال حقيقي من الدراسة أو التطوع: الموقف، تصرفك، والنتيجة.",acceptable:["Por ejemplo, organicé las tareas de un proyecto de clase.","Por ejemplo, ayudé a los visitantes en un evento deportivo.","Por ejemplo, escuché las dudas de mis compañeros y las expliqué."],modelEs:"Por ejemplo, organicé las tareas de un proyecto de clase.",modelAr:"مثلًا، نظّمت مهام مشروع في الدراسة.",checklistAr:"راجع إجابتك: ١) مثال حقيقي حصل فعلًا، ٢) فيه تصرف واضح عملته إنت، ٣) فيه نتيجة محسوسة في الآخر. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Por ejemplo = مثلًا. organicé = نظّمت (ماضي بسيط). confirmo lo que he entendido = بتأكد إني فهمت. a tiempo = في المعاد. المثال من الدراسة أو التطوع ينفع تمامًا لو حقيقي ومناسب للسؤال."}},{id:"iv-u04l03",courseId:"job-interview",unitId:"iv-u04",sourceLessonId:"iv-u04l03",level:"A2",register:"usted",title:"حاجة بتحسّنها",context:"السؤال المقلق: إيه الحاجة اللي محتاج تحسّنها؟ دورك: نقطة حقيقية + إيه اللي بتعمله لتحسينها.",goal:"تجاوب على ¿Qué aspecto necesitas mejorar? بصدق وخطة.",targets:[{es:"Necesito mejorar mi rapidez al escribir.",ar:"محتاج أحسّن سرعتي في الكتابة.",speaker:"paco"},{es:"Estoy practicando para escribir con más rapidez y precisión.",ar:"بتدرّب عشان أكتب أسرع وبدقة أكتر.",speaker:"paco"},{es:"No es un problema grave, pero quiero mejorarlo.",ar:"دي مش مشكلة كبيرة، بس عايز أحسّنها.",speaker:"paco"},{es:"Practico un poco cada día.",ar:"بتدرّب شوية كل يوم.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Ahora la pregunta difícil. ¿Qué aspecto necesitas mejorar?",ar:"دلوقتي السؤال الصعب. إيه الحاجة اللي محتاج تحسّنها؟"},{speaker:"paco",es:"Necesito mejorar mi rapidez al escribir.",ar:"محتاج أحسّن سرعتي في الكتابة."},{speaker:"luna",es:"¿Y qué haces para mejorarla?",ar:"وبتعمل إيه عشان تحسّنها؟"},{speaker:"paco",es:"Estoy practicando para escribir con más rapidez y precisión.",ar:"بتدرّب عشان أكتب أسرع وبدقة أكتر."},{speaker:"luna",es:"¿Con qué frecuencia practicas?",ar:"بتتدرّب كل قد إيه؟"},{speaker:"paco",es:"Practico un poco cada día.",ar:"بتدرّب شوية كل يوم."},{speaker:"luna",es:"Algunos dicen que no tienen puntos débiles.",ar:"في ناس بتقول ماعندهاش نقاط ضعف."},{speaker:"paco",es:"No es mi caso. No es un problema grave, pero quiero mejorarlo.",ar:"مش حالتي. دي مش مشكلة كبيرة، بس عايز أحسّنها."}],questions:[{q:"الحاجة اللي عمر محتاج يحسّنها؟",options:["سرعته في الكتابة","نطقه للحروف الصعبة","ذاكرته للأسماء","تركيزه في الصبح"],answer:"سرعته في الكتابة",rationale:"قال: Necesito mejorar mi rapidez al escribir — محتاج أحسّن سرعتي في الكتابة."},{q:"إيه خطته للتحسين؟",options:["حجز كورس مكثف الشهر الجاي في المعهد","بيتدرّب شوية كل يوم عشان يكتب أسرع وأدق","بيقرا كتب عن إدارة الوقت بس لحد دلوقتي","لسه مبدأش أي خطوة حقيقية"],answer:"بيتدرّب شوية كل يوم عشان يكتب أسرع وأدق",rationale:"قال: Estoy practicando para escribir con más rapidez y precisión وبعدين Practico un poco cada día — بتدرّب شوية كل يوم."},{q:"ليه إجابة عمر على سؤال نقطة التحسين كويسة؟",options:["عشانها قصيرة وبتقفل الموضوع بسرعة","عشانها نقطة ضعف مش موجودة أصلًا عند حد","عشانها بتحوّل السؤال لمديح في نفسه","عشانها نقطة حقيقية ومعاها خطوة بيعملها فعلًا"],answer:"عشانها نقطة حقيقية ومعاها خطوة بيعملها فعلًا",rationale:"قال نقطة حقيقية (rapidez al escribir) ومعاها خطوة (Estoy practicando). القول «ماعنديش نقاط ضعف» بيبان تهرب."}],responseTask:{prompt:"اتسألت: ¿Qué aspecto necesitas mejorar? قول نقطة حقيقية (مش قاتلة للوظيفة) + الخطوة اللي بتعملها لتحسينها.",acceptable:["Necesito mejorar mi rapidez al escribir. Estoy practicando cada día.","Necesito mejorar mi vocabulario técnico. Estoy estudiando con cursos.","Necesito mejorar mi pronunciación. Estoy practicando con audios."],modelEs:"Necesito mejorar mi rapidez al escribir. Estoy practicando cada día.",modelAr:"محتاج أحسّن سرعتي في الكتابة. بتدرّب كل يوم.",checklistAr:"راجع إجابتك: ١) نقطة حقيقية مش «ماعنديش نقاط ضعف»، ٢) مش حاجة بتقصّرك عن جوهر الوظيفة، ٣) خطوة تحسين شغالة بالفعل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Necesito mejorar = محتاج أحسّن. rapidez al escribir = سرعة الكتابة. Estoy practicando = بتدرّب (مستمر). precisión = دقة. القاعدة: نقطة حقيقية + خطوة شغالة. بلاش «نقطة ضعفي إني مثالي زيادة» — محدش بيصدقها."}},{id:"iv-u04l04",courseId:"job-interview",unitId:"iv-u04",sourceLessonId:null,level:"B1",register:"usted",title:"ربط القوة بالوظيفة",context:"متابعة ذكية من مسؤولة التوظيف: طيب نقطة القوة دي هتفيدنا في إيه؟ دورك: تربط المهارة بموقف حقيقي من شغل الوظيفة.",goal:"تربط نقطة القوة بمهمة فعلية في الوظيفة.",targets:[{es:"Escuchar bien ayuda a entender al cliente la primera vez.",ar:"السمع الكويس بيساعدك تفهم العميل من أول مرة.",speaker:"paco"},{es:"Así el cliente no repite su problema dos veces.",ar:"كده العميل مش هيضطر يعيد مشكلته مرتين.",speaker:"paco"},{es:"Y la organización ayuda con las llamadas seguidas.",ar:"والتنظيم بيساعد مع المكالمات الورا بعض.",speaker:"paco"},{es:"Por eso creo que encajo en este puesto.",ar:"عشان كده شايف إني مناسب للوظيفة دي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Bien, escuchas con atención. ¿Cómo nos ayuda eso aquí?",ar:"تمام، إنت بتسمع بانتباه. طيب ده هيفيدنا هنا إزاي؟"},{speaker:"paco",es:"Escuchar bien ayuda a entender al cliente la primera vez.",ar:"السمع الكويس بيساعدك تفهم العميل من أول مرة."},{speaker:"luna",es:"¿Y eso qué diferencia hace?",ar:"وده بيعمل فرق إيه؟"},{speaker:"paco",es:"Así el cliente no repite su problema dos veces.",ar:"كده العميل مش هيضطر يعيد مشكلته مرتين."},{speaker:"luna",es:"¿Y tu organización?",ar:"وتنظيمك لنفسك؟"},{speaker:"paco",es:"Y la organización ayuda con las llamadas seguidas.",ar:"والتنظيم بيساعد مع المكالمات الورا بعض."},{speaker:"luna",es:"Veo que piensas en el trabajo real.",ar:"واضح إنك بتفكر في الشغل الحقيقي."},{speaker:"paco",es:"Por eso creo que encajo en este puesto.",ar:"عشان كده شايف إني مناسب للوظيفة دي."}],questions:[{q:"السمع الكويس بيفيد الوظيفة في إيه حسب كلام عمر؟",options:["العميل بيتفهم من أول مرة ومش بيعيد مشكلته","المدير بيسمع عنك كلام كويس من العملاء","المكالمات بتقصر والشيفت بيخلص بدري","التقرير الشهري بيطلع بأرقام أعلى"],answer:"العميل بيتفهم من أول مرة ومش بيعيد مشكلته",rationale:"قال: Escuchar bien ayuda a entender al cliente la primera vez وبعدين Así el cliente no repite su problema dos veces."},{q:"التنظيم بيساعد في إيه؟",options:["في ترتيب المكتب والأوراق","مع المكالمات الورا بعض","في حفظ أرقام العملاء","في تعلم النظام بسرعة"],answer:"مع المكالمات الورا بعض",rationale:"قال: Y la organización ayuda con las llamadas seguidas — والتنظيم بيساعد مع المكالمات الورا بعض."},{q:"ليه مسؤولة التوظيف اتحمسّت للإجابة؟",options:["عشانه ذكر أرقام وإحصائيات دقيقة جدًا","عشانه قال كلام معسول عن الشركة وتاريخها","عشانه ربط المهارة بموقف حقيقي من الشغل اليومي","عشانه قارن نفسه بالمتقدمين التانيين"],answer:"عشانه ربط المهارة بموقف حقيقي من الشغل اليومي",rationale:"قالت: Veo que piensas en el trabajo real — واضح إنك بتفكر في الشغل الحقيقي. الربط بالواقع هو اللي أقنعها."}],responseTask:{prompt:"اتسألت: نقطة قوتك دي هتفيدنا في إيه؟ اربط المهارة بموقف حقيقي من شغل الوظيفة اليومي.",acceptable:["Escuchar bien ayuda a entender al cliente la primera vez.","La organización ayuda con las llamadas seguidas.","Mantener la calma ayuda cuando el cliente está enfadado."],modelEs:"Escuchar bien ayuda a entender al cliente la primera vez.",modelAr:"السمع الكويس بيساعدك تفهم العميل من أول مرة.",checklistAr:"راجع إجابتك: ١) المهارة مربوطة بمهمة فعلية، ٢) الفرق واضح للعميل أو الفريق، ٣) قفلة بثقة زي encajo en este puesto. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"la primera vez = أول مرة. repetir dos veces = يعيد مرتين. llamadas seguidas = مكالمات ورا بعض. encajar = يناسب/يليق بالوظيفة. القاعدة: مهارة من غير ربط بالشغل = وصف؛ مهارة مربوطة = قيمة."}},{id:"iv-u04l05",courseId:"job-interview",unitId:"iv-u04",sourceLessonId:null,level:"B1",register:"usted",title:"سؤال المتابعة",context:"مسؤولة التوظيف بتعمّق: قولت إنك بتحسّن سرعتك في الكتابة، إيه خطتك بالظبط؟ دورك: تفاصيل خطة حقيقية مش كلام عام.",goal:"تجاوب على سؤال متابعة عن خطة التحسين بتفاصيل محددة.",targets:[{es:"Escribo un texto corto cada día y cuento mis errores.",ar:"بكتب نص قصير كل يوم وبعدّ أغلاطي.",speaker:"paco"},{es:"He mejorado de veinte a treinta palabras por minuto.",ar:"تحسّنت من عشرين لتلاتين كلمة في الدقيقة.",speaker:"paco"},{es:"Mi meta es llegar a cuarenta en tres meses.",ar:"هدفي أوصل لأربعين خلال تلات شهور.",speaker:"paco"},{es:"Si no mejoro, cambio el método.",ar:"لو ما تحسّنتش، هغيّر الطريقة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Dices que practicas cada día. ¿Cuál es tu plan exacto?",ar:"بتقول إنك بتتدرّب كل يوم. إيه خطتك بالظبط؟"},{speaker:"paco",es:"Escribo un texto corto cada día y cuento mis errores.",ar:"بكتب نص قصير كل يوم وبعدّ أغلاطي."},{speaker:"luna",es:"¿Y has notado mejora?",ar:"وحسّيت بتحسّن؟"},{speaker:"paco",es:"He mejorado de veinte a treinta palabras por minuto.",ar:"تحسّنت من عشرين لتلاتين كلمة في الدقيقة."},{speaker:"luna",es:"¿Tienes una meta concreta?",ar:"عندك هدف محدد؟"},{speaker:"paco",es:"Mi meta es llegar a cuarenta en tres meses.",ar:"هدفي أوصل لأربعين خلال تلات شهور."},{speaker:"luna",es:"¿Y si no funciona el método?",ar:"ولو الطريقة منفعتش؟"},{speaker:"paco",es:"Si no mejoro, cambio el método.",ar:"لو ما تحسّنتش، هغيّر الطريقة."}],questions:[{q:"خطة عمر اليومية بالظبط؟",options:["يقرا مقالات طويلة كل يوم بالإسباني","يكتب نص قصير كل يوم ويعدّ أغلاطه","يسمع بودكاست ساعة قبل النوم","يحفظ عشر كلمات جديدة كل أسبوع"],answer:"يكتب نص قصير كل يوم ويعدّ أغلاطه",rationale:"قال: Escribo un texto corto cada día y cuento mis errores — بكتب نص قصير كل يوم وبعدّ أغلاطي."},{q:"قد إيه تحسّن لحد دلوقتي؟",options:["من تلاتين لستين كلمة في الدقيقة","من عشر لخمسين كلمة في الدقيقة","من عشرين لتلاتين كلمة في الدقيقة","من خمس لخمستاشر كلمة في الدقيقة"],answer:"من عشرين لتلاتين كلمة في الدقيقة",rationale:"قال: He mejorado de veinte a treinta palabras por minuto — تحسّنت من عشرين لتلاتين كلمة في الدقيقة."},{q:"إيه اللي بيبيّن إن خطة عمر جادة؟",options:["فيها شهادة معتمدة من معهد دولي معروف","فيها أسماء كتب وكورسات مشهورة على مستوى العالم","فيها وعد بمضاعفة السرعة في أسبوع واحد بس","فيها رقم حالي وهدف محدد بميعاد وبديل لو منفعتش"],answer:"فيها رقم حالي وهدف محدد بميعاد وبديل لو منفعتش",rationale:"عنده رقم حالي (de veinte a treinta)، هدف بميعاد (llegar a cuarenta en tres meses)، وبديل (Si no mejoro, cambio el método)."}],responseTask:{prompt:"اتسألت عن تفاصيل خطة التحسين. ادي خطة محددة: إيه اللي بتعمله، وصلت لفين، وهدفك بميعاد.",acceptable:["Escribo un texto corto cada día y cuento mis errores.","Practico cada día y mido mi progreso cada semana.","Estudio una hora diaria y repaso mis errores los domingos."],modelEs:"Escribo un texto corto cada día y cuento mis errores.",modelAr:"بكتب نص قصير كل يوم وبعدّ أغلاطي.",checklistAr:"راجع إجابتك: ١) خطوة يومية أو أسبوعية محددة، ٢) رقم أو مستوى حالي تعرفه، ٣) هدف بميعاد واقعي. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cuento mis errores = بعدّ أغلاطي. palabras por minuto = كلمات في الدقيقة. meta = هدف. Si no mejoro, cambio = لو ما تحسّنتش، هغيّر. التفاصيل الصغيرة هي اللي بتفرّق بين خطة حقيقية وكلام عام."}},{id:"iv-u04l06",courseId:"job-interview",unitId:"iv-u04",sourceLessonId:null,level:"B1",register:"usted",title:"قوة + تحسين في إجابة واحدة",context:"قفلة الوحدة: سؤال مركّب عن نقطة قوتك ونقطة تحسينك. دورك: إجابة متوازنة: قوة بدليل، وتحسين بخطة.",goal:"تقدّم صورة متوازنة: واثق من قوتك، صادق عن تحسينك.",targets:[{es:"Mi punto fuerte es escuchar, y lo demuestro con ejemplos.",ar:"نقطة قوتي السمع، وبأكّدها بأمثلة.",speaker:"paco"},{es:"También sé qué necesito mejorar y cómo lo hago.",ar:"وكمان عارف محتاج أحسّن إيه وبعمله إزاي.",speaker:"paco"},{es:"No soy perfecto, pero trabajo en mí mismo.",ar:"أنا مش مثالي، بس بشتغل على نفسي.",speaker:"paco"},{es:"Esa combinación es lo que ofrezco.",ar:"المزيج ده هو اللي بقدّمه.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Para terminar esta parte: ¿punto fuerte y punto a mejorar?",ar:"نختم الجزء ده: نقطة قوة ونقطة تحسين؟"},{speaker:"paco",es:"Mi punto fuerte es escuchar, y lo demuestro con ejemplos.",ar:"نقطة قوتي السمع، وبأكّدها بأمثلة."},{speaker:"luna",es:"¿Y el punto a mejorar?",ar:"ونقطة التحسين؟"},{speaker:"paco",es:"También sé qué necesito mejorar y cómo lo hago.",ar:"وكمان عارف محتاج أحسّن إيه وبعمله إزاي."},{speaker:"luna",es:"Suena equilibrado.",ar:"كلام متوازن."},{speaker:"paco",es:"No soy perfecto, pero trabajo en mí mismo.",ar:"أنا مش مثالي، بس بشتغل على نفسي."},{speaker:"luna",es:"¿Cómo resumirías tu perfil?",ar:"تلخّص نفسك إزاي؟"},{speaker:"paco",es:"Esa combinación es lo que ofrezco.",ar:"المزيج ده هو اللي بقدّمه."}],questions:[{q:"إجابة عمر جمعت إيه؟",options:["نقطة قوة مثبتة بأمثلة ونقطة تحسين معاها خطة","نقاط قوة كتير جدًا من غير أي نقطة تحسين","نقطة تحسين واحدة بس من غير أي نقطة قوة","قائمة صفات عامة محفوظة عن ظهر قلب"],answer:"نقطة قوة مثبتة بأمثلة ونقطة تحسين معاها خطة",rationale:"قال: Mi punto fuerte es escuchar, y lo demuestro con ejemplos وبعدين También sé qué necesito mejorar y cómo lo hago."},{q:"ليه مسؤولة التوظيف قالت «كلام متوازن»؟",options:["عشانه واثق من قوته وصادق عن اللي بيحسّنه","عشانه مدح نفسه كتير وانتقدها بنفس القدر","عشانه اتكلم بصوت هادي من غير حماس","عشانه جاوب على السؤالين بكلمة واحدة"],answer:"عشانه واثق من قوته وصادق عن اللي بيحسّنه",rationale:"التوازن واضح في قوله: No soy perfecto, pero trabajo en mí mismo — أنا مش مثالي، بس بشتغل على نفسي."},{q:"أنهي صياغة تلخّص صورة متوازنة أحسن؟",options:["أنا مثالي وماعنديش أي حاجة أحسّنها","أنا مش مثالي، بس بشتغل على نفسي","أنا ضعيف في كل حاجة تقريبًا للأسف","أنا أحسن من أغلب المتقدمين بمراحل"],answer:"أنا مش مثالي، بس بشتغل على نفسي",rationale:"قال حرفيًا: No soy perfecto, pero trabajo en mí mismo. التوازن: ثقة من غير غرور، وصدق من غير جلد ذات."}],responseTask:{prompt:"اتسألت عن نقطة قوتك ونقطة تحسينك مع بعض. قدّم إجابة متوازنة: قوة بدليل + تحسين بخطة + قفلة صادقة.",acceptable:["Mi punto fuerte es escuchar, y lo demuestro con ejemplos. No soy perfecto, pero trabajo en mí mismo.","Escucho con atención y estoy mejorando mi rapidez al escribir.","Soy organizado, y practico cada día para mejorar mi escritura."],modelEs:"Mi punto fuerte es escuchar, y lo demuestro con ejemplos. No soy perfecto, pero trabajo en mí mismo.",modelAr:"نقطة قوتي السمع، وبأكّدها بأمثلة. أنا مش مثالي، بس بشتغل على نفسي.",checklistAr:"راجع إجابتك: ١) قوة محددة مع دليل، ٢) تحسين صادق مع خطوة، ٣) قفلة متوازنة من غير غرور ولا جلد ذات. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"demuestro = بأكّد/بثبت. equilibrado = متوازن. trabajar en mí mismo = أشتغل على نفسي. القاعدة الذهبية: ثقة في القوة + صدق في التحسين + خطة شغالة = صورة محترفة."}}]},{courseId:"job-interview",unit:{id:"iv-u05",title:"أسئلة المواقف الحقيقية",desc:"تحكي موقف صعب حللته، وغلطة اتعلّمت منها، وإزاي بتشتغل تحت ضغط — بقصص حقيقية من غير اختلاق.",cefr:"B1"},lessons:[{id:"iv-u05l01",courseId:"job-interview",unitId:"iv-u05",sourceLessonId:"iv-u05l01",level:"B1",register:"usted",title:"الموقف والتصرف والنتيجة",context:"سؤال القصص: احكيلي عن موقف صعب عرفت تحلّه. دورك: تلخّص الموقف، تقول عملت إيه، وإيه النتيجة — قصة بتاعتك إنت.",goal:"تحكي موقف بثلاث خطوات: الموقف، التصرف، النتيجة.",targets:[{es:"En un proyecto de clase tuvimos un problema de organización.",ar:"في مشروع في الدراسة حصلت عندنا مشكلة تنظيم.",speaker:"paco"},{es:"Repartí las tareas y terminamos a tiempo.",ar:"وزّعت المهام وخلّصنا في المعاد.",speaker:"paco"},{es:"Primero hablé con el grupo para entender el problema.",ar:"الأول اتكلمت مع الجروب عشان أفهم المشكلة.",speaker:"paco"},{es:"La profesora quedó muy contenta con el resultado.",ar:"الدكتورة كانت مبسوطة جدًا من النتيجة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Cuéntame una situación difícil que hayas resuelto.",ar:"احكيلي عن موقف صعب عرفت تحلّه."},{speaker:"paco",es:"En un proyecto de clase tuvimos un problema de organización.",ar:"في مشروع في الدراسة حصلت عندنا مشكلة تنظيم."},{speaker:"luna",es:"¿Qué hiciste primero?",ar:"عملت إيه الأول؟"},{speaker:"paco",es:"Primero hablé con el grupo para entender el problema.",ar:"الأول اتكلمت مع الجروب عشان أفهم المشكلة."},{speaker:"luna",es:"¿Y después?",ar:"وبعد كده؟"},{speaker:"paco",es:"Repartí las tareas y terminamos a tiempo.",ar:"وزّعت المهام وخلّصنا في المعاد."},{speaker:"luna",es:"¿Cómo terminó todo?",ar:"الموضوع خلص إزاي؟"},{speaker:"paco",es:"La profesora quedó muy contenta con el resultado.",ar:"الدكتورة كانت مبسوطة جدًا من النتيجة."}],questions:[{q:"الموقف الصعب كان إيه؟",options:["مشكلة تنظيم في مشروع دراسة","خناقة مع دكتور في الجامعة","ضياع أوراق مهمة قبل التسليم","عطل في الكمبيوتر يوم العرض"],answer:"مشكلة تنظيم في مشروع دراسة",rationale:"قال: En un proyecto de clase tuvimos un problema de organización — في مشروع في الدراسة حصلت عندنا مشكلة تنظيم."},{q:"عمر عمل إيه بالترتيب؟",options:["وزّع المهام على الناس فورًا من غير أي كلام","اتكلم مع الجروب الأول، وبعدين وزّع المهام","اشتكى للدكتورة وطلب يغيّر المشروع كله","ساب الجروب خالص وقرر يشتغل لوحده"],answer:"اتكلم مع الجروب الأول، وبعدين وزّع المهام",rationale:"قال الأول: Primero hablé con el grupo para entender el problema وبعدين: Repartí las tareas y terminamos a tiempo."},{q:"ليه القصة دي نموذج كويس للإجابة؟",options:["فيها دراما وتوتر عالي بيلفت الانتباه","فيها أرقام ومبالغ كبيرة وأسماء مشهورة","فيها موقف وتصرف ونتيجة واضحة وحقيقية","فيها نهاية مفتوحة بتخلّي المستمع فضولي"],answer:"فيها موقف وتصرف ونتيجة واضحة وحقيقية",rationale:"الترتيب ظاهر في الحوار: مشكلة تنظيم (الموقف)، كلام مع الجروب وتوزيع مهام (التصرف)، تسليم في المعاد ودكتورة مبسوطة (النتيجة)."}],responseTask:{prompt:"اتسألت: Cuéntame una situación difícil que hayas resuelto. احكِ قصة حقيقية بتاعتك: الموقف، تصرفك، والنتيجة.",acceptable:["En un proyecto de clase tuvimos un problema de organización. Repartí las tareas y terminamos a tiempo.","En un evento deportivo faltaron voluntarios. Organicé al equipo y todo salió bien.","Un compañero no entendía la tarea. Se la expliqué y terminó su parte a tiempo."],modelEs:"En un proyecto de clase tuvimos un problema de organización. Repartí las tareas y terminamos a tiempo.",modelAr:"في مشروع في الدراسة حصلت عندنا مشكلة تنظيم. وزّعت المهام وخلّصنا في المعاد.",checklistAr:"راجع إجابتك: ١) موقف حقيقي حصل لك إنت، ٢) تصرف واضح عملته بنفسك، ٣) نتيجة محسوسة في الآخر. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"situación difícil = موقف صعب. hayas resuelto = اللي حليته (subjuntivo بعد قصة بتدور على موقف). repartí = وزّعت. a tiempo = في المعاد. متحكيش قصة مش بتاعتك: أول سؤال متابعة هيكشفها."}},{id:"iv-u05l02",courseId:"job-interview",unitId:"iv-u05",sourceLessonId:"iv-u05l02",level:"B1",register:"usted",title:"غلط واتعلّمت منه",context:"سؤال صعب: احكي عن غلطة عملتها. دورك: غلط حقيقي + إزاي صلحته + إيه اللي اتعلّمته — من غير كشف بيانات ناس أو أسرار شغل.",goal:"تقدّم غلطة حقيقية بثلاث خطوات: الغلط، الإصلاح، الدرس.",targets:[{es:"Una vez cometí un error al anotar una fecha.",ar:"مرة غلطت وأنا بسجّل تاريخ.",speaker:"paco"},{es:"Lo comuniqué y corregí el dato.",ar:"بلّغت بالغلط وصحّحت المعلومة.",speaker:"paco"},{es:"Desde entonces compruebo las fechas antes de confirmarlas.",ar:"من ساعتها براجع التواريخ قبل ما أأكدها.",speaker:"paco"},{es:"El error me enseñó a revisar dos veces.",ar:"الغلطة علّمتني أراجع مرتين.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Todos cometemos errores. Cuéntame uno tuyo.",ar:"كلنا بنغلط. احكيلي عن غلطة من غلطاتك."},{speaker:"paco",es:"Una vez cometí un error al anotar una fecha.",ar:"مرة غلطت وأنا بسجّل تاريخ."},{speaker:"luna",es:"¿Y qué hiciste cuando lo notaste?",ar:"وعملت إيه لما لاحظت الغلطة؟"},{speaker:"paco",es:"Lo comuniqué y corregí el dato.",ar:"بلّغت بالغلط وصحّحت المعلومة."},{speaker:"luna",es:"¿Qué aprendiste de eso?",ar:"اتعلّمت إيه من الموقف ده؟"},{speaker:"paco",es:"Desde entonces compruebo las fechas antes de confirmarlas.",ar:"من ساعتها براجع التواريخ قبل ما أأكدها."},{speaker:"luna",es:"Es una buena lección.",ar:"درس كويس."},{speaker:"paco",es:"El error me enseñó a revisar dos veces.",ar:"الغلطة علّمتني أراجع مرتين."}],questions:[{q:"غلطة عمر كانت إيه؟",options:["ضيّع ملف فيه بيانات","نسي ميعاد مهم خالص","بعت إيميل لشخص غلط","سجّل تاريخ غلط"],answer:"سجّل تاريخ غلط",rationale:"قال: Una vez cometí un error al anotar una fecha — مرة غلطت وأنا بسجّل تاريخ."},{q:"أول حاجة عملها لما لاحظ الغلطة؟",options:["استنى لحد ما حد يسأله","خبّى الموضوع ومحدش عرف","بلّغ بالغلط وصحّح المعلومة","رمى المسؤولية على زميله"],answer:"بلّغ بالغلط وصحّح المعلومة",rationale:"قال: Lo comuniqué y corregí el dato — بلّغت بالغلط وصحّحت المعلومة."},{q:"الدرس اللي طلع بيه من الغلطة؟",options:["يتجنب أي مسؤولية عن المواعيد","ميكتبش تواريخ بإيده تاني","يشتغل من غير تقويم خالص","يراجع التواريخ قبل ما يأكدها"],answer:"يراجع التواريخ قبل ما يأكدها",rationale:"قال: Desde entonces compruebo las fechas antes de confirmarlas — من ساعتها براجع التواريخ قبل ما أأكدها."}],responseTask:{prompt:"اتسألت عن غلطة عملتها. احكِ غلطة حقيقية: الغلط، إزاي صلّحته، وإيه اللي اتعلّمته — من غير كشف بيانات ناس.",acceptable:["Una vez cometí un error al anotar una fecha. Lo comuniqué y corregí el dato.","Una vez llegué tarde a una entrega. Avisé al grupo y reorganizamos el trabajo.","Una vez no entendí una instrucción. Pregunté y aprendí a confirmar siempre."],modelEs:"Una vez cometí un error al anotar una fecha. Lo comuniqué y corregí el dato.",modelAr:"مرة غلطت وأنا بسجّل تاريخ. بلّغت بالغلط وصحّحت المعلومة.",checklistAr:"راجع إجابتك: ١) غلطة حقيقية مش مثالية مزيّفة، ٢) إصلاح واضح عملته إنت، ٣) درس متطبق من ساعتها، ٤) من غير أسماء أو بيانات ناس. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cometer un error = يغلط غلطة. anotar = يسجّل. corregí = صحّحت. desde entonces = من ساعتها. compruebo = براجع/بتأكد. بلاش غلطة تكشف بيانات عملاء أو أسرار شغل قديم — دي نقطة ضدك مش ليك."}},{id:"iv-u05l03",courseId:"job-interview",unitId:"iv-u05",sourceLessonId:"iv-u05l03",level:"B1",register:"usted",title:"ضغط وتعاون",context:"سؤال: بتشتغل إزاي تحت ضغط؟ دورك: طريقة حقيقية للتعامل مع الضغط + إمتى بتطلب مساعدة. متقولش إنك عمرك ما بتتوتر.",goal:"تشرح أسلوبك تحت الضغط: أولويات + طلب مساعدة وقت اللزوم.",targets:[{es:"Ordeno las tareas por prioridad.",ar:"برتّب المهام حسب الأولوية.",speaker:"paco"},{es:"Si necesito ayuda, se la pido a mi responsable.",ar:"لو محتاج مساعدة، بطلبها من المسؤول عني.",speaker:"paco"},{es:"El estrés es normal, lo importante es gestionarlo.",ar:"التوتر حاجة طبيعية، المهم تديره صح.",speaker:"paco"},{es:"Así el trabajo no se acumula.",ar:"كده الشغل مش بيتراكم.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Cómo trabajas bajo presión?",ar:"بتشتغل إزاي تحت ضغط؟"},{speaker:"paco",es:"Ordeno las tareas por prioridad.",ar:"برتّب المهام حسب الأولوية."},{speaker:"luna",es:"¿Y si todo es urgente?",ar:"ولو كل حاجة عاجلة؟"},{speaker:"paco",es:"Si necesito ayuda, se la pido a mi responsable.",ar:"لو محتاج مساعدة، بطلبها من المسؤول عني."},{speaker:"luna",es:"¿Nunca te estresas?",ar:"عمرك ما بتتوتر؟"},{speaker:"paco",es:"El estrés es normal, lo importante es gestionarlo.",ar:"التوتر حاجة طبيعية، المهم تديره صح."},{speaker:"luna",es:"¿Por qué en ese orden?",ar:"ليه بالترتيب ده؟"},{speaker:"paco",es:"Así el trabajo no se acumula.",ar:"كده الشغل مش بيتراكم."}],questions:[{q:"أول خطوة بيعملها عمر تحت الضغط؟",options:["يرتّب المهام حسب الأولوية","ياخد بريك طويل على طول","يبدأ بأسهل مهمة ويسيب الباقي","يشتغل على كل حاجة في نفس الوقت"],answer:"يرتّب المهام حسب الأولوية",rationale:"قال: Ordeno las tareas por prioridad — برتّب المهام حسب الأولوية."},{q:"لو كل حاجة عاجلة، عمر بيعمل إيه؟",options:["يسكت ويستحمل لوحده لحد الآخر","يطلب مساعدة من المسؤول عنه","يختار عشوائي ويبدأ فورًا","يأجّل كل حاجة لليوم اللي بعده"],answer:"يطلب مساعدة من المسؤول عنه",rationale:"قال: Si necesito ayuda, se la pido a mi responsable — لو محتاج مساعدة، بطلبها من المسؤول عني."},{q:"ليه إجابة «التوتر طبيعي» أحسن من «عمري ما بتوتر»؟",options:["عشانها بتضحك مسؤولة التوظيف وبتكسر الجدية","عشانها بتقصّر وقت المقابلة وتريّح الطرفين","عشان التوتر مطلوب في الوظيفة دي بالتحديد","عشانها صادقة وبتوري إن عنده طريقة لإدارة التوتر"],answer:"عشانها صادقة وبتوري إن عنده طريقة لإدارة التوتر",rationale:"قال: El estrés es normal, lo importante es gestionarlo — التوتر حاجة طبيعية، المهم تديره صح. «عمري ما بتوتر» مش مقنعة وبتبان تهرب."}],responseTask:{prompt:"اتسألت: ¿Cómo trabajas bajo presión? اشرح طريقتك الحقيقية: ترتيب أولويات + طلب مساعدة وقت اللزوم.",acceptable:["Ordeno las tareas por prioridad. Si necesito ayuda, se la pido a mi responsable.","Hago una lista, empiezo por lo urgente y aviso si hay retraso.","Me concentro en una tarea cada vez y pido ayuda cuando la necesito."],modelEs:"Ordeno las tareas por prioridad. Si necesito ayuda, se la pido a mi responsable.",modelAr:"برتّب المهام حسب الأولوية. لو محتاج مساعدة، بطلبها من المسؤول عني.",checklistAr:"راجع إجابتك: ١) طريقة حقيقية بتستخدمها فعلًا، ٢) وضّح إمتى بتطلب مساعدة، ٣) متقولش إنك عمرك ما بتتوتر. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"bajo presión = تحت ضغط. ordenar por prioridad = يرتّب حسب الأولوية. se la pido = بطلبها منه (la راجعة على المساعدة). gestionar = يدير/يتعامل مع. no se acumula = مش بيتراكم."}},{id:"iv-u05l04",courseId:"job-interview",unitId:"iv-u05",sourceLessonId:null,level:"B1",register:"usted",title:"شخص صعب التعامل",context:"متابعة شائعة: اتعاملت مع شخص صعب قبل كده؟ دورك: موقف حقيقي ركّز فيه على المشكلة مش على الشخص.",goal:"تحكي عن تعامل مع شخص صعب من غير تجريح فيه.",targets:[{es:"Un compañero de grupo no entregaba su parte.",ar:"كان فيه زميل في الجروب مش بيسلّم الجزء بتاعه.",speaker:"paco"},{es:"Hablé con él en privado para entender qué pasaba.",ar:"اتكلمت معاه على انفراد عشان أفهم في إيه.",speaker:"paco"},{es:"Tenía problemas personales, así que le ayudé con su parte.",ar:"كان عنده ظروف شخصية، فساعدته في الجزء بتاعه.",speaker:"paco"},{es:"Al final entregó y el proyecto salió bien.",ar:"في الآخر سلّم والمشروع طلع كويس.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Has trabajado alguna vez con una persona difícil?",ar:"اتعاملت قبل كده مع شخص صعب؟"},{speaker:"paco",es:"Un compañero de grupo no entregaba su parte.",ar:"كان فيه زميل في الجروب مش بيسلّم الجزء بتاعه."},{speaker:"luna",es:"¿Qué hiciste?",ar:"عملت إيه؟"},{speaker:"paco",es:"Hablé con él en privado para entender qué pasaba.",ar:"اتكلمت معاه على انفراد عشان أفهم في إيه."},{speaker:"luna",es:"¿Y qué descubriste?",ar:"واكتشفت إيه؟"},{speaker:"paco",es:"Tenía problemas personales, así que le ayudé con su parte.",ar:"كان عنده ظروف شخصية، فساعدته في الجزء بتاعه."},{speaker:"luna",es:"¿Funcionó?",ar:"الموضوع نفع؟"},{speaker:"paco",es:"Al final entregó y el proyecto salió bien.",ar:"في الآخر سلّم والمشروع طلع كويس."}],questions:[{q:"مشكلة الزميل كانت إيه؟",options:["مش بيسلّم الجزء بتاعه","بيتأخر عن الاجتماعات دايمًا","بياخد رأي لوحده من غير ما يسأل","بيتكلم كتير في وقت الشغل"],answer:"مش بيسلّم الجزء بتاعه",rationale:"قال: Un compañero de grupo no entregaba su parte — كان فيه زميل في الجروب مش بيسلّم الجزء بتاعه."},{q:"عمر اتصرف إزاي الأول؟",options:["بلّغ الدكتورة عنه على طول","اتكلم معاه على انفراد يفهم المشكلة","عمل الجزء بتاعه من غير ما يقوله","طرده من الجروب فورًا"],answer:"اتكلم معاه على انفراد يفهم المشكلة",rationale:"قال: Hablé con él en privado para entender qué pasaba — اتكلمت معاه على انفراد عشان أفهم في إيه."},{q:"إيه اللي ميّز طريقة عمر في التعامل؟",options:["تجاهل الموضوع لحد ما المشكلة حلّت نفسها","اشتكى للمسؤول عشان يتصرف بداله بسرعة","ركّز على المشكلة وساعد الشخص من غير تجريح","واجهه قدّام كل الناس في الاجتماع"],answer:"ركّز على المشكلة وساعد الشخص من غير تجريح",rationale:"اتكلم على انفراد، فهم إن عنده ظروف، وساعده: le ayudé con su parte. النتيجة: Al final entregó y el proyecto salió bien."}],responseTask:{prompt:"اتسألت عن تعاملك مع شخص صعب. احكِ موقف حقيقي ركّز فيه على فهم المشكلة وحلّها، من غير تجريح في الشخص.",acceptable:["Hablé con él en privado para entender qué pasaba y le ayudé.","Escuché su versión primero y buscamos una solución juntos.","Me centré en el problema, no en la persona, y lo resolvimos."],modelEs:"Hablé con él en privado para entender qué pasaba y le ayudé.",modelAr:"اتكلمت معاه على انفراد عشان أفهم في إيه وساعدته.",checklistAr:"راجع إجابتك: ١) موقف حقيقي، ٢) تركيز على المشكلة مش على الشخص، ٣) نتيجة كويسة أو درس واضح. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"en privado = على انفراد. entregar = يسلّم. así que = فـ/عشان كده. al final = في الآخر. القاعدة: لو القصة خلّتك تشتم الشخص، اختار قصة تانية."}},{id:"iv-u05l05",courseId:"job-interview",unitId:"iv-u05",sourceLessonId:null,level:"B1",register:"usted",title:"سؤال افتراضي",context:"نوع تاني: لو حصل كذا، هتعمل إيه؟ دورك: خطوات واضحة بالترتيب، بصيغة الشرط (haría)، مش إجابة عامة.",goal:"تجاوب على سؤال افتراضي بخطوات مرتبة بصيغة الشرط.",targets:[{es:"Si un cliente estuviera muy enfadado, primero escucharía.",ar:"لو عميل كان متضايق جدًا، الأول هسمعه.",speaker:"paco"},{es:"Después comprobaría los datos antes de responder.",ar:"بعد كده هراجع البيانات قبل ما أرد.",speaker:"paco"},{es:"Si no supiera la respuesta, lo consultaría con mi responsable.",ar:"لو معرفتش الإجابة، هسأل المسؤول عني.",speaker:"paco"},{es:"Nunca inventaría una respuesta.",ar:"عمري ما هلفّق إجابة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Una pregunta hipotética: un cliente muy enfadado te llama. ¿Qué harías?",ar:"سؤال افتراضي: عميل متضايق جدًا بيكلّمك. هتعمل إيه؟"},{speaker:"paco",es:"Si un cliente estuviera muy enfadado, primero escucharía.",ar:"لو عميل كان متضايق جدًا، الأول هسمعه."},{speaker:"luna",es:"¿Y después de escuchar?",ar:"وبعد ما تسمعه؟"},{speaker:"paco",es:"Después comprobaría los datos antes de responder.",ar:"بعد كده هراجع البيانات قبل ما أرد."},{speaker:"luna",es:"¿Y si no conoces la respuesta?",ar:"ولو مش عارف الإجابة؟"},{speaker:"paco",es:"Si no supiera la respuesta, lo consultaría con mi responsable.",ar:"لو معرفتش الإجابة، هسأل المسؤول عني."},{speaker:"luna",es:"¿Seguro? Algunos inventan algo rápido.",ar:"متأكد؟ في ناس بتلفّق أي رد سريع."},{speaker:"paco",es:"Nunca inventaría una respuesta.",ar:"عمري ما هلفّق إجابة."}],questions:[{q:"ترتيب خطوات عمر مع العميل المتضايق؟",options:["يرد بسرعة، وبعدين يسمع، وبعدين يراجع","يسمع، يراجع البيانات، وبعدين يرد","يحوّل المكالمة فورًا من غير كلام","يعتذر ويقفل المكالمة بهدوء"],answer:"يسمع، يراجع البيانات، وبعدين يرد",rationale:"قال: primero escucharía وبعدين Después comprobaría los datos antes de responder — الأول هسمعه، بعد كده هراجع البيانات قبل ما أرد."},{q:"لو مش عارف الإجابة هيعمل إيه؟",options:["يقفل السكة مع العميل","يقول أي إجابة سريعة","يسأل المسؤول عنه","يدور على النت والعميل مستني"],answer:"يسأل المسؤول عنه",rationale:"قال: Si no supiera la respuesta, lo consultaría con mi responsable — لو معرفتش الإجابة، هسأل المسؤول عني."},{q:"ليه صيغة الشرط (haría) مهمة في السؤال الافتراضي؟",options:["عشانها الصيغة الوحيدة اللي بتنفع في المكالمات","عشانها أطول من الماضي وبتبهر مسؤولة التوظيف","عشانها بتمنع أي أسئلة متابعة من الطرف التاني","عشانها بتوضح إن ده تصرف متوقع في موقف مش حصل لسه"],answer:"عشانها بتوضح إن ده تصرف متوقع في موقف مش حصل لسه",rationale:"السؤال افتراضي (¿Qué harías?)، فالرد بالشرط: escucharía, comprobaría, consultaría — تصرف متخيّل مش قصة حصلت."}],responseTask:{prompt:"اتسألت سؤال افتراضي عن عميل متضايق. جاوب بخطوات مرتبة بصيغة الشرط: هسمع، هراجع، هرد أو هسأل المسؤول.",acceptable:["Si un cliente estuviera muy enfadado, primero escucharía y después comprobaría los datos.","Primero escucharía con calma y después buscaría una solución.","Si no supiera la respuesta, lo consultaría con mi responsable."],modelEs:"Si un cliente estuviera muy enfadado, primero escucharía y después comprobaría los datos.",modelAr:"لو عميل كان متضايق جدًا، الأول هسمعه وبعد كده هراجع البيانات.",checklistAr:"راجع إجابتك: ١) خطوات مرتبة (الأول… بعد كده…)، ٢) صيغة شرط (escucharía/comprobaría)، ٣) مفيش اختلاق إجابات. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"estuviera enfadado = كان متضايق (subjuntivo في الشرط). escucharía = هسمع. comprobaría = هراجع. consultaría = هسأل/هستشير. inventar = يلفّق. الشرط هنا هو لب السؤال: الموقف مش حصل، فمتجاوبش بالماضي."}},{id:"iv-u05l06",courseId:"job-interview",unitId:"iv-u05",sourceLessonId:null,level:"B1",register:"usted",title:"قصة كاملة بمتابعة",context:"قفلة الوحدة: قصة موقف كاملة، ومسؤولة التوظيف بتسأل سؤالين متابعة. دورك: تفاصيل جاهزة تثبت إن القصة بتاعتك.",goal:"تحكي قصة وترد على المتابعة بتفاصيل متسقة.",targets:[{es:"El año pasado organicé un evento con poco tiempo.",ar:"السنة اللي فاتت نظّمت فعالية في وقت ضيق.",speaker:"paco"},{es:"Eran unas veinte personas y todos tenían una tarea clara.",ar:"كانوا حوالي عشرين شخص وكل واحد كان معاه مهمة واضحة.",speaker:"paco"},{es:"Lo más difícil fue coordinar los horarios.",ar:"أصعب حاجة كانت تنسيق المواعيد.",speaker:"paco"},{es:"Si lo repitiera, empezaría una semana antes.",ar:"لو هعيدها، هبدأ قبلها بأسبوع.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Cuéntame una situación difícil que hayas resuelto, con detalles.",ar:"احكيلي عن موقف صعب حليته، بالتفاصيل."},{speaker:"paco",es:"El año pasado organicé un evento con poco tiempo.",ar:"السنة اللي فاتت نظّمت فعالية في وقت ضيق."},{speaker:"luna",es:"¿Cuánta gente participó?",ar:"كام واحد شارك؟"},{speaker:"paco",es:"Eran unas veinte personas y todos tenían una tarea clara.",ar:"كانوا حوالي عشرين شخص وكل واحد كان معاه مهمة واضحة."},{speaker:"luna",es:"¿Qué fue lo más difícil?",ar:"إيه كانت أصعب حاجة؟"},{speaker:"paco",es:"Lo más difícil fue coordinar los horarios.",ar:"أصعب حاجة كانت تنسيق المواعيد."},{speaker:"luna",es:"¿Qué harías diferente si lo repitieras?",ar:"هتعمل إيه مختلف لو هتعيدها؟"},{speaker:"paco",es:"Si lo repitiera, empezaría una semana antes.",ar:"لو هعيدها، هبدأ قبلها بأسبوع."}],questions:[{q:"قصة عمر عن إيه؟",options:["تنظيم فعالية في وقت ضيق","إنقاذ مشروع كان هيفشل","حل مشكلة تقنية معقدة","تدريب فريق جديد من الصفر"],answer:"تنظيم فعالية في وقت ضيق",rationale:"قال: El año pasado organicé un evento con poco tiempo — السنة اللي فاتت نظّمت فعالية في وقت ضيق."},{q:"أصعب جزء في القصة؟",options:["تنسيق المواعيد بين الناس","إيجاد مكان مناسب للفعالية","جمع فلوس التنظيم المطلوبة","إقناع الناس بالمشاركة أصلًا"],answer:"تنسيق المواعيد بين الناس",rationale:"قال: Lo más difícil fue coordinar los horarios — أصعب حاجة كانت تنسيق المواعيد."},{q:"ليه سؤال المتابعة «كام واحد شارك؟» سؤال اختبار؟",options:["عشان الأرقام الكبيرة بتعجب مسؤولة التوظيف","عشان القصة الحقيقية صاحبها يعرف تفاصيلها بسهولة","عشان السؤال ده موجود في قاعدة بيانات الشركة","عشان عدد المشاركين بيحدد المرتب المتوقع"],answer:"عشان القصة الحقيقية صاحبها يعرف تفاصيلها بسهولة",rationale:"عمر رد فورًا: Eran unas veinte personas — كانوا حوالي عشرين شخص. القصة الملفّقة بتتلخبط في أول تفصيلة."}],responseTask:{prompt:"احكِ قصة موقف صعب حليته، وجهّز نفسك لسؤالين متابعة عن التفاصيل: عدد الناس، أصعب جزء، وإيه اللي كنت هتعمله مختلف.",acceptable:["El año pasado organicé un evento con poco tiempo. Lo más difícil fue coordinar los horarios.","En un proyecto difícil repartí las tareas y terminamos a tiempo. Lo más difícil fue el poco tiempo.","Una vez resolví un problema de organización en clase. Si lo repitiera, empezaría antes."],modelEs:"El año pasado organicé un evento con poco tiempo. Lo más difícil fue coordinar los horarios.",modelAr:"السنة اللي فاتت نظّمت فعالية في وقت ضيق. أصعب حاجة كانت تنسيق المواعيد.",checklistAr:"راجع إجابتك: ١) قصة حقيقية بتفاصيلها، ٢) جاهز لأسئلة المتابعة (أرقام، أصعب جزء)، ٣) تعرف تقول هتعمل إيه مختلف. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"con poco tiempo = في وقت ضيق. unas veinte personas = حوالي عشرين شخص. coordinar = ينسّق. Si lo repitiera, empezaría = لو هعيدها، هبدأ. أسئلة المتابعة بتفرّق بين قصة عشتها وقصة حفظتها."}}]},{courseId:"job-interview",unit:{id:"iv-u06",title:"تمثيل خدمة العملاء",desc:"تمثيل دور موظف خدمة عملاء جوه المقابلة: عميل متضايق، ضيف عنده مشكلة، وسؤال مستواك في اللغة بصدق.",cefr:"B1"},lessons:[{id:"iv-u06l01",courseId:"job-interview",unitId:"iv-u06",sourceLessonId:"iv-u06l01",level:"B1",register:"usted",title:"مكالمة عميل متضايق",context:"تمثيل دور في المقابلة: إنت موظف ومكالمة من عميل متضايق. دورك: اسمع وراجع من غير وعد مش مضمون.",goal:"تمثل مكالمة مع عميل متضايق: سمع، مراجعة، حل واقعي.",targets:[{es:"Primero escucharía sin interrumpir.",ar:"الأول هسمعه من غير ما أقاطعه.",speaker:"paco"},{es:"Después comprobaría el problema antes de proponer una solución.",ar:"بعد كده هراجع المشكلة قبل ما أقترح حل.",speaker:"paco"},{es:"Entiendo que está molesta, y tiene razón.",ar:"فاهم إنك متضايقة، ومعاك حق.",speaker:"paco"},{es:"Voy a revisar su caso y le llamo hoy mismo.",ar:"هراجع الموضوع بتاعك وهكلمك النهارده نفسه.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Vamos a hacer un juego de roles. Yo soy una clienta enfadada.",ar:"هنعمل تمثيل أدوار. أنا عميلة متضايقة."},{speaker:"luna",es:"¿Cómo atenderías a un cliente enfadado?",ar:"هتتعامل إزاي مع عميل متضايق؟"},{speaker:"paco",es:"Primero escucharía sin interrumpir.",ar:"الأول هسمعه من غير ما أقاطعه."},{speaker:"paco",es:"Después comprobaría el problema antes de proponer una solución.",ar:"بعد كده هراجع المشكلة قبل ما أقترح حل."},{speaker:"luna",es:"Perfecto. Ahora soy la clienta: ¡llevo tres días esperando!",ar:"تمام. دلوقتي أنا العميلة: أنا مستنية من تلات أيام!"},{speaker:"paco",es:"Entiendo que está molesta, y tiene razón.",ar:"فاهم إنك متضايقة، ومعاك حق."},{speaker:"paco",es:"Voy a revisar su caso y le llamo hoy mismo.",ar:"هراجع الموضوع بتاعك وهكلمك النهارده نفسه."},{speaker:"luna",es:"Muy bien. No prometiste nada imposible.",ar:"كويس جدًا. ما وعدتش بحاجة مستحيلة."}],questions:[{q:"أول خطوة في طريقة عمر مع العميل المتضايق؟",options:["يسمعه من غير مقاطعة","يعتذر ويحوّله لقسم تاني","يشرح له سياسة الشركة فورًا","يطلب منه يهدى الأول"],answer:"يسمعه من غير مقاطعة",rationale:"قال: Primero escucharía sin interrumpir — الأول هسمعه من غير ما أقاطعه."},{q:"عمر وعد العميلة بإيه؟",options:["يرجّع لها فلوسها كاملة فورًا","يراجع موضوعها ويكلمها نفس اليوم","يديها خصم خمسين في المية","يحوّلها لمدير الشركة حالًا"],answer:"يراجع موضوعها ويكلمها نفس اليوم",rationale:"قال: Voy a revisar su caso y le llamo hoy mismo — هراجع الموضوع بتاعك وهكلمك النهارده نفسه."},{q:"ليه مسؤولة التوظيف مدحت الرد في الآخر؟",options:["عشانه خلّص المكالمة في أقل من دقيقة","عشانه قال للعميلة إنها غلطانة بهدوء","عشانه ما وعدش بحاجة مش في إيده يعملها","عشانه استخدم كلمات إسبانية صعبة جدًا"],answer:"عشانه ما وعدش بحاجة مش في إيده يعملها",rationale:"قالت: Muy bien. No prometiste nada imposible — كويس جدًا. ما وعدتش بحاجة مستحيلة."}],responseTask:{prompt:"في تمثيل أدوار، إنت موظف خدمة عملاء وعميل متضايق بيكلّمك. تعامل معاه: اسمع، اعترف بإحساسه، واعرض خطوة واقعية.",acceptable:["Primero escucharía sin interrumpir. Después comprobaría el problema.","Entiendo que está molesto. Voy a revisar su caso y le llamo hoy mismo.","Siento las molestias. Déjeme comprobarlo y le doy una respuesta hoy."],modelEs:"Primero escucharía sin interrumpir. Después comprobaría el problema.",modelAr:"الأول هسمعه من غير ما أقاطعه. بعد كده هراجع المشكلة.",checklistAr:"راجع إجابتك: ١) سمع من غير مقاطعة، ٢) اعتراف بإحساس العميل، ٣) خطوة واقعية (مراجعة + رد)، ٤) مفيش وعد مش في إيدك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"juego de roles = تمثيل أدوار. sin interrumpir = من غير مقاطعة. tiene razón = معاك حق. hoy mismo = النهارده نفسه. الوعد الواقعي = مراجعة ورد في ميعاد؛ الوعد باسترداد فلوس من غير مراجعة = مشكلة."}},{id:"iv-u06l02",courseId:"job-interview",unitId:"iv-u06",sourceLessonId:"iv-u06l02",level:"B1",register:"usted",title:"ضيف عنده مشكلة",context:"تمثيل دور تاني: إنت موظف استقبال وضيف بيشتكي إن التكييف مش شغّال. دورك: اعتذار + خطوة فورية من غير وعد متسرّع.",goal:"تتعامل مع شكوى ضيف: آسف على الإزعاج + إبلاغ الصيانة + مفيش وعد قبل المراجعة.",targets:[{es:"Siento las molestias. Voy a avisar a mantenimiento.",ar:"آسف على الإزعاج. هبلّغ الصيانة.",speaker:"paco"},{es:"No prometería un cambio de habitación sin comprobarlo.",ar:"مش هوعد بتغيير الأوضة قبل ما أراجع الموضوع.",speaker:"paco"},{es:"¿Me puede dar el número de su habitación, por favor?",ar:"ممكن رقم الأوضة بتاعتك من فضلك؟",speaker:"paco"},{es:"Le confirmo la solución en diez minutos.",ar:"هأكدلك الحل خلال عشر دقايق.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Otro juego de roles: eres recepcionista de un hotel.",ar:"تمثيل تاني: إنت موظف استقبال في فندق."},{speaker:"luna",es:"El huésped dice que el aire acondicionado no funciona.",ar:"الضيف بيقول إن التكييف مش شغّال."},{speaker:"paco",es:"Siento las molestias. Voy a avisar a mantenimiento.",ar:"آسف على الإزعاج. هبلّغ الصيانة."},{speaker:"paco",es:"¿Me puede dar el número de su habitación, por favor?",ar:"ممكن رقم الأوضة بتاعتك من فضلك؟"},{speaker:"luna",es:"El huésped pide cambiar de habitación. ¿Qué dices?",ar:"الضيف عايز يغيّر الأوضة. هتقول إيه؟"},{speaker:"paco",es:"No prometería un cambio de habitación sin comprobarlo.",ar:"مش هوعد بتغيير الأوضة قبل ما أراجع الموضوع."},{speaker:"paco",es:"Le confirmo la solución en diez minutos.",ar:"هأكدلك الحل خلال عشر دقايق."},{speaker:"luna",es:"Excelente. Calmado y sin promesas falsas.",ar:"ممتاز. هادي ومن غير وعود ملهاش أساس."}],questions:[{q:"شكوى الضيف عن إيه؟",options:["الصوت العالي من الشارع","الواي فاي ضعيف جدًا","الأوضة مش نضيفة","التكييف مش شغّال"],answer:"التكييف مش شغّال",rationale:"قالت لونا في التمثيل: El huésped dice que el aire acondicionado no funciona — الضيف بيقول إن التكييف مش شغّال."},{q:"أول رد من عمر كان إيه؟",options:["ده مش تخصصي، كلم الإدارة","التكييف كان شغال الصبح يا فندم","آسف على الإزعاج وهبلّغ الصيانة","ممكن تستنى لبكرة الصبح؟"],answer:"آسف على الإزعاج وهبلّغ الصيانة",rationale:"قال: Siento las molestias. Voy a avisar a mantenimiento — آسف على الإزعاج. هبلّغ الصيانة."},{q:"ليه عمر رفض يوعد بتغيير الأوضة على طول؟",options:["عشان الضيف مش دافع سعر أعلى","عشان الفندق مفهوش أوض فاضية خالص","عشان تغيير الأوضة ممنوع في السياسة","عشان لازم يراجع الموضوع الأول قبل أي وعد"],answer:"عشان لازم يراجع الموضوع الأول قبل أي وعد",rationale:"قال: No prometería un cambio de habitación sin comprobarlo — مش هوعد بتغيير الأوضة قبل ما أراجع الموضوع."}],responseTask:{prompt:"في تمثيل أدوار، إنت موظف استقبال وضيف بيشتكي من التكييف. اعتذر، اعرض خطوة فورية (الصيانة)، ومتعِدش بتغيير الأوضة قبل المراجعة.",acceptable:["Siento las molestias. Voy a avisar a mantenimiento.","Siento las molestias. Déjeme comprobarlo y le confirmo en diez minutos.","Disculpe las molestias. Aviso a mantenimiento ahora mismo."],modelEs:"Siento las molestias. Voy a avisar a mantenimiento.",modelAr:"آسف على الإزعاج. هبلّغ الصيانة.",checklistAr:"راجع إجابتك: ١) اعتذار عن الإزعاج، ٢) خطوة فورية في إيدك (بلاغ الصيانة)، ٣) مفيش وعد بتغيير أوضة قبل المراجعة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Siento las molestias = آسف على الإزعاج. avisar a mantenimiento = يبلّغ الصيانة. habitación = أوضة. sin comprobarlo = من غير مراجعة. جملة الشكوى في التمثيل مش لازم تكون حصلت لك فعلًا — دي محاكاة شغل."}},{id:"iv-u06l03",courseId:"job-interview",unitId:"iv-u06",sourceLessonId:"iv-u06l03",level:"B1",register:"usted",title:"مستواك في اللغة",context:"سؤال مباشر: مستواك في الإسباني إيه؟ دورك: وصف صادق مناسب ليك — متقولش طليق أو معاك مستوى معتمد لو ده مش حقيقي.",goal:"توصف مستواك بصدق: بتتعلم + بتتدرّب + تقدر تعمل إيه فعلًا.",targets:[{es:"Estoy aprendiendo español y sigo practicando cada día.",ar:"بتعلّم إسباني ولسه بتدرّب كل يوم.",speaker:"paco"},{es:"Puedo mantener una conversación sencilla sobre temas conocidos.",ar:"أقدر أعمل حوار بسيط في مواضيع أعرفها.",speaker:"paco"},{es:"No soy fluido todavía, pero mejoro cada semana.",ar:"لسه مش طليق، بس بتحسّن كل أسبوع.",speaker:"paco"},{es:"Si no entiendo algo, pregunto sin problema.",ar:"لو مش فاهم حاجة، بسأل عادي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Qué nivel de español tienes?",ar:"مستواك في الإسباني إيه؟"},{speaker:"paco",es:"Estoy aprendiendo español y sigo practicando cada día.",ar:"بتعلّم إسباني ولسه بتدرّب كل يوم."},{speaker:"luna",es:"¿Puedes atender a un cliente en español?",ar:"تقدر ترد على عميل بالإسباني؟"},{speaker:"paco",es:"Puedo mantener una conversación sencilla sobre temas conocidos.",ar:"أقدر أعمل حوار بسيط في مواضيع أعرفها."},{speaker:"luna",es:"¿Eres fluido?",ar:"إنت طليق؟"},{speaker:"paco",es:"No soy fluido todavía, pero mejoro cada semana.",ar:"لسه مش طليق، بس بتحسّن كل أسبوع."},{speaker:"luna",es:"¿Y si no entiendes algo en una llamada?",ar:"ولو في حاجة مش واضحة في مكالمة؟"},{speaker:"paco",es:"Si no entiendo algo, pregunto sin problema.",ar:"لو مش فاهم حاجة، بسأل عادي."}],questions:[{q:"عمر وصف مستواه إزاي؟",options:["بتعلّم وبقدر أعمل حوار بسيط في مواضيع أعرفها","طليق تمامًا زي الناس اللي اتولدت في إسبانيا","مستوى معتمد C1 من معهد سرفانتس من سنتين","بفهم كل حاجة مظبوط بس مش بتكلم خالص"],answer:"بتعلّم وبقدر أعمل حوار بسيط في مواضيع أعرفها",rationale:"قال: Puedo mantener una conversación sencilla sobre temas conocidos — أقدر أعمل حوار بسيط في مواضيع أعرفها."},{q:"لما سُئل «إنت طليق؟» رد بإيه؟",options:["أيوه طليق تمامًا من زمان","لسه مش طليق بس بتحسّن كل أسبوع","مش هرد على السؤال ده دلوقتي","طلاقتي معتمدة بشهادة دولية"],answer:"لسه مش طليق بس بتحسّن كل أسبوع",rationale:"قال: No soy fluido todavía, pero mejoro cada semana — لسه مش طليق، بس بتحسّن كل أسبوع."},{q:"ليه الصدق عن المستوى أحسن من ادّعاء الطلاقة؟",options:["عشان السؤال ده مجرد مجاملة مش اختبار حقيقي","عشان الطلاقة مش مطلوبة في أي وظيفة من الوظايف","عشان الشركات بتفضّل المبتدئين تمامًا في التوظيف","عشان أول مكالمة حقيقية هتكشف أي ادّعاء فورًا"],answer:"عشان أول مكالمة حقيقية هتكشف أي ادّعاء فورًا",rationale:"الوظيفة شغلها كلام مع عملاء؛ لو قلت طليق ومش طليق، أول يوم شغل هيكشفك. الصدق + خطة تحسين (mejoro cada semana) هو البديل المقنع."}],responseTask:{prompt:"اتسألت: ¿Qué nivel de español tienes? اوصف مستواك بصدق: إيه اللي بتقدر تعمله فعلًا + إنك بتتحسّن.",acceptable:["Estoy aprendiendo español y sigo practicando cada día.","Puedo mantener una conversación sencilla sobre temas conocidos.","No soy fluido todavía, pero mejoro cada semana."],modelEs:"Estoy aprendiendo español y sigo practicando cada día.",modelAr:"بتعلّم إسباني ولسه بتدرّب كل يوم.",checklistAr:"راجع إجابتك: ١) وصف صادق لمستواك، ٢) قول تقدر تعمل إيه فعلًا، ٣) وضّح إنك بتتحسّن، ٤) متدّعيش طلاقة أو شهادة مش موجودة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"nivel = مستوى. fluido = طليق. todavía = لسه. conversación sencilla = حوار بسيط. temas conocidos = مواضيع أعرفها. الادّعاء هنا أخطر من أي سؤال تاني: الشغل نفسه هيكون باللغة."}},{id:"iv-u06l04",courseId:"job-interview",unitId:"iv-u06",sourceLessonId:null,level:"B1",register:"usted",title:"عميل عايز فلوسه",context:"تمثيل تالت: عميل عايز استرداد فلوس. دورك: تفهم طلبه وتشرح الخطوة الحقيقية من غير ما توعد بالاسترداد نفسه.",goal:"تتعامل مع طلب استرداد: سمع + مراجعة الحالة + تصعيد للمختص لو لزم.",targets:[{es:"Entiendo que pide la devolución del dinero.",ar:"فاهم إنك طالب استرداد الفلوس.",speaker:"paco"},{es:"Voy a revisar su pedido para ver qué opciones hay.",ar:"هراجع الأوردر بتاعك عشان أشوف الاختيارات المتاحة.",speaker:"paco"},{es:"No puedo confirmar la devolución sin revisar el caso.",ar:"مش أقدر أأكد الاسترداد قبل ما أراجع الحالة.",speaker:"paco"},{es:"Si hace falta, paso su caso al departamento correspondiente.",ar:"لو لزم، هحوّل حالتك للقسم المختص.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Último juego de roles: el cliente quiere su dinero de vuelta.",ar:"آخر تمثيل: العميل عايز فلوسه ترجع."},{speaker:"paco",es:"Entiendo que pide la devolución del dinero.",ar:"فاهم إنك طالب استرداد الفلوس."},{speaker:"paco",es:"Voy a revisar su pedido para ver qué opciones hay.",ar:"هراجع الأوردر بتاعك عشان أشوف الاختيارات المتاحة."},{speaker:"luna",es:"El cliente insiste: ¡quiero mi dinero ahora!",ar:"العميل بيصرّ: عايز فلوسي دلوقتي!"},{speaker:"paco",es:"No puedo confirmar la devolución sin revisar el caso.",ar:"مش أقدر أأكد الاسترداد قبل ما أراجع الحالة."},{speaker:"luna",es:"¿Y si el caso es complicado?",ar:"ولو الحالة معقدة؟"},{speaker:"paco",es:"Si hace falta, paso su caso al departamento correspondiente.",ar:"لو لزم، هحوّل حالتك للقسم المختص."},{speaker:"luna",es:"Correcto. Firme y amable a la vez.",ar:"صح. حازم ولطيف في نفس الوقت."}],questions:[{q:"العميل في التمثيل عايز إيه؟",options:["استرداد فلوسه","تغيير عنوان التوصيل","خصم على الطلب الجاي","رقم المدير المباشر"],answer:"استرداد فلوسه",rationale:"قالت لونا: el cliente quiere su dinero de vuelta — العميل عايز فلوسه ترجع."},{q:"ليه عمر ما أكدش الاسترداد فورًا؟",options:["عشان الاسترداد ممنوع نهائيًا","عشان لازم يراجع الحالة الأول","عشان العميل مش معاه فاتورة","عشان النظام مقفول في الوقت ده"],answer:"عشان لازم يراجع الحالة الأول",rationale:"قال: No puedo confirmar la devolución sin revisar el caso — مش أقدر أأكد الاسترداد قبل ما أراجع الحالة."},{q:"لو الحالة معقدة، عمر هيعمل إيه؟",options:["يطلب من العميل يكلمه بكرة","يرفض الطلب نهائي ويقفل","يحوّلها للقسم المختص","يوعده بأي حاجة عشان يخلّص منه"],answer:"يحوّلها للقسم المختص",rationale:"قال: Si hace falta, paso su caso al departamento correspondiente — لو لزم، هحوّل حالتك للقسم المختص."}],responseTask:{prompt:"في تمثيل أدوار، عميل بيصرّ على استرداد فلوسه فورًا. تعامل معاه: افهم الطلب، راجع الحالة، ومتأكدش الاسترداد قبل المراجعة.",acceptable:["Entiendo que pide la devolución. Voy a revisar su pedido para ver qué opciones hay.","No puedo confirmar la devolución sin revisar el caso. Si hace falta, paso su caso al departamento correspondiente.","Entiendo su petición. Déjeme revisar el pedido y le explico las opciones."],modelEs:"Entiendo que pide la devolución. Voy a revisar su pedido para ver qué opciones hay.",modelAr:"فاهم إنك طالب استرداد الفلوس. هراجع الأوردر بتاعك عشان أشوف الاختيارات المتاحة.",checklistAr:"راجع إجابتك: ١) اعتراف بالطلب، ٢) مراجعة الحالة قبل أي تأكيد، ٣) تصعيد للقسم المختص لو لزم، ٤) مفيش وعد بفلوس من غير مراجعة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"devolución del dinero = استرداد الفلوس. pedido = أوردر/طلب. qué opciones hay = الاختيارات المتاحة. pasar el caso = يحوّل الحالة. الفرق المهم: تأكيد استلام الطلب ≠ تأكيد الاسترداد نفسه."}},{id:"iv-u06l05",courseId:"job-interview",unitId:"iv-u06",sourceLessonId:null,level:"B1",register:"usted",title:"لما مش فاهم العميل",context:"سؤال عملي: لو العميل بيتكلم بسرعة ومش فاهمه؟ دورك: تطلب الإعادة بأدب بدل ما تخمّن وترد غلط.",goal:"تطلب الإعادة أو التبسيط بأدب: ¿Puede repetirlo, por favor?",targets:[{es:"¿Puede repetirlo más despacio, por favor?",ar:"ممكن تعيدها بشكل أهدى، من فضلك؟",speaker:"paco"},{es:"¿Puede decirlo con otras palabras?",ar:"ممكن تقولها بطريقة تانية؟",speaker:"paco"},{es:"Quiero asegurarme de que entiendo bien.",ar:"عايز أتأكد إني فاهم صح.",speaker:"paco"},{es:"Prefiero preguntar antes que dar una respuesta equivocada.",ar:"بفضّل أسأل أحسن أدي رد غلط.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Qué haces si el cliente habla muy rápido y no le entiendes?",ar:"بتعمل إيه لو العميل بيتكلم بسرعة ومش فاهمه؟"},{speaker:"paco",es:"¿Puede repetirlo más despacio, por favor?",ar:"ممكن تعيدها بشكل أهدى، من فضلك؟"},{speaker:"luna",es:"¿Y si sigue sin quedar claro?",ar:"ولو برضه الكلام مش واضح؟"},{speaker:"paco",es:"¿Puede decirlo con otras palabras?",ar:"ممكن تقولها بطريقة تانية؟"},{speaker:"luna",es:"Algunos adivinan en vez de preguntar.",ar:"في ناس بتخمّن بدل ما تسأل."},{speaker:"paco",es:"Prefiero preguntar antes que dar una respuesta equivocada.",ar:"بفضّل أسأل أحسن أدي رد غلط."},{speaker:"paco",es:"Quiero asegurarme de que entiendo bien.",ar:"عايز أتأكد إني فاهم صح."},{speaker:"luna",es:"Exactamente. Preguntar es profesional.",ar:"بالظبط. السؤال ده احتراف مش ضعف."}],questions:[{q:"لو العميل بيتكلم بسرعة، عمر بيقول إيه؟",options:["اتكلم عربي لو سمحت يا فندم","ممكن تعيدها بشكل أهدى من فضلك","استنى ثانية، مش سمعك خالص","هرد عليك بالإيميل أحسن"],answer:"ممكن تعيدها بشكل أهدى من فضلك",rationale:"قال: ¿Puede repetirlo más despacio, por favor? — ممكن تعيدها بشكل أهدى، من فضلك؟"},{q:"لو الكلام برضه مش واضح، الخطوة التانية؟",options:["يقفل المكالمة بأدب شديد","يخمّن المعنى ويرد على طول","يطلب منه يقولها بطريقة تانية","يدّعي إن السماعة عطلانة"],answer:"يطلب منه يقولها بطريقة تانية",rationale:"قال: ¿Puede decirlo con otras palabras? — ممكن تقولها بطريقة تانية؟"},{q:"ليه السؤال أحسن من التخمين؟",options:["عشان السؤال بيوري إنك مش فاهم اللغة","عشان التخمين بيوفّر وقت المكالمة الطويل","عشان العملاء بيحبوا يشرحوا مرتين دايمًا","عشان الرد الغلط أسوأ من طلب الإعادة بكتير"],answer:"عشان الرد الغلط أسوأ من طلب الإعادة بكتير",rationale:"قال: Prefiero preguntar antes que dar una respuesta equivocada — بفضّل أسأل أحسن أدي رد غلط."}],responseTask:{prompt:"اتسألت: لو مش فاهم العميل في مكالمة، هتعمل إيه؟ وضّح إنك بتطلب الإعادة أو التبسيط بأدب بدل التخمين.",acceptable:["¿Puede repetirlo más despacio, por favor?","¿Puede decirlo con otras palabras, por favor?","Prefiero preguntar antes que dar una respuesta equivocada."],modelEs:"¿Puede repetirlo más despacio, por favor?",modelAr:"ممكن تعيدها بشكل أهدى، من فضلك؟",checklistAr:"راجع إجابتك: ١) طلب إعادة بأدب، ٢) بديل: طلب تبسيط أو كلمات تانية، ٣) مفيش تخمين ورد غلط. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"repetir = يعيد. más despacio = بشكل أهدى/أبطأ. con otras palabras = بكلمات تانية. asegurarme = أتأكد. equivocada = غلط. طلب الإعادة عادي جدًا حتى للناطقين الأصليين."}},{id:"iv-u06l06",courseId:"job-interview",unitId:"iv-u06",sourceLessonId:null,level:"B1",register:"usted",title:"مكالمة كاملة من الأول للآخر",context:"قفلة الوحدة: تمثيل مكالمة كاملة — تحية، سماع المشكلة، خطوة، قفلة. دورك: تربط كل اللي اتعلّمته في مكالمة واحدة.",goal:"تدير مكالمة كاملة: تحية مهنية، سماع، خطوة واقعية، قفلة لطيفة.",targets:[{es:"Buenos días, gracias por llamar. ¿En qué puedo ayudarle?",ar:"صباح الخير، شكرًا لاتصالك. أقدر أساعدك في إيه؟",speaker:"paco"},{es:"Ya veo. Permítame un momento para revisar su caso.",ar:"فاهم. اذنيلي لحظة أراجع الموضوع بتاعك.",speaker:"paco"},{es:"Gracias por su paciencia. Quedo en llamarle esta tarde.",ar:"شكرًا لصبرك. هكلمك النهارده العصر.",speaker:"paco"},{es:"Que tenga un buen día.",ar:"يومك سعيد.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Ahora la llamada completa. Empiezo yo: ¡mi pedido no llegó!",ar:"دلوقتي المكالمة الكاملة. هبدأ أنا: الأوردر بتاعي موصلش!"},{speaker:"paco",es:"Buenos días, gracias por llamar. ¿En qué puedo ayudarle?",ar:"صباح الخير، شكرًا لاتصالك. أقدر أساعدك في إيه؟"},{speaker:"luna",es:"¡Que mi pedido no llegó y lo necesito!",ar:"الأوردر بتاعي موصلش وأنا محتاجاه!"},{speaker:"paco",es:"Ya veo. Permítame un momento para revisar su caso.",ar:"فاهم. اذنيلي لحظة أراجع الموضوع بتاعك."},{speaker:"luna",es:"Vale. ¿Y cuándo tendré una respuesta?",ar:"تمام. وهيبقى عندي رد إمتى؟"},{speaker:"paco",es:"Gracias por su paciencia. Quedo en llamarle esta tarde.",ar:"شكرًا لصبرك. هكلمك النهارده العصر."},{speaker:"luna",es:"De acuerdo, espero su llamada.",ar:"ماشي، هستنى مكالمتك."},{speaker:"paco",es:"Que tenga un buen día.",ar:"يومك سعيد."}],questions:[{q:"مشكلة العميلة في المكالمة؟",options:["الأوردر بتاعها موصلش","الفاتورة فيها غلط","المنتج وصل بايظ","التطبيق مش بيفتح معاها"],answer:"الأوردر بتاعها موصلش",rationale:"قالت: ¡Que mi pedido no llegó y lo necesito! — الأوردر بتاعي موصلش وأنا محتاجاه!"},{q:"عمر أكد على رد في ميعاد إزاي؟",options:["قال هكلمك النهارده العصر","قال هكلمك لما يحصل جديد","قال ابعتلي إيميل وهرد عليك","قال هتكلمك الشركة قريب جدًا"],answer:"قال هكلمك النهارده العصر",rationale:"قال: Quedo en llamarle esta tarde — هكلمك النهارده العصر."},{q:"ترتيب المكالمة النموذجي اللي مشي عليه عمر؟",options:["اعتذار طويل، شرح السياسة، طلب تقييم، قفلة","تحية، سماع المشكلة، مراجعة، قفلة بميعاد رد","سماع، تحويل فوري، قفلة سريعة، من غير ميعاد","طلب بيانات، وعد بالحل، شكر، قفلة"],answer:"تحية، سماع المشكلة، مراجعة، قفلة بميعاد رد",rationale:"الحوار ماشي كده بالظبط: Buenos días (تحية)، سماع الشكوى، Permítame un momento para revisar (مراجعة)، Quedo en llamarle esta tarde (قفلة بميعاد)."}],responseTask:{prompt:"مثّل مكالمة كاملة: حيّي العميل، اسمع مشكلته (أوردر موصلش)، اعرض مراجعة الحالة، واقفل بميعاد رد واضح.",acceptable:["Buenos días, gracias por llamar. ¿En qué puedo ayudarle?","Ya veo. Permítame un momento para revisar su caso. Quedo en llamarle esta tarde.","Entiendo. Voy a revisar su pedido y le llamo hoy. Que tenga un buen día."],modelEs:"Buenos días, gracias por llamar. ¿En qué puedo ayudarle?",modelAr:"صباح الخير، شكرًا لاتصالك. أقدر أساعدك في إيه؟",checklistAr:"راجع إجابتك: ١) تحية مهنية، ٢) سماع من غير مقاطعة، ٣) خطوة واقعية بميعاد، ٤) قفلة لطيفة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿En qué puedo ayudarle? = أقدر أساعدك في إيه؟ Permítame = اذنيلي. Quedo en llamarle = هكلّمك (اتفاق). esta tarde = النهارده العصر. Que tenga un buen día = يومك سعيد (قفلة قياسية)."}}]},{courseId:"job-interview",unit:{id:"iv-u07",title:"المواعيد والمهارات والمرتب",desc:"تتكلم بصدق عن مواعيدك وأدواتك وتوقعاتك للمرتب: مفيش موافقة على كل حاجة، ومفيش أرقام ملفّقة.",cefr:"B1"},lessons:[{id:"iv-u07l01",courseId:"job-interview",unitId:"iv-u07",sourceLessonId:"iv-u07l01",level:"B1",register:"usted",title:"الشيفتات وبداية الشغل",context:"سؤال عملي: تقدر تبدأ إمتى؟ دورك: تقول المواعيد اللي تناسبك بصدق — مش مطلوب توافق على كل الشيفتات.",goal:"تجاوب على ¿Cuándo podrías incorporarte? وتسأل عن مواعيد الشيفتات.",targets:[{es:"Podría incorporarme el lunes.",ar:"ممكن أبدأ الشغل يوم الاتنين.",speaker:"paco"},{es:"Necesitaría conocer el horario de los turnos.",ar:"محتاج أعرف مواعيد الشيفتات.",speaker:"paco"},{es:"Puedo trabajar por la mañana y por la tarde.",ar:"أقدر أشتغل الصبح والعصر.",speaker:"paco"},{es:"Los fines de semana los tengo complicados por mis estudios.",ar:"الويك إند صعب عندي بسبب دراستي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hablemos de disponibilidad. ¿Cuándo podrías incorporarte?",ar:"هنتكلم عن المواعيد. تقدر تبدأ الشغل إمتى؟"},{speaker:"paco",es:"Podría incorporarme el lunes.",ar:"ممكن أبدأ الشغل يوم الاتنين."},{speaker:"luna",es:"¿Tienes preferencia de horario?",ar:"عندك تفضيل في المواعيد؟"},{speaker:"paco",es:"Necesitaría conocer el horario de los turnos.",ar:"محتاج أعرف مواعيد الشيفتات."},{speaker:"luna",es:"Tenemos turnos de mañana, de tarde y de noche.",ar:"عندنا شيفتات صبح وعصر وليل."},{speaker:"paco",es:"Puedo trabajar por la mañana y por la tarde.",ar:"أقدر أشتغل الصبح والعصر."},{speaker:"luna",es:"¿Y los fines de semana?",ar:"والويك إند؟"},{speaker:"paco",es:"Los fines de semana los tengo complicados por mis estudios.",ar:"الويك إند صعب عندي بسبب دراستي."}],questions:[{q:"عمر يقدر يبدأ الشغل إمتى؟",options:["يوم الاتنين","بعد شهر كامل","في نفس اليوم","أول السنة الجديدة"],answer:"يوم الاتنين",rationale:"قال: Podría incorporarme el lunes — ممكن أبدأ الشغل يوم الاتنين."},{q:"الشيفتات اللي تناسب عمر؟",options:["الليل بس","الصبح والعصر","الويك إند بس","أي شيفت من غير استثناء"],answer:"الصبح والعصر",rationale:"قال: Puedo trabajar por la mañana y por la tarde — أقدر أشتغل الصبح والعصر."},{q:"ليه عمر قال إن الويك إند صعب بدل ما يوافق على طول؟",options:["عشان الشغل في الويك إند ممنوع قانونيًا في الحالة دي","عشانه مش عايز الشغل ده أصلًا وبيدوّر على غيره","عشان الصدق عن مواعيدك أحسن من وعد مش هتقدر عليه","عشان مسؤولة التوظيف قالتله يقول كده بالظبط"],answer:"عشان الصدق عن مواعيدك أحسن من وعد مش هتقدر عليه",rationale:"قال بوضوح: Los fines de semana los tengo complicados por mis estudios — الويك إند صعب عندي بسبب دراستي. الموافقة على كل الشيفتات وبعدين التنازل أسوأ بكتير."}],responseTask:{prompt:"اتسألت: ¿Cuándo podrías incorporarte? قول ميعاد بداية حقيقي + المواعيد اللي تناسبك بصدق، واسأل عن الشيفتات.",acceptable:["Podría incorporarme el lunes. Necesitaría conocer el horario de los turnos.","Podría empezar la semana que viene. ¿Cuál es el horario de los turnos?","Puedo incorporarme el lunes. Prefiero los turnos de mañana."],modelEs:"Podría incorporarme el lunes. Necesitaría conocer el horario de los turnos.",modelAr:"ممكن أبدأ الشغل يوم الاتنين. محتاج أعرف مواعيد الشيفتات.",checklistAr:"راجع إجابتك: ١) ميعاد بداية حقيقي تقدر عليه، ٢) المواعيد اللي تناسبك بصدق، ٣) سؤال عن الشيفتات قبل الالتزام. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"incorporarse = يبدأ شغل جديد. turno = شيفت. por la mañana = الصبح، por la tarde = العصر/بالليل بدري، por la noche = بالليل. los tengo complicados = صعبة عليّا. الصدق هنا مش رفض للشغل — ده ترتيب صح."}},{id:"iv-u07l02",courseId:"job-interview",unitId:"iv-u07",sourceLessonId:"iv-u07l02",level:"B1",register:"usted",title:"الأدوات وحدود المواعيد",context:"سؤالين متلازمين: بتعرف تستخدم البرامج دي؟ ومتاح إمتى؟ دورك: لو متعرفش برنامج قول ده ووضّح استعدادك تتعلّمه، من غير ادّعاء خبرة.",goal:"تقول اللي بتعرفه واللي لسه هتتعلّمه بصدق، وتحدد حدود مواعيدك.",targets:[{es:"Sé utilizar hojas de cálculo.",ar:"بعرف أستخدم جداول البيانات.",speaker:"paco"},{es:"No he utilizado ese programa, pero puedo aprender.",ar:"مستخدمتش البرنامج ده قبل كده، بس أقدر أتعلّم.",speaker:"paco"},{es:"No tengo disponibilidad por la noche.",ar:"مش متاح للشغل بالليل.",speaker:"paco"},{es:"Aprendo programas nuevos con facilidad.",ar:"بتعلّم برامج جديدة بسهولة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Qué herramientas sabes utilizar?",ar:"بتعرف تستخدم أنهي أدوات؟"},{speaker:"paco",es:"Sé utilizar hojas de cálculo.",ar:"بعرف أستخدم جداول البيانات."},{speaker:"paco",es:"Aprendo programas nuevos con facilidad.",ar:"بتعلّم برامج جديدة بسهولة."},{speaker:"luna",es:"¿Has utilizado alguna vez nuestro sistema de tickets?",ar:"استخدمت قبل كده نظام التذاكر بتاعنا؟"},{speaker:"paco",es:"No he utilizado ese programa, pero puedo aprender.",ar:"مستخدمتش البرنامج ده قبل كده، بس أقدر أتعلّم."},{speaker:"luna",es:"¿Y disponibilidad para turnos de noche?",ar:"ومتاح لشيفتات الليل؟"},{speaker:"paco",es:"No tengo disponibilidad por la noche.",ar:"مش متاح للشغل بالليل."},{speaker:"luna",es:"Gracias por la claridad. Lo apuntamos.",ar:"شكرًا على الوضوح. هنسجّل ده."}],questions:[{q:"الأداة اللي عمر بيعرفها؟",options:["أنظمة إدارة المخزون","برامج التصميم والمونتاج","لغات البرمجة الأساسية","جداول البيانات"],answer:"جداول البيانات",rationale:"قال: Sé utilizar hojas de cálculo — بعرف أستخدم جداول البيانات."},{q:"رد عمر على نظام مايعرفهوش؟",options:["مش بحب الأنظمة دي عمومًا","استخدمته كتير في شغلي القديم","مستخدمتهوش قبل كده بس أقدر أتعلّم","هتعلّمه لوحده في بيتي بعد الاتفاق"],answer:"مستخدمتهوش قبل كده بس أقدر أتعلّم",rationale:"قال: No he utilizado ese programa, pero puedo aprender — مستخدمتش البرنامج ده قبل كده، بس أقدر أتعلّم."},{q:"ليه صيغة «مستخدمتهوش بس أقدر أتعلّم» صح؟",options:["عشان البرامج دي مش مهمة في الشغل أصلًا ولا حاجة","عشانها أقصر إجابة ممكنة على السؤال ده في المقابلة","عشانها بتهرب من السؤال بشكل ذكي ومحدش هيلاحظ","عشانها صادقة وبتوري استعداد للتعلم من غير ادّعاء خبرة"],answer:"عشانها صادقة وبتوري استعداد للتعلم من غير ادّعاء خبرة",rationale:"الصيغة بتجمع نصين: صدق (No he utilizado) + استعداد (puedo aprender). ادّعاء الخبرة هيتكشف في أول يوم تدريب."}],responseTask:{prompt:"اتسألت عن أدوات بتستخدمها وبرنامج متعرفوش. قول اللي بتعرفه بثقة، واللي متعرفوش بصيغة: لا + استعداد للتعلم.",acceptable:["Sé utilizar hojas de cálculo. No he utilizado ese programa, pero puedo aprender.","Manejo el correo y las hojas de cálculo. Ese sistema no lo conozco, pero lo aprendo rápido.","Tengo experiencia con hojas de cálculo. De ese programa no, pero me formo sin problema."],modelEs:"Sé utilizar hojas de cálculo. No he utilizado ese programa, pero puedo aprender.",modelAr:"بعرف أستخدم جداول البيانات. مستخدمتش البرنامج ده قبل كده، بس أقدر أتعلّم.",checklistAr:"راجع إجابتك: ١) اللي بتعرفه بثقة، ٢) اللي متعرفوش بصدق + استعداد للتعلم، ٣) حدود مواعيدك واضحة، ٤) مفيش ادّعاء خبرة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"herramienta = أداة. hoja de cálculo = جدول بيانات. disponibilidad = توافر/إتاحة. apuntar = يسجّل. لاحظ النفي بالمضارع التام: No he utilizado = مستخدمتش قبل كده (لحد دلوقتي)."}},{id:"iv-u07l03",courseId:"job-interview",unitId:"iv-u07",sourceLessonId:"iv-u07l03",level:"B1",register:"usted",title:"توقعات المرتب",context:"السؤال الحساس: إيه توقعاتك للمرتب؟ دورك: تسأل عن النطاق بدل ما ترمي رقم، وتوضّح المبلغ إجمالي ولا صافي. مفيش رقم نموذجي هنا.",goal:"تدير سؤال المرتب باحتراف: نطاق الوظيفة الأول، وإجمالي ولا صافي.",targets:[{es:"¿Podría indicarme la banda salarial del puesto?",ar:"ممكن حضرتك توضّحيلي نطاق مرتب الوظيفة؟",speaker:"paco"},{es:"¿Se trata de un importe bruto o neto?",ar:"المبلغ ده إجمالي قبل الخصومات ولا صافي؟",speaker:"paco"},{es:"Mi expectativa depende del horario y las condiciones.",ar:"توقعي مرتبط بالمواعيد والشروط.",speaker:"paco"},{es:"Estoy abierto a escuchar la propuesta.",ar:"منفتح أسمع العرض.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Cuáles son tus expectativas salariales?",ar:"إيه توقعاتك للمرتب؟"},{speaker:"paco",es:"¿Podría indicarme la banda salarial del puesto?",ar:"ممكن حضرتك توضّحيلي نطاق مرتب الوظيفة؟"},{speaker:"luna",es:"La banda va de mil a mil doscientos.",ar:"النطاق من ألف لألف ومتين."},{speaker:"paco",es:"¿Se trata de un importe bruto o neto?",ar:"المبلغ ده إجمالي قبل الخصومات ولا صافي؟"},{speaker:"luna",es:"Es bruto. El neto depende de tu situación.",ar:"إجمالي. الصافي بيختلف حسب حالتك."},{speaker:"paco",es:"Mi expectativa depende del horario y las condiciones.",ar:"توقعي مرتبط بالمواعيد والشروط."},{speaker:"luna",es:"¿Te parece razonable la banda?",ar:"النطاق ده مناسب ليك؟"},{speaker:"paco",es:"Estoy abierto a escuchar la propuesta.",ar:"منفتح أسمع العرض."}],questions:[{q:"أول حاجة عمر عملها لما اتسأل عن المرتب؟",options:["سأل عن نطاق مرتب الوظيفة","رمى رقم كبير جدًا على طول","قال إن المرتب مش مهم خالص","طلب أعلى رقم في السوق"],answer:"سأل عن نطاق مرتب الوظيفة",rationale:"قال: ¿Podría indicarme la banda salarial del puesto? — ممكن حضرتك توضّحيلي نطاق مرتب الوظيفة؟"},{q:"النطاق اللي ذكرته مسؤولة التوظيف كان إجمالي ولا صافي؟",options:["صافي بعد كل الخصومات مباشرة","إجمالي، والصافي بيختلف حسب الحالة","محددش، والموضوع اتأجل","الرقم اتقال بالدولار مش باليورو"],answer:"إجمالي، والصافي بيختلف حسب الحالة",rationale:"قالت: Es bruto. El neto depende de tu situación — إجمالي. الصافي بيختلف حسب حالتك."},{q:"ليه سؤال «إجمالي ولا صافي؟» سؤال محترف؟",options:["عشان مسؤولة التوظيف لازم تكون قالت رقم غلط","عشان السؤال ده بيأجل أي كلام عن الفلوس للأبد","عشان ده بيبين إنك محاسب أو دارس محاسبة","عشان الفرق بينهم بيغيّر قيمة العرض الحقيقية تمامًا"],answer:"عشان الفرق بينهم بيغيّر قيمة العرض الحقيقية تمامًا",rationale:"سأل: ¿Se trata de un importe bruto o neto? — الإجمالي قبل الخصومات مش هو اللي بيوصل إيدك، فلازم تعرف المقصود قبل ما تقيّم العرض."}],responseTask:{prompt:"اتسألت: ¿Cuáles son tus expectativas salariales? بدل رقم من عندك، اسأل عن نطاق الوظيفة ووضّح إجمالي ولا صافي، واربط توقعك بالشروط.",acceptable:["¿Podría indicarme la banda salarial del puesto?","¿Se trata de un importe bruto o neto?","Mi expectativa depende del horario y las condiciones. Estoy abierto a escuchar la propuesta."],modelEs:"¿Podría indicarme la banda salarial del puesto?",modelAr:"ممكن حضرتك توضّحيلي نطاق مرتب الوظيفة؟",checklistAr:"راجع إجابتك: ١) اسأل عن النطاق قبل ما تقول رقم، ٢) وضّح إجمالي ولا صافي، ٣) اربط توقعك بالشروط، ٤) مفيش رقم ملفّق ولا استخفاف بالموضوع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"expectativas salariales = توقعات المرتب. banda salarial = نطاق المرتب. bruto = إجمالي قبل الخصومات، neto = صافي. Estoy abierto a = منفتح على. الرقم اللي بيتقال في المقابلة لازم تفهم هو إيه بالظبط قبل ما تقول موافق أو لأ."}},{id:"iv-u07l04",courseId:"job-interview",unitId:"iv-u07",sourceLessonId:null,level:"B1",register:"usted",title:"التدريب والتأقلم",context:"قبل ما تتم الاتفاق: اسأل عن التدريب الأولاني. دورك: تعرف المدة، المدفوع ولا لأ، وإيه المطلوب منك فيه.",goal:"تسأل عن فترة التدريب بأسئلة عملية وواضحة.",targets:[{es:"¿Cuánto dura el periodo de formación?",ar:"فترة التدريب بتاخد قد إيه؟",speaker:"paco"},{es:"¿La formación es remunerada?",ar:"التدريب ده مدفوع؟",speaker:"paco"},{es:"¿Qué se espera de mí en las primeras semanas?",ar:"المطلوب مني إيه في أول أسبوعين؟",speaker:"paco"},{es:"¿Tendré a alguien para consultar mis dudas?",ar:"هيبقى فيه حد أسأله لو عندي استفسار؟",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Alguna pregunta sobre la formación inicial?",ar:"عندك أي سؤال عن التدريب الأولاني؟"},{speaker:"paco",es:"¿Cuánto dura el periodo de formación?",ar:"فترة التدريب بتاخد قد إيه؟"},{speaker:"luna",es:"Dos semanas, con un compañero de apoyo.",ar:"أسبوعين، مع زميل مساعد."},{speaker:"paco",es:"¿La formación es remunerada?",ar:"التدريب ده مدفوع؟"},{speaker:"luna",es:"Sí, es remunerada por completo.",ar:"أيوه، مدفوع بالكامل."},{speaker:"paco",es:"¿Qué se espera de mí en las primeras semanas?",ar:"المطلوب مني إيه في أول أسبوعين؟"},{speaker:"luna",es:"Escuchar llamadas y practicar con el sistema.",ar:"تسمع مكالمات وتتدرّب على النظام."},{speaker:"paco",es:"¿Tendré a alguien para consultar mis dudas?",ar:"هيبقى فيه حد أسأله لو عندي استفسار؟"}],questions:[{q:"فترة التدريب في الشركة دي؟",options:["أسبوعين مع زميل مساعد","شهر كامل لوحدك","تلات أيام بس أونلاين","مفيش تدريب أصلًا"],answer:"أسبوعين مع زميل مساعد",rationale:"قالت: Dos semanas, con un compañero de apoyo — أسبوعين، مع زميل مساعد."},{q:"التدريب مدفوع ولا لأ؟",options:["مدفوع جزئي بس","مدفوع بالكامل","مش مدفوع خالص","مدفوع بعد سنة خبرة"],answer:"مدفوع بالكامل",rationale:"قالت: Sí, es remunerada por completo — أيوه، مدفوع بالكامل."},{q:"المطلوب من عمر في أول أسبوعين؟",options:["يحقق أرقام مبيعات محددة","يرد على كل العملاء لوحده","يسمع مكالمات ويتدرّب على النظام","يدرّب الموظفين الجدد بنفسه"],answer:"يسمع مكالمات ويتدرّب على النظام",rationale:"قالت: Escuchar llamadas y practicar con el sistema — تسمع مكالمات وتتدرّب على النظام."}],responseTask:{prompt:"اسأل عن التدريب الأولاني قبل ما تتم الاتفاق: المدة، مدفوع ولا لأ، والمطلوب منك فيه.",acceptable:["¿Cuánto dura el periodo de formación? ¿Es remunerada?","¿Qué se espera de mí en las primeras semanas?","¿Tendré a alguien para consultar mis dudas?"],modelEs:"¿Cuánto dura el periodo de formación? ¿Es remunerada?",modelAr:"فترة التدريب بتاخد قد إيه؟ ومدفوعة؟",checklistAr:"راجع إجابتك: ١) سؤال عن المدة، ٢) سؤال عن المقابل المادي، ٣) سؤال عن المتوقع منك أو الدعم الموجود. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"formación inicial = التدريب الأولاني. durar = ياخد وقت. remunerada = مدفوعة. compañero de apoyo = زميل مساعد. dudas = استفسارات. السؤال عن التدريب مش عيب — ده بيبين إنك بتحسبها صح."}},{id:"iv-u07l05",courseId:"job-interview",unitId:"iv-u07",sourceLessonId:null,level:"B1",register:"usted",title:"التزام سابق لازم يتقال",context:"موقف حقيقي: عندك إجازة أو التزام محجوز قبل ما تبدأ. دورك: تقوله في المقابلة مش أول يوم شغل.",goal:"تصرّح بالتزام سابق بوضوح وبأدب، وتقترح حل.",targets:[{es:"Tengo un compromiso familiar la primera semana de julio.",ar:"عندي التزام عائلي أول أسبوع في يوليو.",speaker:"paco"},{es:"Lo digo ahora para evitar problemas de planificación.",ar:"بقول ده دلوقتي عشان نتجنب مشاكل في الجدولة.",speaker:"paco"},{es:"Puedo compensar esos días con otros turnos.",ar:"أقدر أعوّض الأيام دي بشيفتات تانية.",speaker:"paco"},{es:"Prefiero ser claro desde el principio.",ar:"بفضّل أكون واضح من الأول.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Algo que debamos saber sobre tu disponibilidad?",ar:"في حاجة لازم نعرفها عن مواعيدك؟"},{speaker:"paco",es:"Tengo un compromiso familiar la primera semana de julio.",ar:"عندي التزام عائلي أول أسبوع في يوليو."},{speaker:"paco",es:"Lo digo ahora para evitar problemas de planificación.",ar:"بقول ده دلوقتي عشان نتجنب مشاكل في الجدولة."},{speaker:"luna",es:"¿Cuántos días necesitarías?",ar:"محتاج كام يوم؟"},{speaker:"paco",es:"Tres días. Puedo compensar esos días con otros turnos.",ar:"تلات أيام. أقدر أعوّض الأيام دي بشيفتات تانية."},{speaker:"luna",es:"Aprecio que lo menciones ahora.",ar:"بقدّر إنك ذكرت ده دلوقتي."},{speaker:"paco",es:"Prefiero ser claro desde el principio.",ar:"بفضّل أكون واضح من الأول."},{speaker:"luna",es:"Así podemos organizarnos sin sorpresas.",ar:"كده نقدر نرتّب الشغل من غير أي مفاجأة."}],questions:[{q:"الالتزام اللي صرّح بيه عمر؟",options:["امتحانات جامعة آخر السنة","التزام عائلي أول أسبوع في يوليو","سفر شغل لشركة تانية","مواعيد دكتور أسبوعية ثابتة"],answer:"التزام عائلي أول أسبوع في يوليو",rationale:"قال: Tengo un compromiso familiar la primera semana de julio — عندي التزام عائلي أول أسبوع في يوليو."},{q:"عمر اقترح حل إيه؟",options:["يشتغل من البيت في الأيام دي","يلغي الالتزام العائلي خالص","يعوّض الأيام دي بشيفتات تانية","يأجّل بداية شغله شهر كامل"],answer:"يعوّض الأيام دي بشيفتات تانية",rationale:"قال: Puedo compensar esos días con otros turnos — أقدر أعوّض الأيام دي بشيفتات تانية."},{q:"ليه مسؤولة التوظيف قدّرت كلامه؟",options:["عشانه وعدها بشغل إضافي مجاني مقابل ده","عشان الالتزام كان قصير جدًا ومش مهم خالص","عشانها عندها نفس الالتزام العائلي في يوليو","عشانه قال الالتزام في المقابلة مش بعد التعيين"],answer:"عشانه قال الالتزام في المقابلة مش بعد التعيين",rationale:"قالت: Aprecio que lo menciones ahora — بقدّر إنك ذكرت ده دلوقتي. الإعلان المبكر بيدّي فرصة للترتيب، المفاجأة بتبوّظ الجدولة."}],responseTask:{prompt:"عندك التزام سابق (إجازة أو مواعيد) هيأثر على شغلك. صرّح بيه في المقابلة بأدب واقترح تعويض.",acceptable:["Tengo un compromiso familiar la primera semana de julio. Puedo compensar esos días con otros turnos.","Tengo unos días comprometidos en agosto. Lo digo ahora para evitar problemas de planificación.","Prefiero ser claro desde el principio: tengo un compromiso previo esos días."],modelEs:"Tengo un compromiso familiar la primera semana de julio. Puedo compensar esos días con otros turnos.",modelAr:"عندي التزام عائلي أول أسبوع في يوليو. أقدر أعوّض الأيام دي بشيفتات تانية.",checklistAr:"راجع إجابتك: ١) التصريح في المقابلة مش بعد التعيين، ٢) مدة محددة، ٣) اقتراح تعويض عملي، ٤) نبرة هادية مش اعتذارية زيادة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"compromiso = التزام. evitar = يتجنب. planificación = جدولة/تخطيط. compensar = يعوّض. desde el principio = من الأول. التصريح المبكر علامة احتراف، مش نقطة ضعف."}},{id:"iv-u07l06",courseId:"job-interview",unitId:"iv-u07",sourceLessonId:null,level:"B1",register:"usted",title:"تلخيص الشروط قبل القفلة",context:"قفلة الوحدة: قبل ما المقابلة تخلص، لخّص اللي اتفق عليه. دورك: تلخيص مهني للمواعيد والأدوات والمرتب يمنع سوء الفهم.",goal:"تلخّص الشروط بجملة واحدة منظمة وتأكد منها.",targets:[{es:"Entonces, para confirmar: empiezo el lunes, turnos de mañana o tarde.",ar:"طيب عشان أأكد: هبدأ الاتنين، شيفتات صبح أو عصر.",speaker:"paco"},{es:"La formación es de dos semanas y remunerada.",ar:"التدريب أسبوعين ومدفوع.",speaker:"paco"},{es:"La banda salarial es de mil a mil doscientos en bruto.",ar:"نطاق المرتب من ألف لألف ومتين إجمالي.",speaker:"paco"},{es:"¿Es correcto todo lo que he entendido?",ar:"اللي فهمته ده صح كله؟",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Antes de terminar, ¿quieres repasar lo hablado?",ar:"قبل ما نخلص، عايز نراجع اللي اتكلمنا فيه؟"},{speaker:"paco",es:"Entonces, para confirmar: empiezo el lunes, turnos de mañana o tarde.",ar:"طيب عشان أأكد: هبدأ الاتنين، شيفتات صبح أو عصر."},{speaker:"paco",es:"La formación es de dos semanas y remunerada.",ar:"التدريب أسبوعين ومدفوع."},{speaker:"paco",es:"La banda salarial es de mil a mil doscientos en bruto.",ar:"نطاق المرتب من ألف لألف ومتين إجمالي."},{speaker:"luna",es:"Todo correcto. Buena memoria.",ar:"كله صح. ذاكرة كويسة."},{speaker:"paco",es:"¿Es correcto todo lo que he entendido?",ar:"اللي فهمته ده صح كله؟"},{speaker:"luna",es:"Sí, sin ningún error.",ar:"أيوه، من غير أي غلط."},{speaker:"paco",es:"Perfecto. Así salgo con todo claro.",ar:"ممتاز. كده هخرج وكل حاجة واضحة."}],questions:[{q:"تلخيص عمر شمل إيه؟",options:["البداية والشيفتات والتدريب والمرتب","البداية والإجازات والخصومات بس","اسم المدير ورقم التليفون","تاريخ الشركة وعدد فروعها"],answer:"البداية والشيفتات والتدريب والمرتب",rationale:"لخّص: empiezo el lunes، turnos de mañana o tarde، formación de dos semanas remunerada، banda de mil a mil doscientos en bruto."},{q:"مسؤولة التوظيف أكدت التلخيص إزاي؟",options:["قالت كله صح من غير أي غلط","قالت فيه نقطتين محتاجين تعديل","طلبت تلخيص مكتوب بالإيميل","قالت هتراجع وترد عليه بعدين"],answer:"قالت كله صح من غير أي غلط",rationale:"قالت: Sí, sin ningún error — أيوه، من غير أي غلط."},{q:"ليه التلخيص قبل القفلة حركة محترفة؟",options:["عشانه بيطوّل المقابلة وده مطلوب دايمًا","عشانه بيمنع سوء الفهم وبيوري إنك سامع كويس","عشانه بيخلي مسؤولة التوظيف ترفع المرتب","عشانه بديل رسمي عن العقد المكتوب"],answer:"عشانه بيمنع سوء الفهم وبيوري إنك سامع كويس",rationale:"التلخيص خلّاها ترد: Todo correcto. Buena memoria — كله صح. ذاكرة كويسة. أي غلط كان هيتراجع في اللحظة دي مش بعد التعيين."}],responseTask:{prompt:"لخّص اللي اتفق عليه في المقابلة بجملة منظمة: البداية، الشيفتات، التدريب، المرتب — وتأكد إن فهمك صح.",acceptable:["Entonces, para confirmar: empiezo el lunes, turnos de mañana o tarde. ¿Es correcto todo lo que he entendido?","Para confirmar: empiezo el lunes y la banda salarial es en bruto. ¿Es correcto?","Resumiendo: cubro los turnos de mañana, dos semanas de formación y la banda indicada. ¿Todo correcto?"],modelEs:"Entonces, para confirmar: empiezo el lunes, turnos de mañana o tarde. ¿Es correcto todo lo que he entendido?",modelAr:"طيب عشان أأكد: هبدأ الاتنين، شيفتات صبح أو عصر. اللي فهمته ده صح كله؟",checklistAr:"راجع إجابتك: ١) تلخيص منظم للنقاط الأساسية، ٢) سؤال تأكيد في الآخر، ٣) مفيش إضافة بنود جديدة في التلخيص. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"para confirmar = عشان أأكد. repasar = يراجع. en bruto = إجمالي. salir con todo claro = أخرج وكل حاجة واضحة. التلخيص بيحميك إنت كمان: لو فهمت غلط، ده آخر وقت سهل للتصحيح."}}]},{courseId:"job-interview",unit:{id:"iv-u08",title:"أسئلتك وقفلة المقابلة",desc:"تسأل أسئلة ذكية عن الشغل والخطوات الجاية، وتقفل المقابلة بشكر مهني من غير افتراض قبول.",cefr:"B1"},lessons:[{id:"iv-u08l01",courseId:"job-interview",unitId:"iv-u08",sourceLessonId:"iv-u08l01",level:"B1",register:"usted",title:"اسأل عن الشغل نفسه",context:"لحظة «عندك أسئلة؟». دورك: سؤال إجابته مش واضحة في إعلان الشغل ولا في الكلام اللي اتقال — سؤال عن الشغل نفسه.",goal:"تسأل أسئلة مهمة عن المهام والتدريب والفريق.",targets:[{es:"¿Cuáles serían mis tareas principales?",ar:"إيه هي مهامي الأساسية؟",speaker:"paco"},{es:"¿Hay formación inicial para este puesto?",ar:"فيه تدريب في بداية الوظيفة دي؟",speaker:"paco"},{es:"¿Cómo se organiza el equipo?",ar:"الفريق متقسّم إزاي؟",speaker:"paco"},{es:"¿Con cuántas personas trabajaría día a día?",ar:"هشتغل مع كام شخص يوميًا؟",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Antes de terminar, ¿tienes alguna pregunta?",ar:"قبل ما نخلص، عندك أي سؤال؟"},{speaker:"paco",es:"¿Cuáles serían mis tareas principales?",ar:"إيه هي مهامي الأساسية؟"},{speaker:"luna",es:"Atender llamadas y registrar cada caso en el sistema.",ar:"ترد على مكالمات وتسجّل كل حالة في النظام."},{speaker:"paco",es:"¿Hay formación inicial para este puesto?",ar:"فيه تدريب في بداية الوظيفة دي؟"},{speaker:"luna",es:"Sí, dos semanas con apoyo de un compañero.",ar:"أيوه، أسبوعين مع دعم من زميل."},{speaker:"paco",es:"¿Cómo se organiza el equipo?",ar:"الفريق متقسّم إزاي؟"},{speaker:"luna",es:"En grupos pequeños, con un responsable por grupo.",ar:"مجموعات صغيرة، وكل مجموعة ليها مسؤول."},{speaker:"paco",es:"¿Con cuántas personas trabajaría día a día?",ar:"هشتغل مع كام شخص يوميًا؟"}],questions:[{q:"أول سؤال سأله عمر؟",options:["إيه مهامي الأساسية","إمتى هقبض أول مرتب","فين أقرب موقف عربيات","كام يوم إجازة في السنة"],answer:"إيه مهامي الأساسية",rationale:"قال: ¿Cuáles serían mis tareas principales? — إيه هي مهامي الأساسية؟"},{q:"إجابة مسؤولة التوظيف عن التدريب؟",options:["مفيش تدريب رسمي موجود","أسبوعين مع دعم من زميل","يوم واحد أونلاين بس","شهر تدريب في مقر تاني"],answer:"أسبوعين مع دعم من زميل",rationale:"قالت: Sí, dos semanas con apoyo de un compañero — أيوه، أسبوعين مع دعم من زميل."},{q:"ليه أسئلة عمر كويسة؟",options:["عشانها كلها عن الفلوس والإجازات مباشرة","عشانها قصيرة ومش بتاخد وقت من المقابلة","عشانها عن الشغل نفسه ومش مكتوبة في الإعلان","عشانها بتوري إنه ما قراش الإعلان"],answer:"عشانها عن الشغل نفسه ومش مكتوبة في الإعلان",rationale:"سأل عن المهام والتدريب وتنظيم الفريق — تفاصيل بتفرق في شغلك اليومي ومش موجودة في الإعلان."}],responseTask:{prompt:"قالولك: ¿Tienes alguna pregunta? اسأل سؤالين عن الشغل نفسه: المهام، التدريب، أو تنظيم الفريق.",acceptable:["¿Cuáles serían mis tareas principales?","¿Hay formación inicial para este puesto?","¿Cómo se organiza el equipo?"],modelEs:"¿Cuáles serían mis tareas principales?",modelAr:"إيه هي مهامي الأساسية؟",checklistAr:"راجع إجابتك: ١) سؤال عن الشغل نفسه، ٢) إجابته مش موجودة في الإعلان، ٣) بلاش تبدأ بالفلوس والإجازات. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"tareas principales = المهام الأساسية. serían = هتكون (شرطي مهذب). día a día = يوميًا. السؤال الذكي بيقول للي قدامك إنك فاهم الشغل ومهتم بيه فعلًا."}},{id:"iv-u08l02",courseId:"job-interview",unitId:"iv-u08",sourceLessonId:"iv-u08l02",level:"B1",register:"usted",title:"الخطوة اللي جاية",context:"قبل القفلة: اسأل عن الخطوات الجاية والتوقيت. دورك: سؤال منظم من غير افتراض إنك اتقبلت أو إن فيه ميعاد مؤكد.",goal:"تسأل عن الخطوات الجاية والتوقيت المتوقع بأدب.",targets:[{es:"¿Cuáles son los siguientes pasos del proceso?",ar:"إيه الخطوات اللي جاية في التقديم؟",speaker:"paco"},{es:"¿Cuándo estiman comunicar la decisión?",ar:"متوقعين تبلغوا بالقرار إمتى؟",speaker:"paco"},{es:"¿Necesitan alguna información adicional?",ar:"حضرتكم محتاجين أي معلومات زيادة؟",speaker:"paco"},{es:"¿Por dónde me comunicarían la decisión si me eligen?",ar:"هتبلغوني بالقرار إزاي لو اختاروني؟",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Alguna pregunta más antes de cerrar?",ar:"أي سؤال تاني قبل ما نقفل؟"},{speaker:"paco",es:"¿Cuáles son los siguientes pasos del proceso?",ar:"إيه الخطوات اللي جاية في التقديم؟"},{speaker:"luna",es:"Revisamos todas las entrevistas y llamamos a los seleccionados.",ar:"بنراجع كل المقابلات وبنكلّم المقبولين."},{speaker:"paco",es:"¿Cuándo estiman comunicar la decisión?",ar:"متوقعين تبلغوا بالقرار إمتى؟"},{speaker:"luna",es:"Aproximadamente en una semana.",ar:"تقريبًا خلال أسبوع."},{speaker:"paco",es:"¿Necesitan alguna información adicional?",ar:"حضرتكم محتاجين أي معلومات زيادة؟"},{speaker:"luna",es:"No, tu expediente está completo.",ar:"لأ، الملف بتاعك كامل."},{speaker:"paco",es:"¿Por dónde me comunicarían la decisión si me eligen?",ar:"هتبلغوني بالقرار إزاي لو اختاروني؟"}],questions:[{q:"الخطوة الجاية في التقديم حسب كلام مسؤولة التوظيف؟",options:["توقيع العقد النهائي في نفس اليوم","مقابلة تانية مع المدير العام للشركة","اختبار لغة مكتوب وفوري في المقر","مراجعة المقابلات والاتصال بالمقبولين"],answer:"مراجعة المقابلات والاتصال بالمقبولين",rationale:"قالت: Revisamos todas las entrevistas y llamamos a los seleccionados — بنراجع كل المقابلات وبنكلّم المقبولين."},{q:"التوقيت المتوقع للقرار؟",options:["بعد شهر على الأقل","في نفس اليوم بالليل","تقريبًا خلال أسبوع","مفيش توقيت محدد خالص"],answer:"تقريبًا خلال أسبوع",rationale:"قالت: Aproximadamente en una semana — تقريبًا خلال أسبوع."},{q:"ليه صيغة «متوقعين تبلغوا بالقرار إمتى؟» أحسن من «هتقبلوني إمتى؟»",options:["عشانها بتمنعهم يكلموا حد تاني","عشانها أسرع في النطق وأسهل في الفهم","عشانها بتلزم الشركة بميعاد قانوني","عشانها سؤال عن التوقيت من غير افتراض قبول"],answer:"عشانها سؤال عن التوقيت من غير افتراض قبول",rationale:"قال: ¿Cuándo estiman comunicar la decisión? — بيسأل عن قرار وتوقيت مش عن قبول مضمون. الافتراض بيبان استعلاء."}],responseTask:{prompt:"قبل القفلة، اسأل عن الخطوات الجاية والتوقيت المتوقع، واعرض أي معلومات زيادة محتاجينها.",acceptable:["¿Cuáles son los siguientes pasos del proceso? ¿Cuándo estiman comunicar la decisión?","¿Cuándo estiman comunicar la decisión?","¿Necesitan alguna información adicional?"],modelEs:"¿Cuáles son los siguientes pasos del proceso? ¿Cuándo estiman comunicar la decisión?",modelAr:"إيه الخطوات اللي جاية في التقديم؟ ومتوقعين تبلغوا بالقرار إمتى؟",checklistAr:"راجع إجابتك: ١) سؤال عن الخطوات، ٢) سؤال عن التوقيت المتوقع، ٣) عرض مساعدة أو معلومات زيادة، ٤) مفيش افتراض قبول. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"siguientes pasos = الخطوات الجاية. proceso = عملية التقديم. estiman = متوقعين. expediente = ملف. comunicar la decisión = يبلّغوا بالقرار. السؤال عن التوقيت حقك؛ افتراض النتيجة مش حقك."}},{id:"iv-u08l03",courseId:"job-interview",unitId:"iv-u08",sourceLessonId:"iv-u08l03",level:"B1",register:"usted",title:"مراجعة وقفلة",context:"قفلة المقابلة: شكر مهني وانطباع أخير كويس. دورك: تشكر على الوقت والمعلومات، وتقول إنك متاح لأي توضيح — النجاح هنا فهم اللغة مش ضمان وظيفة.",goal:"تقفل المقابلة بشكر مهني وجملة انطباع أخير.",targets:[{es:"Gracias por su tiempo y por la información.",ar:"شكرًا على وقت حضرتك وعلى المعلومات.",speaker:"paco"},{es:"Me ha gustado conocer mejor el puesto.",ar:"اتبسطت إني عرفت تفاصيل أكتر عن الوظيفة.",speaker:"paco"},{es:"Quedo a su disposición para cualquier aclaración.",ar:"أنا متاح لو حضرتكم محتاجين أي توضيح.",speaker:"paco"},{es:"Le agradezco esta oportunidad.",ar:"بشكر حضرتك على الفرصة دي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hemos terminado las preguntas. ¿Algo más que añadir?",ar:"خلّصنا الأسئلة. في حاجة عايز تضيفها؟"},{speaker:"paco",es:"Gracias por su tiempo y por la información.",ar:"شكرًا على وقت حضرتك وعلى المعلومات."},{speaker:"paco",es:"Me ha gustado conocer mejor el puesto.",ar:"اتبسطت إني عرفت تفاصيل أكتر عن الوظيفة."},{speaker:"luna",es:"Ha sido un placer hablar contigo, Omar.",ar:"كان ممتع الكلام معاك يا عمر."},{speaker:"paco",es:"Quedo a su disposición para cualquier aclaración.",ar:"أنا متاح لو حضرتكم محتاجين أي توضيح."},{speaker:"paco",es:"Le agradezco esta oportunidad.",ar:"بشكر حضرتك على الفرصة دي."},{speaker:"luna",es:"Te llamaremos en una semana aproximadamente.",ar:"هنكلّمك خلال أسبوع تقريبًا."},{speaker:"paco",es:"Perfecto. Que tenga un buen día.",ar:"ممتاز. يومك سعيد."}],questions:[{q:"عمر شكر مسؤولة التوظيف على إيه؟",options:["وقتها والمعلومات اللي قدّمتها","القهوة والاستقبال الكويس","قبوله في الوظيفة مقدمًا","تأجيلها اجتماع مهم جدًا عشانه"],answer:"وقتها والمعلومات اللي قدّمتها",rationale:"قال: Gracias por su tiempo y por la información — شكرًا على وقت حضرتك وعلى المعلومات."},{q:"جملة «متاح لأي توضيح» بالإسباني؟",options:["Quedo en su casa para cualquier invitación","Quedo a su disposición para cualquier aclaración","Estoy en su oficina para cualquier reunión","Voy a su empresa mañana para cualquier celebración"],answer:"Quedo a su disposición para cualquier aclaración",rationale:"دي الجملة اللي قالها حرفيًا: Quedo a su disposición para cualquier aclaración."},{q:"ليه القفلة دي نموذجية؟",options:["تذكيرهم إنه عنده عروض تانية أحسن بكتير وده بيشيل عنه أي ضغط","قبول فوري للعرض من غير أي تفكير أو مراجعة للشروط","طلب رفع المرتب المتوقع قبل ما يقفل الخط فورًا","شكر مهني + انطباع إيجابي + إتاحة للتواصل من غير ضغط"],answer:"شكر مهني + انطباع إيجابي + إتاحة للتواصل من غير ضغط",rationale:"شكر (Gracias por su tiempo)، انطباع (Me ha gustado conocer mejor el puesto)، إتاحة (Quedo a su disposición). مفيش ضغط ولا افتراض نتيجة."}],responseTask:{prompt:"اقفل المقابلة: اشكر على الوقت والمعلومات، قول انطباعك الكويس عن الوظيفة، واعرض نفسك لأي توضيح.",acceptable:["Gracias por su tiempo y por la información. Me ha gustado conocer mejor el puesto.","Quedo a su disposición para cualquier aclaración. Le agradezco esta oportunidad.","Gracias por la entrevista. Me ha gustado mucho conocer el puesto y el equipo."],modelEs:"Gracias por su tiempo y por la información. Me ha gustado conocer mejor el puesto.",modelAr:"شكرًا على وقت حضرتك وعلى المعلومات. اتبسطت إني عرفت تفاصيل أكتر عن الوظيفة.",checklistAr:"راجع إجابتك: ١) شكر على الوقت، ٢) انطباع إيجابي صادق، ٣) إتاحة لأي توضيح، ٤) مفيش افتراض قبول ولا ضغط على النتيجة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"un placer = متعة. Quedo a su disposición = أنا متاح لحضرتكم. aclaración = توضيح. agradecer = يشكر بامتنان. القفلة آخر انطباع بيفضل — خليه مهني وهادي."}},{id:"iv-u08l04",courseId:"job-interview",unitId:"iv-u08",sourceLessonId:null,level:"B1",register:"usted",title:"سؤال عن يوم شغل عادي",context:"سؤال بيفرّق المتقدم الجاد: يوم الشغل العادي بيبقى عامل إزاي؟ دورك: سؤال عملي بيوريك الصورة الحقيقية قبل ما توافق.",goal:"تسأل عن اليوم العادي وأكبر تحدٍ في الوظيفة.",targets:[{es:"¿Cómo es un día normal en este puesto?",ar:"اليوم العادي في الوظيفة دي عامل إزاي؟",speaker:"paco"},{es:"¿Cuál es el mayor reto para alguien que empieza?",ar:"إيه أكبر تحدي لواحد لسه بادي؟",speaker:"paco"},{es:"¿Qué diferencia a quien tiene éxito aquí?",ar:"إيه اللي بيفرّق اللي بينجح هنا عن غيره؟",speaker:"paco"},{es:"Gracias, eso me ayuda a imaginarme el trabajo.",ar:"شكرًا، ده بيساعدني أتخيّل الشغل بشكل حقيقي.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Alguna pregunta sobre el trabajo en sí?",ar:"أي سؤال عن الشغل نفسه؟"},{speaker:"paco",es:"¿Cómo es un día normal en este puesto?",ar:"اليوم العادي في الوظيفة دي عامل إزاي؟"},{speaker:"luna",es:"Llamadas seguidas, pausas cortas y registro de casos.",ar:"مكالمات ورا بعض، بريكات قصيرة، وتسجيل الحالات."},{speaker:"paco",es:"¿Cuál es el mayor reto para alguien que empieza?",ar:"إيه أكبر تحدي لواحد لسه بادي؟"},{speaker:"luna",es:"Acostumbrarse al ritmo de las primeras semanas.",ar:"التعود على إيقاع أول أسبوعين."},{speaker:"paco",es:"¿Qué diferencia a quien tiene éxito aquí?",ar:"إيه اللي بيفرّق اللي بينجح هنا عن غيره؟"},{speaker:"luna",es:"La paciencia y las ganas de aprender.",ar:"الصبر والرغبة في التعلم."},{speaker:"paco",es:"Gracias, eso me ayuda a imaginarme el trabajo.",ar:"شكرًا، ده بيساعدني أتخيّل الشغل بشكل حقيقي."}],questions:[{q:"اليوم العادي في الوظيفة حسب الوصف؟",options:["مكالمات ورا بعض وبريكات قصيرة وتسجيل حالات","اجتماعات طويلة وتقارير أسبوعية مفصلة ومنظمة","شغل مكتب هادي ومكالمات قليلة جدًا","مهمات خارجية وتنقل بين فروع"],answer:"مكالمات ورا بعض وبريكات قصيرة وتسجيل حالات",rationale:"قالت: Llamadas seguidas, pausas cortas y registro de casos — مكالمات ورا بعض، بريكات قصيرة، وتسجيل الحالات."},{q:"أكبر تحدي للي لسه بادي؟",options:["حفظ أسماء كل زملاء الفريق","التعود على إيقاع أول أسبوعين","تعلم لغة برمجة جديدة تمامًا","التعامل مع مدير صعب جدًا الطباع"],answer:"التعود على إيقاع أول أسبوعين",rationale:"قالت: Acostumbrarse al ritmo de las primeras semanas — التعود على إيقاع أول أسبوعين."},{q:"ليه سؤال «يوم الشغل العادي» سؤال ذكي؟",options:["عشانه بيبعد الكلام تمامًا عن موضوع المرتب وظروفه","عشانه سؤال سهل ومسؤولة التوظيف بتحب أسئلة زيه","عشانه بيكشف الصورة الحقيقية للشغل قبل الالتزام","عشانه سؤال مضحك بيكسر الجو الرسمي شوية"],answer:"عشانه بيكشف الصورة الحقيقية للشغل قبل الالتزام",rationale:"عمر علّق بنفسه: Gracias, eso me ayuda a imaginarme el trabajo — ده بيساعدني أتخيّل الشغل بشكل حقيقي."}],responseTask:{prompt:"اسأل عن يوم الشغل العادي وأكبر تحدي في الوظيفة — سؤالين بيكشفوا الصورة الحقيقية قبل ما توافق.",acceptable:["¿Cómo es un día normal en este puesto? ¿Cuál es el mayor reto para alguien que empieza?","¿Cuál es el mayor reto para alguien que empieza?","¿Qué diferencia a quien tiene éxito aquí?"],modelEs:"¿Cómo es un día normal en este puesto? ¿Cuál es el mayor reto para alguien que empieza?",modelAr:"اليوم العادي في الوظيفة دي عامل إزاي؟ وإيه أكبر تحدي لواحد لسه بادي؟",checklistAr:"راجع إجابتك: ١) سؤال عن اليوم العادي، ٢) سؤال عن التحدي أو معيار النجاح، ٣) شكر بعد الإجابة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"día normal = يوم عادي. reto = تحدي. ritmo = إيقاع. acostumbrarse = يتعود. tener éxito = ينجح. الأسئلة دي بتخدمك إنت: بتوافق على صورة حقيقية مش خيال."}},{id:"iv-u08l05",courseId:"job-interview",unitId:"iv-u08",sourceLessonId:null,level:"B1",register:"usted",title:"لما مش فاهم السؤال نفسه",context:"سؤال من مسؤولة التوظيف وصل بشكل غلط أو مش واضح. دورك: تطلب توضيح بأدب بدل ما تجاوب على سؤال تاني.",goal:"تطلب إعادة أو توضيح السؤال بأدب مهني.",targets:[{es:"¿Podría repetir la pregunta, por favor?",ar:"ممكن حضرتك تعيدي السؤال، من فضلك؟",speaker:"paco"},{es:"No estoy seguro de haber entendido bien.",ar:"مش متأكد إني فهمت صح.",speaker:"paco"},{es:"¿Se refiere a mi experiencia o a mis estudios?",ar:"حضرتك قصدك على خبرتي ولا دراستي؟",speaker:"paco"},{es:"Ahora sí, gracias. Le respondo.",ar:"كده تمام، شكرًا. هرد على حضرتك.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Háblame de tu trayectoria formativa.",ar:"احكيلي عن مسارك التعليمي."},{speaker:"paco",es:"¿Podría repetir la pregunta, por favor?",ar:"ممكن حضرتك تعيدي السؤال، من فضلك؟"},{speaker:"luna",es:"Claro. Quiero saber qué has estudiado y por qué.",ar:"أكيد. عايزة أعرف درست إيه وليه."},{speaker:"paco",es:"No estoy seguro de haber entendido bien.",ar:"مش متأكد إني فهمت صح."},{speaker:"paco",es:"¿Se refiere a mi experiencia o a mis estudios?",ar:"حضرتك قصدك على خبرتي ولا دراستي؟"},{speaker:"luna",es:"A tus estudios, en este caso.",ar:"لدراستك، في الحالة دي."},{speaker:"paco",es:"Ahora sí, gracias. Le respondo.",ar:"كده تمام، شكرًا. هرد على حضرتك."},{speaker:"luna",es:"Perfecto, adelante.",ar:"ممتاز، اتفضل."}],questions:[{q:"لما السؤال ماوصلش، عمر عمل إيه؟",options:["جاوب بأي كلام عام","طلب إعادة السؤال بأدب","سكت ومردش خالص","ضحك وغيّر الموضوع خالص"],answer:"طلب إعادة السؤال بأدب",rationale:"قال: ¿Podría repetir la pregunta, por favor? — ممكن حضرتك تعيدي السؤال، من فضلك؟"},{q:"عمر حدّد قصد السؤال إزاي؟",options:["رد على الاتنين في نفس الوقت تقريبًا","خمّن إنها بتقصد خبرته وخلاص","سأل: قصدك على خبرتي ولا دراستي؟","قالها إن السؤال مش واضح أصلًا"],answer:"سأل: قصدك على خبرتي ولا دراستي؟",rationale:"قال: ¿Se refiere a mi experiencia o a mis estudios? — حضرتك قصدك على خبرتي ولا دراستي؟"},{q:"إيه الخطر في الرد على سؤال مش فاهمه؟",options:["السؤال بيتحسب غلط مهما كان الرد","مفيش أي خطر، المهم تتكلم بثقة","مسؤولة التوظيف هتنهي المقابلة فورًا وغصب عنها","ممكن ترد على حاجة تانية وتبان مش مركّز"],answer:"ممكن ترد على حاجة تانية وتبان مش مركّز",rationale:"عمر طلب الإعادة وبعدين حدّد القصد، وبعدها رد على السؤال الصح. الرد على سؤال تاني أسوأ من طلب توضيح."}],responseTask:{prompt:"سؤال في المقابلة وصل بشكل مش واضح. اطلب الإعادة بأدب، ولو محتاج، حدّد قصد السؤال بسؤال قصير.",acceptable:["¿Podría repetir la pregunta, por favor? No estoy seguro de haber entendido bien.","No estoy seguro de haber entendido bien. ¿Se refiere a mi experiencia o a mis estudios?","Perdone, ¿podría explicar la pregunta con otras palabras?"],modelEs:"¿Podría repetir la pregunta, por favor? No estoy seguro de haber entendido bien.",modelAr:"ممكن حضرتك تعيدي السؤال، من فضلك؟ مش متأكد إني فهمت صح.",checklistAr:"راجع إجابتك: ١) طلب إعادة بأدب، ٢) لو محتاج، سؤال يحدد القصد، ٣) مفيش رد على سؤال مش فاهمه. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Podría repetir? = ممكن تعيدي؟ (شرطي مهذب). se refiere a = قصدك على. trayectoria = مسار. Adelante = اتفضل. طلب التوضيح بيبين تركيز، مش ضعف."}},{id:"iv-u08l06",courseId:"job-interview",unitId:"iv-u08",sourceLessonId:null,level:"B1",register:"usted",title:"مقابلة كاملة مصغرة",context:"قفلة الكورس: مقابلة تجريبية مصغرة من التحية للوداع. دورك: تربط كل الوحدات — تعريف صادق، مثال حقيقي، سؤال عن الشغل، وشكر.",goal:"تدير مقابلة كاملة قصيرة بربط كل المهارات.",targets:[{es:"Buenos días. Gracias por recibirme.",ar:"صباح الخير. شكرًا إنك مستقبلاني.",speaker:"paco"},{es:"Me interesa el puesto porque disfruto ayudando a los clientes.",ar:"مهتم بالوظيفة عشان بحب أساعد العملاء.",speaker:"paco"},{es:"¿Cuáles serían mis tareas principales en las primeras semanas?",ar:"إيه مهامي الأساسية في أول أسبوعين؟",speaker:"paco"},{es:"Gracias por su tiempo. Quedo a su disposición para cualquier aclaración.",ar:"شكرًا على وقت حضرتك. أنا متاح لو حضرتكم محتاجين أي توضيح.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenos días, Omar. Empecemos.",ar:"صباح الخير يا عمر. يلا نبدأ."},{speaker:"paco",es:"Buenos días. Gracias por recibirme.",ar:"صباح الخير. شكرًا إنك مستقبلاني."},{speaker:"luna",es:"¿Por qué te interesa este puesto?",ar:"إنت مهتم بالوظيفة دي ليه؟"},{speaker:"paco",es:"Me interesa el puesto porque disfruto ayudando a los clientes.",ar:"مهتم بالوظيفة عشان بحب أساعد العملاء."},{speaker:"luna",es:"¿Tienes alguna pregunta sobre el trabajo?",ar:"عندك أي سؤال عن الشغل؟"},{speaker:"paco",es:"¿Cuáles serían mis tareas principales en las primeras semanas?",ar:"إيه مهامي الأساسية في أول أسبوعين؟"},{speaker:"luna",es:"Buena pregunta. Luego te cuento los pasos siguientes.",ar:"سؤال كويس. بعدين هقولك الخطوات الجاية."},{speaker:"paco",es:"Gracias por su tiempo. Quedo a su disposición para cualquier aclaración.",ar:"شكرًا على وقت حضرتك. أنا متاح لو حضرتكم محتاجين أي توضيح."}],questions:[{q:"المقابلة المصغرة مشيت بترتيب إيه؟",options:["تحية، سبب اهتمام، سؤال عن الشغل، شكر وقفلة","تحية، طلب مرتب أعلى، تفاوض سريع، قفلة عاجلة","سكوت طويل، ردود قصيرة، اعتذار وخروج","أسئلة كتير ورا بعض، وداع من غير شكر"],answer:"تحية، سبب اهتمام، سؤال عن الشغل، شكر وقفلة",rationale:"الحوار ماشي كده: Buenos días (تحية)، disfruto ayudando (سبب)، tareas principales (سؤال)، Gracias por su tiempo (قفلة)."},{q:"جملة القفلة الكاملة اللي قالها عمر؟",options:["شكرًا على وقت حضرتك وأنا متاح لأي توضيح","شكرًا وهستنى خبر قبولي الرسمي النهارده","شكرًا وعايز أعرف قيمة مرتبي دلوقتي","شكرًا وهبعتلكم سيرتي الذاتية على الإيميل"],answer:"شكرًا على وقت حضرتك وأنا متاح لأي توضيح",rationale:"قال: Gracias por su tiempo. Quedo a su disposición para cualquier aclaración — شكرًا على وقت حضرتك. أنا متاح لو حضرتكم محتاجين أي توضيح."},{q:"إيه اللي بيفرّق مقابلة متدرب عليها عن واحدة ارتجالية؟",options:["سرعة رد عالية من غير أي توقف","جمل جاهزة بتتقال بشكل طبيعي مش محفوظة حرفي","عدد كبير من الكلمات الصعبة والنادرة في التخصص","تجنب أي سؤال عن تفاصيل الشغل اليومي"],answer:"جمل جاهزة بتتقال بشكل طبيعي مش محفوظة حرفي",rationale:"كل جمل عمر جاية من الوحدات السابقة بس مربوطة بشكل طبيعي: التحضير = جمل جاهزة، الأداء = ربط طبيعي."}],responseTask:{prompt:"مثّل مقابلة كاملة قصيرة: حيّي، اشرح سبب اهتمامك، اسأل عن مهامك، واقفل بشكر مهني.",acceptable:["Buenos días. Gracias por recibirme. Me interesa el puesto porque disfruto ayudando a los clientes.","Me interesa el puesto porque me gusta el trato con la gente. ¿Cuáles serían mis tareas principales?","Gracias por su tiempo. Me ha gustado conocer mejor el puesto. Quedo a su disposición."],modelEs:"Buenos días. Gracias por recibirme. Me interesa el puesto porque disfruto ayudando a los clientes.",modelAr:"صباح الخير. شكرًا إنك مستقبلاني. مهتم بالوظيفة عشان بحب أساعد العملاء.",checklistAr:"راجع إجابتك: ١) تحية مهنية، ٢) سبب اهتمام حقيقي، ٣) سؤال عن الشغل، ٤) قفلة بشكر من غير افتراض نتيجة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Gracias por recibirme = شكرًا على استقبالكم لي. Empecemos = يلا نبدأ. Quedo a su disposición = أنا متاح لحضرتكم. دي قفلة الكورس كله: لو قدرت تعمل المقابلة دي بصوت عالي من غير ورقة، إنت جاهز."}}]},{courseId:"everyday-core",unit:{id:"p0-a",title:"كلمات صغيرة بتفرق",desc:"كلمات قصيرة بتتقال كتير كل يوم: كمان، يبقى، ولا أنا، مع إن، يمكن، نفس الحاجة — وإزاي تستخدمها صح.",cefr:"A1"},lessons:[{id:"p0-a-l01",courseId:"everyday-core",unitId:"p0-a",sourceLessonId:"p0-a-l01",level:"A1",register:"tú",title:"كمان",context:"بتتفق مع صاحبك في حاجة أو بتقول إنك بتعمل نفس الحاجة. دورك: تستخدم también في مكانها الصح.",goal:"تقول «أنا كمان» وتستخدم también في أول الجملة أو آخرها.",targets:[{es:"También hablo inglés.",ar:"أنا بتكلم إنجليزي كمان.",speaker:"luna"},{es:"A mí también me gusta el inglés.",ar:"أنا كمان الإنجليزي عاجبني.",speaker:"paco"},{es:"Yo también.",ar:"أنا كمان.",speaker:"paco"},{es:"También tomo té.",ar:"أنا بشرب شاي كمان.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Estudias español?",ar:"بتذاكري إسباني؟"},{speaker:"luna",es:"Sí. También hablo inglés.",ar:"أيوه. أنا بتكلم إنجليزي كمان."},{speaker:"paco",es:"A mí también me gusta el inglés.",ar:"أنا كمان الإنجليزي عاجبني."},{speaker:"luna",es:"Me gusta el café por la mañana.",ar:"بحب القهوة الصبح."},{speaker:"paco",es:"Yo también.",ar:"أنا كمان."},{speaker:"luna",es:"¿Y por la tarde?",ar:"والعصر؟"},{speaker:"paco",es:"También tomo té.",ar:"أنا بشرب شاي كمان."}],questions:[{q:"لونا بتتكلم أنهي لغات؟",options:["إسباني وإنجليزي كمان","إسباني بس وخلاص","إنجليزي بس وخلاص"],answer:"إسباني وإنجليزي كمان",rationale:"قالت: También hablo inglés — أنا بتكلم إنجليزي كمان (يعني بتتكلم الاتنين)."},{q:"«A mí también me gusta» معناها إيه؟",options:["أنا بس اللي عاجبني","أنا كمان عاجبني","أنا كمان مش عاجبني"],answer:"أنا كمان عاجبني",rationale:"باكو قالها ردًا على إن لونا بتتكلم إنجليزي: A mí también me gusta el inglés — أنا كمان الإنجليزي عاجبني."},{q:"también ممكن تيجي فين في الجملة؟",options:["في الآخر بس ومش أول الجملة","في النص بس وممنوع غير كده","في الأول أو في الآخر"],answer:"في الأول أو في الآخر",rationale:"زي ما سمعت: También hablo inglés (في الأول) وTambién tomo té بنفس الطريقة، وممكن كمان Hablo inglés también (في الآخر)."}],responseTask:{prompt:"صاحبك قال: Me gusta el café. رد عليه وقول إنك كمان بتحب القهوة.",acceptable:["A mí también.","Yo también.","A mí también me gusta."],modelEs:"A mí también.",modelAr:"أنا كمان.",checklistAr:"راجع إجابتك: ١) المعنى (كمان) واضح، ٢) الترتيب صح: A mí también أو Yo también، ٣) نبرة ودية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"también = كمان / برضه. ممكن تيجي في أول الجملة (También hablo inglés) أو في الآخر (Hablo inglés también). Yo también = أنا كمان: رد سريع لما بتتفق مع حد."}},{id:"p0-a-l02",courseId:"everyday-core",unitId:"p0-a",sourceLessonId:"p0-a-l02",level:"A1",register:"tú",title:"يبقى… لأ… بس",context:"خطط اتغيرت وبتعيد ترتيبها مع صاحبتك. دورك: تستخدم entonces للنتيجة وsino للتصحيح بعد النفي.",goal:"تقول «يبقى…» بـ entonces وتصحّح بـ sino: مش ده، ده.",targets:[{es:"Entonces, ¿vamos mañana?",ar:"يبقى هنروح بكرة؟",speaker:"paco"},{es:"No quiero café, sino té.",ar:"مش عايزة قهوة، عايزة شاي.",speaker:"luna"},{es:"No voy hoy, sino mañana.",ar:"مش رايحة النهارده، رايحة بكرة.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Hoy no puedo salir.",ar:"النهارده مش هقدر أخرج."},{speaker:"paco",es:"Entonces, ¿vamos mañana?",ar:"يبقى هنروح بكرة؟"},{speaker:"luna",es:"Sí, mañana sí.",ar:"أيوه، بكرة تمام."},{speaker:"paco",es:"¿Quieres café?",ar:"عايزة قهوة؟"},{speaker:"luna",es:"No quiero café, sino té.",ar:"مش عايزة قهوة، عايزة شاي."},{speaker:"paco",es:"¿Vas hoy al centro?",ar:"رايحة وسط البلد النهارده؟"},{speaker:"luna",es:"No voy hoy, sino mañana.",ar:"مش رايحة النهارده، رايحة بكرة."}],questions:[{q:"الاتنين هيروحوا إمتى؟",options:["النهارده","بكرة","بعد بكرة"],answer:"بكرة",rationale:"لونا قالت: Hoy no puedo salir، وباكو اقترح: Entonces, ¿vamos mañana? ووافقت: Sí, mañana sí."},{q:"لونا عايزة تشرب إيه؟",options:["الاتنين مع بعض","قهوة مش شاي","شاي مش قهوة"],answer:"شاي مش قهوة",rationale:"قالت: No quiero café, sino té — مش عايزة قهوة، عايزة شاي."},{q:"sino بتتستخدم إزاي؟",options:["بعد جملة منفية عشان تصحّح: مش ده، ده","بمعنى «لو مش» وتنفع في أي جملة عادية","في أول الجملة كأداة ترحيب بالكلام"],answer:"بعد جملة منفية عشان تصحّح: مش ده، ده",rationale:"في الجملتين فيه no قبلها: No quiero café, sino té وNo voy hoy, sino mañana. متلخبطهاش مع si no (لو … مش)."}],responseTask:{prompt:"صاحبتك قالت: ¿Vienes hoy? رد: مش النهارده — بكرة، مستخدم sino.",acceptable:["No voy hoy, sino mañana.","No, hoy no. Mañana sí.","Hoy no puedo, mañana sí."],modelEs:"No voy hoy, sino mañana.",modelAr:"مش رايح النهارده، رايح بكرة.",checklistAr:"راجع إجابتك: ١) نفي الأول (no)، ٢) التصحيح بـ sino، ٣) المعلومة الجديدة واضحة (بكرة). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"entonces = يبقى / يعني كده (نتيجة لكلام قبلها). sino = بس / لكن، بتيجي بس بعد جملة منفية عشان تصحّح: مش ده، ده. انتبه للفرق: si no (كلمتين) = لو … مش."}},{id:"p0-a-l03",courseId:"everyday-core",unitId:"p0-a",sourceLessonId:"p0-a-l03",level:"A1",register:"tú",title:"ولا أنا",context:"صاحبك قال حاجة منفية وإنت زيك. دورك: تقول «ولا أنا» وتستخدم tampoco وnadie وningún صح.",goal:"ترد على النفي بـ tampoco وتستخدم ningún وnadie من غير no زيادة.",targets:[{es:"A mí tampoco.",ar:"ولا أنا.",speaker:"luna"},{es:"No tengo ningún problema.",ar:"معنديش أي مشكلة.",speaker:"luna"},{es:"Nadie está aquí.",ar:"مفيش حد هنا.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"No me gusta el frío.",ar:"البرد مش عاجبني."},{speaker:"luna",es:"A mí tampoco.",ar:"ولا أنا."},{speaker:"paco",es:"¿Tienes algún problema?",ar:"عندك أي مشكلة؟"},{speaker:"luna",es:"No tengo ningún problema.",ar:"معنديش أي مشكلة."},{speaker:"paco",es:"¿Hay alguien en casa?",ar:"في حد في البيت؟"},{speaker:"luna",es:"Nadie está aquí.",ar:"لأ، مفيش حد هنا."}],questions:[{q:"لونا عاجبها البرد؟",options:["مش مهتمة بالجو","أيوه، بتحبه جدًا","لأ، ولا هو عاجبها"],answer:"لأ، ولا هو عاجبها",rationale:"باكو قال: No me gusta el frío، ولونا ردت: A mí tampoco — ولا أنا (يعني هي كمان مش عاجبها)."},{q:"«A mí tampoco» معناها إيه؟",options:["ولا أنا","أنا كمان","أنا الأول"],answer:"ولا أنا",rationale:"tampoco = ولا/ولا أنا، بتتقال رد على جملة منفية. عكسها: A mí también = أنا كمان للإيجاب."},{q:"«Nadie está aquí» — محتاجين no قبل الفعل؟",options:["أيوه، دايمًا لازم no قبل الفعل في كل الجمل","لأ، لما الكلمة المنفية في الأول مفيش no","بس لو الجملة سؤال مش خبر عادي"],answer:"لأ، لما الكلمة المنفية في الأول مفيش no",rationale:"زي ما سمعت: Nadie está aquí من غير no. بس لو الكلمة المنفية جهت بعد الفعل بنحط no: No veo a nadie."}],responseTask:{prompt:"صاحبك قال: No me gusta levantarme temprano. وإنت زيه. رد بـ tampoco.",acceptable:["A mí tampoco.","A mí tampoco me gusta.","Yo tampoco."],modelEs:"A mí tampoco.",modelAr:"ولا أنا.",checklistAr:"راجع إجابتك: ١) tampoco للرد على نفي، ٢) مفيش también غلط، ٣) النبرة ودية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"tampoco = ولا (للنفي): ولا أنا، ولا هو. ningún قبل اسم مذكر مفرد (ninguna للمؤنث). nadie = مفيش حد. لو الكلمة المنفية في الأول مفيش no: Nadie está aquí. لو بعد الفعل: No veo a nadie."}},{id:"p0-a-l04",courseId:"everyday-core",unitId:"p0-a",sourceLessonId:"p0-a-l04",level:"A1",register:"tú",title:"حد ومع إن",context:"في حد بيخبط على الباب والوقت متأخر. دورك: تستخدم alguien للحد المجهول وaunque لـ«مع إن» وademás للزيادة.",goal:"تقول «في حد» و«مع إن» و«وفوق كده» بالإسباني.",targets:[{es:"Alguien llama a la puerta.",ar:"في حد بيخبط على الباب.",speaker:"paco"},{es:"Aunque es tarde, salgo a ver.",ar:"مع إن الوقت متأخر، هخرج أشوف.",speaker:"paco"},{es:"Además, es barata.",ar:"وفوق كده، رخيص.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Oyes algo?",ar:"سامع حاجة؟"},{speaker:"paco",es:"Sí. Alguien llama a la puerta.",ar:"أيوه. في حد بيخبط على الباب."},{speaker:"luna",es:"Es tarde. ¿Quién puede ser?",ar:"الوقت متأخر. مين ممكن يكون؟"},{speaker:"paco",es:"No sé. Aunque es tarde, salgo a ver.",ar:"مش عارف. مع إن الوقت متأخر، هخرج أشوف."},{speaker:"luna",es:"¿Por qué quieres comprar esta camisa?",ar:"ليه عايز تشتري القميص ده؟"},{speaker:"paco",es:"Es bonita. Además, es barata.",ar:"حلو. وفوق كده، رخيص."}],questions:[{q:"مين اللي عند الباب؟",options:["مش عارفين — في حد بيخبط","الجيران عرفوهم","عامل التوصيل المعتاد"],answer:"مش عارفين — في حد بيخبط",rationale:"باكو قال: Alguien llama a la puerta (في حد بيخبط) ورد على السؤال بـ No sé."},{q:"«Aunque es tarde, salgo a ver» معناها إيه؟",options:["عشان الوقت متأخر، هخرج أشوف","مع إن الوقت متأخر، هخرج أشوف","لو الوقت متأخر، هخرج أشوف"],answer:"مع إن الوقت متأخر، هخرج أشوف",rationale:"aunque هنا = مع إن / رغم إن، والحقيقة معروفة (الوقت متأخر فعلًا) فالفعل عادي مش subjuntivo."},{q:"«además» بتضيف إيه للكلام؟",options:["نفي للجملة اللي قبلها","سبب للجملة اللي قبلها","معلومة كمان فوق اللي اتقال"],answer:"معلومة كمان فوق اللي اتقال",rationale:"باكو قال سببين للشراء: Es bonita وبعدين زاد: Además, es barata — وفوق كده، رخيصة."}],responseTask:{prompt:"في حد بيخبط على الباب وإنت اللي سامع. قول لصاحبتك إن في حد على الباب وإنك هتروح تشوف مع إن الوقت متأخر.",acceptable:["Alguien llama a la puerta. Aunque es tarde, salgo a ver.","Hay alguien en la puerta. Voy a ver.","Alguien llama. Voy a abrir aunque es tarde."],modelEs:"Alguien llama a la puerta. Aunque es tarde, salgo a ver.",modelAr:"في حد بيخبط على الباب. مع إن الوقت متأخر، هخرج أشوف.",checklistAr:"راجع إجابتك: ١) alguien للحد المجهول، ٢) aunque + فعل عادي لأن الحقيقة معروفة، ٣) الجملة مفهومة من غير ترجمة حرفية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"alguien = حد / في حد. aunque = مع إن / رغم إن (هنا مع الفعل العادي لأن الحقيقة معروفة). además = وفوق كده / وكمان. llama a la puerta = بيخبط على الباب."}},{id:"p0-a-l05",courseId:"everyday-core",unitId:"p0-a",sourceLessonId:"p0-a-l05",level:"A1",register:"tú",title:"يمكن وكفاية",context:"سؤال عن أحوالك وعن خطة لسه مش متأكدة. دورك: ترد بـ bastante وquizás وincluso.",goal:"تقول «كويس كفاية» و«يمكن» و«حتى في الصيف».",targets:[{es:"Bastante bien.",ar:"كويس كفاية.",speaker:"paco"},{es:"Quizás mañana.",ar:"يمكن بكرة.",speaker:"paco"},{es:"Incluso en verano.",ar:"حتى في الصيف.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Cómo estás?",ar:"عامل إيه؟"},{speaker:"paco",es:"Bastante bien.",ar:"كويس كفاية."},{speaker:"luna",es:"¿Vienes con nosotros el sábado?",ar:"جاي معانا يوم السبت؟"},{speaker:"paco",es:"No sé. Quizás mañana.",ar:"مش عارف. يمكن بكرة."},{speaker:"luna",es:"Hace frío aquí.",ar:"الجو برد هنا."},{speaker:"paco",es:"Incluso en verano.",ar:"حتى في الصيف."}],questions:[{q:"باكو عامل إيه؟",options:["تعبان أوي","وحش خالص","كويس كفاية"],answer:"كويس كفاية",rationale:"رد على ¿Cómo estás? بـ: Bastante bien — كويس كفاية."},{q:"باكو حسم موضوع يوم السبت؟",options:["لأ لسه، يمكن يعرف بكرة","أيوه، أكيد جاي يوم السبت","لأ، رفض نهائي من غير سبب"],answer:"لأ لسه، يمكن يعرف بكرة",rationale:"قال: No sé. Quizás mañana — مش عارف. يمكن بكرة."},{q:"«incluso» معناها إيه؟",options:["بس","حتى","تقريبًا"],answer:"حتى",rationale:"قال: Incluso en verano — حتى في الصيف (يعني البرد موجود حتى في الصيف)."}],responseTask:{prompt:"سألوك: ¿Cómo estás? و¿Vienes mañana? رد على السؤالين: كويس كفاية، وممكن بكرة تعرف.",acceptable:["Bastante bien. Quizás mañana lo sé.","Bastante bien, gracias. No sé, quizás mañana.","Bastante bien. Quizás venga, no estoy seguro."],modelEs:"Bastante bien. Quizás mañana lo sé.",modelAr:"كويس كفاية. يمكن بكرة أعرف.",checklistAr:"راجع إجابتك: ١) bastante = كفاية/أكتر من عادي، ٢) quizás = يمكن، ٣) عدم التأكد واضح (no sé). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"bastante = كفاية / أكتر من عادي (قبل الأسماء بتتغير: bastantes problemas). quizás / quizá = يمكن. incluso = حتى. seguro = متأكد: No estoy seguro = مش متأكد."}},{id:"p0-a-l06",courseId:"everyday-core",unitId:"p0-a",sourceLessonId:"p0-a-l06",level:"A1",register:"tú",title:"نفس الحاجة",context:"لقيت صاحبتك لابسة نفس قميصك، وبعدين بتطلب في القهوة. دورك: تستخدم mismo بأنواعه وتقول «نفس الحاجة لو سمحت».",goal:"تستخدم mismo/misma و«lo mismo» و«una cosa más».",targets:[{es:"La misma camisa que tú.",ar:"نفس القميص بتاعك.",speaker:"luna"},{es:"Lo mismo, por favor.",ar:"نفس الحاجة لو سمحت.",speaker:"paco"},{es:"Una cosa más: la cuenta.",ar:"حاجة كمان: الحساب.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¡Mira tu camisa!",ar:"بصي قميصك!"},{speaker:"luna",es:"Sí. La misma camisa que tú.",ar:"أيوه. نفس القميص بتاعك."},{speaker:"paco",es:"¡Qué casualidad!",ar:"يا لهوي على المصادفة!"},{speaker:"luna",es:"¿Qué quieres tomar?",ar:"عايز تشرب إيه؟"},{speaker:"paco",es:"Lo mismo, por favor.",ar:"نفس الحاجة لو سمحت."},{speaker:"luna",es:"¿Algo más?",ar:"أي حاجة تانية؟"},{speaker:"paco",es:"Una cosa más: la cuenta.",ar:"حاجة كمان: الحساب."}],questions:[{q:"ليه باكو اتفاجئ؟",options:["لونا جابتله هدية","لونا لابسة نفس قميصه","القميص كان غالي جدًا"],answer:"لونا لابسة نفس قميصه",rationale:"قالت: La misma camisa que tú — نفس القميص بتاعك."},{q:"«Lo mismo, por favor» بتتقال إمتى؟",options:["لما ترفض أي طلب يتقدملك","لما تطلب حاجة مختلفة تمامًا عن الكل","لما تطلب نفس الحاجة اللي طلبها غيرك"],answer:"لما تطلب نفس الحاجة اللي طلبها غيرك",rationale:"لونا سألته يشرب إيه فقال: Lo mismo, por favor — نفس الحاجة (بتاعتها) لو سمحت."},{q:"«mismo» بتتغير إزاي؟",options:["حسب النوع والعدد: mismo / misma / mismos / mismas","مش بتتغير خالص أبدًا مهما كان الاسم","بتتغير حسب الشخص اللي بيتكلم بس ومش مرتبطة بالاسم"],answer:"حسب النوع والعدد: mismo / misma / mismos / mismas",rationale:"سمعت: La misma camisa (مؤنث مفرد) وLo mismo (المحايد). القاعدة: el mismo / la misma / los mismos / las mismas."}],responseTask:{prompt:"في القهوة، صاحبتك طلبت شاي وإنت عايز نفس الحاجة، وعايز كمان تطلب الحساب. قول الطلبين.",acceptable:["Lo mismo, por favor. Una cosa más: la cuenta.","Para mí lo mismo. Y la cuenta, por favor.","Yo quiero lo mismo. La cuenta también, por favor."],modelEs:"Lo mismo, por favor. Una cosa más: la cuenta.",modelAr:"نفس الحاجة لو سمحت. حاجة كمان: الحساب.",checklistAr:"راجع إجابتك: ١) lo mismo لطلب نفس الحاجة، ٢) una cosa más لإضافة طلب، ٣) por favor موجودة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"mismo = نفس، وبتتغير: el mismo / la misma / los mismos / las mismas. cosa = حاجة (مؤنث). ¡Qué casualidad! = يا لهوي على المصادفة! la cuenta = الحساب."}}]},{courseId:"everyday-core",unit:{id:"p0-b",title:"كلمة على الماشي (إسبانيا)",desc:"تعبيرات سريعة بتسمعها كل يوم في إسبانيا: ماشي، طبعًا، بص، جامد، أهلًا بيك، بالتوفيق — وإزاي تقولها طبيعي.",cefr:"A1"},lessons:[{id:"p0-b-l01",courseId:"everyday-core",unitId:"p0-b",sourceLessonId:"p0-b-l01",level:"A1",register:"tú",title:"ماشي، تمام",context:"باكو ولونا بيظبطوا معاد يتقابلوا فيه بكرة.",goal:"تستخدم vale للموافقة والتأكيد زي ما بتتقال في إسبانيا.",targets:[{es:"Vale, de acuerdo.",ar:"تمام، اتفقنا.",speaker:"luna"},{es:"Vale, nos vemos.",ar:"ماشي، نتقابل.",speaker:"luna"},{es:"¡Vale, vale!",ar:"ماشي ماشي!",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Quedamos mañana a las seis?",ar:"هنتقابل بكرة الساعة ستة؟"},{speaker:"luna",es:"Vale, de acuerdo.",ar:"تمام، اتفقنا."},{speaker:"paco",es:"¿En la puerta del cine?",ar:"قدام باب السينما؟"},{speaker:"luna",es:"Vale, nos vemos.",ar:"ماشي، نتقابل."},{speaker:"paco",es:"¿Y traigo las entradas?",ar:"وأنا أجيب التذاكر؟"},{speaker:"luna",es:"¡Vale, vale!",ar:"ماشي ماشي!"},{speaker:"paco",es:"Jaja, entendido.",ar:"ههه، فهمت."}],questions:[{q:"لونا وافقت على معاد بكرة بإيه؟",options:["Vale, de acuerdo.","No, mañana no puedo.","Bueno… no sé."],answer:"Vale, de acuerdo.",rationale:"قالت: Vale, de acuerdo. يعني تمام، اتفقنا على المعاد."},{q:"كلمة vale في إسبانيا معناها إيه؟",options:["كلمة رسمية للشغل والمكاتب بس ومش للكلام اليومي","تمام أو ماشي، وبتتقال طول اليوم","معناها مع السلامة وقت الوداع"],answer:"تمام أو ماشي، وبتتقال طول اليوم",rationale:"vale = تمام / ماشي، وسمعناها في الحوار أكتر من مرة في مواقف موافقة."},{q:"«¡Vale, vale!» بتعبر عن إيه؟",options:["طلب إعادة الكلام تاني","رفض مهذب للاقتراح","خلاص فهمت ومتفقين"],answer:"خلاص فهمت ومتفقين",rationale:"لونا قالتها لما باكو زود سؤال تالت، يعني خلاص فهمت وماشي."}],responseTask:{prompt:"صاحبك الإسباني بيسألك: ¿Quedamos mañana a las cinco? رد عليه إنك موافق واستخدم vale.",acceptable:["Vale, de acuerdo.","Vale, nos vemos mañana.","¡Vale!"],modelEs:"Vale, de acuerdo.",modelAr:"تمام، اتفقنا.",checklistAr:"راجع إجابتك: ١) استخدمت vale، ٢) المعنى موافقة واضحة، ٣) النبرة ودية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"vale في إسبانيا = تمام / ماشي / حاضر، وبتتقال طول الوقت في الكلام اليومي. ¡Vale, vale! = خلاص فهمت. في أمريكا اللاتينية بتسمعها أقل بكتير."}},{id:"p0-b-l02",courseId:"everyday-core",unitId:"p0-b",sourceLessonId:"p0-b-l02",level:"A1",register:"tú",title:"طبعًا",context:"لونا بتطلب من باكو مساعدة، وبيتكلموا عن حفلة صاحبتهم.",goal:"ترد بطبعًا وأكيد، وتفهم bueno في أول الجملة.",targets:[{es:"¡Claro!",ar:"طبعًا!",speaker:"paco"},{es:"Claro que sí.",ar:"أيوه طبعًا.",speaker:"paco"},{es:"Bueno… no sé.",ar:"امم… مش عارف.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Me ayudas con la maleta?",ar:"تساعدني في الشنطة؟"},{speaker:"paco",es:"¡Claro!",ar:"طبعًا!"},{speaker:"luna",es:"¿Vienes a la fiesta de Ana?",ar:"هتيجي حفلة آنا؟"},{speaker:"paco",es:"Claro que sí.",ar:"أيوه طبعًا."},{speaker:"luna",es:"¿Y sabes dónde es?",ar:"وعارف مكانها فين؟"},{speaker:"paco",es:"Bueno… no sé.",ar:"امم… مش عارف."},{speaker:"luna",es:"Es cerca de la plaza.",ar:"قريبة من الميدان."},{speaker:"paco",es:"Vale, nos vemos allí.",ar:"ماشي، نتقابل هناك."}],questions:[{q:"باكو رد على طلب المساعدة بإيه؟",options:["Bueno… no sé.","¡Claro!","Un momento."],answer:"¡Claro!",rationale:"رد فورًا: ¡Claro! يعني طبعًا هساعدك."},{q:"«Claro que sí» معناها إيه؟",options:["امم، يمكن","لأ، مش ممكن","أيوه طبعًا"],answer:"أيوه طبعًا",rationale:"قالها رد على سؤال هتيجي الحفلة، يعني أيوه أكيد جاي."},{q:"bueno في أول جملة باكو معناها إيه؟",options:["كلمة تفكير قبل الرد، زي «امم»","صفة معناها كويس بتمدح المكان والجو","تحية بتتقال الصبح"],answer:"كلمة تفكير قبل الرد، زي «امم»",rationale:"في الجملة Bueno… no sé. جاية في الأول كلمة استهلال بيفكر بيها قبل ما يرد، مش صفة."}],responseTask:{prompt:"صاحبتك سألتك: ¿Vienes conmigo al mercado? رد إنك جاي معاها باستخدام claro.",acceptable:["Claro que sí.","¡Claro!","Claro, vamos."],modelEs:"Claro que sí.",modelAr:"أيوه طبعًا.",checklistAr:"راجع إجابتك: ١) استخدمت claro، ٢) المعنى موافقة أكيدة، ٣) الجملة قصيرة وطبيعية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"claro = طبعًا / أكيد، و Claro que sí تأكيد أقوى. bueno في أول الجملة كلمة بنفكر بيها قبل ما نرد، زي «امم» أو «يعني»، ومش دايمًا معناها «كويس»."}},{id:"p0-b-l03",courseId:"everyday-core",unitId:"p0-b",sourceLessonId:"p0-b-l03",level:"A1",register:"tú",title:"بص واسمع",context:"لونا وباكو في الشارع والدنيا بتمطر.",goal:"تلفت الانتباه بـ mira و oye، وتستعجل حد بـ venga.",targets:[{es:"Mira, un taxi.",ar:"بص، تاكسي.",speaker:"luna"},{es:"Oye, espera.",ar:"اسمعي، استني.",speaker:"paco"},{es:"Venga, vamos.",ar:"يلا بينا.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Mira, un taxi.",ar:"بص، تاكسي."},{speaker:"paco",es:"Oye, espera.",ar:"اسمعي، استني."},{speaker:"luna",es:"¿Por qué?",ar:"ليه؟"},{speaker:"paco",es:"Es que llueve.",ar:"عشان بتمطر."},{speaker:"luna",es:"Venga, vamos.",ar:"يلا بينا."},{speaker:"paco",es:"¡Venga!",ar:"يلا!"}],questions:[{q:"لونا لفتت انتباه باكو للتاكسي بكلمة إيه؟",options:["Venga","Oye","Mira"],answer:"Mira",rationale:"قالت: Mira, un taxi. يعني بص، تاكسي."},{q:"باكو قال «Oye, espera» ليه؟",options:["عشان يطلب منها تستنى، الدنيا بتمطر","عشان يقفل باب التاكسي ويمشي","عشان يسلم عليها أول ما شافها واقفة"],answer:"عشان يطلب منها تستنى، الدنيا بتمطر",rationale:"قالها قبل ما يوضح: Es que llueve. يعني عشان بتمطر."},{q:"«venga» في آخر الحوار معناها إيه؟",options:["استنى","يلا","بص"],answer:"يلا",rationale:"Venga, vamos. = يلا بينا، وباكو رد عليها: ¡Venga!"}],responseTask:{prompt:"شفت صاحبك ماشي بسرعة والدنيا بتمطر. ناديه بكلمة بتلفت الانتباه وقوله يستنى.",acceptable:["Oye, espera.","¡Oye, espera!","Mira, espera."],modelEs:"Oye, espera.",modelAr:"اسمع، استنى.",checklistAr:"راجع إجابتك: ١) بدأت بـ oye أو mira، ٢) طلبت منه يستنى بـ espera، ٣) الجملة قصيرة ومناسبة للشارع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"mira و oye بنبدأ بيهم الكلام عشان نلفت الانتباه، ودي صيغة tú. مع حد كبير أو غريب بنقول mire / oiga. venga = يلا، بنقولها عشان نستعجل حد أو نشجعه."}},{id:"p0-b-l04",courseId:"everyday-core",unitId:"p0-b",sourceLessonId:"p0-b-l04",level:"A1",register:"tú",title:"جامد!",context:"باكو وري لونا موبايله الجديد.",goal:"تعبر عن إعجابك بـ guay و estupendo و genial.",targets:[{es:"¡Qué guay!",ar:"جامد!",speaker:"luna"},{es:"Es estupendo.",ar:"ده تحفة.",speaker:"luna"},{es:"¡Genial!",ar:"برافو!",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Tengo un móvil nuevo.",ar:"عندي موبايل جديد."},{speaker:"luna",es:"¡Qué guay!",ar:"جامد!"},{speaker:"paco",es:"Y la cámara es muy buena.",ar:"والكاميرا حلوة جدًا."},{speaker:"luna",es:"Es estupendo.",ar:"ده تحفة."},{speaker:"paco",es:"¿Vamos a probarlo?",ar:"نروح نجربه؟"},{speaker:"luna",es:"Vale, vamos.",ar:"ماشي، يلا."},{speaker:"paco",es:"¡Genial!",ar:"برافو!"}],questions:[{q:"«guay» معناها إيه؟",options:["جامد أو حلو، كلمة شبابية إسبانية","كلمة رسمية بتتكتب في الإيميلات والمكاتب","غالية جدًا عن الميزانية"],answer:"جامد أو حلو، كلمة شبابية إسبانية",rationale:"guay = جامد / حلو، ومش بتتغير للمؤنث: الموبايل guay والبيت guay."},{q:"لونا وصفت الموبايل بإيه؟",options:["Es caro.","Es estupendo.","Es muy pequeño."],answer:"Es estupendo.",rationale:"قالت: Es estupendo. يعني ده تحفة."},{q:"باكو اقترح إيه؟",options:["يشتروا موبايل تاني","يرجعوا الموبايل للمحل اللي اشتروه منه","يروحوا يجربوا الموبايل"],answer:"يروحوا يجربوا الموبايل",rationale:"سأل: ¿Vamos a probarlo? يعني نروح نجربه."}],responseTask:{prompt:"صاحبك وراك صور رحلته وعجبتك جدًا. عبر عن إعجابك بكلمة شبابية إسبانية.",acceptable:["¡Qué guay!","¡Genial!","Es estupendo."],modelEs:"¡Qué guay!",modelAr:"جامد!",checklistAr:"راجع إجابتك: ١) اخترت كلمة إعجاب، ٢) مناسبة لكلام الشباب في إسبانيا، ٣) النبرة متحمسة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"guay كلمة شبابية إسبانية = جامد / حلو، ومش بتتغير للمؤنث: el móvil es guay و la casa es guay. estupendo و genial إعجاب أعم شوية ومناسبين لناس أكبر."}},{id:"p0-b-l05",courseId:"everyday-core",unitId:"p0-b",sourceLessonId:"p0-b-l05",level:"A1",register:"tú",title:"أهلًا بيك",context:"باكو وصل يزور لونا أول مرة.",goal:"ترحب بحد، وترد على المجاملات، وتقول كلمة وداع لطيفة.",targets:[{es:"¡Bienvenido!",ar:"أهلًا بيك!",speaker:"luna"},{es:"Igualmente.",ar:"وإنتي كمان.",speaker:"paco"},{es:"Cuídate.",ar:"خلي بالك من نفسك.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¡Bienvenido!",ar:"أهلًا بيك!"},{speaker:"paco",es:"Gracias, encantado.",ar:"متشكر، متشرف."},{speaker:"luna",es:"¿Qué tal el viaje?",ar:"الرحلة كانت عاملة إيه؟"},{speaker:"paco",es:"Muy bien, gracias.",ar:"كويسة جدًا، متشكر."},{speaker:"luna",es:"Que tengas un buen día.",ar:"يومك سعيد."},{speaker:"paco",es:"Igualmente.",ar:"وإنتي كمان."},{speaker:"luna",es:"Cuídate.",ar:"خلي بالك من نفسك."}],questions:[{q:"لو هترحب بست بتقول إيه؟",options:["¡Bienvenidos!","¡Bienvenido!","¡Bienvenida!"],answer:"¡Bienvenida!",rationale:"Bienvenido للراجل، Bienvenida للست، Bienvenidos لمجموعة."},{q:"باكو قال «Igualmente» رد على إيه؟",options:["على أمنية «يومك سعيد»","على سؤال عن الرحلة","على كلمة «أهلًا بيك» في الترحيب"],answer:"على أمنية «يومك سعيد»",rationale:"جت مباشرة بعد: Que tengas un buen día."},{q:"«Cuídate» بنقولها امتى؟",options:["في أول التعارف بين شخصين مش بيعرفوا بعض","وقت الوداع، ومعناها خلي بالك من نفسك","عند الاعتذار عن غلطة"],answer:"وقت الوداع، ومعناها خلي بالك من نفسك",rationale:"لونا قالتها في آخر الحوار وهما بيودعوا بعض: Cuídate. = خلي بالك من نفسك."}],responseTask:{prompt:"صاحبك الإسباني وصل بيتك أول مرة. رحب بيه بالإسباني.",acceptable:["¡Bienvenido!","¡Bienvenido a casa!","Hola, bienvenido."],modelEs:"¡Bienvenido!",modelAr:"أهلًا بيك!",checklistAr:"راجع إجابتك: ١) استخدمت bienvenido مذكر للراجل، ٢) علامة التعجب ¡...! موجودة، ٣) نبرة ترحيب دافية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¡Bienvenido! للراجل و ¡Bienvenida! للست. igualmente = وإنت/وإنتي كمان، رد جاهز على أي أمنية أو مجاملة. cuídate = خلي بالك من نفسك وبتتقال وقت الوداع. الراجل يقول encantado والست encantada."}},{id:"p0-b-l06",courseId:"everyday-core",unitId:"p0-b",sourceLessonId:"p0-b-l06",level:"A1",register:"tú",title:"بالتوفيق",context:"لونا عندها امتحان وباكو بيشجعها.",goal:"تتمنى التوفيق لحد قبل حاجة مهمة، وتهنئه بعد النجاح.",targets:[{es:"¡Suerte!",ar:"بالتوفيق!",speaker:"paco"},{es:"Tengo prisa.",ar:"أنا مستعجلة.",speaker:"luna"},{es:"¡Felicidades!",ar:"مبروك!",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Mañana tengo un examen.",ar:"بكرة عندي امتحان."},{speaker:"paco",es:"¡Suerte!",ar:"بالتوفيق!"},{speaker:"luna",es:"Gracias.",ar:"متشكرة."},{speaker:"paco",es:"¿A qué hora es?",ar:"الامتحان الساعة كام؟"},{speaker:"luna",es:"A las nueve. Tengo prisa.",ar:"الساعة تسعة. أنا مستعجلة."},{speaker:"paco",es:"¡Venga, vamos!",ar:"يلا بينا!"},{speaker:"luna",es:"¡Aprobé el examen!",ar:"نجحت في الامتحان!"},{speaker:"paco",es:"¡Felicidades!",ar:"مبروك!"}],questions:[{q:"«¡Suerte!» بنقولها امتى؟",options:["بعد ما حد ينجح أو يكسب","قبل امتحان أو موعد مهم","وقت الوداع في الشارع"],answer:"قبل امتحان أو موعد مهم",rationale:"باكو قالها لما لونا قالت: Mañana tengo un examen. يعني قبل الامتحان."},{q:"لونا قالت «Tengo prisa» ليه؟",options:["عشان التاكسي مش واقف ليها خالص","عشان عايزة تنام بدري","عشان امتحانها قريب ومستعجلة"],answer:"عشان امتحانها قريب ومستعجلة",rationale:"قالت: A las nueve. Tengo prisa. يعني الامتحان الساعة تسعة وهي مستعجلة."},{q:"لما لونا قالت إنها نجحت، باكو رد بإيه؟",options:["¡Felicidades!","¡Suerte!","¡Cuídate mucho!"],answer:"¡Felicidades!",rationale:"رد على: ¡Aprobé el examen! بـ: ¡Felicidades! يعني مبروك."}],responseTask:{prompt:"صاحبتك عندها مقابلة شغل بكرة. تمنى لها التوفيق بالإسباني.",acceptable:["¡Suerte!","¡Suerte mañana!","¡Mucha suerte!"],modelEs:"¡Suerte!",modelAr:"بالتوفيق!",checklistAr:"راجع إجابتك: ١) استخدمت suerte، ٢) مناسبة لموقف قبل حاجة مهمة، ٣) النبرة مشجعة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"suerte = حظ، وبنقول ¡Suerte! قبل امتحان أو مقابلة أو أي موعد مهم. felicidades = مبروك بعد نجاح أو فرح أو عيد ميلاد. tengo prisa = أنا مستعجل، وصيغتها واحدة للراجل والست."}}]},{courseId:"everyday-core",unit:{id:"p0-c",title:"الطلبات بأدب",desc:"إزاي تطلب حاجة أو مساعدة بشكل لطيف: ممكن، لو سمحت، عندك، ساعدني، استناني، لو مفيش مشكلة.",cefr:"A1–A2"},lessons:[{id:"p0-c-l01",courseId:"everyday-core",unitId:"p0-c",sourceLessonId:null,level:"A1",register:"tú",title:"ممكن أفتح؟",context:"باكو قاعد في بيت لونا والجو حر.",goal:"تطلب إذن أو حاجة بسيطة بـ ¿Puedo...? و ¿Me das...?.",targets:[{es:"¿Puedo abrir la ventana?",ar:"ممكن أفتح الشباك؟",speaker:"paco"},{es:"¿Me das un vaso de agua?",ar:"هاتيلي كوباية مية؟",speaker:"paco"},{es:"Claro, abre.",ar:"طبعًا، افتح.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Hace calor aquí.",ar:"الجو حر هنا."},{speaker:"luna",es:"Sí, un poco.",ar:"أيوه، شوية."},{speaker:"paco",es:"¿Puedo abrir la ventana?",ar:"ممكن أفتح الشباك؟"},{speaker:"luna",es:"Claro, abre.",ar:"طبعًا، افتح."},{speaker:"paco",es:"Gracias. ¿Me das un vaso de agua?",ar:"متشكر. هاتيلي كوباية مية؟"},{speaker:"luna",es:"Sí, un momento.",ar:"أيوه، ثانية واحدة."},{speaker:"paco",es:"¡Qué amable!",ar:"كلكي ذوق!"}],questions:[{q:"باكو طلب إذن بإيه؟",options:["يفتح الشباك","يقفل الباب","يشغل المروحة"],answer:"يفتح الشباك",rationale:"سأل: ¿Puedo abrir la ventana? يعني ممكن أفتح الشباك؟"},{q:"«¿Me das un vaso de agua?» معناها إيه؟",options:["عايز تشرب إيه دلوقتي معايا؟","تديني كوباية مية؟","المية ساقعة؟"],answer:"تديني كوباية مية؟",rationale:"¿Me das...? = تديني…؟، و un vaso de agua = كوباية مية."},{q:"لونا وافقت على طلب باكو بإيه؟",options:["Bueno… no sé.","No, está rota.","Claro, abre."],answer:"Claro, abre.",rationale:"ردت: Claro, abre. يعني طبعًا، افتح."}],responseTask:{prompt:"إنت قاعد في بيت صاحبك والجو حر. اطلب إذنه تفتح الشباك بالإسباني.",acceptable:["¿Puedo abrir la ventana?","¿Abro la ventana?","¿Puedo abrir la ventana, por favor?"],modelEs:"¿Puedo abrir la ventana?",modelAr:"ممكن أفتح الشباك؟",checklistAr:"راجع إجابتك: ١) بدأت بـ ¿Puedo، ٢) الفعل abrir في صيغته الأساسية، ٣) السؤال مهذب وواضح. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Puedo + فعل أساسي = ممكن أعمل…؟ أسهل طريقة تطلب بيها إذن: ¿Puedo entrar? ممكن أدخل؟ ولما تطلب حاجة من حد: ¿Me das...? = تديني…؟ ومع por favor الطلب بيبقى أهدى."}},{id:"p0-c-l02",courseId:"everyday-core",unitId:"p0-c",sourceLessonId:null,level:"A1",register:"tú",title:"لو سمحت",context:"لونا بتذاكر وباكو بيساعدها يجيب حاجتها.",goal:"تطلب حاجة بأدب بـ por favor وتشكر حد ساعدك.",targets:[{es:"¿Me traes el libro, por favor?",ar:"هاتلي الكتاب لو سمحت؟",speaker:"luna"},{es:"¿Me pasas el bolígrafo?",ar:"تديني القلم؟",speaker:"luna"},{es:"Gracias, eres un sol.",ar:"متشكرة، أنت جوهرة.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Me traes el libro, por favor?",ar:"هاتلي الكتاب لو سمحت؟"},{speaker:"paco",es:"Sí, ¿el rojo o el azul?",ar:"أيوه، الأحمر ولا الأزرق؟"},{speaker:"luna",es:"El rojo. ¿Me pasas el bolígrafo?",ar:"الأحمر. تديني القلم؟"},{speaker:"paco",es:"Toma.",ar:"اتفضلي."},{speaker:"luna",es:"Gracias, eres un sol.",ar:"متشكرة، أنت جوهرة."},{speaker:"paco",es:"De nada, ¿algo más?",ar:"العفو، حاجة تانية؟"},{speaker:"luna",es:"No, eso es todo.",ar:"لأ، كده كفاية."}],questions:[{q:"لونا طلبت الكتاب بإيه؟",options:["¿Dónde está el libro rojo?","¿Me traes el libro, por favor?","¿Quieres leer el libro conmigo ahora?"],answer:"¿Me traes el libro, por favor?",rationale:"قالت: ¿Me traes el libro, por favor? يعني هاتلي الكتاب لو سمحت."},{q:"«por favor» بتتقال ليه؟",options:["عشان نلغي الطلب خالص","عشان نستعجل تنفيذ الطلب","عشان الطلب يبقى مهذب"],answer:"عشان الطلب يبقى مهذب",rationale:"por favor = لو سمحت، بتتحط في أول الطلب أو آخره."},{q:"لونا وصفت باكو بإيه لما ساعدها؟",options:["أنت جوهرة","أنت بطيء","أنت مشغول"],answer:"أنت جوهرة",rationale:"قالت: Gracias, eres un sol. يعني متشكرة، أنت جوهرة."}],responseTask:{prompt:"إنت في بيت صاحبتك وعايز كوباية مية. اطلبها منها بأدب بالإسباني.",acceptable:["¿Me das un vaso de agua, por favor?","¿Me traes agua, por favor?","Un vaso de agua, por favor."],modelEs:"¿Me das un vaso de agua, por favor?",modelAr:"هاتيلي كوباية مية لو سمحت؟",checklistAr:"راجع إجابتك: ١) استخدمت por favor، ٢) الطلب واضح (كوباية مية)، ٣) النبرة مهذبة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"por favor = لو سمحت، بتتحط في أول الطلب أو آخره وبتحول أي طلب لمهذب. ¿Me traes...? = هاتلي…؟ و ¿Me pasas...? = تناولني…؟ ولما حد يساعدك ممكن تقوله eres un sol يعني أنت جوهرة."}},{id:"p0-c-l03",courseId:"everyday-core",unitId:"p0-c",sourceLessonId:null,level:"A1",register:"tú",title:"عندك شاحن؟",context:"موبايل باكو فصل وهو محتاج شاحن.",goal:"تسأل حد لو عنده حاجة وتطلبها منه.",targets:[{es:"¿Tienes un cargador?",ar:"عندك شاحن؟",speaker:"paco"},{es:"¿Me lo prestas?",ar:"تسلّفيهولي؟",speaker:"paco"},{es:"Te lo devuelvo mañana.",ar:"هرجعهولك بكرة.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Tienes un cargador?",ar:"عندك شاحن؟"},{speaker:"luna",es:"¿De móvil?",ar:"بتاع موبايل؟"},{speaker:"paco",es:"Sí, el mío no funciona.",ar:"أيوه، بتاعي مش شغال."},{speaker:"luna",es:"Sí, tengo uno.",ar:"أيوه، عندي واحد."},{speaker:"paco",es:"¿Me lo prestas?",ar:"تسلّفيهولي؟"},{speaker:"luna",es:"Claro, toma.",ar:"طبعًا، اتفضل."},{speaker:"paco",es:"Gracias. Te lo devuelvo mañana.",ar:"متشكر. هرجعهولك بكرة."}],questions:[{q:"باكو محتاج إيه؟",options:["سماعة ودن","موبايل جديد","شاحن موبايل"],answer:"شاحن موبايل",rationale:"سأل: ¿Tienes un cargador? وقال إن بتاعه مش شغال."},{q:"«¿Me lo prestas?» معناها إيه؟",options:["تسلّفيهولي؟","تبيعهولي؟","تشيله عني؟"],answer:"تسلّفيهولي؟",rationale:"prestar = يسلف، يعني تسلّفيهولي شوية وهرجعه."},{q:"باكو هيعمل إيه بكرة؟",options:["هيشتري شاحن جديد","هيرجع الشاحن للونا","هيصلح الشاحن القديم"],answer:"هيرجع الشاحن للونا",rationale:"قال: Te lo devuelvo mañana. يعني هرجعهولك بكرة."}],responseTask:{prompt:"موبايلك فصل ومحتاج شاحن. اسأل صاحبك لو عنده شاحن بالإسباني.",acceptable:["¿Tienes un cargador?","¿Tienes cargador?","Oye, ¿tienes un cargador?"],modelEs:"¿Tienes un cargador?",modelAr:"عندك شاحن؟",checklistAr:"راجع إجابتك: ١) استخدمت ¿Tienes، ٢) سألت عن الشاحن cargador، ٣) سؤال قصير ومباشر. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Tienes...? = عندك…؟ للسؤال عن أي حاجة. ولما تطلبها: ¿Me lo prestas? = تسلّفيهولي؟ والرد الكويس: Te lo devuelvo mañana = هرجعهولك بكرة."}},{id:"p0-c-l04",courseId:"everyday-core",unitId:"p0-c",sourceLessonId:null,level:"A1–A2",register:"tú",title:"ساعدني",context:"لونا بتنقل كراتين تقيلة في البيت.",goal:"تطلب مساعدة بشكل طبيعي وترد على طلب مساعدة.",targets:[{es:"¿Me echas una mano?",ar:"تديني في إيدي؟",speaker:"luna"},{es:"Es muy pesada.",ar:"دي تقيلة جدًا.",speaker:"luna"},{es:"Cuenta conmigo.",ar:"اعتمدي عليا.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Me echas una mano?",ar:"تديني في إيدي؟"},{speaker:"paco",es:"Claro, ¿con qué?",ar:"طبعًا، في إيه؟"},{speaker:"luna",es:"Con esta caja. Es muy pesada.",ar:"في الكرتونة دي. دي تقيلة جدًا."},{speaker:"paco",es:"Vamos, la subimos juntos.",ar:"يلا، نطلعها سوا."},{speaker:"luna",es:"Gracias, no puedo sola.",ar:"متشكرة، مش هقدر لوحدي."},{speaker:"paco",es:"Cuenta conmigo.",ar:"اعتمدي عليا."}],questions:[{q:"«¿Me echas una mano?» معناها إيه؟",options:["تديني في إيدي وتساعدني؟","تديني فلوس لآخر الشهر؟","تمسك التليفون مكاني لحد ما أرجع؟"],answer:"تديني في إيدي وتساعدني؟",rationale:"echar una mano = يساعد، تعبير شائع جدًا في إسبانيا."},{q:"لونا محتاجة مساعدة في إيه؟",options:["فتح شباك عالق","نقل كرتونة تقيلة","تصليح الموبايل القديم"],answer:"نقل كرتونة تقيلة",rationale:"قالت: Con esta caja. Es muy pesada. يعني في الكرتونة دي، دي تقيلة جدًا."},{q:"«Cuenta conmigo» معناها إيه؟",options:["احسب الفلوس معايا","عدّ عليا بكرة","اعتمدي عليا"],answer:"اعتمدي عليا",rationale:"باكو قالها رد على شكر لونا، يعني اعتمدي عليا في أي وقت."}],responseTask:{prompt:"شنطتك تقيلة ومش هتعرف تشيلها لوحدك. اطلب من صاحبك يساعدك بالإسباني.",acceptable:["¿Me echas una mano?","¿Me ayudas?","¿Me echas una mano con esto?"],modelEs:"¿Me echas una mano?",modelAr:"تديني في إيدي؟",checklistAr:"راجع إجابتك: ١) طلبت مساعدة واضحة، ٢) استخدمت una mano أو ayudas، ٣) النبرة ودية مش أمر. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Me echas una mano? = تديني في إيدي؟ أشهر طريقة يطلب بيها الإسبان المساعدة. ¿Me ayudas? أبسط وأوضح. والرد الجميل: Cuenta conmigo = اعتمدي عليا."}},{id:"p0-c-l05",courseId:"everyday-core",unitId:"p0-c",sourceLessonId:null,level:"A1–A2",register:"tú",title:"استناني",context:"باكو متأخر ولونا مستنياه قدام السينما.",goal:"تطلب من حد يستناك وترد لما تكون متأخر.",targets:[{es:"¿Me esperas cinco minutos?",ar:"تستنيني خمس دقايق؟",speaker:"paco"},{es:"Voy de camino.",ar:"أنا في السكة.",speaker:"paco"},{es:"No tardes mucho.",ar:"متتأخرش كتير.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Luna, ¿dónde estás?",ar:"لونا، إنتي فين؟"},{speaker:"luna",es:"En la puerta del cine.",ar:"قدام باب السينما."},{speaker:"paco",es:"¿Me esperas cinco minutos?",ar:"تستنيني خمس دقايق؟"},{speaker:"luna",es:"Vale, pero la película empieza pronto.",ar:"ماشي، بس الفيلم هيبدأ قريب."},{speaker:"paco",es:"Voy de camino.",ar:"أنا في السكة."},{speaker:"luna",es:"No tardes mucho.",ar:"متتأخرش كتير."},{speaker:"paco",es:"¡Ya llego!",ar:"أنا جاي حالًا!"}],questions:[{q:"باكو طلب من لونا إيه؟",options:["تدخل الفيلم من غيره","تشتري التذاكر لوحدها","تستناه خمس دقايق"],answer:"تستناه خمس دقايق",rationale:"قال: ¿Me esperas cinco minutos? يعني تستنيني خمس دقايق."},{q:"«Voy de camino» معناها إيه؟",options:["أنا في السكة","أنا لسه قاعد في البيت","أنا مش جاي خالص"],answer:"أنا في السكة",rationale:"قالها بعد ما لونا وافقت تستناه، يعني أنا في السكة."},{q:"لونا قلقانة من إيه؟",options:["باكو ينسى التذاكر في البيت","الفيلم يبدأ قبل ما باكو يوصل","السينما تقفل بدري النهارده خالص"],answer:"الفيلم يبدأ قبل ما باكو يوصل",rationale:"قالت: pero la película empieza pronto. يعني الفيلم هيبدأ قريب."}],responseTask:{prompt:"إنت متأخر عن معاد مع صاحبتك. اطلب منها تستناك عشر دقايق بالإسباني.",acceptable:["¿Me esperas diez minutos?","Espérame diez minutos, por favor.","¿Me esperas un poco?"],modelEs:"¿Me esperas diez minutos?",modelAr:"تستنيني عشر دقايق؟",checklistAr:"راجع إجابتك: ١) استخدمت esperas أو espérame، ٢) حددت المدة، ٣) النبرة لطيفة مش أمر. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Me esperas...? = تستناني…؟ و Espérame = استناني. Voy de camino = أنا في السكة، رد سريع لما تكون متأخر. ¡Ya llego! = أنا جاي حالًا!"}},{id:"p0-c-l06",courseId:"everyday-core",unitId:"p0-c",sourceLessonId:null,level:"A1–A2",register:"tú",title:"لو مفيش مشكلة",context:"لونا عايزة باكو يوصلها للمحطة الصبح بدري.",goal:"تطلب طلب كبير بشكل لطيف ومتحفظ.",targets:[{es:"¿Podrías llevarme a la estación mañana?",ar:"تقدر توصلني للمحطة بكرة؟",speaker:"luna"},{es:"Si no te importa.",ar:"لو مفيش مشكلة معاك.",speaker:"luna"},{es:"Te debo una.",ar:"جميلك عليا.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"¿Podrías llevarme a la estación mañana?",ar:"تقدر توصلني للمحطة بكرة؟"},{speaker:"paco",es:"¿A qué hora?",ar:"الساعة كام؟"},{speaker:"luna",es:"Si no te importa. A las siete.",ar:"لو مفيش مشكلة معاك. الساعة سبعة."},{speaker:"paco",es:"Es muy temprano…",ar:"دي بدري جدًا…"},{speaker:"luna",es:"Lo sé, pero el tren sale a las ocho.",ar:"عارفة، بس القطر هيمشي الساعة تمنية."},{speaker:"paco",es:"Bueno, vale. Te llevo.",ar:"امم، ماشي. هوصلك."},{speaker:"luna",es:"¡Gracias! Te debo una.",ar:"متشكرة! جميلك عليا."}],questions:[{q:"«¿Podrías…?» بنستخدمها ليه؟",options:["للأمر المباشر في الشغل","لطلب كبير بشكل لطيف ومتحفظ","للسؤال عن الأسعار في السوق"],answer:"لطلب كبير بشكل لطيف ومتحفظ",rationale:"¿Podrías...? = تقدر…؟ أنعم من ¿Puedes...? وبتسيب مساحة للطرف التاني."},{q:"«si no te importa» معناها إيه؟",options:["لو سمحت يا فندم معلش","لو مش فاضي خالص","لو مفيش مشكلة معاك"],answer:"لو مفيش مشكلة معاك",rationale:"لونا قالت: Si no te importa. A las siete. يعني لو مفيش مشكلة معاك، الساعة سبعة."},{q:"باكو وافق في الآخر؟",options:["أيوه، قال هوصلها","لأ، رفض نهائي","قال يمكن بكرة يعرف"],answer:"أيوه، قال هوصلها",rationale:"قال: Bueno, vale. Te llevo. يعني امم، ماشي، هوصلك."}],responseTask:{prompt:"محتاج صاحبك يوصلك للمطار بدري جدًا. اطلبها منه بشكل لطيف ومتحفظ بالإسباني.",acceptable:["¿Podrías llevarme al aeropuerto?","¿Podrías llevarme al aeropuerto, si no te importa?","¿Me llevas al aeropuerto, por favor?"],modelEs:"¿Podrías llevarme al aeropuerto?",modelAr:"تقدر توصلني للمطار؟",checklistAr:"راجع إجابتك: ١) استخدمت ¿Podrías أو صيغة مهذبة، ٢) الطلب واضح (توصيلة للمطار)، ٣) سيبت مساحة للرفض. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Podrías...? = تقدر…؟ أنعم صيغة لطلب كبير، ألطف من ¿Puedes...? وزود si no te importa لو مفيش مشكلة معاك عشان تسيب مساحة. ولما حد يعملك جميل قوله Te debo una = جميلك عليا."}}]},{courseId:"everyday-core",unit:{id:"p0-d",title:"مش فاهم، ممكن توضح؟",desc:"إزاي تقول إنك مش فاهم وتطلب توضيح من غير إحراج: مش فاهم، عيد تاني، ببطء، يعني إيه، قصدك إيه، أكيد؟",cefr:"A1–A2"},lessons:[{id:"p0-d-l01",courseId:"everyday-core",unitId:"p0-d",sourceLessonId:null,level:"A1",register:"tú",title:"مش فاهم",context:"لونا بتشرح لباكو طريقة لعبة جديدة.",goal:"تقول إنك مش فاهم وتسأل عن معنى كلمة.",targets:[{es:"No entiendo.",ar:"مش فاهم.",speaker:"paco"},{es:"¿Qué significa «robar»?",ar:"يعني إيه «robar»؟",speaker:"paco"},{es:"Ahora sí.",ar:"كده تمام، فهمت.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Primero robas dos cartas.",ar:"أول حاجة تسحب كارتين."},{speaker:"paco",es:"No entiendo.",ar:"مش فاهم."},{speaker:"luna",es:"¿Qué no entiendes?",ar:"أنهي جزء مش واضح؟"},{speaker:"paco",es:"¿Qué significa «robar»?",ar:"يعني إيه «robar»؟"},{speaker:"luna",es:"Tomar una carta del mazo.",ar:"تاخد كارت من الكومة."},{speaker:"paco",es:"Ahora sí.",ar:"كده تمام، فهمت."},{speaker:"luna",es:"¿Jugamos?",ar:"نلعب؟"}],questions:[{q:"باكو قال إيه لما مش فهم؟",options:["No entiendo.","No tengo cartas.","No quiero jugar."],answer:"No entiendo.",rationale:"قال: No entiendo. يعني مش فاهم."},{q:"«robar» في اللعبة معناها إيه؟",options:["تسرق كارت من صاحبك","تاخد كارت من الكومة","ترمي الكروت على الترابيزة"],answer:"تاخد كارت من الكومة",rationale:"لونا شرحت: Tomar una carta del mazo. يعني تاخد كارت من الكومة."},{q:"«¿Qué significa…?» بنستخدمها ليه؟",options:["نقول إننا موافقين","نسأل عن سعر حاجة","نسأل عن معنى كلمة"],answer:"نسأل عن معنى كلمة",rationale:"باكو سأل: ¿Qué significa «robar»? يعني إيه كلمة robar؟"}],responseTask:{prompt:"صاحبك بيتكلم بسرعة وإنت مش فاهم. قوله إنك مش فاهم بالإسباني.",acceptable:["No entiendo.","No entiendo nada.","Perdón, no entiendo."],modelEs:"No entiendo.",modelAr:"مش فاهم.",checklistAr:"راجع إجابتك: ١) قولت No entiendo، ٢) الجملة قصيرة وواضحة، ٣) ممكن تزود Perdón في الأول للأدب. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"No entiendo = مش فاهم، جملة عادية جدًا ومش عيب تقولها. عشان تسأل عن معنى كلمة: ¿Qué significa...? = يعني إيه…؟ ولما تفهم في الآخر قول: Ahora sí = كده تمام، فهمت."}},{id:"p0-d-l02",courseId:"everyday-core",unitId:"p0-d",sourceLessonId:null,level:"A1",register:"tú",title:"عيدها تاني",context:"لونا بتقول لباكو عنوان بيتها بسرعة في التليفون.",goal:"تطلب من حد يعيد الكلام أو يتكلم ببطء.",targets:[{es:"¿Puedes repetir, por favor?",ar:"ممكن تعيدي تاني لو سمحت؟",speaker:"paco"},{es:"Más despacio, por favor.",ar:"ببطء أكتر لو سمحت.",speaker:"paco"},{es:"Una vez más.",ar:"مرة كمان.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Mi calle es Doctor Márquez, número diecisiete.",ar:"شارعي دكتور ماركيز، رقم سبعتاشر."},{speaker:"paco",es:"¿Puedes repetir, por favor?",ar:"ممكن تعيدي تاني لو سمحت؟"},{speaker:"luna",es:"Doctor Márquez, diecisiete.",ar:"دكتور ماركيز، سبعتاشر."},{speaker:"paco",es:"Más despacio, por favor.",ar:"ببطء أكتر لو سمحت."},{speaker:"luna",es:"Doc-tor Már-quez. Die-ci-sie-te.",ar:"دوك-تور مار-كيز. سبع-تا-شر."},{speaker:"paco",es:"Una vez más.",ar:"مرة كمان."},{speaker:"luna",es:"¡Perfecto, lo tienes!",ar:"برافو كده!"}],questions:[{q:"باكو طلب من لونا تعيد العنوان بإيه؟",options:["¿Dónde vives tú exactamente?","¿Puedes repetir, por favor?","¿Hablas inglés también?"],answer:"¿Puedes repetir, por favor?",rationale:"قال: ¿Puedes repetir, por favor? يعني ممكن تعيدي تاني لو سمحت."},{q:"«Más despacio» معناها إيه؟",options:["بسرعة أكتر","بصوت أعلى","ببطء أكتر"],answer:"ببطء أكتر",rationale:"قال: Más despacio, por favor. عشان لونا بتتكلم بسرعة."},{q:"«Una vez más» معناها إيه؟",options:["مرة كمان","مرة واحدة بس","خلاص كفاية"],answer:"مرة كمان",rationale:"باكو عايز يسمع العنوان مرة تانية، فقال: Una vez más."}],responseTask:{prompt:"صاحبتك قالت جملة بسرعة وإنت مسامعتهاش. اطلب منها تعيدها ببطء بالإسباني.",acceptable:["¿Puedes repetir, por favor?","Más despacio, por favor.","Repite, por favor."],modelEs:"Más despacio, por favor.",modelAr:"ببطء أكتر لو سمحت.",checklistAr:"راجع إجابتك: ١) طلبت إعادة أو تبطئة، ٢) استخدمت por favor، ٣) النبرة مهذبة مش متضايقة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Puedes repetir? = ممكن تعيد؟ و Más despacio = ببطء أكتر. الاتنين مع por favor بيبقوا مهذبين جدًا. Una vez más = مرة كمان لما تحتاج تسمعها تالت."}},{id:"p0-d-l03",courseId:"everyday-core",unitId:"p0-d",sourceLessonId:null,level:"A1",register:"tú",title:"إيه؟",context:"باكو بيحكي للونا خبر غريب.",goal:"ترد باستغراب وتطلب توضيح لما الكلام مش مفهوم.",targets:[{es:"¿Cómo?",ar:"إيه؟ إزاي؟",speaker:"luna"},{es:"¿Qué quieres decir?",ar:"تقصد إيه؟",speaker:"luna"},{es:"¡No me digas!",ar:"معقولة!",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Gané un viaje a París.",ar:"كسبت رحلة لباريس."},{speaker:"luna",es:"¿Cómo?",ar:"إيه؟ إزاي؟"},{speaker:"paco",es:"En un concurso de la radio.",ar:"في مسابقة في الراديو."},{speaker:"luna",es:"¿Qué quieres decir?",ar:"تقصد إيه؟"},{speaker:"paco",es:"Llamé y respondí bien.",ar:"كلمتهم وجاوبت صح."},{speaker:"luna",es:"¡No me digas!",ar:"معقولة!"},{speaker:"paco",es:"Sí, en serio.",ar:"أيوه، بجد."}],questions:[{q:"باكو كسب إيه؟",options:["موبايل حديث","عربية جديدة","رحلة لباريس"],answer:"رحلة لباريس",rationale:"قال: Gané un viaje a París. يعني كسبت رحلة لباريس."},{q:"«¿Qué quieres decir?» معناها إيه؟",options:["تقصد إيه؟","عايز تروح فين؟","بتحكي عن إيه؟"],answer:"تقصد إيه؟",rationale:"لونا سألتها عشان تفهم أكتر: ¿Qué quieres decir?"},{q:"«¡No me digas!» بتعبر عن إيه؟",options:["رفض قاطع للكلام","استغراب ودهشة","طلب سكوت فوري"],answer:"استغراب ودهشة",rationale:"قالتها لونا لما فهمت الخبر، يعني معقولة! مش مصدقة."}],responseTask:{prompt:"صاحبتك قالتلك خبر مش مصدقاه. رد باستغراب واسألها تقصد إيه بالإسباني.",acceptable:["¿Qué quieres decir?","¿Cómo? ¿Qué quieres decir?","¡No me digas! ¿En serio?"],modelEs:"¿Qué quieres decir?",modelAr:"تقصد إيه؟",checklistAr:"راجع إجابتك: ١) عبرت عن استغراب، ٢) سألت عن القصد، ٣) النبرة ودية مش متشككة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Cómo? = إيه؟ إزاي؟ رد سريع لما الكلام يستغرب. ¿Qué quieres decir? = تقصد إيه؟ لما محتاج توضيح أكتر. ¡No me digas! = معقولة! بتتقال لما الخبر يفاجئك."}},{id:"p0-d-l04",courseId:"everyday-core",unitId:"p0-d",sourceLessonId:null,level:"A1",register:"tú",title:"بتتقال إزاي؟",context:"لونا بتساعد باكو يكتب رسالة بالإسباني.",goal:"تسأل إزاي بتتقال أو بتتكتب كلمة بالإسباني.",targets:[{es:"¿Cómo se dice «شمس» en español?",ar:"«شمس» بتتقال إزاي بالإسباني؟",speaker:"paco"},{es:"¿Cómo se escribe?",ar:"بتتكتب إزاي؟",speaker:"paco"},{es:"¿Con ese o con ele?",ar:"بحرف الـ s ولا الـ l؟",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Cómo se dice «شمس» en español?",ar:"«شمس» بتتقال إزاي بالإسباني؟"},{speaker:"luna",es:"Sol.",ar:"Sol."},{speaker:"paco",es:"¿Cómo se escribe?",ar:"بتتكتب إزاي؟"},{speaker:"luna",es:"Ese, o, ele.",ar:"s و o و l."},{speaker:"paco",es:"¿Con ese o con ele?",ar:"بحرف الـ s ولا الـ l؟"},{speaker:"luna",es:"Con las dos: ese-o-ele.",ar:"بالتنين: s-o-l."},{speaker:"paco",es:"¡Fácil!",ar:"سهلة!"}],questions:[{q:"«شمس» بالإسباني إيه؟",options:["Sol","Luna","Mar"],answer:"Sol",rationale:"لونا قالت: Sol. يعني شمس."},{q:"«¿Cómo se escribe?» معناها إيه؟",options:["بتتنطق إزاي؟","بتتكتب إزاي؟","معناها إيه؟"],answer:"بتتكتب إزاي؟",rationale:"باكو سألها بعد ما عرف الكلمة: ¿Cómo se escribe?"},{q:"«sol» بتتكتب بحروف إيه؟",options:["ele-u-ene","ese-o-te","ese-o-ele"],answer:"ese-o-ele",rationale:"لونا قالت: Con las dos: ese-o-ele. يعني s-o-l."}],responseTask:{prompt:"عايز تعرف «قمر» بتتقال إزاي بالإسباني. اسأل صاحبتك بالإسباني.",acceptable:["¿Cómo se dice «قمر» en español?","¿Cómo se dice قمر?","¿Qué significa luna?"],modelEs:"¿Cómo se dice «قمر» en español?",modelAr:"«قمر» بتتقال إزاي بالإسباني؟",checklistAr:"راجع إجابتك: ١) استخدمت ¿Cómo se dice، ٢) حطيت الكلمة المطلوبة، ٣) قفلت بـ en español أو وضحت القصد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Cómo se dice...? = بتتقال إزاي…؟ و ¿Cómo se escribe? = بتتكتب إزاي؟ أهم سؤالين لأي حد بيتعلم لغة. أسماء الحروف بالإسباني: ese = s، ele = l، ene = n."}},{id:"p0-d-l05",courseId:"everyday-core",unitId:"p0-d",sourceLessonId:null,level:"A1–A2",register:"tú",title:"قصدك إيه؟",context:"لونا بتقول لباكو «المكان اللي جنب البيت» وهو مش متأكد تقصد أنهي واحد.",goal:"تتأكد إنك فاهم قصد اللي قدامك.",targets:[{es:"¿Te refieres al parque?",ar:"قصدك على الجنينة؟",speaker:"paco"},{es:"O sea, ¿el de la esquina?",ar:"يعني اللي على الناصية؟",speaker:"paco"},{es:"Eso es.",ar:"هو ده بالظبط.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Vamos al lugar junto a mi casa.",ar:"هنروح المكان اللي جنب بيتي."},{speaker:"paco",es:"¿Te refieres al parque?",ar:"قصدك على الجنينة؟"},{speaker:"luna",es:"No, al café.",ar:"لأ، على القهوة."},{speaker:"paco",es:"O sea, ¿el de la esquina?",ar:"يعني اللي على الناصية؟"},{speaker:"luna",es:"Eso es.",ar:"هو ده بالظبط."},{speaker:"paco",es:"Ah, ya lo sé.",ar:"آه، عرفته."}],questions:[{q:"«¿Te refieres a…?» معناها إيه؟",options:["بتحلم بـ…؟","بتفتكر…؟","قصدك على…؟"],answer:"قصدك على…؟",rationale:"باكو سأل: ¿Te refieres al parque? عشان يتأكد من قصد لونا."},{q:"لونا كانت قصدها على إيه؟",options:["القهوة اللي على الناصية","الجنينة جنب البيت","بيت صاحبتهم القديم اللي في وسط البلد"],answer:"القهوة اللي على الناصية",rationale:"قالت: No, al café. وأكدت على سؤاله: Eso es."},{q:"«o sea» معناها إيه؟",options:["لكن","يعني","عشان"],answer:"يعني",rationale:"باكو قال: O sea, ¿el de la esquina? يعني بيوضح فهمه للكلام."}],responseTask:{prompt:"صاحبك قال «المكان المعتاد» وإنت مش متأكد يقصد أنهي واحد. اتأكد من قصده بالإسباني.",acceptable:["¿Te refieres al café de siempre?","O sea, ¿el de la esquina?","¿Cuál exactamente?"],modelEs:"¿Te refieres al café de siempre?",modelAr:"قصدك على القهوة المعتادة؟",checklistAr:"راجع إجابتك: ١) استخدمت ¿Te refieres a أو o sea، ٢) سميت المكان اللي فاهمه، ٣) سؤال قصير للتأكيد مش للشك. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Te refieres a...? = قصدك على…؟ أدق سؤال للتأكد من الفهم. o sea = يعني، بتفتح بيها جملة توضيح. ولما تلاقي القصد صح قول: Eso es. = هو ده بالظبط."}},{id:"p0-d-l06",courseId:"everyday-core",unitId:"p0-d",sourceLessonId:null,level:"A1–A2",register:"tú",title:"أكيد؟",context:"باكو بيقول للونا إن المحل هيقفل بدري النهارده.",goal:"تتأكد من معلومة قبل ما تتصرف على أساسها.",targets:[{es:"¿Seguro?",ar:"متأكد؟",speaker:"luna"},{es:"¿En serio?",ar:"بجد؟",speaker:"luna"},{es:"Lo vi en la puerta.",ar:"شفتها على الباب.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"La tienda cierra a las dos hoy.",ar:"المحل هيقفل الساعة اتنين النهارده."},{speaker:"luna",es:"¿Seguro?",ar:"متأكد؟"},{speaker:"paco",es:"Sí. Lo vi en la puerta.",ar:"أيوه. شفتها على الباب."},{speaker:"luna",es:"¿En serio?",ar:"بجد؟"},{speaker:"paco",es:"Sí, hay un cartel.",ar:"أيوه، في لافتة."},{speaker:"luna",es:"Entonces vamos ahora.",ar:"يبقى نروح دلوقتي."},{speaker:"paco",es:"Sí, corre.",ar:"أيوه، يلا بسرعة."}],questions:[{q:"«¿Seguro?» بنقولها ليه؟",options:["نوافق على اقتراح","نتأكد من معلومة","نعتذر عن غلطة"],answer:"نتأكد من معلومة",rationale:"لونا سألت: ¿Seguro? عشان تتأكد إن المحل فعلًا هيقفل بدري."},{q:"باكو عرف المعلومة منين؟",options:["من رسالة وصلته على الموبايل","من خبر في التلفزيون","من لافتة على باب المحل"],answer:"من لافتة على باب المحل",rationale:"قال: Lo vi en la puerta. و Sí, hay un cartel. يعني شاف لافتة على الباب."},{q:"لونا قررت تعمل إيه؟",options:["تروح المحل دلوقتي","تستنى لبكرة الصبح","تكلم صاحب المحل أولًا"],answer:"تروح المحل دلوقتي",rationale:"قالت: Entonces vamos ahora. يعني يبقى نروح دلوقتي."}],responseTask:{prompt:"صاحبتك قالتلك إن الفصل اتلغى النهارده. اتأكد منها بالإسباني.",acceptable:["¿Segura?","¿En serio?","¿Segura? ¿En serio?"],modelEs:"¿Segura?",modelAr:"متأكدة؟",checklistAr:"راجع إجابتك: ١) استخدمت ¿Seguro/¿Segura أو ¿En serio، ٢) الصيغة مناسبة للمخاطب، ٣) سؤال قصير للتأكد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Seguro? = متأكد؟ للراجل و ¿Segura? = متأكدة؟ للست. ¿En serio? = بجد؟ أعم وتنفع مع الاتنين. ولو انت اللي متأكد قول: Lo vi = شفتها، أو Lo sé = أنا عارف."}}]},{courseId:"everyday-core",unit:{id:"p0-e",title:"الرفض اللطيف",desc:"إزاي تقول لأ من غير ما تجرح حد: مش هقدر، المرة الجاية، مش فاضي، شكرًا بس لأ، مش بحب، بجد لأ.",cefr:"A1–A2"},lessons:[{id:"p0-e-l01",courseId:"everyday-core",unitId:"p0-e",sourceLessonId:null,level:"A1",register:"tú",title:"مش هقدر",context:"باكو عازم لونا على الكورة بس عندها شغل.",goal:"تعتذر عن دعوة بلطف وتقول السبب.",targets:[{es:"Lo siento, no puedo.",ar:"آسفة، مش هقدر.",speaker:"luna"},{es:"Tengo mucho trabajo.",ar:"عندي شغل كتير.",speaker:"luna"},{es:"Qué pena.",ar:"يا خسارة.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Vienes al fútbol el sábado?",ar:"هتيجي الكورة يوم السبت؟"},{speaker:"luna",es:"Lo siento, no puedo.",ar:"آسفة، مش هقدر."},{speaker:"paco",es:"¿Por qué no?",ar:"ليه كده؟"},{speaker:"luna",es:"Tengo mucho trabajo.",ar:"عندي شغل كتير."},{speaker:"paco",es:"Qué pena.",ar:"يا خسارة."},{speaker:"luna",es:"Disfrutad mucho.",ar:"استمتعوا قوي."},{speaker:"paco",es:"Gracias, Luna.",ar:"متشكر يا لونا."}],questions:[{q:"لونا ردت على الدعوة بإيه؟",options:["Lo siento, no puedo.","Sí, claro que voy.","No me gusta el fútbol."],answer:"Lo siento, no puedo.",rationale:"قالت: Lo siento, no puedo. يعني آسفة، مش هقدر."},{q:"ليه لونا مش هتروح؟",options:["عندها امتحان بكرة","عندها شغل كتير","مسافرة لبلد تانية"],answer:"عندها شغل كتير",rationale:"قالت: Tengo mucho trabajo. يعني عندي شغل كتير."},{q:"«Qué pena» معناها إيه؟",options:["مع السلامة","مبروك","يا خسارة"],answer:"يا خسارة",rationale:"باكو قالها لما عرف إن لونا مش جاية، يعني يا خسارة."}],responseTask:{prompt:"صاحبك عازمك على الخروج وإنت مشغول. اعتذر وارفض بلطف بالإسباني.",acceptable:["Lo siento, no puedo.","Lo siento, tengo trabajo.","No puedo, lo siento."],modelEs:"Lo siento, no puedo.",modelAr:"آسف، مش هقدر.",checklistAr:"راجع إجابتك: ١) اعتذرت بـ lo siento، ٢) الرفض واضح (no puedo)، ٣) النبرة لطيفة مش جافة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Lo siento = آسف، وبعدها no puedo = مش هقدر. الرفض مع اعتذار بيبقى لطيف. Qué pena = يا خسارة، بنقولها لما حد يعتذر عننا."}},{id:"p0-e-l02",courseId:"everyday-core",unitId:"p0-e",sourceLessonId:null,level:"A1–A2",register:"tú",title:"المرة الجاية",context:"لونا عازمة باكو على العشا في بيتها وهو مرتبط.",goal:"ترفض دعوة وتسيب الباب مفتوح للمرة الجاية.",targets:[{es:"Me encantaría, pero no puedo.",ar:"والله نفسي، بس مش هقدر.",speaker:"paco"},{es:"No pasa nada.",ar:"ولا يهمك.",speaker:"luna"},{es:"La próxima vez, seguro.",ar:"المرة الجاية، أكيد.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Vienes a cenar mañana?",ar:"هتيجي تتعشى معانا بكرة؟"},{speaker:"paco",es:"Me encantaría, pero no puedo.",ar:"والله نفسي، بس مش هقدر."},{speaker:"luna",es:"¿Estás ocupado?",ar:"مرتبط بحاجة؟"},{speaker:"paco",es:"Sí, ceno con mi hermano.",ar:"أيوه، هتعشى مع أخويا."},{speaker:"luna",es:"No pasa nada.",ar:"ولا يهمك."},{speaker:"paco",es:"La próxima vez, seguro.",ar:"المرة الجاية، أكيد."},{speaker:"luna",es:"Vale, te aviso.",ar:"ماشي، هبلغك."}],questions:[{q:"«Me encantaría, pero…» بتفيد إيه؟",options:["موافقة كاملة من غير تردد","رفض لطيف مع رغبة حقيقية","طلب تغيير مكان الدعوة"],answer:"رفض لطيف مع رغبة حقيقية",rationale:"يعني نفسي أروح بس مش هقدر: Me encantaría, pero no puedo."},{q:"باكو مش هيروح العشا ليه؟",options:["تعبان ومش قادر","مسافر للشغل بكرة","هيتعشى مع أخوه"],answer:"هيتعشى مع أخوه",rationale:"قال: Sí, ceno con mi hermano. يعني أيوه، هتعشى مع أخويا."},{q:"«No pasa nada» معناها إيه؟",options:["ولا يهمك","مفيش حاجة خالص","متعملش كده تاني"],answer:"ولا يهمك",rationale:"لونا قالتها عشان تطمن باكو بعد اعتذاره، يعني ولا يهمك."}],responseTask:{prompt:"صاحبتك عازماك على القهوة وإنت مرتبط. ارفض بلطف واقترح المرة الجاية بالإسباني.",acceptable:["Me encantaría, pero no puedo. La próxima vez.","No puedo hoy, la próxima vez seguro.","Lo siento, estoy ocupado. La próxima vez."],modelEs:"Me encantaría, pero no puedo. La próxima vez.",modelAr:"والله نفسي، بس مش هقدر. المرة الجاية.",checklistAr:"راجع إجابتك: ١) وضحت إنك نفسك (me encantaría)، ٢) الرفض مهذب، ٣) اقترحت المرة الجاية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Me encantaría = والله نفسي، ألطف بداية لرفض دعوة. La próxima vez = المرة الجاية، بتسيب الباب مفتوح. No pasa nada = ولا يهمك، بتطمن اللي بيعتذر."}},{id:"p0-e-l03",courseId:"everyday-core",unitId:"p0-e",sourceLessonId:null,level:"A1–A2",register:"tú",title:"مش فاضي دلوقتي",context:"باكو عايز لونا تساعده في ترجمة وهي وراها معاد دكتور.",goal:"ترفض دلوقتي وتقدم وقت بديل.",targets:[{es:"Ahora no puedo, lo siento.",ar:"دلوقتي مش هقدر، آسفة.",speaker:"luna"},{es:"Tengo una cita con el médico.",ar:"عندي معاد دكتور.",speaker:"luna"},{es:"Esta tarde sí.",ar:"العصر أقدر.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Me ayudas con la traducción?",ar:"تساعديني في الترجمة؟"},{speaker:"luna",es:"Ahora no puedo, lo siento.",ar:"دلوقتي مش هقدر، آسفة."},{speaker:"paco",es:"¿Estás ocupada?",ar:"مشغولة؟"},{speaker:"luna",es:"Sí. Tengo una cita con el médico.",ar:"أيوه. عندي معاد دكتور."},{speaker:"paco",es:"Ah, vale. ¿Y esta tarde?",ar:"آه ماشي. والعصر؟"},{speaker:"luna",es:"Esta tarde sí.",ar:"العصر أقدر."},{speaker:"paco",es:"¡Genial! Gracias.",ar:"برافو! متشكر."}],questions:[{q:"لونا مش فاضية دلوقتي ليه؟",options:["رايحة تتمرن في الجيم","عندها شغل في البيت","عندها معاد دكتور"],answer:"عندها معاد دكتور",rationale:"قالت: Sí. Tengo una cita con el médico. يعني أيوه، عندي معاد دكتور."},{q:"«¿Estás ocupada?» معناها إيه؟",options:["مشغولة؟","جوعانة؟","زعلانة؟"],answer:"مشغولة؟",rationale:"ocupada = مشغولة للست، و ocupado = مشغول للراجل."},{q:"لونا هتقدر تساعد امتى؟",options:["الصبح بدري","العصر","الأسبوع الجاي"],answer:"العصر",rationale:"قالت: Esta tarde sí. يعني العصر أقدر."}],responseTask:{prompt:"صاحبك طلب منك خدمة وإنت مش فاضي دلوقتي بس فاضي بكرة. رد عليه بالإسباني.",acceptable:["Ahora no puedo, lo siento. Mañana sí.","Ahora estoy ocupado, mañana puedo.","Lo siento, ahora no. Mañana sí."],modelEs:"Ahora no puedo, lo siento. Mañana sí.",modelAr:"دلوقتي مش هقدر، آسف. بكرة أقدر.",checklistAr:"راجع إجابتك: ١) الرفض دلوقتي واضح، ٢) فيه اعتذار لطيف، ٣) قدمت وقت بديل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Ahora no = دلوقتي لأ، والبديل هو اللي بيحلي الرفض: Mañana sí = بكرة أقدر. ocupado للراجل و ocupada للست: مشغول / مشغولة."}},{id:"p0-e-l04",courseId:"everyday-core",unitId:"p0-e",sourceLessonId:null,level:"A1–A2",register:"tú",title:"شكرًا بس لأ",context:"لونا بتقدم لباكو أكل زيادة في بيتها.",goal:"تشكر وترفض عرض أكل أو حاجة من غير ما تكسف اللي قدامك.",targets:[{es:"Gracias, pero no.",ar:"متشكر، بس لأ.",speaker:"paco"},{es:"Estoy lleno.",ar:"أنا شبعان.",speaker:"paco"},{es:"No, de verdad.",ar:"لأ بجد.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Quieres más pastel?",ar:"عايز كيك تاني؟"},{speaker:"paco",es:"Gracias, pero no. Estoy lleno.",ar:"متشكر، بس لأ. أنا شبعان."},{speaker:"luna",es:"¿Un poco de fruta?",ar:"شوية فاكهة؟"},{speaker:"paco",es:"No, de verdad. Muchas gracias.",ar:"لأ بجد. متشكر جدًا."},{speaker:"luna",es:"¿Y un café?",ar:"وقهوة؟"},{speaker:"paco",es:"Un café sí, gracias.",ar:"القهوة أيوه، متشكر."},{speaker:"luna",es:"¡Ahora mismo!",ar:"حالًا!"}],questions:[{q:"باكو رفض الكيك بإيه؟",options:["Gracias, pero no.","¡Qué asco!","No me gusta nada."],answer:"Gracias, pero no.",rationale:"قال: Gracias, pero no. Estoy lleno. يعني متشكر، بس لأ، أنا شبعان."},{q:"باكو قبل إيه في الآخر؟",options:["الكيك","القهوة","الفاكهة"],answer:"القهوة",rationale:"قال: Un café sí, gracias. يعني القهوة أيوه، متشكر."},{q:"ليه باكو رفض الأكل الزيادة؟",options:["عشانه مستعجل جدًا","عشانه مش بيحب الكيك","عشانه شبعان"],answer:"عشانه شبعان",rationale:"قال: Estoy lleno. يعني أنا شبعان."}],responseTask:{prompt:"صاحبتك بتقدملك أكل زيادة وإنت شبعان. اشكرها وارفض بلطف بالإسباني.",acceptable:["Gracias, pero no. Estoy lleno.","No, gracias. Estoy lleno.","Gracias, pero estoy lleno."],modelEs:"Gracias, pero no. Estoy lleno.",modelAr:"متشكر، بس لأ. أنا شبعان.",checklistAr:"راجع إجابتك: ١) شكرت الأول، ٢) الرفض مهذب (pero no)، ٣) وضحت السبب. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Gracias, pero no = متشكر، بس لأ: الشكر قبل الرفض بيخففها. Estoy lleno = أنا شبعان (للراجل، وللست llena). de verdad = بجد، بتوكد الكلام."}},{id:"p0-e-l05",courseId:"everyday-core",unitId:"p0-e",sourceLessonId:null,level:"A1",register:"tú",title:"مش بحب",context:"باكو ولونا في مطعم وباكو مش بياكل سمك.",goal:"تقول إنك مش بتحب حاجة من غير ما تكون وقح.",targets:[{es:"No me gusta el pescado.",ar:"مش بحب السمك.",speaker:"paco"},{es:"Ni el salmón.",ar:"ولا السلمون.",speaker:"paco"},{es:"El pollo, como siempre.",ar:"الفراخ، زي كل مرة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Pides el pescado?",ar:"هتطلب السمك؟"},{speaker:"paco",es:"No. No me gusta el pescado.",ar:"لأ. مش بحب السمك."},{speaker:"luna",es:"¿En serio? ¿Ni el salmón?",ar:"بجد؟ ولا السلمون؟"},{speaker:"paco",es:"Ni el salmón.",ar:"ولا السلمون."},{speaker:"luna",es:"¿Qué pides entonces?",ar:"هتطلب إيه يبقى؟"},{speaker:"paco",es:"El pollo, como siempre.",ar:"الفراخ، زي كل مرة."},{speaker:"luna",es:"¡Eres aburrido!",ar:"إنت ممل!"}],questions:[{q:"باكو مش بياكل إيه؟",options:["السلطة","الفراخ","السمك"],answer:"السمك",rationale:"قال: No. No me gusta el pescado. يعني لأ، مش بحب السمك."},{q:"«ni» معناها إيه؟",options:["ولا","برضه","بس"],answer:"ولا",rationale:"قال: Ni el salmón. يعني ولا السلمون."},{q:"باكو هيطلب إيه؟",options:["السمك","الفراخ","المكرونة"],answer:"الفراخ",rationale:"قال: El pollo, como siempre. يعني الفراخ، زي كل مرة."}],responseTask:{prompt:"صاحبك بيعرض عليك لحم وإنت مش بتاكله. قوله إنك مش بتحبه بالإسباني.",acceptable:["No me gusta la carne.","No como carne.","No me gusta, gracias."],modelEs:"No me gusta la carne.",modelAr:"مش بحب اللحم.",checklistAr:"راجع إجابتك: ١) استخدمت no me gusta، ٢) سميت الحاجة، ٣) النبرة عادية مش حادة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"No me gusta... = مش بحب… طريقة عادية ومش وقحة. ni = ولا في النفي: Ni el salmón = ولا السلمون. como siempre = زي كل مرة."}},{id:"p0-e-l06",courseId:"everyday-core",unitId:"p0-e",sourceLessonId:null,level:"A1–A2",register:"tú",title:"بجد، لأ",context:"لونا بتحاول تقنع باكو يروح حفلة وهو تعبان.",goal:"ترفض بشكل مؤكد ولطيف لما حد يصر.",targets:[{es:"De verdad, no.",ar:"بجد، لأ.",speaker:"paco"},{es:"Mañana trabajo.",ar:"بكرة عندي شغل.",speaker:"paco"},{es:"Segurísimo. Otro día.",ar:"متأكد جدًا. يوم تاني.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¡Vamos a la fiesta!",ar:"يلا نروح الحفلة!"},{speaker:"paco",es:"No, gracias. Estoy cansado.",ar:"لأ متشكر. أنا تعبان."},{speaker:"luna",es:"¡Pero solo una hora!",ar:"ساعة واحدة بس!"},{speaker:"paco",es:"De verdad, no. Mañana trabajo.",ar:"بجد، لأ. بكرة عندي شغل."},{speaker:"luna",es:"¿Seguro que no?",ar:"متأكد؟"},{speaker:"paco",es:"Segurísimo. Otro día.",ar:"متأكد جدًا. يوم تاني."},{speaker:"luna",es:"Vale, descansa.",ar:"ماشي، ارتاح."}],questions:[{q:"لونا أصرت على باكو بعد أول رفض؟",options:["لأ، سكتت فورًا","أيوه، مرتين","أيوه، خمس مرات"],answer:"أيوه، مرتين",rationale:"بعد رفضه قالت: ¡Pero solo una hora! وبعدين سألت: ¿Seguro que no?"},{q:"«De verdad, no» بتفيد إيه؟",options:["طلب مهلة للتفكير","موافقة متحمسة جدًا","رفض مؤكد بس مهذب"],answer:"رفض مؤكد بس مهذب",rationale:"باكو قالها بعد إصرار لونا، يعني بجد، لأ، والقرار نهائي."},{q:"باكو اقترح إيه في الآخر؟",options:["يوم تاني","ساعة واحدة بس","حفلة في بيته"],answer:"يوم تاني",rationale:"قال: Segurísimo. Otro día. يعني متأكد جدًا، يوم تاني."}],responseTask:{prompt:"صاحبتك بتصر تطلع معاها وإنت تعبان فعلًا. ارفض بشكل مؤكد ولطيف واقترح يوم تاني بالإسباني.",acceptable:["De verdad, no. Otro día.","No, lo siento. Estoy cansado. Otro día.","No puedo, de verdad. Otro día seguro."],modelEs:"De verdad, no. Otro día.",modelAr:"بجد، لأ. يوم تاني.",checklistAr:"راجع إجابتك: ١) الرفض مؤكد (de verdad)، ٢) السبب واضح، ٣) اقترحت بديل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"لما حد يصر، كرر الرفض مع de verdad = بجد وضيف سبب وبديل: Otro día = يوم تاني. ¿Seguro que no? = متأكد؟ و Segurísimo = متأكد جدًا."}}]},{courseId:"everyday-core",unit:{id:"p0-f",title:"الخطط والمشاكل اليومية",desc:"نعمل إيه بكرة؟ هنتقابل فين؟ الخطة اتغيرت، حاجة بوظت، مفتاحي ضاع — وإمتى tú وإمتى usted.",cefr:"A1–A2"},lessons:[{id:"p0-f-l01",courseId:"everyday-core",unitId:"p0-f",sourceLessonId:null,level:"A1",register:"tú",title:"نعمل إيه بكرة؟",context:"باكو ولونا بيخططوا للويك إند.",goal:"تقترح خطة وترد على اقتراح.",targets:[{es:"¿Qué hacemos mañana?",ar:"نعمل إيه بكرة؟",speaker:"paco"},{es:"¿Vamos a la playa?",ar:"نروح البحر؟",speaker:"luna"},{es:"Me apunto.",ar:"أنا معاكم.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Qué hacemos mañana?",ar:"نعمل إيه بكرة؟"},{speaker:"luna",es:"¿Vamos a la playa?",ar:"نروح البحر؟"},{speaker:"paco",es:"Buena idea. ¿Quién más va?",ar:"فكرة حلوة. مين كمان رايح؟"},{speaker:"luna",es:"Ana y su hermano.",ar:"آنا وأخوها."},{speaker:"paco",es:"Me apunto.",ar:"أنا معاكم."},{speaker:"luna",es:"¡Perfecto!",ar:"برافو!"}],questions:[{q:"لونا اقترحت إيه؟",options:["نروح البحر","نروح السينما","نقعد في البيت"],answer:"نروح البحر",rationale:"قالت: ¿Vamos a la playa? يعني نروح البحر؟"},{q:"«Me apunto» معناها إيه؟",options:["مش جاي معاكم","أنا معاكم","هفكر وأقولكم"],answer:"أنا معاكم",rationale:"باكو قالها بعد ما سمع الخطة، يعني أنا معاكم."},{q:"مين رايح البحر معاهم؟",options:["أخو باكو","آنا وصاحبتها","آنا وأخوها"],answer:"آنا وأخوها",rationale:"قالت لونا: Ana y su hermano. يعني آنا وأخوها."}],responseTask:{prompt:"اقترح على صاحبك تروحوا السينما بكرة بالإسباني.",acceptable:["¿Vamos al cine mañana?","¿Qué hacemos mañana? ¿Vamos al cine?","Vamos al cine mañana."],modelEs:"¿Vamos al cine mañana?",modelAr:"نروح السينما بكرة؟",checklistAr:"راجع إجابتك: ١) استخدمت vamos a، ٢) حددت المكان والوقت، ٣) صيغة اقتراح بعلامة سؤال. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"¿Vamos a...? = نروح…؟ أشهر طريقة لاقتراح خطة. ¿Qué hacemos? = نعمل إيه؟ و Me apunto = أنا معاكم، رد سريع للموافقة على خطة."}},{id:"p0-f-l02",courseId:"everyday-core",unitId:"p0-f",sourceLessonId:null,level:"A1",register:"tú",title:"هنتقابل فين؟",context:"باكو ولونا بيظبطوا مكان ومعاد المقابلة.",goal:"تتفق على مكان ومعاد بـ quedar.",targets:[{es:"¿Dónde quedamos?",ar:"هنتقابل فين؟",speaker:"luna"},{es:"En la entrada.",ar:"عند المدخل.",speaker:"luna"},{es:"Quedamos a las cinco.",ar:"هنتقابل الساعة خمسة.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"¿Dónde quedamos?",ar:"هنتقابل فين؟"},{speaker:"paco",es:"¿En la plaza?",ar:"في الميدان؟"},{speaker:"luna",es:"En la entrada.",ar:"عند المدخل."},{speaker:"paco",es:"Vale. ¿A qué hora?",ar:"ماشي. الساعة كام؟"},{speaker:"luna",es:"¿A las cinco?",ar:"الساعة خمسة؟"},{speaker:"paco",es:"Quedamos a las cinco.",ar:"هنتقابل الساعة خمسة."},{speaker:"luna",es:"¡Nos vemos!",ar:"أشوفك!"}],questions:[{q:"«quedar» في الكلام ده معناها إيه؟",options:["يقعدوا في البيت لوحدهم","يتقابلوا في مكان ومعاد","يتكلموا في التليفون بس"],answer:"يتقابلوا في مكان ومعاد",rationale:"¿Dónde quedamos? = هنتقابل فين؟"},{q:"هيتقابلوا فين؟",options:["قدام المحطة","عند النافورة","عند المدخل"],answer:"عند المدخل",rationale:"قالت: En la entrada. يعني عند المدخل."},{q:"هيتقابلوا الساعة كام؟",options:["خمسة","أربعة","ستة"],answer:"خمسة",rationale:"قال: Quedamos a las cinco. يعني هنتقابل الساعة خمسة."}],responseTask:{prompt:"اسأل صاحبتك هتتقابلوا فين بالإسباني.",acceptable:["¿Dónde quedamos?","¿Dónde nos vemos?","¿Quedamos en la plaza?"],modelEs:"¿Dónde quedamos?",modelAr:"هنتقابل فين؟",checklistAr:"راجع إجابتك: ١) استخدمت quedamos أو nos vemos، ٢) سؤال عن المكان، ٣) قصير وطبيعي. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"quedar = يتفق الناس يتقابلوا: ¿Dónde quedamos? = هنتقابل فين؟ و Quedamos a las cinco = هنتقابل الساعة خمسة. ¡Nos vemos! = أشوفك!"}},{id:"p0-f-l03",courseId:"everyday-core",unitId:"p0-f",sourceLessonId:null,level:"A1–A2",register:"tú",title:"الخطة اتغيرت",context:"باكو عنده شغل زيادة فمحتاج يأجل الخروجة.",goal:"تعلن تغيير خطة وتقترح موعد بديل.",targets:[{es:"Tenemos que cambiar de plan.",ar:"لازم نغير الخطة.",speaker:"paco"},{es:"Lo pasamos al sábado.",ar:"نأجلها ليوم السبت.",speaker:"luna"},{es:"Sin problema.",ar:"من غير مشكلة.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Luna. Tenemos que cambiar de plan.",ar:"لونا، لازم نغير الخطة."},{speaker:"luna",es:"¿Qué pasó?",ar:"حصل إيه؟"},{speaker:"paco",es:"Tengo trabajo el viernes.",ar:"عندي شغل يوم الجمعة."},{speaker:"luna",es:"No pasa nada.",ar:"ولا يهمك."},{speaker:"paco",es:"¿Vamos el sábado?",ar:"نروح يوم السبت؟"},{speaker:"luna",es:"Sí. Lo pasamos al sábado.",ar:"أيوه، نأجلها ليوم السبت."},{speaker:"paco",es:"Gracias.",ar:"متشكر."},{speaker:"luna",es:"Sin problema.",ar:"من غير مشكلة."}],questions:[{q:"ليه باكو عايز يغير الخطة؟",options:["الجو هيكون وحش","تعبان جدًا وعايز ينام بدري","عنده شغل يوم الجمعة"],answer:"عنده شغل يوم الجمعة",rationale:"قال: Tengo trabajo el viernes. يعني عندي شغل يوم الجمعة."},{q:"«Lo pasamos al sábado» معناها إيه؟",options:["نأجلها ليوم السبت","نلغيها خالص","نروح السبت الصبح بدري"],answer:"نأجلها ليوم السبت",rationale:"pasar algo al + يوم = نأجلها ليوم…"},{q:"الخطة الجديدة إيه؟",options:["الخروجة يوم الجمعة","الخروجة يوم السبت","مفيش خروجة خالص"],answer:"الخروجة يوم السبت",rationale:"اتفقوا: ¿Vamos el sábado? وردت لونا: Sí. Lo pasamos al sábado."}],responseTask:{prompt:"عندك ظرف ومحتاج تأجل معاد مع صاحبتك. قولها بالإسباني واقترح يوم تاني.",acceptable:["Tenemos que cambiar de plan. ¿Vamos otro día?","Lo siento, no puedo. ¿Lo pasamos al domingo?","Tengo que cambiar el plan. ¿El domingo?"],modelEs:"Tenemos que cambiar de plan. ¿Vamos otro día?",modelAr:"لازم نغير الخطة. نروح يوم تاني؟",checklistAr:"راجع إجابتك: ١) أعلنت تغيير الخطة، ٢) السبب أو الاعتذار موجود، ٣) اقترحت موعد بديل. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cambiar de plan = نغير الخطة. pasar algo al + يوم = نأجلها ليوم…: Lo pasamos al sábado. Sin problema = من غير مشكلة، رد مرتاح على أي تأجيل."}},{id:"p0-f-l04",courseId:"everyday-core",unitId:"p0-f",sourceLessonId:null,level:"A1–A2",register:"tú",title:"الموبايل بوظ",context:"موبايل لونا مش شغال وباكو بيحاول يساعدها.",goal:"توصف عطل بسيط وتقترح حل.",targets:[{es:"Mi móvil no funciona.",ar:"موبايلي مش شغال.",speaker:"luna"},{es:"No enciende.",ar:"مش بيفتح خالص.",speaker:"luna"},{es:"Hay que llevarlo a arreglar.",ar:"لازم نوديه يتصلح.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Mi móvil no funciona.",ar:"موبايلي مش شغال."},{speaker:"paco",es:"¿Qué le pasa?",ar:"فيه إيه؟"},{speaker:"luna",es:"No enciende.",ar:"مش بيفتح خالص."},{speaker:"paco",es:"¿Tiene batería?",ar:"عنده شحن؟"},{speaker:"luna",es:"Sí, está cargado.",ar:"أيوه، متشاحن."},{speaker:"paco",es:"Hay que llevarlo a arreglar.",ar:"لازم نوديه يتصلح."},{speaker:"luna",es:"Qué rollo.",ar:"يا لهوي."}],questions:[{q:"موبايل لونا فيه إيه؟",options:["مش بيفتح خالص","الشاشة مكسورة","بيفصل لوحده كل شوية"],answer:"مش بيفتح خالص",rationale:"قالت: No enciende. يعني مش بيفتح خالص."},{q:"«Hay que llevarlo a arreglar» معناها إيه؟",options:["لازم نرميه ونجيب غيره","لازم نوديه يتصلح","لازم نشحنه طول الليل"],answer:"لازم نوديه يتصلح",rationale:"hay que + مصدر = لازم نعمل، و arreglar = يصلح."},{q:"«Qué rollo» بتعبر عن إيه؟",options:["خوف شديد","فرحة كبيرة ومفاجئة","ضيق من موقف ممل"],answer:"ضيق من موقف ممل",rationale:"لونا قالتها لما عرفت إن الموبايل لازم يتصلح، يعني يا لهوي."}],responseTask:{prompt:"المروحة عندك مش شغالة. قول لصاحبك إنها مش شغالة بالإسباني.",acceptable:["El ventilador no funciona.","Mi ventilador no funciona.","No funciona el ventilador."],modelEs:"El ventilador no funciona.",modelAr:"المروحة مش شغالة.",checklistAr:"راجع إجابتك: ١) no funciona موجودة، ٢) سميت الحاجة المعطلة، ٣) جملة خبرية بسيطة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"no funciona = مش شغال، أول جملة لأي عطل. no enciende = مش بيفتح، للأجهزة. hay que + مصدر = لازم نعمل: Hay que llevarlo = لازم نوديه. Qué rollo = يا لهوي."}},{id:"p0-f-l05",courseId:"everyday-core",unitId:"p0-f",sourceLessonId:null,level:"A1–A2",register:"tú",title:"مفتاحي ضاع",context:"باكو مش لاقي مفاتيحه قبل الخروج.",goal:"تقول إنك ضيعت حاجة وتسأل حد لو شافها.",targets:[{es:"No encuentro mis llaves.",ar:"مش لاقي مفاتيحي.",speaker:"paco"},{es:"¿Las has visto?",ar:"شفتيهم؟",speaker:"paco"},{es:"¡Qué despiste!",ar:"يا سلام على النسيان!",speaker:"luna"}],dialogue:[{speaker:"paco",es:"No encuentro mis llaves.",ar:"مش لاقي مفاتيحي."},{speaker:"luna",es:"¿Dónde las dejaste?",ar:"سيبتهم فين؟"},{speaker:"paco",es:"No sé. ¿Las has visto?",ar:"مش عارف. شفتيهم؟"},{speaker:"luna",es:"¿En la mesa?",ar:"على الترابيزة؟"},{speaker:"paco",es:"No están ahí.",ar:"مش هناك."},{speaker:"luna",es:"¡Mira! ¡En la puerta!",ar:"بص! في الباب!"},{speaker:"paco",es:"¡Ay, gracias!",ar:"آه، متشكر!"},{speaker:"luna",es:"¡Qué despiste!",ar:"يا سلام على النسيان!"}],questions:[{q:"باكو مش لاقي إيه؟",options:["موبايله","محفظته","مفاتيحه"],answer:"مفاتيحه",rationale:"قال: No encuentro mis llaves. يعني مش لاقي مفاتيحي."},{q:"«¿Las has visto?» معناها إيه؟",options:["شفتيهم؟","سمعتهم؟","خدتهم؟"],answer:"شفتيهم؟",rationale:"باكو بيسأل لونا لو شافت المفاتيح: ¿Las has visto?"},{q:"المفاتيح كانت فين؟",options:["على الترابيزة","في الباب","في الشنطة"],answer:"في الباب",rationale:"لونا قالت: ¡Mira! ¡En la puerta! يعني بص، في الباب."}],responseTask:{prompt:"مش لاقي محفظتك. قول لصاحبتك إنك مش لاقيها بالإسباني.",acceptable:["No encuentro mi cartera.","He perdido mi cartera.","No encuentro la cartera."],modelEs:"No encuentro mi cartera.",modelAr:"مش لاقي محفظتي.",checklistAr:"راجع إجابتك: ١) استخدمت no encuentro أو he perdido، ٢) سميت الحاجة الضايعة، ٣) جملة واضحة وقصيرة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"No encuentro = مش لاقي، و He perdido = ضاع مني. ¿Las has visto? = شفتيهم؟ للمفاتيح، مؤنث جمع. ¡Qué despiste! = يا سلام على النسيان!"}},{id:"p0-f-l06",courseId:"everyday-core",unitId:"p0-f",sourceLessonId:null,level:"A1–A2",register:"tú",title:"tú ولا usted؟",context:"لونا بتشرح لباكو فرق الأسلوب مع الناس الكبيرة.",goal:"تعرف إمتى تقول tú وإمتى usted، وتفهم فرق vosotros و ustedes.",targets:[{es:"Conmigo, tú.",ar:"معايا، كلمني بـ tú.",speaker:"luna"},{es:"¿Cómo está usted?",ar:"حضرتك عامل إيه؟",speaker:"paco"},{es:"Así, con respeto.",ar:"كده، باحترام.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"En España, ¿tú o usted con los vecinos?",ar:"في إسبانيا، نقول tú ولا usted للجيران؟"},{speaker:"luna",es:"Depende. Con la gente mayor, usted.",ar:"على حسب. مع الناس الكبيرة، usted."},{speaker:"paco",es:"¿Y contigo?",ar:"ومعاكي إنتي؟"},{speaker:"luna",es:"Conmigo, tú.",ar:"معايا، كلمني بـ tú."},{speaker:"paco",es:"¿Cómo está usted? ¿Así?",ar:"حضرتك عامل إيه؟ كده؟"},{speaker:"luna",es:"¡Muy bien! Así, con respeto.",ar:"برافو! كده، باحترام."},{speaker:"paco",es:"¿Y en Latinoamérica?",ar:"وفي أمريكا اللاتينية؟"},{speaker:"luna",es:"Allí usted se usa más, y no usan vosotros.",ar:"هناك usted بتتقال أكتر، ومش بيستخدموا vosotros."}],questions:[{q:"مع الناس الكبيرة في إسبانيا بنقول إيه؟",options:["tú","usted","vosotros"],answer:"usted",rationale:"لونا قالت: Con la gente mayor, usted. يعني مع الناس الكبيرة، usted."},{q:"لونا عايزة باكو يكلمها بإيه؟",options:["él","usted","tú"],answer:"tú",rationale:"قالت: Conmigo, tú. يعني معايا، كلمني بـ tú."},{q:"في أمريكا اللاتينية إيه الصح؟",options:["usted بتتقال أكتر ومش بيستخدموا vosotros","كل الناس بتقول tú في كل المواقف الرسمية والعادية","vosotros للكلام الرسمي جدًا"],answer:"usted بتتقال أكتر ومش بيستخدموا vosotros",rationale:"قالت: Allí usted se usa más, y no usan vosotros."}],responseTask:{prompt:"قابلت جارك الكبير الإسباني في السلم. سلم عليه باحترام بالإسباني.",acceptable:["Buenos días, ¿cómo está usted?","¿Cómo está usted?","Buenas tardes, ¿cómo está?"],modelEs:"Buenos días, ¿cómo está usted?",modelAr:"صباح الخير، حضرتك عامل إيه؟",checklistAr:"راجع إجابتك: ١) فيه تحية، ٢) استخدمت usted مش tú، ٣) النبرة محترمة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"tú لصحابك والناس في سنك، و usted للكبير والرسمي: ¿Cómo estás? بتبقى ¿Cómo está usted?. vosotros بتتقال في إسبانيا للجمع، وفي أمريكا اللاتينية بيستخدموا ustedes مكانها."}}]},{courseId:"call-center",unit:{id:"cc-u01",title:"بداية المكالمة",desc:"تبدأ المكالمة بأدب، تعرّف نفسك، وتفهم العميل حتى لو الخط مش واضح.",cefr:"A2–B1"},lessons:[{id:"cc-u01l01",courseId:"call-center",unitId:"cc-u01",sourceLessonId:"cc-u01l01",level:"A2",register:"usted",title:"ابدأ المكالمة صح",context:"عميل متصل بخدمة العملاء عشان فاتورة مش فاهمها. دورك: تفتح المكالمة بتحية، تعرّف نفسك، وتسأل إزاي تقدر تساعد، وكل ده بصيغة حضرتك.",goal:"بعد الدرس ده حتقدر تفتح مكالمة خدمة عملاء بالإسباني: تحية + اسمك + عرض المساعدة، وتاخد اسم العميل بأدب.",targets:[{es:"Buenos días, le atiende Luna.",ar:"صباح الخير، مع حضرتك لونا.",speaker:"luna"},{es:"¿En qué puedo ayudarle?",ar:"أقدر أساعد حضرتك في إيه؟",speaker:"luna"},{es:"Llamo por una factura que no entiendo.",ar:"بأتصل عشان فاتورة مش فاهمها.",speaker:"paco"},{es:"Cuénteme qué es lo que no entiende de la factura.",ar:"احكيلي إيه اللي مش فاهمه في الفاتورة.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola, buenos días. Llamo por una factura que no entiendo.",ar:"أهلًا، صباح الخير. بأتصل عشان فاتورة مش فاهمها."},{speaker:"luna",es:"Claro, lo revisamos juntos. ¿Me dice su nombre, por favor?",ar:"طبعًا، حنراجعها مع بعض. تقوللي حضرتك اسمك، لو سمحت؟"},{speaker:"paco",es:"Sí, soy Paco Martín.",ar:"أيوه، أنا باكو مارتين."},{speaker:"luna",es:"Gracias, Paco. Un momento mientras abro su cuenta.",ar:"شكرًا يا باكو. لحظة واحدة لحد ما أفتح حساب حضرتك."},{speaker:"paco",es:"Sin prisa, gracias.",ar:"على مهلك، شكرًا."},{speaker:"luna",es:"Ya estoy aquí. Cuénteme qué es lo que no entiende de la factura.",ar:"أنا مع حضرتك. احكيلي إيه اللي مش فاهمه في الفاتورة."}],questions:[{q:"العميل متصل ليه؟",options:["عنده مشكلة في الخط","عنده فاتورة مش فاهمها","عايز يلغي الخدمة","عايز يشتكي من موظف"],answer:"عنده فاتورة مش فاهمها",rationale:"قال حرفيًا: Llamo por una factura que no entiendo = بأتصل عشان فاتورة مش فاهمها. مفيش كلام عن إلغاء ولا شكوى ولا عطل في الخط."},{q:"إيه أول حاجة طلبتها الموظفة من العميل؟",options:["رقم الفاتورة","عنوانه","اسمه","رقم كارته"],answer:"اسمه",rationale:"الموظفة قالت: ¿Me dice su nombre, por favor? = تقولي اسمك، لو سمحت؟ الاسم بس هو اللي اتطلب، ومش لازم بيانات حساسة في أول مكالمة."},{q:"أنسب جملة يفتح بيها موظف الكول سنتر المكالمة؟",options:["¿Qué quiere?","Buenos días. Dígame.","Buenos días, le atiende Luna. ¿En qué puedo ayudarle?","Hola, ¿sí? ¿Qué pasa?"],answer:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",rationale:"البداية الصح: تحية + تعريف نفسك (le atiende + الاسم) + عرض مساعدة بصيغة حضرتك. ¿Qué quiere? حرفيًا عايز إيه؟ وهي فظّة جدًا في خدمة العملاء، و¿sí? ¿Qué pasa? مش بداية مهنية."}],responseTask:{prompt:"تخيل إنك موظف الكول سنتر والتليفون رن. ابدأ المكالمة بالإسباني: تحية + اسمك + سؤال تقدر تساعد بيه العميل.",acceptable:["Buenos días, le atiende Luna. ¿En qué puedo ayudarle?","Buenas tardes, le atiende Paco. ¿En qué puedo ayudarle?","Buenos días, le atiende Luna. ¿Cómo puedo ayudarle?","Hola, buenos días. Le atiende Luna. ¿En qué puedo ayudarle?"],modelEs:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",modelAr:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟",checklistAr:"راجع إجابتك بنفسك: ١) فيها تحية مناسبة لوقت اليوم، ٢) عرّفت نفسك بـ le atiende + اسمك، ٣) سألت بأدب بصيغة حضرتك (le). ردك مفتوح: أي صياغة مهذبة سليمة مقبولة، مش لازم تطابق النموذج حرفيًا.",explanation:"le atiende + الاسم = 'مع حضرتك …'، صيغة ثابتة بتتقال في خدمة العملاء في إسبانيا. ¿En qué puedo ayudarle? فيها le في الآخر للمخاطب الرسمي (حضرتك)."}},{id:"cc-u01l02",courseId:"call-center",unitId:"cc-u01",sourceLessonId:"cc-u01l02",level:"A2",register:"usted",title:"نتكلم بأنهي لغة؟",context:"عميل أجنبي متردد في أول المكالمة وسأل لو في حد بيتكلم إنجليزي. دورك: تشجّعه يكمل بالإسباني من غير ما تدّعي إن إنجليزيتك كاملة، وتوفرله جو مريح يتكلم فيه.",goal:"بعد الدرس ده حتقدر تتعامل مع سؤال 'بتتكلم إنجليزي؟' بصدق، وتعرض تكمل بالإسباني ببطء، وتطمن العميل إنه ياخد وقته.",targets:[{es:"¿Habla usted inglés?",ar:"حضرتك بتتكلمي إنجليزي؟",speaker:"paco"},{es:"Podemos hablar en español despacio, si quiere.",ar:"نقدر نتكلم بالإسباني ببطء، لو حضرتك تحب.",speaker:"luna"},{es:"Tómese su tiempo.",ar:"خد وقت حضرتك.",speaker:"luna"},{es:"Así practico.",ar:"كده أتمرن.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenas tardes, le atiende Luna. ¿En qué puedo ayudarle?",ar:"مساء الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Eh… hola. ¿Habla usted inglés?",ar:"امم… أهلًا. حضرتك بتتكلمي إنجليزي؟"},{speaker:"luna",es:"Un poquito. Podemos hablar en español despacio, si quiere.",ar:"شوية، بس نقدر نتكلم بالإسباني ببطء، لو حضرتك تحب."},{speaker:"paco",es:"Vale, mejor en español. Así practico.",ar:"تمام، أحسن بالإسباني. كده أتمرن."},{speaker:"luna",es:"¡Muy bien! Entonces le escucho. Tómese su tiempo.",ar:"برافو! يبقى أنا سامعاك. خد وقت حضرتك."},{speaker:"paco",es:"Gracias. Es sobre mi contrato de internet.",ar:"شكرًا. الموضوع عن عقد النت بتاعي."},{speaker:"luna",es:"Perfecto, le ayudo con eso. ¿Me dice su número de cliente cuando quiera?",ar:"تمام، حأساعد حضرتك في ده. تقوللي رقم العميل بتاع حضرتك لما تكون جاهز؟"}],questions:[{q:"العميل فضّل يكمل بأنهي لغة في الآخر؟",options:["بالإنجليزي","بالإسباني عشان يتمرن","قفل وقال حيكلم حد تاني","طلب يبعت إيميل بدل المكالمة"],answer:"بالإسباني عشان يتمرن",rationale:"قال: Vale, mejor en español. Así practico = تمام، أحسن بالإسباني، كده أتمرن كمان. Vale في إسبانيا = تمام/ماشي."},{q:"«Tómese su tiempo» معناها إيه؟",options:["وقتك خلص","خد وقت حضرتك","استنى على الخط شوية","عندك وقت كتير أوي"],answer:"خد وقت حضرتك",rationale:"tomarse su tiempo = ياخد وقته من غير استعجال، وهنا بصيغة أمر مهذبة (usted). الموظفة بتطمنه مش بتستعجله."},{q:"عميل سألك لو بتتكلم إنجليزي وإنت مش متقنها. أنسب رد مهني؟",options:["تتظاهر إنك متقنها وتكمل","تعرض تكمل بالإسباني ببطء ووضوح","تقفل المكالمة بأدب","تحوّله فورًا من غير ما تشرح ليه"],answer:"تعرض تكمل بالإسباني ببطء ووضوح",rationale:"الصدق المهني أحسن حل: Un poquito, pero podemos hablar en español despacio. التظاهر حيسبب أخطاء أكبر، والقفل أو التحويل من غير شرح بيضايق العميل."}],responseTask:{prompt:"عميل سألك: «¿Habla usted inglés?» رد بالإسباني بصدق، وشجّعه يكمل بالإسباني ببطء لو ده يناسبه.",acceptable:["Un poquito, pero podemos hablar en español despacio, si quiere.","Sí, un poco, pero si quiere hablamos en español despacio y así practica.","Hablo un poco de inglés, pero puedo ayudarle en español despacio.","Un poco, pero le escucho con calma en español. Tómese su tiempo."],modelEs:"Un poquito, pero podemos hablar en español despacio, si quiere.",modelAr:"شوية، بس نقدر نتكلم بالإسباني ببطء، لو حضرتك تحب.",checklistAr:"راجع إجابتك: ١) رديت على السؤال بصدق (un poquito / un poco)، ٢) عرضت بديل عملي (español despacio)، ٣) الجملة بصيغة حضرتك (quiere / le). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"si quiere = لو حضرتك تحب، صيغة usted من querer. despacio حال معناها ببطء. Tómese أمر مهذب من tomarse، والـ se في الآخر للمخاطب الرسمي."}},{id:"cc-u01l03",courseId:"call-center",unitId:"cc-u01",sourceLessonId:"cc-u01l03",level:"A2",register:"usted",title:"الخط مش واضح",context:"عميلة متصلة والخط عليه شوشرة، فوصلتك نص جملتها بس. دورك: توضح إنك مش سامع كويس، وتطلب الإعادة والكلام ببطء بأدب، من غير ما تخمّن.",goal:"بعد الدرس ده حتقدر تتعامل مع خط وحش: تقول إنك مش سامع، تطلب إعادة، وتأكد إنك فهمت قبل ما تكمل.",targets:[{es:"Perdone, no le oigo bien.",ar:"آسف، مش سامع حضرتك كويس.",speaker:"paco"},{es:"¿Puede repetirlo, por favor?",ar:"ممكن حضرتك تعيدي الكلام، لو سمحت؟",speaker:"paco"},{es:"¿Puede hablar más despacio?",ar:"ممكن حضرتك تتكلم أبطأ شوية؟",speaker:"paco"},{es:"Ya lo he entendido.",ar:"فهمت حضرتك دلوقتي.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días, le atiende Paco. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك باكو. أقدر أساعد حضرتك في إيه؟"},{speaker:"luna",es:"Hola, llamo porque mi pedido… no llegó el martes.",ar:"أهلًا، بأتصل عشان طلبي… ماوصلش يوم التلات."},{speaker:"paco",es:"Perdone, no le oigo bien. ¿Puede repetirlo, por favor?",ar:"آسف، مش سامع حضرتك كويس. ممكن حضرتك تعيدي الكلام، لو سمحت؟"},{speaker:"luna",es:"Sí, claro. Digo que mi pedido no llegó el martes.",ar:"أيوه طبعًا. بقول إن طلبي ماوصلش يوم التلات."},{speaker:"paco",es:"Gracias. Hay mucho ruido en la línea. ¿Puede hablar más despacio?",ar:"شكرًا. في شوشرة على الخط. ممكن حضرتك تتكلمي أبطأ شوية؟"},{speaker:"luna",es:"Sí, perdón. Mi pedido no llegó el martes.",ar:"أيوه، آسفة. طلبي ماوصلش يوم التلات."},{speaker:"paco",es:"Ahora sí, perfecto. Ya lo he entendido. Lo revisamos ahora mismo.",ar:"كده تمام، ممتاز. فهمت حضرتك دلوقتي. حنراجعه دلوقتي حالًا."}],questions:[{q:"ليه الموظف طلب من العميلة تعيد الكلام؟",options:["مش سامعها كويس بسبب شوشرة على الخط","مش فاهم الإسباني بتاعها","عايز يتأكد من اسمها","العميلة بتتكلم في موضوع تاني"],answer:"مش سامعها كويس بسبب شوشرة على الخط",rationale:"قال: No le oigo bien وHay mucho ruido en la línea = مش سامعك كويس وفي شوشرة على الخط. مشكلته صوت مش فهم."},{q:"مشكلة العميلة إيه بالظبط؟",options:["فاتورة غلط","عايزة تشتكي من موظف","عايزة تغيّر عنوانها","طلبها ماوصلش يوم التلات"],answer:"طلبها ماوصلش يوم التلات",rationale:"قالت مرتين: Mi pedido no llegó el martes = طلبي ماوصلش يوم التلات. مفيش ذكر لفاتورة ولا عنوان."},{q:"مش سامع العميل نص جملته. إيه التصرف الصح؟",options:["تخمّن باقي الجملة وتكمل","تسكت وتستنى يعيد لوحده","تطلب منه يعيد بأدب وتوضح إن في شوشرة","تقفل عشان الخط وحش"],answer:"تطلب منه يعيد بأدب وتوضح إن في شوشرة",rationale:"التخمين في شغل خدمة العملاء بيعمل أخطاء في البيانات. الصح: Perdone, no le oigo bien. ¿Puede repetirlo, por favor? — اعتذار بسيط + طلب إعادة واضح."}],responseTask:{prompt:"الخط عليه شوشرة ومش سامع العميل آخر جملة. قول بالإسباني إنك مش سامع كويس واطلب الإعادة بأدب.",acceptable:["Perdone, no le oigo bien. ¿Puede repetirlo, por favor?","Lo siento, hay mucho ruido. ¿Puede hablar más despacio?","Perdone, no le escucho bien. ¿Me lo repite, por favor?","Disculpe, la línea no se oye bien. ¿Puede repetir la última parte?"],modelEs:"Perdone, no le oigo bien. ¿Puede repetirlo, por favor?",modelAr:"آسف، مش سامع حضرتك كويس. ممكن حضرتك تعيد الكلام، لو سمحت؟",checklistAr:"راجع إجابتك: ١) فيها اعتذار أو استئذان بسيط (Perdone / Lo siento)، ٢) وضحت إن المشكلة سمع (no le oigo / no le escucho)، ٣) طلبت الإعادة بأدب (¿Puede repetir…?). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"no le oigo bien = مش سامع حضرتك كويس، وتنفع للراجل والست لأن le هنا للاحترام مش للجنس. Perdone بصيغة usted للاعتذار أو الاستئذان. repetirlo: الـ lo بتشاور على الكلام اللي اتقال."}},{id:"cc-u01l04",courseId:"call-center",unitId:"cc-u01",sourceLessonId:null,level:"B1",register:"usted",title:"مكالمة وصلت للقسم الغلط",context:"عميلة اتصلت بقسم الفواتير بالغلط، ومشكلتها فنية. دورك: توضح مين القسم المختص، وتحوّلها مع ملاحظة باللي قالته، من غير ما تخليها تعيد الشرح من الأول.",goal:"بعد الدرس ده حتقدر تتعامل مع مكالمة مش بتاعت قسمك: توجّه العميل للقسم الصح وتحوّله باحتراف من غير ما يحس إنه اتلفّت.",targets:[{es:"Eso lo lleva el departamento técnico.",ar:"ده بيتابعه القسم الفني.",speaker:"paco"},{es:"No se preocupe, que le paso con ellos ahora mismo.",ar:"متقلقيش، ححوّلك لهم دلوقتي حالًا.",speaker:"paco"},{es:"¿Tengo que explicarlo todo otra vez?",ar:"لازم أشرح الموضوع من الأول تاني؟",speaker:"luna"},{es:"No hace falta.",ar:"مفيش داعي.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenas tardes, le atiende Paco, de facturación. ¿En qué puedo ayudarle?",ar:"مساء الخير، مع حضرتك باكو من قسم الفواتير. أقدر أساعد حضرتك في إيه؟"},{speaker:"luna",es:"Hola, es que mi internet no funciona desde ayer.",ar:"أهلًا، المشكلة إن النت عندي مش شغال من إمبارح."},{speaker:"paco",es:"Entiendo. Mire. Eso lo lleva el departamento técnico. No se preocupe, que le paso con ellos ahora mismo.",ar:"فاهم حضرتك. بصي حضرتك، ده بيتابعه القسم الفني. متقلقيش، ححوّلك لهم دلوقتي حالًا."},{speaker:"luna",es:"¿Tengo que explicarlo todo otra vez?",ar:"لازم أشرح الموضوع من الأول تاني؟"},{speaker:"paco",es:"No hace falta. Les paso una nota con lo que me ha contado.",ar:"مفيش داعي. حبعت لهم ملاحظة باللي شرحتيه."},{speaker:"luna",es:"Ah, genial. Muchas gracias.",ar:"أه، جميل. شكرًا جدًا."},{speaker:"paco",es:"Un segundo, por favor. Le paso ahora.",ar:"ثانية واحدة لو سمحت. ححوّلك دلوقتي."}],questions:[{q:"العميلة محتاجة أنهي قسم فعلًا؟",options:["قسم الفواتير","قسم المبيعات","خدمة العملاء العامة","القسم الفني"],answer:"القسم الفني",rationale:"الموظف قال: eso lo lleva el departamento técnico = ده بيتابعه القسم الفني. النت مش شغال يبقى مشكلة فنية، مش فواتير."},{q:"هل العميلة حتشرح مشكلتها من الأول بعد التحويل؟",options:["أيوه، لازم تعيد كل حاجة","لأ، الموظف حيبعت ملاحظة باللي قالته","لأ، القسم التاني مش محتاج تفاصيل","أيوه، بس المرة دي كتابة"],answer:"لأ، الموظف حيبعت ملاحظة باللي قالته",rationale:"قال: Les paso una nota con lo que me ha contado = حبعت لهم ملاحظة باللي شرحتيه. les هنا مفعول غير مباشر (لهم) فصحيحة."},{q:"مكالمة وصلت لقسمك بالغلط وهي بتخص قسم تاني. أنسب تصرف؟",options:["تقول للعميل ده مش شغلي وتقفل","تديه رقم القسم التاني وتخليه يكلم نفسه","توضح مين المختص وتحوّله مع ملاحظة بمشكلته","تفضل تعتذر كتير من غير تحويل"],answer:"توضح مين المختص وتحوّله مع ملاحظة بمشكلته",rationale:"التحويل مع ملاحظة بيوفر على العميل إعادة الشرح وبيحترم وقته. قول 'ده مش شغلي' أو الترقيع بالاعتذار من غير فعل مش حل."}],responseTask:{prompt:"عميل شرح مشكلة فنية وإنت في قسم الفواتير. قول بالإسباني إن القسم الفني هو المختص، وإنك حتحوّله دلوقتي، وطمنه إنه مش هيشرح من الأول.",acceptable:["Eso lo lleva el departamento técnico. No se preocupe, que le paso con ellos ahora mismo.","Entiendo. Le paso con el departamento técnico ahora mismo, no hace falta que lo explique otra vez.","Mire, eso es del departamento técnico. Le paso ahora y les envío una nota con su caso.","No se preocupe, ahora le paso con mis compañeros del departamento técnico y les cuento su problema."],modelEs:"Eso lo lleva el departamento técnico. No se preocupe, que le paso con ellos ahora mismo.",modelAr:"ده بيتابعه القسم الفني. متقلقيش، ححوّلك لهم دلوقتي حالًا.",checklistAr:"راجع إجابتك: ١) سمّيت القسم المختص (departamento técnico)، ٢) قولت إنك حتحوّل (le paso con…)، ٣) طمنت العميل إنه مش حيعيد الشرح (no hace falta / una nota). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"le paso con ellos = ححوّل حضرتك لهم، وpasar بتتستخدم للمكالمات. no hace falta = مفيش داعي. Mire = بصّي بصيغة حضرتك للفت الانتباه بأدب."}},{id:"cc-u01l05",courseId:"call-center",unitId:"cc-u01",sourceLessonId:null,level:"B1",register:"usted",title:"عميل زعلان من أول ثانية",context:"عميل فتح المكالمة بعصبية قبل ما يقول مشكلته، لأنه مستني على الخط من عشرين دقيقة. دورك: تمتص العصبية من غير ما تتجاهلها، وتوجّه الكلام للحل بسرعة.",goal:"بعد الدرس ده حتقدر ترد على عميل زعلان: تقر بحقه، تعتذر عن الانتظار، وتسأله عن المشكلة من غير ما تزوّد الموقف.",targets:[{es:"Siento mucho la espera.",ar:"متأسفة جدًا على الانتظار.",speaker:"luna"},{es:"Entiendo su enfado.",ar:"فاهمة زعل حضرتك.",speaker:"luna"},{es:"Cuénteme qué ha pasado y lo miramos ya.",ar:"احكيلي إيه اللي حصل ونبص عليه حالًا.",speaker:"luna"},{es:"Gracias por su paciencia.",ar:"شكرًا على صبر حضرتك.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¡Por fin! Llevo veinte minutos esperando. ¡Esto es una vergüenza!",ar:"أخيرًا! ليا عشرين دقيقة مستني. ده عيب!"},{speaker:"luna",es:"Tiene toda la razón. Siento mucho la espera. Le atiende Luna. Cuénteme qué ha pasado y lo miramos ya.",ar:"مع حضرتك كل الحق، وأنا متأسفة جدًا على الانتظار. مع حضرتك لونا. احكيلي إيه اللي حصل ونبص عليه حالًا."},{speaker:"paco",es:"Es que me han cobrado dos veces este mes.",ar:"المشكلة إنهم خصموا مني مرتين الشهر ده."},{speaker:"luna",es:"Entiendo su enfado. Lo reviso ahora mismo y le digo exactamente qué veo.",ar:"فاهمة زعل حضرتك. حراجعها دلوقتي حالًا وحأقولك بالظبط أنا شايفة إيه."},{speaker:"paco",es:"Vale. A ver.",ar:"تمام. نشوف."},{speaker:"luna",es:"Gracias por su paciencia. Ya estoy con ello.",ar:"شكرًا على صبر حضرتك. أنا عليها دلوقتي."}],questions:[{q:"العميل كان زعلان في أول المكالمة ليه؟",options:["استنى عشرين دقيقة على الخط","الفاتورة غالية","الموقع مش شغال","محدش رد على إيميله"],answer:"استنى عشرين دقيقة على الخط",rationale:"قال: Llevo veinte minutos esperando = ليا عشرين دقيقة مستني. llevo + مدة + فعل = ليا مدة بعمل كذا."},{q:"إيه مشكلة الفلوس اللي حكى عنها بعد كده؟",options:["الخصم اتأخر عن المعاد","عايز يدفع كاش","اتخصم منه مرتين الشهر ده","الشركة رفعت السعر"],answer:"اتخصم منه مرتين الشهر ده",rationale:"قال: me han cobrado dos veces este mes = خصموا مني مرتين الشهر ده. cobrar = يخصم/يحاسب."},{q:"عميل فتح المكالمة بعصبية. إيه أحسن أول رد؟",options:["تفكّره بقواعد الشركة فورًا","تقر بحقه وتعتذر عن الانتظار وتعرض تبص على المشكلة حالًا","تطلب منه يهدى الأول قبل ما تسمعه","تتجاهل العصبية وتسأل عن رقم حسابه"],answer:"تقر بحقه وتعتذر عن الانتظار وتعرض تبص على المشكلة حالًا",rationale:"Tiene toda la razón, y siento mucho la espera — الاعتراف بالحق + الاعتذار بيهدي الموقف. طلب 'اهدى' بيبان كتوبيخ، وتجاهل العصبية بيزوّدها."}],responseTask:{prompt:"عميل فتح المكالمة بجملة: «¡Llevo veinte minutos esperando!» رد بالإسباني: تقر بحقه، تعتذر عن الانتظار، وتطلب منه يحكي المشكلة.",acceptable:["Tiene toda la razón, y siento mucho la espera. Cuénteme qué ha pasado y lo miramos ya.","Entiendo su enfado. Siento la espera. Cuénteme qué ha pasado y lo miramos ya.","Lamento mucho la espera. Dígame qué ha pasado y lo reviso ahora mismo.","Tiene razón. Perdone la espera. Cuénteme qué ha pasado, por favor."],modelEs:"Tiene toda la razón, y siento mucho la espera. Cuénteme qué ha pasado y lo miramos ya.",modelAr:"مع حضرتك كل الحق، وأنا متأسفة جدًا على الانتظار. احكيلي إيه اللي حصل ونبص عليه حالًا.",checklistAr:"راجع إجابتك: ١) فيها اعتراف بحق العميل أو تعاطف (Tiene razón / Entiendo su enfado)، ٢) اعتذار عن الانتظار (siento / lamento la espera)، ٣) سؤال مفتوح عن المشكلة (Cuénteme / Dígame). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Tiene toda la razón = مع حضرتك كل الحق. siento وlamento الاتنين = أنا متأسف(ة)، وlamento رسمي أكتر شوية. Cuénteme وDígame أوامر مهذبة بصيغة usted."}},{id:"cc-u01l06",courseId:"call-center",unitId:"cc-u01",sourceLessonId:null,level:"B1",register:"usted",title:"افتتاحية صعبة على خط تعبان",context:"مكالمة فيها كل تحديات البداية مع بعض: عميلة إسبانيها مش قوي، وبتسأل عن الإنجليزي، والخط عليه شوشرة. دورك: تفتح المكالمة، تطمنها، تتعامل مع الشوشرة، وتأكد إنك فهمت طلبها قبل ما تكمل.",goal:"درس مراجعة: حتجمع مهارات الوحدة في مكالمة واحدة، من التحية لحد تأكيد فهم طلب العميلة.",targets:[{es:"No se preocupe.",ar:"متقلقيش.",speaker:"paco"},{es:"Hablamos en español despacio, así me entiende mejor.",ar:"حنتكلم بالإسباني ببطء، كده حتفهمني أحسن.",speaker:"paco"},{es:"Entonces llama por su contrato y quiere cambiarlo, ¿verdad?",ar:"يبقى حضرتك متصلة عشان العقد وعايزة تغيّريه، صح؟",speaker:"paco"},{es:"Eso es.",ar:"بالظبط كده.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Buenos días, le atiende Paco. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك باكو. أقدر أساعد حضرتك في إيه؟"},{speaker:"luna",es:"Eh… ¿habla usted inglés? Es que mi español no es muy bueno.",ar:"امم… حضرتك بتتكلم إنجليزي؟ عشان… إسباني مش أحسن حاجة."},{speaker:"paco",es:"No se preocupe. Hablamos en español despacio, así me entiende mejor.",ar:"متقلقيش. حنتكلم بالإسباني ببطء، كده حتفهمني أحسن."},{speaker:"luna",es:"Vale. Llamo por mi contrato, quiero…",ar:"تمام. بأتصل عشان العقد بتاعي، عايزة…"},{speaker:"paco",es:"Perdone, no le oigo bien. ¿Puede repetirlo, por favor?",ar:"آسف، مش سامع حضرتك كويس. ممكن تعيدي الكلام، لو سمحت؟"},{speaker:"luna",es:"Sí. Llamo por mi contrato. Quiero cambiarlo.",ar:"أيوه. بأتصل عشان العقد بتاعي. عايزة أغيّره."},{speaker:"paco",es:"Perfecto, ahora sí. Entonces llama por su contrato y quiere cambiarlo, ¿verdad?",ar:"تمام، كده وصلت. يبقى حضرتك متصلة عشان العقد وعايزة تغيّريه، صح؟"},{speaker:"luna",es:"Eso es.",ar:"بالظبط كده."},{speaker:"paco",es:"Muy bien. Un momento y lo vemos juntos.",ar:"تمام جدًا. لحظة واحدة ونشوفها مع بعض."}],questions:[{q:"العميلة عايزة تعمل إيه في عقدها؟",options:["تلغيه","تسأل عن سعره بس","تغيّره","تجدده"],answer:"تغيّره",rationale:"قالت: Quiero cambiarlo = عايزة أغيّره. cambiar = يغيّر، مش يلغي (cancelar) ولا يجدد (renovar)."},{q:"الموظف عمل إيه قبل ما يكمل في الموضوع؟",options:["أكد إنه فهم طلبها صح بإعادة المعنى","حوّلها لقسم تاني","طلب رقم كارتها","قالها تبعت إيميل"],answer:"أكد إنه فهم طلبها صح بإعادة المعنى",rationale:"قال: Entonces llama por su contrato y quiere cambiarlo, ¿verdad? — أعاد المعنى وسأل صح؟ دي أفضل طريقة تتأكد إنك فاهم قبل ما تتصرف."},{q:"عميل إسبانيه ضعيف والخط فيه شوشرة. إيه أفضل أسلوب؟",options:["تتكلم بسرعتك العادية عشان تخلص بسرعة","تتكلم بصوت عالي جدًا","تطلب منه يكتب إيميل بدل المكالمة","تكمل بالإسباني ببطء، تطلب إعادة عند الشوشرة، وتأكد الفهم بإعادة المعنى"],answer:"تكمل بالإسباني ببطء، تطلب إعادة عند الشوشرة، وتأكد الفهم بإعادة المعنى",rationale:"الثلاث خطوات دول بيشتغلوا مع بعض: despacio للفهم، ¿Puede repetirlo? عند الشوشرة، و¿verdad? للتأكيد. الصوت العالي مش بيحل مشكلة الفهم."}],responseTask:{prompt:"عميلة قالت إن إسبانيها مش قوي والخط عليه شوشرة. اكتب ردك بالإسباني: طمنها، واعرض تتكلم ببطء، ووضح إنها تقدر تطلب الإعادة في أي وقت.",acceptable:["No se preocupe. Hablamos en español despacio, y si no me oye bien, me lo dice y lo repito.","Tranquila, no pasa nada. Le escucho y hablamos despacio, y si no me oye bien, me lo dice y lo repito.","No se preocupe, vamos despacio. Si no me oye bien, me lo dice y lo repito.","No pasa nada. Hablamos despacio y con calma, y si no me oye bien, lo repito."],modelEs:"No se preocupe. Hablamos en español despacio, y si no me oye bien, me lo dice y lo repito.",modelAr:"متقلقيش. حنتكلم بالإسباني ببطء، ولو مش سامعاني كويس قوليلي وأنا أعيد.",checklistAr:"راجع إجابتك: ١) فيها طمأنة (No se preocupe / Tranquila / No pasa nada)، ٢) عرض واضح للكلام ببطء (despacio)، ٣) وضحت إنها تقدر تطلب الإعادة (si no me oye, me lo dice y lo repito). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"no pasa nada = ولا يهمك / مفيش مشكلة. así هنا معناها كده/عشان كده. ¿verdad? في آخر الجملة = صح؟ وبتتسأل للتأكيد على الفهم."}}]},{courseId:"call-center",unit:{id:"cc-u02",title:"تأكيد الهوية والخصوصية",desc:"تطلب أقل بيانات لازمة للتحقق، وتوضح حدود الخصوصية، من غير أسرار ولا بيانات كروت.",cefr:"A2–B1"},lessons:[{id:"cc-u02l01",courseId:"call-center",unitId:"cc-u02",sourceLessonId:"cc-u02l01",level:"A2",register:"usted",title:"نتأكد مين اللي بيكلمنا",context:"عميل متصل يسأل عن حالة طلبه. دورك: قبل ما تدي أي معلومة، تتأكد إن المتصل هو صاحب الطلب ببيانات بسيطة، من غير أي بيانات حساسة.",goal:"بعد الدرس ده حتقدر تشرح ليه لازم تحقق، وتطلب الاسم والإيميل بأدب، وتبدأ تدي المعلومة بعد التأكد بس.",targets:[{es:"Quiero saber el estado de mi pedido.",ar:"عايز أعرف حالة طلبي.",speaker:"paco"},{es:"Antes de darle información, necesito confirmar que es usted el titular.",ar:"قبل ما أديك أي معلومة، محتاجة أتأكد إن حضرتك صاحب الطلب.",speaker:"luna"},{es:"¿Me dice su nombre completo y el correo con el que hizo el pedido?",ar:"تقوللي اسمك بالكامل والإيميل اللي عملت بيه الطلب؟",speaker:"luna"},{es:"Ahora sí le puedo dar el estado.",ar:"دلوقتي أقدر أقولك الحالة.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola. Quiero saber el estado de mi pedido.",ar:"أهلًا. عايز أعرف حالة طلبي."},{speaker:"luna",es:"Claro. Antes de darle información, necesito confirmar que es usted el titular.",ar:"طبعًا. قبل ما أديك أي معلومة، محتاجة أتأكد إن حضرتك صاحب الطلب."},{speaker:"paco",es:"Sí, sí, soy yo.",ar:"أيوه أيوه، أنا."},{speaker:"luna",es:"¿Me dice su nombre completo y el correo con el que hizo el pedido?",ar:"تقوللي اسمك بالكامل والإيميل اللي عملت بيه الطلب؟"},{speaker:"paco",es:"Paco Martín. El correo es paco punto martin arroba correo punto es.",ar:"باكو مارتين. والإيميل paco نقطة martin آت correo نقطة es."},{speaker:"luna",es:"Perfecto, ya lo tengo. Ahora sí le puedo dar el estado.",ar:"تمام، كده تمام. دلوقتي أقدر أقولك الحالة."}],questions:[{q:"الموظفة استنت ليه قبل ما تقول حالة الطلب؟",options:["عشان لازم تتأكد الأول إن المتصل هو صاحب الطلب","عشان عايزة تسأل المشرف","عشان النظام بطيء","عشان مش لاقية الطلب"],answer:"عشان لازم تتأكد الأول إن المتصل هو صاحب الطلب",rationale:"قالت: Antes de darle información, necesito confirmar que es usted el titular = قبل ما أديك معلومة، محتاجة أتأكد إن حضرتك صاحب الطلب. titular = صاحب الحساب أو الطلب."},{q:"إيه البيانات اللي طلبتها الموظفة؟",options:["رقم الكارت","الاسم بالكامل والإيميل","كلمة السر","عنوان البيت بالكامل"],answer:"الاسم بالكامل والإيميل",rationale:"طلبت: nombre completo والـ correo اللي اتعمل بيه الطلب. بيانات بسيطة، مش أسرار زي كارت أو كلمة سر."},{q:"متصل قال «أنا صاحب الحساب» وخلاص. تعمل إيه؟",options:["تصدقه وتديله البيانات فورًا","تقفل لأنه ممكن يكون متحايل","تطلب بيانات بسيطة تتأكد بيها قبل ما تدي أي معلومة","تطلب منه الرقم السري يثبت بيه"],answer:"تطلب بيانات بسيطة تتأكد بيها قبل ما تدي أي معلومة",rationale:"الكلام لوحده مش تحقق. الاسم والإيميل بيكونوا كفاية كبداية في أنظمة كتير، من غير ما تطلب أسرار."}],responseTask:{prompt:"عميل طلب حالة طلبه. قبل ما تديه المعلومة، قول بالإسباني إنك محتاج تتأكد من هويته، واطلب الاسم بالكامل والإيميل.",acceptable:["Antes de darle información, necesito confirmar que es usted el titular. ¿Me dice su nombre completo y el correo con el que hizo el pedido?","Claro. Primero necesito confirmar su identidad. ¿Me dice su nombre y el correo del pedido?","Por supuesto. ¿Me confirma su nombre completo y el correo con el que hizo el pedido?","Con gusto. Antes necesito verificar que es usted. ¿Me dice su nombre y su correo electrónico?"],modelEs:"Antes de darle información, necesito confirmar que es usted el titular. ¿Me dice su nombre completo y el correo con el que hizo el pedido?",modelAr:"قبل ما أديك أي معلومة، محتاجة أتأكد إن حضرتك صاحب الطلب. تقوللي اسمك بالكامل والإيميل اللي عملت بيه الطلب؟",checklistAr:"راجع إجابتك: ١) وضحت إن في تحقق قبل المعلومة (antes de…, necesito confirmar)، ٢) طلبت الاسم والإيميل بأدب (¿Me dice…?)، ٣) مفيش طلب لبيانات حساسة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"titular = صاحب الحساب أو الطلب. antes de + مصدر = قبل ما. ¿Me dice su nombre? = تقوللي اسم حضرتك؟ — me معناها ليّ (الموظفة اللي بتستقبل الاسم)، وصيغة الاحترام ظاهرة في dice و su، مش في me."}},{id:"cc-u02l02",courseId:"call-center",unitId:"cc-u02",sourceLessonId:"cc-u02l02",level:"B1",register:"usted",title:"المتصل مش صاحب الحساب",context:"عميلة متصلة تسأل عن رصيد حساب والدها. دورك: ترفض إعطاء المعلومة بأدب لأنها مش صاحبة الحساب، وتعرض حل قانوني واضح.",goal:"بعد الدرس ده حتقدر توضح حدود الخصوصية من غير ما تجرح حد، وتقترح بديل: صاحب الحساب يتصل أو يعمل تصريح مكتوب.",targets:[{es:"Llamo por mi padre, quiero saber su saldo.",ar:"بأتصل عن بابا، عايزة أعرف الرصيد بتاعه.",speaker:"luna"},{es:"Solo puedo dar esa información al titular de la cuenta.",ar:"أقدر أدي المعلومة دي لصاحب الحساب بس.",speaker:"paco"},{es:"Tiene que llamar él, o autorizarle por escrito.",ar:"لازم هو يتصل، أو يعمل لك تصريح مكتوب.",speaker:"paco"},{es:"Gracias por su comprensión.",ar:"شكرًا لتفهم حضرتك.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenos días. Llamo por mi padre, quiero saber su saldo.",ar:"صباح الخير. بأتصل عن بابا، عايزة أعرف الرصيد بتاعه."},{speaker:"paco",es:"Gracias por llamar. Lo siento. Solo puedo dar esa información al titular de la cuenta.",ar:"شكرًا إنك بلّغتينا. أنا آسف، بس أقدر أدي المعلومة دي لصاحب الحساب بس."},{speaker:"luna",es:"Pero es mi padre, yo me ocupo de sus cosas.",ar:"بس ده بابا، وأنا اللي بتابع مصالحه."},{speaker:"paco",es:"Lo entiendo, y es normal que usted le ayude. Tiene que llamar él, o autorizarle por escrito. Es por seguridad.",ar:"فاهم حضرتك، وطبيعي إنك بتساعديه. لازم هو يتصل، أو يعمل لك تصريح مكتوب. ده للأمان."},{speaker:"luna",es:"Vale, le digo que os llame él.",ar:"تمام، حأقوله يتصل بيكوا."},{speaker:"paco",es:"Perfecto. Gracias por su comprensión.",ar:"تمام. شكرًا لتفهم حضرتك."}],questions:[{q:"العميلة عايزة تعرف إيه؟",options:["رقم حساب جديد","حالة طلبها هي","فاتورة قديمة ليها","رصيد حساب باباها"],answer:"رصيد حساب باباها",rationale:"قالت: Llamo por mi padre, quiero saber su saldo = بأتصل عن بابا، عايزة أعرف رصيده. saldo = رصيد."},{q:"ليه الموظف رفض يدي المعلومة؟",options:["عشان المتصلة مش صاحبة الحساب","عشان النظام مش شغال","عشان المعلومة مش موجودة","عشان معاد القفل قرب"],answer:"عشان المتصلة مش صاحبة الحساب",rationale:"قال: solo puedo dar esa información al titular de la cuenta. القرابة لوحدها مش صلاحية، حتى لو النية كويسة."},{q:"إيه الحل اللي الموظف اقترحه؟",options:["تبعت صورة بطاقته على واتساب","الأب يتصل بنفسه أو يعمل تصريح مكتوب","تقول الرقم السري بتاعه","مفيش أي حل"],answer:"الأب يتصل بنفسه أو يعمل تصريح مكتوب",rationale:"قال: tiene que llamar él, o autorizarle por escrito. autorizar por escrito = تصريح مكتوب. دي قنوات قانونية معروفة."}],responseTask:{prompt:"متصلة بتسأل عن رصيد حساب والدها. اشرح لها بالإسباني بأدب إن المعلومة دي لصاحب الحساب بس، واقترح حل.",acceptable:["Lo siento, pero solo puedo dar esa información al titular de la cuenta.","Lo entiendo, pero por seguridad solo hablo de la cuenta con el titular.","Siento decirle que esa información solo se la puedo dar al titular. Que llame él, por favor.","Por seguridad, no puedo dar datos de la cuenta a otra persona. Tiene que llamar él o autorizarle por escrito."],modelEs:"Lo siento, pero solo puedo dar esa información al titular de la cuenta.",modelAr:"أنا آسف، بس أقدر أدي المعلومة دي لصاحب الحساب بس.",checklistAr:"راجع إجابتك: ١) فيها اعتذار أو تفهم (Lo siento / Lo entiendo)، ٢) السبب واضح (titular / seguridad)، ٣) عرضت بديل عملي. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"por seguridad = للأمان. autorizarle por escrito = يعمل لك تصريح مكتوب. me ocupo de sus cosas = بتابع مصالحه. لاحظ إن الرفض المهذب بييجي مع سبب وبديل، مش رفض وخلاص."}},{id:"cc-u02l03",courseId:"call-center",unitId:"cc-u02",sourceLessonId:"cc-u02l03",level:"B1",register:"usted",title:"متطلبش أسرار",context:"عميل عرض يقول الرقم السري بتاع كارته عشان يساعدك في التحقق. دورك: توقفه فورًا، توضح إن البيانات دي مش بتتطلب أبدًا، وتشرح طريقة التحقق الآمنة.",goal:"بعد الدرس ده حتقدر تمنع العميل من كشف بيانات حساسة بأدب، وتوجّهه لطريقة تحقق آمنة زي كود على الموبايل.",targets:[{es:"No me lo diga nunca.",ar:"متقولهوليش أبدًا.",speaker:"luna"},{es:"Nadie de la empresa se los va a pedir.",ar:"محدش في الشركة حيطلبهم منك.",speaker:"luna"},{es:"Para comprobar su identidad uso el correo o un código que le mando al móvil.",ar:"عشان أتأكد من حضرتك بستخدم الإيميل أو كود ببعته على الموبايل.",speaker:"luna"},{es:"Ya está verificado.",ar:"كده اتأكدنا.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Quiere el PIN de mi tarjeta para comprobarlo?",ar:"عايزة الرقم السري بتاع الكارت عشان تتأكدي؟"},{speaker:"luna",es:"No. No me lo diga nunca. Ni el PIN ni la contraseña. Nadie de la empresa se los va a pedir.",ar:"لأ، متقولهوليش أبدًا. لا الرقم السري ولا كلمة السر. محدش في الشركة حيطلبهم منك."},{speaker:"paco",es:"Ah, ¿no? Pensaba que sí.",ar:"أه، لأ؟ كنت فاكر أيوه."},{speaker:"luna",es:"No. Para comprobar su identidad uso el correo o un código que le mando al móvil.",ar:"لأ. عشان أتأكد من حضرتك بستخدم الإيميل أو كود ببعته على الموبايل."},{speaker:"paco",es:"Vale, mándeme el código.",ar:"تمام، ابعتيلي الكود."},{speaker:"luna",es:"Ya le llegó. ¿Me dice los cuatro números?",ar:"كده وصلك. تقوللي الأربع أرقام؟"},{speaker:"paco",es:"Siete, cero, tres, nueve.",ar:"٧٠٣٩."},{speaker:"luna",es:"Correcto. Ya está verificado.",ar:"صح. كده اتأكدنا."}],questions:[{q:"العميل عرض يقول إيه من تلقاء نفسه؟",options:["كلمة سر حسابه","عنوانه","الرقم السري بتاع الكارت","رقم حسابه البنكي"],answer:"الرقم السري بتاع الكارت",rationale:"سأل: ¿Quiere mi PIN de la tarjeta? — PIN = الرقم السري. الموظفة وقفته فورًا."},{q:"الموظفة بتتأكد من الهوية إزاي؟",options:["بصورة من البطاقة","بسؤال عن اسم الأم","ببصمة الصوت","بكود على الموبايل أو بالإيميل"],answer:"بكود على الموبايل أو بالإيميل",rationale:"قالت: uso el correo o un código que le mando al móvil. comprobar la identidad = يتأكد من الهوية."},{q:"عميل عايز يقولك الرقم السري بتاع كارته. إيه التصرف الصح؟",options:["توقفه فورًا وتوضح إن محدش في الشركة بيطلب الرقم ده","تسمعه بس متكتبهوش","تطلب منه يبعته في رسالة","تاخده وتسجله في الملاحظات"],answer:"توقفه فورًا وتوضح إن محدش في الشركة بيطلب الرقم ده",rationale:"قول الرقم السري حتى للموظف بيكسر الأمان. No me lo diga nunca + شرح البديل الآمن هو التصرف الصح."}],responseTask:{prompt:"عميل بدأ يقول الرقم السري بتاعه. وقّفه بأدب بالإسباني، ووضح إن البيانات دي مش بتتطلب، وقول إيه البديل الآمن.",acceptable:["No, no me lo diga nunca. Ni el PIN ni la contraseña. Nadie de la empresa se los va a pedir.","No me diga el PIN, por favor. Nadie de la empresa se lo va a pedir. Para verificarle le mando un código al móvil.","No, por seguridad no me diga ese número. Le verifico con un código al móvil.","No hace falta el PIN. Le mando un código al móvil para comprobar su identidad."],modelEs:"No, no me lo diga nunca. Ni el PIN ni la contraseña. Nadie de la empresa se los va a pedir.",modelAr:"لأ، متقولهوليش أبدًا. لا الرقم السري ولا كلمة السر. محدش في الشركة حيطلبهم منك.",checklistAr:"راجع إجابتك: ١) وقفته فورًا (No me lo diga)، ٢) وضحت إن البيانات دي مش بتتطلب أبدًا، ٣) عرضت بديل آمن (código al móvil / correo). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"ni… ni = لا… ولا. se los va a pedir: los بتشاور على الـ PIN وكلمة السر. verificar / comprobar la identidad = التحقق من الهوية. no hace falta = مش مطلوب."}},{id:"cc-u02l04",courseId:"call-center",unitId:"cc-u02",sourceLessonId:null,level:"B1",register:"usted",title:"العميل بيقول بيانات كارته لوحده",context:"عميل بدأ يملي رقم كارته كامل من غير ما حد يسأله. دورك: تقاطعه بأدب قبل ما يكمل، وتوضح إن بيانات الكارت مش مطلوبة ومش بتظهر ليك أصلًا.",goal:"بعد الدرس ده حتقدر تقاطع العميل بأدب لحمايته، وتوضح إيه البيانات اللي بتكفي للمراجعة.",targets:[{es:"Perdone que le corte.",ar:"آسفة إني بقاطعك.",speaker:"luna"},{es:"No me dé el número completo de la tarjeta.",ar:"متدينيش رقم الكارت كامل.",speaker:"luna"},{es:"Con el número de pedido y su correo es suficiente.",ar:"برقم الطلب والإيميل كفاية.",speaker:"luna"},{es:"Ya veo el pago.",ar:"كده شايفة الدفع.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Le doy el número de mi tarjeta: cinco, tres…",ar:"حأقولك رقم الكارت بتاعي: خمسة، تلاتة…"},{speaker:"luna",es:"Perdone que le corte. No me dé el número completo de la tarjeta. No lo necesito.",ar:"آسفة إني بقاطعك. متدينيش رقم الكارت كامل. مش محتاجاه."},{speaker:"paco",es:"¿Ah, no? ¿Y cómo comprueba el pago?",ar:"أه، لأ؟ وحتتأكدي من الدفع إزاي؟"},{speaker:"luna",es:"Con el número de pedido y su correo es suficiente. Los datos de la tarjeta no los veo yo.",ar:"برقم الطلب والإيميل كفاية. بيانات الكارت أنا مش بشوفها أصلًا."},{speaker:"paco",es:"Vale, entonces el pedido es el cuatro, cinco, ocho, dos, tres.",ar:"تمام، يبقى الطلب هو ٤٥٨٢٣."},{speaker:"luna",es:"Gracias. Un momento… Ya veo el pago.",ar:"شكرًا. لحظة واحدة… كده شايفة الدفع."}],questions:[{q:"الموظفة قاطعت العميل ليه؟",options:["عشان الخط بيفصل","عشان بدأ يقول رقم كارته كامل","عشان مش سامعاه","عشان المكالمة طالت"],answer:"عشان بدأ يقول رقم كارته كامل",rationale:"قاطعته بـ Perdone que le corte أول ما بدأ يقول أرقام الكارت. المقاطعة هنا حماية للعميل مش قلة ذوق."},{q:"الموظفة بتقدر تتأكد من الدفع بإيه؟",options:["رقم الكارت كامل","صورة من الكارت","رقم الطلب والإيميل","تاريخ ميلاد العميل"],answer:"رقم الطلب والإيميل",rationale:"قالت: Con el número de pedido y su correo es suficiente = برقم الطلب والإيميل كفاية. es suficiente = كفاية."},{q:"عميل بيملي بيانات حساسة من غير ما حد يسأله. التصرف الصح؟",options:["تسجّلها بسرعة قبل ما يغيّر رأيه","تطلب منه يعيدها ببطء","تسكت وتسمع","توقفه بأدب وتوضح إنك مش محتاج البيانات دي"],answer:"توقفه بأدب وتوضح إنك مش محتاج البيانات دي",rationale:"الموظف مش المفروض يستقبل بيانات كارت كاملة في مكالمة. المقاطعة المهذبة + توضيح البديل بتحمي العميل وشركتك."}],responseTask:{prompt:"عميل بدأ يقول رقم كارته كامل. وقّفه بأدب بالإسباني ووضح إيه اللي يكفي للمراجعة.",acceptable:["Perdone que le corte. No me dé el número completo de la tarjeta. No lo necesito.","No me dé el número de la tarjeta, por favor. Con el número de pedido es suficiente.","Perdone, un momento. No necesito los datos de la tarjeta, solo el número de pedido.","Le corto un segundo: no me dé datos de la tarjeta. Con su correo y el pedido me vale."],modelEs:"Perdone que le corte. No me dé el número completo de la tarjeta. No lo necesito.",modelAr:"آسفة إني بقاطعك. متدينيش رقم الكارت كامل. مش محتاجاه.",checklistAr:"راجع إجابتك: ١) اعتذار عن المقاطعة (Perdone que le corte)، ٢) منع واضح لبيانات الكارت (no me dé…)، ٣) توضيح البديل (número de pedido / correo). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Perdone que le corte = آسف إني بقاطع حضرتك، cortar هنا = يقاطع. es suficiente = كفاية. me vale = بتكفيني، تعبير إسباني شائع ومهذب."}},{id:"cc-u02l05",courseId:"call-center",unitId:"cc-u02",sourceLessonId:null,level:"B1",register:"usted",title:"زعلان من أسئلة التحقق",context:"عميل متضايق لأنه اتسأل أسئلة تحقق إمبارح، والنهارده بيتسأل تاني. دورك: تتفهم ضيقه، تشرح إن الأسئلة لحمايته، وتقلل عددها لأقل حاجة ممكنة.",goal:"بعد الدرس ده حتقدر تبرر أسئلة التحقق من غير ما تخلي العميل يحس إنه متهم، وتخلّص التحقق بسرعة.",targets:[{es:"Es por la seguridad de su cuenta.",ar:"ده عشان أمان حساب حضرتك.",speaker:"luna"},{es:"Solo dos cosas rápidas.",ar:"حاجتين بسرعة بس.",speaker:"luna"},{es:"Ya está.",ar:"كده خلصنا.",speaker:"luna"},{es:"Gracias, de verdad.",ar:"شكرًا، بجد.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Otra vez preguntas? ¡Si llamé ayer y ya me lo preguntaron todo!",ar:"أسئلة تاني؟ أنا كلمتكم إمبارح واتسألت كل حاجة!"},{speaker:"luna",es:"Tiene razón. Sé que es un momento pesado. Es por la seguridad de su cuenta.",ar:"مع حضرتك حق. عارفة إنها لحظة تقيلة. ده عشان أمان حساب حضرتك."},{speaker:"paco",es:"Bueno… está bien. Pregunte.",ar:"طيب… ماشي. اسألي."},{speaker:"luna",es:"Solo dos cosas rápidas. Su código postal y el correo de la cuenta.",ar:"حاجتين بسرعة بس: الكود البريدي بتاع حضرتك والإيميل بتاع الحساب."},{speaker:"paco",es:"El código es dos, ocho, cero, cero, cuatro. Y el correo, paco punto martin arroba correo punto es.",ar:"الكود ٢٨٠٠٤. والإيميل paco نقطة martin آت correo نقطة es."},{speaker:"luna",es:"Perfecto. Ya está. Gracias, de verdad. Sé que molesta.",ar:"تمام. كده خلصنا. شكرًا، بجد. عارفة إن الموضوع مضايقك."}],questions:[{q:"العميل متضايق من إيه؟",options:["من أسئلة التحقق المتكررة","من سعر الخدمة","من صوت الموظفة","من الانتظار على الخط"],answer:"من أسئلة التحقق المتكررة",rationale:"قال: ¿Otra vez preguntas? = أسئلة تاني؟ وقال إنه اتصل إمبارح واتسأل كل حاجة. otra vez = تاني/مرة كمان."},{q:"الموظفة بررت الأسئلة بإيه؟",options:["سياسة جديدة","أمان حساب العميل","طلب من المدير","مشكلة في النظام"],answer:"أمان حساب العميل",rationale:"قالت: es por la seguridad de su cuenta = ده عشان أمان حساب حضرتك. seguridad = أمان."},{q:"كام حاجة طلبتها الموظفة للتحقق؟",options:["حاجة واحدة","تلاتة","حاجتين","أربعة"],answer:"حاجتين",rationale:"قالت: Solo dos cosas rápidas — الكود البريدي والإيميل. التقليل لأقل بيانات بيحترم وقت العميل."}],responseTask:{prompt:"عميل متضايق من أسئلة التحقق المتكررة. طمنه بالإسباني إن الأسئلة لحمايته، ووضح إنها حاجتين بسرعة بس.",acceptable:["Tiene razón, y es un momento pesado, lo sé. Pero es por la seguridad de su cuenta. Solo dos cosas rápidas.","Lo entiendo, es pesado, lo sé. Pero es por su seguridad. Solo dos preguntas rápidas.","Le entiendo. Es por la seguridad de su cuenta, y solo le pregunto dos cosas.","Sé que molesta, pero es por su seguridad. Son solo dos cosas rápidas."],modelEs:"Tiene razón, y es un momento pesado, lo sé. Pero es por la seguridad de su cuenta. Solo dos cosas rápidas.",modelAr:"مع حضرتك حق، وأنا عارفة إنها لحظة تقيلة. بس ده عشان أمان حساب حضرتك. حاجتين بسرعة بس.",checklistAr:"راجع إجابتك: ١) فيها تفهم أو اعتراف بحق العميل، ٢) سبب واضح (seguridad de su cuenta)، ٣) وعد بسرعة (solo dos cosas rápidas). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"pesado هنا وصف للموقف: تقيل/مضايق. lo sé = أنا عارف(ة). molestar = يضايق. Solo dos cosas rápidas بيطمن العميل إن الموضوع مش حيطول."}},{id:"cc-u02l06",courseId:"call-center",unitId:"cc-u02",sourceLessonId:null,level:"B1",register:"usted",title:"تحقق كامل من الأول للآخر",context:"عميلة عايزة تغيّر الإيميل بتاع حسابها، ومش فاكرة الإيميل القديم. دورك: تمشي في التحقق خطوة خطوة، وتلاقي بديل آمن لما البيانات مش متوفرة، من غير ما تطلب أسرار.",goal:"درس مراجعة: حتجمع خطوات التحقق في مكالمة واحدة، من طلب الاسم لحد تأكيد الهوية بكود الموبايل.",targets:[{es:"Antes de cambiar nada, necesito confirmar que es usted la titular.",ar:"قبل ما أغيّر أي حاجة، محتاج أتأكد إن حضرتك صاحبة الحساب.",speaker:"paco"},{es:"No me acuerdo bien.",ar:"مش فاكراه كويس.",speaker:"luna"},{es:"No pasa nada.",ar:"ولا يهمك.",speaker:"paco"},{es:"Le mando un código al móvil que tenemos registrado.",ar:"حبعتلك كود على الموبايل المسجل عندنا.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenos días, le atiende Paco. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك باكو. أقدر أساعد حضرتك في إيه؟"},{speaker:"luna",es:"Hola, quiero cambiar el correo de mi cuenta.",ar:"أهلًا، عايزة أغيّر الإيميل بتاع حسابي."},{speaker:"paco",es:"Claro. Antes de cambiar nada, necesito confirmar que es usted la titular.",ar:"طبعًا. قبل ما أغيّر أي حاجة، محتاج أتأكد إن حضرتك صاحبة الحساب."},{speaker:"luna",es:"Sí, soy Luna García.",ar:"أيوه، أنا لونا جارسيا."},{speaker:"paco",es:"Gracias. ¿Me confirma el correo actual de la cuenta?",ar:"شكرًا. تأكديلي الإيميل الحالي بتاع الحساب؟"},{speaker:"luna",es:"Es que… No me acuerdo bien.",ar:"المشكلة إني مش فاكراه كويس…"},{speaker:"paco",es:"No pasa nada. Le mando un código al móvil que tenemos registrado. Me dice los cuatro números cuando le llegue.",ar:"ولا يهمك. حبعتلك كود على الموبايل المسجل عندنا. تقوليلي الأربع أرقام لما يوصلك."},{speaker:"luna",es:"Ya llegó: dos, cinco, uno, ocho.",ar:"وصل: ٢٥١٨."},{speaker:"paco",es:"Correcto. Ya está verificada su identidad. Ahora sí, cambiamos el correo.",ar:"صح. كده الهوية اتأكدت. دلوقتي نغيّر الإيميل."}],questions:[{q:"العميلة عايزة تعمل إيه؟",options:["تفتح حساب جديد","تقفل حسابها","تشتكي من كود","تغيّر الإيميل بتاع حسابها"],answer:"تغيّر الإيميل بتاع حسابها",rationale:"قالت: quiero cambiar el correo de mi cuenta = عايزة أغيّر الإيميل بتاع حسابي. cambiar = يغيّر."},{q:"لما العميلة مش فاكرة الإيميل، الموظف عمل إيه؟",options:["بعت كود على الموبايل المسجل","سألها عن كلمة السر","طلب رقم كارتها","قفل المكالمة"],answer:"بعت كود على الموبايل المسجل",rationale:"قال: Le mando un código al móvil que tenemos registrado = حبعتلك كود على الموبايل المسجل عندنا. registrado = مسجل."},{q:"عميل مش فاكر بيانات التحقق. إيه البديل الآمن؟",options:["نسأله سؤال سهل ونعدّيه","نبعت كود على وسيلة مسجلة عندنا","نلغي التحقق لو كان مهذب","نديله تلت محاولات يخمّن"],answer:"نبعت كود على وسيلة مسجلة عندنا",rationale:"الكود على الموبايل المسجل بيثبت إن اللي ماسك التليفون هو صاحب الحساب فعلًا. التخمين أو إلغاء التحقق بيفتح باب للتحايل."}],responseTask:{prompt:"عميلة مش فاكرة الإيميل المسجل. طمنها بالإسباني واعرض بديل تحقق آمن.",acceptable:["No pasa nada. Le mando un código al móvil que tenemos registrado y me dice los cuatro números.","No se preocupe. Le envío un código al móvil registrado y me dice los números.","Tranquila. Podemos verificarlo con un código al móvil.","No pasa nada, hay otra forma: le mando un código al móvil."],modelEs:"No pasa nada. Le mando un código al móvil que tenemos registrado y me dice los cuatro números.",modelAr:"ولا يهمك. حبعتلك كود على الموبايل المسجل عندنا وتقوليلي الأربع أرقام.",checklistAr:"راجع إجابتك: ١) فيها طمأنة (No pasa nada / No se preocupe / Tranquila)، ٢) عرضت بديل تحقق آمن (código al móvil)، ٣) مفيش طلب أسرار. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"no pasa nada = ولا يهمك / مفيش مشكلة. registrado = مسجل. acordarse = يفتكر، فـ No me acuerdo = مش فاكر(ة). tranquila للست وtranquilo للراجل."}}]},{courseId:"call-center",unit:{id:"cc-u03",title:"فهم المشكلة وتأكيد التفاصيل",desc:"تسمع المشكلة من غير افتراض، تسأل عن البداية والتوقيت والجهاز، وتعيد المعنى للتأكيد.",cefr:"A2–B1"},lessons:[{id:"cc-u03l01",courseId:"call-center",unitId:"cc-u03",sourceLessonId:"cc-u03l01",level:"A2",register:"usted",title:"إيه المشكلة بالظبط؟",context:"عميل متصل عشان النت عنده بطيء. دورك: تسأل أسئلة مفتوحة تفهم بيها المشكلة بالظبط، من غير ما تفترض سبب.",goal:"بعد الدرس ده حتقدر تسأل عن المشكلة بشكل مفتوح، وتعرف تفاصيل زي التوقيت اللي بتحصل فيه.",targets:[{es:"Es que mi internet va muy lento.",ar:"المشكلة إن النت عندي بطيء جدًا",speaker:"paco"},{es:"¿Me cuenta qué pasa exactamente?",ar:"احكيلي بيحصل إيه بالظبط؟",speaker:"luna"},{es:"Las páginas tardan mucho en abrir.",ar:"الصفحات بتاخد وقت كبير عشان تفتح",speaker:"paco"},{es:"¿Le pasa todo el día o a ciertas horas?",ar:"بيحصل مع حضرتك طول اليوم ولا في ساعات معينة؟",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola. Es que mi internet va muy lento.",ar:"أهلًا. المشكلة إن النت عندي بطيء جدًا."},{speaker:"luna",es:"Entiendo. ¿Me cuenta qué pasa exactamente?",ar:"فاهمة حضرتك. احكيلي بيحصل إيه بالظبط؟"},{speaker:"paco",es:"Pues, mire. Las páginas tardan mucho en abrir. Y el vídeo se corta.",ar:"يعني بصي حضرتك. الصفحات بتاخد وقت كبير عشان تفتح. والفيديو بيقطع."},{speaker:"luna",es:"Vale. ¿Le pasa todo el día o a ciertas horas?",ar:"تمام. بيحصل مع حضرتك طول اليوم ولا في ساعات معينة؟"},{speaker:"paco",es:"Sobre todo por la tarde.",ar:"أكتر حاجة العصر."},{speaker:"luna",es:"Perfecto, eso me ayuda. Lo apunto en su caso.",ar:"جميل، ده بيساعدني. حدوّنه في ملف حضرتك."}],questions:[{q:"شكوى العميل إيه؟",options:["النت قاطع خالص","النت بطيء","الفاتورة غالية","الراوتر مش بيشتغل"],answer:"النت بطيء",rationale:"قال: mi internet va muy lento = النت بطيء جدًا. مفيش قطع كامل (no funciona) ولا كلام عن فاتورة."},{q:"الموظفة عرفت إيه عن توقيت المشكلة؟",options:["بتحصل أكتر حاجة العصر","بتحصل بالليل بس","بتحصل طول اليوم","بتحصل الصبح بس"],answer:"بتحصل أكتر حاجة العصر",rationale:"العميل قال: Sobre todo por la tarde = أكتر حاجة العصر. sobre todo = أكتر حاجة / خصوصًا."},{q:"أول ما العميل يقول مشكلته، إيه أحسن رد؟",options:["تقترح حل فوري قبل ما تسمع التفاصيل","تقوله دي مشكلة معروفة ومتسألش أكتر","تحوّله على طول للقسم الفني","تسأل أسئلة مفتوحة تفهم بيها المشكلة بالظبط"],answer:"تسأل أسئلة مفتوحة تفهم بيها المشكلة بالظبط",rationale:"¿Me cuenta qué pasa exactamente? — السؤال المفتوح بيخلّي العميل يشرح، والحل من غير فهم ممكن يكون غلط."}],responseTask:{prompt:"عميل قال: «النت عندي بطيء». اسأله سؤالين بالإسباني يفهموك المشكلة أكتر.",acceptable:["¿Me cuenta qué pasa exactamente? ¿Le pasa todo el día o a ciertas horas?","¿Qué pasa exactamente? ¿Desde cuándo le pasa?","¿Me explica qué pasa? ¿En qué momentos va lento?","¿Qué es lo que no funciona bien? ¿Le pasa siempre?"],modelEs:"¿Me cuenta qué pasa exactamente? ¿Le pasa todo el día o a ciertas horas?",modelAr:"احكيلي بيحصل إيه بالظبط؟ بيحصل مع حضرتك طول اليوم ولا في ساعات معينة؟",checklistAr:"راجع إجابتك: ١) سؤال مفتوح عن المشكلة (qué pasa / cómo)، ٢) سؤال عن الوقت أو التكرار (cuándo / todo el día)، ٣) مفيش حكم مسبق على السبب. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"exactamente = بالظبط. a ciertas horas = في ساعات معينة. tardar en = ياخد وقت في. se corta = بيقطع (للفيديو والمكالمات)."}},{id:"cc-u03l02",courseId:"call-center",unitId:"cc-u03",sourceLessonId:"cc-u03l02",level:"A2",register:"usted",title:"من إمتى؟",context:"عميلة متصلة عشان الواي فاي بيفصل كتير. دورك: تعرف بداية المشكلة وتوقيتها، وتربطها بأي تغيير حصل في البيت.",goal:"بعد الدرس ده حتقدر تسأل «من إمتى؟» بصيغة حضرتك، وتسأل عن تغييرات حصلت وقت بداية المشكلة.",targets:[{es:"El wifi se me corta mucho.",ar:"الواي فاي بيفصل مني كتير",speaker:"luna"},{es:"¿Desde cuándo le pasa?",ar:"من إمتى بيحصل مع حضرتك؟",speaker:"paco"},{es:"Desde el martes, más o menos.",ar:"من يوم التلات، تقريبًا.",speaker:"luna"},{es:"Eso es una pista.",ar:"ده خيط مهم",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenas tardes, le atiende Paco. ¿En qué puedo ayudarle?",ar:"مساء الخير، مع حضرتك باكو. أقدر أساعد حضرتك في إيه؟"},{speaker:"luna",es:"Hola. El wifi se me corta mucho.",ar:"أهلًا. الواي فاي بيفصل مني كتير."},{speaker:"paco",es:"Lo siento. ¿Desde cuándo le pasa?",ar:"أنا آسف. من إمتى بيحصل مع حضرتك؟"},{speaker:"luna",es:"Desde el martes, más o menos.",ar:"من يوم التلات، تقريبًا."},{speaker:"paco",es:"¿Y se corta a la misma hora o en cualquier momento?",ar:"وبيفصل في نفس الساعة ولا في أي وقت؟"},{speaker:"luna",es:"En cualquier momento, incluso de noche.",ar:"في أي وقت، حتى بالليل."},{speaker:"paco",es:"De acuerdo. ¿Cambió algo en casa el martes? ¿Un mueble, un aparato nuevo?",ar:"ماشي. حاجة اتغيّرت في البيت يوم التلات؟ قطعة عفش؟ جهاز جديد؟"},{speaker:"luna",es:"Pues sí, pusimos una tele nueva.",ar:"أيوه فعلًا، ركّبنا تليفزيون جديد."},{speaker:"paco",es:"Perfecto. Eso es una pista. Lo apunto y lo revisamos.",ar:"جميل. ده خيط مهم. حدوّنه ونراجع الموضوع."}],questions:[{q:"المشكلة بدأت إمتى؟",options:["من يوم التلات تقريبًا","من أسبوعين","من الصبح","من شهر"],answer:"من يوم التلات تقريبًا",rationale:"قالت: Desde el martes, más o menos = من يوم التلات تقريبًا. desde = من، y más o menos = تقريبًا."},{q:"إيه التغيير اللي حصل في البيت؟",options:["راوتر جديد","نقلوا الراوتر لمكان تاني","تليفزيون جديد","جددوا العقد"],answer:"تليفزيون جديد",rationale:"قالت: pusimos una tele nueva = ركّبنا تليفزيون جديد. poner هنا = يركّب/يحط. الأجهزة الجديدة ممكن تسبب تشويش على الواي فاي."},{q:"«¿Desde cuándo le pasa?» بتسأل عن إيه؟",options:["من إمتى والمشكلة بتحصل","المشكلة بتحصل فين","المشكلة بتحصل ليه","المشكلة بتحصل مع مين"],answer:"من إمتى والمشكلة بتحصل",rationale:"desde cuándo = من إمتى. لو عايز تسأل ليه تقول ¿por qué? ولو فين ¿dónde?."}],responseTask:{prompt:"عميلة قالت: «الواي فاي بيفصل كتير». اسألها بالإسباني عن بداية المشكلة وتوقيت حدوثها.",acceptable:["¿Desde cuándo le pasa? ¿Se corta a la misma hora o en cualquier momento?","¿Desde cuándo tiene este problema? ¿Le pasa siempre?","¿Desde cuándo le pasa? ¿Y a qué horas se corta?","¿Cuándo empezó? ¿Le pasa todo el día?"],modelEs:"¿Desde cuándo le pasa? ¿Se corta a la misma hora o en cualquier momento?",modelAr:"من إمتى بيحصل مع حضرتك؟ بيفصل في نفس الساعة ولا في أي وقت؟",checklistAr:"راجع إجابتك: ١) سؤال عن البداية (desde cuándo / cuándo empezó)، ٢) سؤال عن التوقيت أو التكرار، ٣) صيغة حضرتك (le). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"desde cuándo = من إمتى. desde el martes = من يوم التلات. se corta = بيفصل (فعل انعكاسي). cualquier momento = أي وقت. incluso = حتى."}},{id:"cc-u03l03",courseId:"call-center",unitId:"cc-u03",sourceLessonId:"cc-u03l03",level:"B1",register:"usted",title:"جهاز واحد ولا كل الأجهزة؟",context:"عميل بيقول النت مش شغال على الموبايل. دورك: تحدد إذا كانت المشكلة في جهاز واحد ولا في الخط نفسه، عشان تعرف تبدأ منين.",goal:"بعد الدرس ده حتقدر تفرّق بين مشكلة في جهاز واحد ومشكلة في الخط كله، وتسأل عن الواي فاي والبيانات.",targets:[{es:"No me va internet en el móvil.",ar:"النت مش شغال عندي على الموبايل",speaker:"paco"},{es:"¿Y en el ordenador o la tele le funciona bien?",ar:"وعلى الكمبيوتر أو التليفزيون شغال مع حضرتك كويس؟",speaker:"luna"},{es:"El problema es solo en el móvil.",ar:"المشكلة في الموبايل بس",speaker:"luna"},{es:"Con eso ya sé por dónde empezar.",ar:"كده عرفت أبدأ منين.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola. No me va internet en el móvil.",ar:"أهلًا. النت مش شغال عندي على الموبايل."},{speaker:"luna",es:"Vale. ¿Y en el ordenador o la tele le funciona bien?",ar:"تمام. وعلى الكمبيوتر أو التليفزيون شغال مع حضرتك كويس؟"},{speaker:"paco",es:"Sí, en el ordenador va perfecto.",ar:"أيوه، على الكمبيوتر شغال مية المية."},{speaker:"luna",es:"Entonces, vale. El problema es solo en el móvil. ¿Le pasa con wifi y con datos, o solo con wifi?",ar:"يبقى تمام. المشكلة في الموبايل بس. بيحصل مع الواي فاي وبيانات الموبايل، ولا مع الواي فاي بس؟"},{speaker:"paco",es:"Solo con wifi.",ar:"مع الواي فاي بس."},{speaker:"luna",es:"Perfecto. Con eso ya sé por dónde empezar. Lo vemos juntos.",ar:"جميل. كده عرفت أبدأ منين. نشوفها مع بعض."}],questions:[{q:"النت شغال كويس على أنهي جهاز؟",options:["على الكمبيوتر","على الموبايل","مش شغال على أي جهاز","على التليفزيون بس"],answer:"على الكمبيوتر",rationale:"قال: en el ordenador va perfecto = على الكمبيوتر شغال مية المية. va هنا = شغال، تعبير عامي شائع جدًا."},{q:"المشكلة على الموبايل بتحصل مع إيه؟",options:["مع الواي فاي والبيانات","مع البيانات بس","مع الواي فاي بس","مع الاتنين بالتناوب"],answer:"مع الواي فاي بس",rationale:"قال: Solo con wifi. datos هنا = بيانات الموبايل (باقة النت)، مش بيانات شخصية."},{q:"ليه السؤال عن باقي الأجهزة مهم؟",options:["عشان يقنع العميل يشتري جهاز جديد","عشان يحدد إذا كانت المشكلة في الخط ولا في جهاز واحد","عشان يعرف موديل الموبايل","عشان يقفل المكالمة بسرعة"],answer:"عشان يحدد إذا كانت المشكلة في الخط ولا في جهاز واحد",rationale:"لو كل الأجهزة فيها المشكلة يبقى الخط، ولو جهاز واحد بس يبقى إعدادات الجهاز. ده أول تقسيم في الدعم الفني."}],responseTask:{prompt:"عميل قال: «النت مش شغال على الموبايل». اسأله سؤال واحد بالإسباني يفرّق بين مشكلة في الخط ومشكلة في الجهاز.",acceptable:["¿Y en el ordenador o la tele le funciona bien?","¿Le funciona en otros aparatos, como el ordenador?","¿En el ordenador le va bien?","¿Le pasa solo en el móvil o en todo?"],modelEs:"¿Y en el ordenador o la tele le funciona bien?",modelAr:"وعلى الكمبيوتر أو التليفزيون شغال مع حضرتك كويس؟",checklistAr:"راجع إجابتك: ١) سؤال واحد واضح، ٢) بيقارن بين أجهزة مختلفة، ٣) صيغة حضرتك (le). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"funcionar = يشتغل (للأجهزة والخدمات). no me va = مش شغال عندي، تعبير عامي إسباني مفيد. aparato = جهاز. solo = بس."}},{id:"cc-u03l04",courseId:"call-center",unitId:"cc-u03",sourceLessonId:null,level:"B1",register:"usted",title:"أعيد اللي فهمته",context:"عميلة شرحت مشكلة في التطبيق بشكل سريع. دورك: تعيد اللي فهمته بكلامك وتسألها لو فهمك صح، قبل ما تفتح أي بلاغ.",goal:"بعد الدرس ده حتقدر تستخدم إعادة المعنى للتأكيد، وتسأل «كده صح؟» بأكتر من طريقة.",targets:[{es:"La aplicación se me cierra cuando intento pagar.",ar:"التطبيق بيقفل لما بحاول أدفع",speaker:"luna"},{es:"A ver si le entendí bien.",ar:"نشوف لو أنا فهمتك صح",speaker:"paco"},{es:"¿Es así?",ar:"كده صح؟",speaker:"paco"},{es:"El pago falla solo con la tarjeta nueva.",ar:"الدفع بيفشل مع الكارت الجديد بس",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hola. La aplicación se me cierra cuando intento pagar.",ar:"أهلًا. التطبيق بيقفل مني لما بحاول أدفع."},{speaker:"paco",es:"Vale. A ver si le entendí bien. Abre la aplicación, va a pagar, y en ese momento la aplicación se cierra. ¿Es así?",ar:"تمام. نشوف لو أنا فهمتك صح. بتفتحي التطبيق، بتروحي تدفعي، وفي اللحظة دي التطبيق بيقفل. كده صح؟"},{speaker:"luna",es:"Eso es.",ar:"بالظبط كده."},{speaker:"paco",es:"¿Y le pasa con cualquier tarjeta o con una en concreto?",ar:"وبيحصل مع أي كارت ولا مع كارت معين؟"},{speaker:"luna",es:"Solo con una, la del banco nuevo.",ar:"مع واحد بس، بتاع البنك الجديد."},{speaker:"paco",es:"Perfecto. El pago falla solo con la tarjeta nueva. Y la aplicación se cierra. ¿Correcto?",ar:"جميل. الدفع بيفشل مع الكارت الجديد بس. والتطبيق بيقفل. صح؟"},{speaker:"luna",es:"Correcto.",ar:"صح."},{speaker:"paco",es:"Muy bien. Con eso ya puedo abrir el caso.",ar:"تمام جدًا. كده أقدر أفتح البلاغ."}],questions:[{q:"المشكلة بتحصل إمتى بالظبط؟",options:["عند فتح التطبيق","عند محاولة الدفع","عند تسجيل الدخول","عند تحديث التطبيق"],answer:"عند محاولة الدفع",rationale:"قالت: se me cierra cuando intento pagar = بيقفل لما بحاول أدفع. intentar = يحاول."},{q:"الموظف بيعمل إيه بجملة «A ver si le entendí bien»؟",options:["بيطلب من العميلة تسكت","بيغيّر الموضوع","بيأكد فهمه بإعادة اللي سمعه","بيعتذر عن مشكلة"],answer:"بيأكد فهمه بإعادة اللي سمعه",rationale:"a ver si le entendí bien = نشوف لو فهمتك صح، وبعدها بيعيد المشكلة بكلامه ويسأل ¿es así? = كده صح؟"},{q:"المشكلة مع كام كارت؟",options:["كل الكروت","مفيش كارت شغال","الكارت القديم بس","كارت واحد بس، بتاع البنك الجديد"],answer:"كارت واحد بس، بتاع البنك الجديد",rationale:"قالت: Solo con una, la del banco nuevo = مع واحد بس، بتاع البنك الجديد. en concreto = معين/بالتحديد."}],responseTask:{prompt:"عميلة شرحت مشكلة في التطبيق. أعيد اللي فهمته بالإسباني واسألها لو فهمك صح.",acceptable:["A ver si le entendí bien: abre la aplicación, va a pagar, y en ese momento la aplicación se cierra, ¿es así?","Entonces, si le entendí bien, el pago falla solo con la tarjeta nueva, ¿correcto?","Le repito para confirmar: la aplicación se cierra al pagar, ¿es así?","A ver: abre la aplicación, intenta pagar y se cierra. ¿Es así?"],modelEs:"A ver si le entendí bien: abre la aplicación, va a pagar, y en ese momento la aplicación se cierra, ¿es así?",modelAr:"نشوف لو أنا فهمتك صح: بتفتحي التطبيق، بتروحي تدفعي، وفي اللحظة دي التطبيق بيقفل، كده صح؟",checklistAr:"راجع إجابتك: ١) فيها إعادة للمعنى بكلامك، ٢) بتخلص بسؤال تأكيد (¿es así? / ¿correcto?)، ٣) مفيش تخمين زيادة على اللي اتقال. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"a ver si le entendí bien = نشوف لو فهمتك صح. ¿es así? و¿correcto? = كده صح؟ en concreto = معين/بالتحديد. al + مصدر = عند/لما."}},{id:"cc-u03l05",courseId:"call-center",unitId:"cc-u03",sourceLessonId:null,level:"B1",register:"usted",title:"عميل بيحكي كتير",context:"عميل بدأ يحكي قصة طويلة فيها إشعار من البنك وأخوه المهندس والأسبوع اللي فات. دورك: توجّهه بأدب للمشكلة الرئيسية من غير ما تقاطعه بفظاظة.",goal:"بعد الدرس ده حتقدر تنظّم مكالمة مع عميل كلامه كتير: تعترف إنك سامع، وترجّع الكلام للمشكلة الأساسية بسؤال واحد محدد.",targets:[{es:"Vamos por partes.",ar:"واحدة واحدة.",speaker:"luna"},{es:"¿Cuál es el problema principal hoy?",ar:"إيه المشكلة الرئيسية النهارده؟",speaker:"luna"},{es:"Está sin internet desde esta mañana.",ar:"حضرتك مفيش عندك نت من الصبح.",speaker:"luna"},{es:"Con eso trabajamos.",ar:"كده نقدر نشتغل.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Mire, es que primero me llegó el aviso del banco, luego llamé a mi hermano, que trabaja en informática, y me dijo que igual es el router, y también la semana pasada…",ar:"بصي حضرتك، الأول وصلني إشعار من البنك، وبعدين كلمت أخويا اللي شغال في الكمبيوترات، وقالي يمكن الراوتر، وكمان الأسبوع اللي فات…"},{speaker:"luna",es:"Le entiendo, hay muchas cosas. Vamos por partes. ¿Cuál es el problema principal hoy?",ar:"فاهمة حضرتك، في حاجات كتير. واحدة واحدة. إيه المشكلة الرئيسية النهارده؟"},{speaker:"paco",es:"Que no tengo internet.",ar:"إني مفيش عندي نت."},{speaker:"luna",es:"Vale, ese es el principal. ¿Y desde cuándo?",ar:"تمام، دي الرئيسية. ومن إمتى؟"},{speaker:"paco",es:"Desde esta mañana.",ar:"من الصبح."},{speaker:"luna",es:"Perfecto. Está sin internet desde esta mañana. ¿Algo más que note raro?",ar:"جميل. يبقى حضرتك مفيش عندك نت من الصبح. في حاجة تانية ملاحظاها غريبة؟"},{speaker:"paco",es:"No, solo eso.",ar:"لأ، بس كده."},{speaker:"luna",es:"Muy bien. Con eso trabajamos.",ar:"تمام جدًا. كده نقدر نشتغل."}],questions:[{q:"مشكلة العميل الرئيسية إيه؟",options:["الراوتر بايظ","أخوه مهندس كمبيوتر","البنك بعت إشعار","مفيش نت من الصبح"],answer:"مفيش نت من الصبح",rationale:"لما اتسأل عن المشكلة الرئيسية قال: Que no tengo internet، وبعدين: Desde esta mañana. باقي الكلام كان خلفية مش المشكلة."},{q:"الموظفة نظّمت الكلام إزاي؟",options:["سألت عن المشكلة الرئيسية الأول وبعدين التفاصيل","قفلت المكالمة","طلبت منه يتصل تاني","حوّلته لقسم تاني على طول"],answer:"سألت عن المشكلة الرئيسية الأول وبعدين التفاصيل",rationale:"قالت: Vamos por partes. ¿Cuál es el problema principal hoy? — واحدة واحدة: الأول الرئيسية، وبعدين من إمتى وهل في حاجة تانية."},{q:"«Vamos por partes» معناها إيه؟",options:["هنروح أماكن كتير","هنتكلم في مواضيع كتير","هنقفل دلوقتي","واحدة واحدة"],answer:"واحدة واحدة",rationale:"ir por partes = نمشي جزء جزء / واحدة واحدة. تعبير مفيد جدًا لتنظيم أي مكالمة فيها تفاصيل كتير."}],responseTask:{prompt:"عميل بيحكي قصة طويلة فيها تفاصيل كتير. وجّهه بأدب بالإسباني للمشكلة الرئيسية.",acceptable:["Le entiendo, hay muchas cosas. Vamos por partes. ¿Cuál es el problema principal hoy?","Vale, vamos por partes. ¿Cuál es el problema principal?","Le escucho. Vamos por partes: ¿qué es lo más importante ahora?","Entiendo. Vamos por partes. ¿Cuál es el problema de hoy?"],modelEs:"Le entiendo, hay muchas cosas. Vamos por partes. ¿Cuál es el problema principal hoy?",modelAr:"فاهمة حضرتك، في حاجات كتير. واحدة واحدة. إيه المشكلة الرئيسية النهارده؟",checklistAr:"راجع إجابتك: ١) اعتراف إنك سامع (Le entiendo / Le escucho)، ٢) vamos por partes أو ما يعادلها، ٣) سؤال واحد محدد عن المشكلة الرئيسية. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"vamos por partes = واحدة واحدة. principal = رئيسية. notar = يلاحظ. raro = غريب. algo más = حاجة تانية."}},{id:"cc-u03l06",courseId:"call-center",unitId:"cc-u03",sourceLessonId:null,level:"B1",register:"usted",title:"استقبال مشكلة كامل",context:"مكالمة كاملة من أولها: عميلة بتشتكي من نت بطيء. دورك: تجمع كل أسئلة الوحدة في مكالمة واحدة: المشكلة بالظبط، من إمتى، على أنهي جهاز، في أنهي وقت، وبعدين تأكيد بالمعنى وفتح بلاغ.",goal:"درس مراجعة: حتجمع أسئلة فهم المشكلة في تسلسل واحد طبيعي، وتخلّص بتأكيد وبلاغ.",targets:[{es:"Tarda mucho en cargar cualquier página.",ar:"بياخد وقت كبير عشان يحمل أي صفحة",speaker:"luna"},{es:"¿Le pasa en todos los aparatos o solo en uno?",ar:"بيحصل على كل الأجهزة ولا على جهاز واحد بس؟",speaker:"paco"},{es:"A ver si le entendí bien.",ar:"نشوف لو أنا فهمتك صح",speaker:"paco"},{es:"Abro su caso ahora mismo.",ar:"حفتح البلاغ بتاع حضرتك دلوقتي حالًا.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"Buenas tardes, le atiende Paco. ¿En qué puedo ayudarle?",ar:"مساء الخير، مع حضرتك باكو. أقدر أساعد حضرتك في إيه؟"},{speaker:"luna",es:"Hola, mi internet va lento.",ar:"أهلًا، النت عندي بطيء."},{speaker:"paco",es:"Lo siento. ¿Me cuenta qué pasa exactamente? ¿Desde cuándo le pasa?",ar:"أنا آسف. احكيلي بيحصل إيه بالظبط؟ ومن إمتى بيحصل مع حضرتك؟"},{speaker:"luna",es:"Pues, mire. Tarda mucho en cargar cualquier página. Desde el lunes.",ar:"يعني بص حضرتك. بياخد وقت كبير عشان يحمل أي صفحة. من يوم الاتنين."},{speaker:"paco",es:"¿Le pasa en todos los aparatos o solo en uno?",ar:"بيحصل على كل الأجهزة ولا على جهاز واحد بس؟"},{speaker:"luna",es:"Solo en la tele, y sobre todo por la noche.",ar:"على التليفزيون بس، وأكتر حاجة بالليل."},{speaker:"paco",es:"Perfecto. A ver si le entendí bien. Desde el lunes, internet va lento solo en la tele y sobre todo por la noche. ¿Es así?",ar:"جميل. نشوف لو أنا فهمتك صح. من يوم الاتنين، النت بطيء على التليفزيون بس وأكتر حاجة بالليل. كده صح؟"},{speaker:"luna",es:"Eso es.",ar:"بالظبط كده."},{speaker:"paco",es:"Muy bien. Abro su caso ahora mismo.",ar:"تمام جدًا. حفتح البلاغ بتاع حضرتك دلوقتي حالًا."}],questions:[{q:"المشكلة موجودة على أنهي جهاز؟",options:["كل الأجهزة","التليفزيون بس","الموبايل بس","الكمبيوتر والموبايل"],answer:"التليفزيون بس",rationale:"قالت: Solo en la tele = على التليفزيون بس. aparato = جهاز، وla tele = التليفزيون."},{q:"المشكلة بتبان أكتر إمتى؟",options:["الصبح","الضهر","مفيش وقت معين","بالليل"],answer:"بالليل",rationale:"قالت: sobre todo por la noche = أكتر حاجة بالليل. por la noche = بالليل."},{q:"بعد ما جمعت التفاصيل، إيه الخطوة اللي قبل فتح البلاغ؟",options:["تعيد المعنى وتأكد مع العميل إن فهمك صح","تفتح البلاغ على طول من غير تأكيد","تقول للعميل جرّب الحلول المعروفة","تطلب منه يتصل بكرة"],answer:"تعيد المعنى وتأكد مع العميل إن فهمك صح",rationale:"الموظف قال: A ver si le entendí bien… ¿es así? — التأكيد قبل فتح البلاغ بيمنع بلاغات غلط ومكالمات متكررة."}],responseTask:{prompt:"لخّص بالإسباني مشكلة العميلة وأكدها معاها: نت بطيء من يوم الاتنين، على التليفزيون بس، وأكتر بالليل.",acceptable:["A ver si le entendí bien: desde el lunes, internet va lento solo en la tele y sobre todo por la noche, ¿es así?","Entonces: desde el lunes, lento solo en la tele y por la noche, ¿correcto?","Le repito: desde el lunes va lento en la tele, sobre todo por la noche, ¿es así?","Si no me equivoco: desde el lunes, lento en la tele, sobre todo de noche, ¿verdad?"],modelEs:"A ver si le entendí bien: desde el lunes, internet va lento solo en la tele y sobre todo por la noche, ¿es así?",modelAr:"نشوف لو فهمتك صح: من يوم الاتنين، النت بطيء على التليفزيون بس وأكتر حاجة بالليل، كده صح؟",checklistAr:"راجع إجابتك: ١) لخّصت البداية (desde el lunes)، ٢) والجهاز (solo en la tele)، ٣) والوقت (por la noche)، ٤) وخلّصت بسؤال تأكيد. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"sobre todo = أكتر حاجة. si no me equivoco = لو أنا مش غلطان. cargar = يحمل (للصفحات). abrir un caso = يفتح بلاغ."}}]},{courseId:"call-center",unit:{id:"cc-u04",title:"خطوات الحل مع العميل",desc:"تدي خطوة بسيطة وواضحة، تتابع نتيجتها، ومتفترضش نجاحها ومتلومش العميل لو فشلت.",cefr:"B1"},lessons:[{id:"cc-u04l01",courseId:"call-center",unitId:"cc-u04",sourceLessonId:"cc-u04l01",level:"B1",register:"usted",title:"نجرب خطوة خطوة",context:"عميل عنده مشكلة في النت. دورك: تبدأ بأبسط خطوة، إعادة تشغيل الراوتر، وتشرحها بالتفصيل من غير افتراض إن العميل عارف.",goal:"بعد الدرس ده حتقدر توجّه العميل لإعادة تشغيل الراوتر بأوامر مهذبة وواضحة، وتقوله يستنى لحد متى قبل ما يجرب.",targets:[{es:"Vamos a probar una cosa sencilla primero.",ar:"حنجرب حاجة بسيطة الأول",speaker:"luna"},{es:"Apáguelo con el botón de atrás",ar:"اطفيّه من الزرار اللي ورا",speaker:"luna"},{es:"Espere a que las luces se pongan fijas.",ar:"استنى لحد ما اللمبات تثبت",speaker:"luna"},{es:"Pruebe a abrir una página y me cuenta.",ar:"جرب تفتح صفحة واحكيلي",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Vale. Vamos a probar una cosa sencilla primero. ¿Ve el router?",ar:"تمام. حنجرب حاجة بسيطة الأول. شايف الراوتر؟"},{speaker:"paco",es:"Sí, lo tengo delante.",ar:"أيوه، قدامي."},{speaker:"luna",es:"Perfecto. Apáguelo con el botón de atrás y espere diez segundos.",ar:"جميل. اطفيّه من الزرار اللي ورا واستنى عشر ثواني."},{speaker:"paco",es:"Ya está apagado.",ar:"كده طفي."},{speaker:"luna",es:"Muy bien. Ahora enciéndalo. Espere a que las luces se pongan fijas.",ar:"تمام جدًا. دلوقتي شغّله. استنى لحد ما اللمبات تثبت."},{speaker:"paco",es:"Ya están fijas.",ar:"كده ثبتت."},{speaker:"luna",es:"Genial. Pruebe a abrir una página y me cuenta.",ar:"برافو. جرب تفتح صفحة واحكيلي."}],questions:[{q:"إيه أول خطوة طلبتها الموظفة؟",options:["يفصل الراوتر ويستنى عشر ثواني","يعيد ضبط المصنع","يغيّر مكان الراوتر","يكلم الشركة المصنعة"],answer:"يفصل الراوتر ويستنى عشر ثواني",rationale:"قالت: Apáguelo… y espere diez segundos = اطفيّه واستنى عشر ثواني. apagar = يطفي، encender = يشغّل."},{q:"لازم يستنى لحد إيه قبل ما يجرب النت؟",options:["لحد ما النور يطفي خالص","لحد ساعتين","لحد ما اللمبات تثبت","لحد ما يسمع صوت"],answer:"لحد ما اللمبات تثبت",rationale:"قالت: espere a que las luces se pongan fijas = استنى لحد ما اللمبات تثبت. fijas = ثابتة، مش بتومض."},{q:"ليه نبدأ بخطوة بسيطة زي إعادة التشغيل؟",options:["عشان نضيّع وقت العميل","عشان دي الخطوة الوحيدة الموجودة","عشان مشاكل كتير بتتحل بيها وهي أسرع وأسهل خطوة","عشان نثبت للعميل إنه غلطان"],answer:"عشان مشاكل كتير بتتحل بيها وهي أسرع وأسهل خطوة",rationale:"إعادة التشغيل مجانية وسريعة وبتحل نسبة كبيرة من المشاكل، فالمنطق يقول نبدأ بيها قبل أي حاجة أعقد."}],responseTask:{prompt:"وجّه عميل بالإسباني لإعادة تشغيل الراوتر: يطفيه، يستنى عشر ثواني، ويشغّله.",acceptable:["Apague el router, espere diez segundos y enciéndalo otra vez.","Vamos a reiniciar el router: apáguelo, espere diez segundos y enciéndalo.","Apáguelo con el botón, espere diez segundos y vuelva a encenderlo.","Primero apague el router, espere diez segundos y luego enciéndalo."],modelEs:"Apague el router, espere diez segundos y enciéndalo otra vez.",modelAr:"اطفي الراوتر، استنى عشر ثواني، وشغّله تاني.",checklistAr:"راجع إجابتك: ١) أمر إطفاء مهذب (apague / apáguelo)، ٢) مدة الانتظار واضحة، ٣) أمر تشغيل مهذب (enciéndalo). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"أوامر usted بتلزق الضمير في الآخر: apague + lo → apáguelo (اطفيّه)، encienda + lo → enciéndalo (شغّله). reiniciar = يعيد تشغيل. otra vez = تاني."}},{id:"cc-u04l02",courseId:"call-center",unitId:"cc-u04",sourceLessonId:"cc-u04l02",level:"B1",register:"usted",title:"عملت كده خلاص",context:"عميلة جرّبت إعادة التشغيل بنفسها قبل ما تتصل. دورك: تصدّقها، متكررش الخطوة، وتنتقل للي بعدها من غير ما تشكك في كلامها.",goal:"بعد الدرس ده حتقدر تتعامل مع «أنا عملت كده خلاص»: تشكر العميل على المعلومة وتكمل من نقطة جديدة.",targets:[{es:"Ya lo he hecho dos veces.",ar:"أنا عملت كده خلاص مرتين.",speaker:"luna"},{es:"Así no lo repetimos y vamos al siguiente paso.",ar:"كده مش حنعيدها وحنروح للخطوة اللي بعدها.",speaker:"paco"},{es:"Le creo.",ar:"أنا مصدق حضرتك.",speaker:"paco"},{es:"La luz de internet está roja.",ar:"لمبة النت حمرا.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¿Probó a reiniciar el router?",ar:"جربت حضرتك تعيدي تشغيل الراوتر؟"},{speaker:"luna",es:"Sí. Ya lo he hecho dos veces.",ar:"أيوه. أنا عملت كده خلاص مرتين."},{speaker:"paco",es:"De acuerdo, gracias por decírmelo. Así no lo repetimos y vamos al siguiente paso.",ar:"ماشي، شكرًا إنك قولتيلي. كده مش حنعيدها وحنروح للخطوة اللي بعدها."},{speaker:"luna",es:"Gracias, porque de verdad ya lo hice.",ar:"شكرًا، عشان بجد أنا عملتها."},{speaker:"paco",es:"Le creo. ¿Me dice qué luces tiene ahora mismo el router?",ar:"أنا مصدق حضرتك. تقوليلي الراوتر عليه لمبات إيه دلوقتي؟"},{speaker:"luna",es:"La luz de internet está roja.",ar:"لمبة النت حمرا."},{speaker:"paco",es:"Vale, eso cambia las cosas. Lo apunto y seguimos por ahí.",ar:"تمام، ده بيغيّر الموضوع. حدوّنه ونكمل من النقطة دي."}],questions:[{q:"العميلة عملت إيه قبل المكالمة؟",options:["أعادت تشغيل الراوتر مرتين","كلمت الشركة تلت مرات","غيّرت الراوتر","لغت العقد"],answer:"أعادت تشغيل الراوتر مرتين",rationale:"قالت: Ya lo he hecho dos veces = عملت كده خلاص مرتين. ya lo he hecho من التراكيب اللي بتتقال كتير في الدعم."},{q:"لمبة النت لونها إيه دلوقتي؟",options:["خضرا","صفرا","مطفية","حمرا"],answer:"حمرا",rationale:"قالت: La luz de internet está roja = لمبة النت حمرا. roja = حمرا."},{q:"ليه مهم تسأل لو العميل جرّب الخطوة قبل ما تشرحها؟",options:["عشان تختبر صبره","عشان متتكررش خطوة اتعملت وتضيّع وقت وتضايقه","عشان تتأكد إنه فاهم إسباني","عشان تثبت إن الغلط غلطه"],answer:"عشان متتكررش خطوة اتعملت وتضيّع وقت وتضايقه",rationale:"تكرار خطوة العميل عملها بيخليه يحس إنك مش سامعه. Así no lo repetimos بيوفر وقت وبيبني ثقة."}],responseTask:{prompt:"عميلة قالت: «Ya lo he hecho dos veces». رد بالإسباني: صدّقها، اشكرها، وانتقل للخطوة اللي بعدها.",acceptable:["De acuerdo, gracias por decírmelo. Así no lo repetimos y vamos al siguiente paso.","Perfecto, entonces no lo repetimos. Vamos al siguiente paso.","Vale, le creo. Pasamos al siguiente paso.","Gracias. Entonces saltamos ese paso y probamos otra cosa."],modelEs:"De acuerdo, gracias por decírmelo. Así no lo repetimos y vamos al siguiente paso.",modelAr:"ماشي، شكرًا إنك قولتيلي. كده مش حنعيدها وحنروح للخطوة اللي بعدها.",checklistAr:"راجع إجابتك: ١) تصديق العميل (Le creo / De acuerdo)، ٢) عدم تكرار الخطوة (no lo repetimos)، ٣) انتقال واضح (siguiente paso). ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"Ya lo he hecho = عملت كده خلاص. el siguiente paso = الخطوة اللي بعدها. pasar a / seguir por = ينتقل لـ. gracias por + مصدر = شكرًا على."}},{id:"cc-u04l03",courseId:"call-center",unitId:"cc-u04",sourceLessonId:"cc-u04l03",level:"B1",register:"usted",title:"اسأل عن النتيجة",context:"شرحت للعميل خطوة. دورك: تطلب منه يجرب ويقولك النتيجة، ومتفترضش أبدًا إن الخطوة نجحت من غير ما تسمع منه.",goal:"بعد الدرس ده حتقدر تتابع نتيجة أي خطوة بشكل صحيح، وتعرف تقول «لسه زي ما هو» و«الإشارة مش واصلة كويس».",targets:[{es:"¿Puede abrir una página y decirme qué ve?",ar:"ممكن حضرتك تفتح صفحة وتقوللي شايف إيه؟",speaker:"luna"},{es:"Sigue igual.",ar:"لسه زي ما هو",speaker:"paco"},{es:"Ese paso no lo ha resuelto.",ar:"الخطوة دي محلّتش المشكلة",speaker:"luna"},{es:"La señal no llega bien.",ar:"الإشارة مش واصلة كويس",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Vale, ya está encendido. ¿Puede abrir una página y decirme qué ve?",ar:"تمام، كده اتشغّل. ممكن حضرتك تفتح صفحة وتقوللي شايف إيه؟"},{speaker:"paco",es:"Un momento… No. Sigue igual.",ar:"لحظة واحدة… لأ. لسه زي ما هو."},{speaker:"luna",es:"De acuerdo. Ese paso no lo ha resuelto. Probamos otra cosa.",ar:"ماشي. الخطوة دي محلّتش المشكلة. نجرب حاجة تانية."},{speaker:"paco",es:"¿Y ahora qué hacemos?",ar:"ودلوقتي نعمل إيه؟"},{speaker:"luna",es:"Voy a revisar la línea desde aquí. Dos minutos, por favor.",ar:"حراجع الخط من ناحيتي. دقيقتين، لو سمحت."},{speaker:"paco",es:"Vale.",ar:"تمام."},{speaker:"luna",es:"Gracias por esperar. La señal no llega bien. Le explico el siguiente paso.",ar:"شكرًا على الانتظار. الإشارة مش واصلة كويس. حأشرح لحضرتك الخطوة اللي بعدها."}],questions:[{q:"هل إعادة التشغيل حلّت المشكلة؟",options:["أيوه، اشتغل خالص","مش عارفين لسه","لأ، لسه زي ما هو","النت بقى أسرع شوية"],answer:"لأ، لسه زي ما هو",rationale:"قال: No, sigue igual = لأ، لسه زي ما هو. seguir igual = يفضل على حاله."},{q:"الموظفة عرفت نتيجة الخطوة إزاي؟",options:["خمّنت","افترضت إنها نجحت","النظام قالها لوحده","سألت العميل يجرب ويوصف اللي شافه"],answer:"سألت العميل يجرب ويوصف اللي شافه",rationale:"طلبت: ¿Puede abrir una página y decirme qué ve? = ممكن حضرتك تفتح صفحة وتقوللي شايف إيه؟ افتراض إن المشكلة اتحلّت من غير تأكيد ممكن يقفل بلاغ وهو لسه مفتوح."},{q:"«sigue igual» معناها إيه؟",options:["اتحسّن شوية","اتحلّت المشكلة","بقى أسوأ","لسه زي ما هو"],answer:"لسه زي ما هو",rationale:"seguir = يفضل/يكمّل، y igual = زي ما هو. مقابلها: ya funciona = اشتغل خلاص."}],responseTask:{prompt:"شرحت للعميل خطوة. اطلب منه بالإسباني يجرب ويقولك النتيجة، من غير ما تفترض إنها نجحت.",acceptable:["¿Puede abrir una página y decirme qué ve?","Pruebe ahora y me cuenta si funciona.","Pruebe a abrir una página, por favor, y me dice qué ve.","Ahora pruébelo y cuénteme el resultado."],modelEs:"¿Puede abrir una página y decirme qué ve?",modelAr:"تمام، كده اتشغّل. ممكن حضرتك تفتح صفحة وتقوللي شايف إيه؟",checklistAr:"راجع إجابتك: ١) طلب تجربة واضح (pruebe)، ٢) طلب وصف النتيجة (qué ve / el resultado)، ٣) مفيش افتراض نجاح. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"seguir igual = يفضل زي ما هو. resolver = يحل (مشكلة). la señal = الإشارة. resultado = نتيجة. pruébelo = جرّبه."}},{id:"cc-u04l04",courseId:"call-center",unitId:"cc-u04",sourceLessonId:null,level:"B1",register:"usted",title:"الخطوة منجحتش",context:"عميلة جرّبت خطوة ومنجحتش. دورك: تطمنها إن ده طبيعي وإحنا بنجرّب خطوة خطوة، تشيل اللوم عنها، وتكمل للخطوة اللي بعدها.",goal:"بعد الدرس ده حتقدر تتعامل مع خطوة فشلت: تشيل اللوم عن العميل وتحوّل الطاقة للخطوة اللي بعدها.",targets:[{es:"Lo probé y nada, sigue sin funcionar.",ar:"جربته ومفيش فايدة، لسه مش شغال.",speaker:"luna"},{es:"No es culpa suya.",ar:"ده مش غلط حضرتك.",speaker:"paco"},{es:"Probamos el siguiente paso.",ar:"نجرب الخطوة اللي بعدها.",speaker:"paco"},{es:"Cámbielo y me dice qué pasa.",ar:"غيّريه وقوليلي بيحصل إيه.",speaker:"paco"}],dialogue:[{speaker:"paco",es:"¿Lo probó? ¿Funciona ahora?",ar:"جربتيه؟ اشتغل دلوقتي؟"},{speaker:"luna",es:"Lo probé y nada, sigue sin funcionar.",ar:"جربته ومفيش فايدة، لسه مش شغال."},{speaker:"paco",es:"De acuerdo, no pasa nada. No es culpa suya. Probamos el siguiente paso.",ar:"ماشي، ولا يهمك. ده مش غلط حضرتك. نجرب الخطوة اللي بعدها."},{speaker:"luna",es:"¿Cuál es?",ar:"إيه هي؟"},{speaker:"paco",es:"Vamos a probar con otro cable, si tiene uno en casa.",ar:"حنجرب بكابل تاني، لو عند حضرتك واحد في البيت."},{speaker:"luna",es:"Sí, tengo uno del ordenador viejo.",ar:"أيوه، عندي واحد بتاع الكمبيوتر القديم."},{speaker:"paco",es:"Perfecto. Cámbielo y me dice qué pasa.",ar:"جميل. غيّريه وقوليلي بيحصل إيه."}],questions:[{q:"هل الخطوة الأولى نجحت؟",options:["أيوه","نجحت نص نص","لأ، لسه مش شغال","مش واضح"],answer:"لأ، لسه مش شغال",rationale:"قالت: Lo probé y nada, sigue sin funcionar = جربته ومفيش فايدة. y nada تعبير شائع معناه ومفيش نتيجة."},{q:"الخطوة اللي بعدها إيه؟",options:["تجربة كابل تاني","تغيير الراوتر بالكامل","إلغاء الخدمة","فتح بلاغ فورًا"],answer:"تجربة كابل تاني",rationale:"قال: Vamos a probar con otro cable = حنجرب بكابل تاني. cable = كابل."},{q:"ليه الموظف قال «No es culpa suya»؟",options:["عشان يتهم الشركة","عشان يقفل المكالمة","عشان يضحك عليها","عشان يوضح إن فشل الخطوة مش غلطها ويطمنها"],answer:"عشان يوضح إن فشل الخطوة مش غلطها ويطمنها",rationale:"culpa = غلط/ذنب. عملاء كتير بيحسوا إنهم فشلوا لما الخطوة متنجحش، فشيل اللوم بيحافظ على تعاونهم."}],responseTask:{prompt:"عميلة قالت إن الخطوة منجحتش. رد بالإسباني: طمنها إن ده مش غلطها، واعرض الخطوة اللي بعدها.",acceptable:["De acuerdo, no pasa nada. No es culpa suya. Probamos el siguiente paso.","No pasa nada. Vamos a probar otra cosa.","No se preocupe, es normal. Probamos el siguiente paso.","Vale, no pasa nada. Tenemos más opciones. Probamos otra."],modelEs:"De acuerdo, no pasa nada. No es culpa suya. Probamos el siguiente paso.",modelAr:"ماشي، ولا يهمك. ده مش غلط حضرتك. نجرب الخطوة اللي بعدها.",checklistAr:"راجع إجابتك: ١) طمأنة (no pasa nada / no se preocupe)، ٢) إزالة لوم (no es culpa suya / es normal)، ٣) خطوة تالية واضحة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"culpa = غلط/ذنب. No es culpa suya = مش غلط حضرتك. probar = يجرب (جربته = lo probé). cambiar = يغيّر. Cámbielo = غيّريه."}},{id:"cc-u04l05",courseId:"call-center",unitId:"cc-u04",sourceLessonId:null,level:"B1",register:"usted",title:"عميل مش خبير تقني",context:"عميل بيقول من البداية إنه مش فاهم في التكنولوجيا. دورك: تطمنه، وتمشي ببطء، وتصف كل حاجة بشكل بسيط وتشجعه مع كل خطوة.",goal:"بعد الدرس ده حتقدر توجّه عميل غير تقني: خطوات صغيرة، وصف بسيط للأشكال، وتشجيع مستمر.",targets:[{es:"No entiendo de tecnología.",ar:"أنا مش فاهم في التكنولوجيا",speaker:"paco"},{es:"Vamos muy despacio y paso a paso.",ar:"حنمشي ببطء جدًا وخطوة خطوة",speaker:"luna"},{es:"Púlselo una vez y me dice qué luces se apagan.",ar:"ادوس عليه مرة واحدة وقوللي أنهي لمبات طفت.",speaker:"luna"},{es:"Lo está haciendo genial.",ar:"إنت بتعملها صح جدًا.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"Se lo aviso. No entiendo de tecnología.",ar:"أنا بحذرك من دلوقتي. أنا مش فاهم في التكنولوجيا."},{speaker:"luna",es:"No se preocupe. Vamos muy despacio y paso a paso. ¿Ve la caja del internet, con luces?",ar:"متقلقش. حنمشي ببطء جدًا وخطوة خطوة. شايف علبة النت، اللي عليها لمبات؟"},{speaker:"paco",es:"Sí, la veo.",ar:"أيوه، شايفها."},{speaker:"luna",es:"Perfecto. ¿Ve un botón atrás, pequeño?",ar:"جميل. شايف زرار ورا، صغير؟"},{speaker:"paco",es:"Sí, hay uno negro.",ar:"أيوه، في واحد أسود."},{speaker:"luna",es:"Ese. Púlselo una vez y me dice qué luces se apagan.",ar:"هو ده. ادوس عليه مرة واحدة وقوللي أنهي لمبات طفت."},{speaker:"paco",es:"Se apagaron todas.",ar:"طفت كلها."},{speaker:"luna",es:"Muy bien. Lo está haciendo genial. Ahora esperamos un minuto y lo encendemos otra vez.",ar:"تمام جدًا. إنت بتعملها صح جدًا. دلوقتي نستنى دقيقة ونشغّله تاني."}],questions:[{q:"العميل حذّر من إيه في الأول؟",options:["إنه مش فاهم في التكنولوجيا","إن الراوتر بايظ","إنه مستعجل","إنه مش عايز يدفع"],answer:"إنه مش فاهم في التكنولوجيا",rationale:"قال: no entiendo de tecnología = مش فاهم في التكنولوجيا. se lo aviso = أنا بحذرك / بقولك من دلوقتي."},{q:"الموظفة وصفت الزرار إزاي عشان يلاقيه؟",options:["زرار أحمر كبير","زرار صغير ورا","زرار جنب الشاشة","زرار فوق العلبة"],answer:"زرار صغير ورا",rationale:"قالت: un botón atrás, pequeño = زرار ورا، صغير. الوصف بالمكان والحجم بيساعد أكتر من المصطلحات."},{q:"عميل بيقول إنه مش فاهم في التكنولوجيا. أسلوبك إزاي؟",options:["تستخدم المصطلحات التقنية عشان يتعلم","تطلب منه يجيب حد يفهم","تقوله إن ده مش دورك","تشرح بخطوات صغيرة ووصف بسيط وتشجعه"],answer:"تشرح بخطوات صغيرة ووصف بسيط وتشجعه",rationale:"vamos muy despacio y paso a paso + Lo está haciendo genial — خطوات صغيرة وتشجيع بيخلّي العميل يكمل بدل ما يتوتر ويقفل."}],responseTask:{prompt:"عميل قال إنه مش فاهم في التكنولوجيا. طمنه بالإسباني ووضحله إنك حتمشي معاه خطوة خطوة.",acceptable:["No se preocupe, vamos muy despacio y paso a paso.","Tranquilo, le explico paso a paso, sin tecnicismos.","No pasa nada, vamos despacio. Yo le guío.","No se preocupe, lo hacemos juntos, paso a paso."],modelEs:"No se preocupe, vamos muy despacio y paso a paso.",modelAr:"متقلقش، حنمشي ببطء جدًا وخطوة خطوة.",checklistAr:"راجع إجابتك: ١) طمأنة (no se preocupe / tranquilo)، ٢) وعد بخطوات صغيرة (paso a paso / despacio)، ٣) مفيش مصطلحات معقدة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"paso a paso = خطوة خطوة. pulsar = يدوس على زرار. guiar = يوجّه. tecnicismos = مصطلحات تقنية. lo está haciendo genial = إنت بتعملها صح جدًا."}},{id:"cc-u04l06",courseId:"call-center",unitId:"cc-u04",sourceLessonId:null,level:"B1",register:"usted",title:"خطوات كاملة مع متابعة النتيجة",context:"مكالمة كاملة من الأول: نت مش شغال من إمبارح. دورك: تسأل لو جرّب إعادة التشغيل، توجّهه خطوة خطوة، تتابع النتيجة، ولما تفشل تنتقل للي بعدها من غير لوم.",goal:"درس مراجعة: حتجمع تسلسل خطوات الحل كله: سؤال عن محاولة سابقة، توجيه، متابعة نتيجة، وتصرف مهني عند الفشل.",targets:[{es:"¿Probó ya a reiniciar el router?",ar:"حضرتك جربت تعيد تشغيل الراوتر قبل كده؟",speaker:"luna"},{es:"Lo hacemos juntos, paso a paso.",ar:"نعملها مع بعض، خطوة خطوة",speaker:"luna"},{es:"Cuando las luces estén fijas, abra una página y me cuenta qué ve.",ar:"لما اللمبات تثبت، افتح صفحة واحكيلي شايف إيه.",speaker:"luna"},{es:"Sigue sin funcionar.",ar:"لسه مش شغال",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Buenos días, le atiende Luna. ¿En qué puedo ayudarle?",ar:"صباح الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola, mi internet no funciona desde ayer.",ar:"أهلًا، النت عندي مش شغال من إمبارح."},{speaker:"luna",es:"Lo siento. ¿Probó ya a reiniciar el router?",ar:"أنا آسفة. حضرتك جربت تعيد تشغيل الراوتر قبل كده؟"},{speaker:"paco",es:"No, la verdad es que no.",ar:"لأ، الحقيقة لأ."},{speaker:"luna",es:"Vale. Lo hacemos juntos, paso a paso. Apague el router y espere diez segundos.",ar:"تمام. نعملها مع بعض، خطوة خطوة. اطفي الراوتر واستنى عشر ثواني."},{speaker:"paco",es:"Ya está. ¿Lo enciendo?",ar:"كده خلاص. أشغّله؟"},{speaker:"luna",es:"Sí, enciéndalo. Cuando las luces estén fijas, abra una página y me cuenta qué ve.",ar:"أيوه، شغّله. لما اللمبات تثبت، افتح صفحة واحكيلي شايف إيه."},{speaker:"paco",es:"Pues… No. Sigue sin funcionar.",ar:"يعني… لأ. لسه مش شغال."},{speaker:"luna",es:"De acuerdo, no pasa nada, no es culpa suya. Voy a revisar la línea desde aquí y le digo el siguiente paso.",ar:"ماشي، ولا يهمك، ده مش غلط حضرتك. حراجع الخط من ناحيتي وحأقولك الخطوة اللي بعدها."},{speaker:"paco",es:"Perfecto, gracias.",ar:"جميل، شكرًا."}],questions:[{q:"هل العميل جرّب إعادة التشغيل قبل المكالمة؟",options:["أيوه، مرتين","أيوه، مرة واحدة","لأ","مش فاكر"],answer:"لأ",rationale:"قال: No, la verdad es que no = لأ، الحقيقة لأ. la verdad es que… = الحقيقة إن…"},{q:"نتيجة إعادة التشغيل كانت إيه؟",options:["النت اشتغل","الراوتر بايظ خالص","المشكلة اتحلت نصها","النت لسه مش شغال"],answer:"النت لسه مش شغال",rationale:"قال: sigue sin funcionar = لسه مش شغال. seguir sin + مصدر = يفضل من غير ما يعمل."},{q:"الموظفة قررت تعمل إيه بعد فشل الخطوة؟",options:["تقفل المكالمة","تراجع الخط من ناحيتها وتقوله الخطوة اللي بعدها","تلوم العميل","تحوّله فورًا"],answer:"تراجع الخط من ناحيتها وتقوله الخطوة اللي بعدها",rationale:"قالت: Voy a revisar la línea desde aquí y le digo el siguiente paso. من غير لوم ولا قفل ولا وعود فاضية."}],responseTask:{prompt:"وجّه عميل بالإسباني لإعادة تشغيل الراوتر، وبعدين اطلب منه يجرب ويقولك النتيجة.",acceptable:["Apague el router y espere diez segundos. Cuando las luces estén fijas, abra una página y me cuenta qué ve.","Vamos a reiniciar: apáguelo, espere diez segundos, enciéndalo y me dice si funciona.","Apáguelo diez segundos, enciéndalo, y cuando las luces estén fijas me cuenta qué ve.","Apague el router, espere diez segundos, y luego pruebe a abrir una página y me dice."],modelEs:"Apague el router y espere diez segundos. Cuando las luces estén fijas, abra una página y me cuenta qué ve.",modelAr:"اطفي الراوتر واستنى عشر ثواني. لما اللمبات تثبت، افتح صفحة واحكيلي شايف إيه.",checklistAr:"راجع إجابتك: ١) خطوة الإطفاء والانتظار واضحة، ٢) متى يجرب (las luces fijas)، ٣) طلب وصف النتيجة من غير افتراض نجاح. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cuando las luces estén fijas = لما اللمبات تثبت، وبعد cuando للمستقبل بنستخدم صيغة خاصة (estén مش están). fijas = ثابتة. reiniciar = يعيد تشغيل."}}]},{courseId:"call-center",unit:{id:"cc-u05",title:"الطلبات والمدفوعات بأمان",desc:"تسأل عن مرجع الطلب، تشرح حالة الدفع والطلب من غير جمع بيانات كارت، ومن غير وعود مش مؤكدة.",cefr:"B1–B2"},lessons:[{id:"cc-u05l01",courseId:"call-center",unitId:"cc-u05",sourceLessonId:"cc-u05l01",level:"B1",register:"usted",title:"طلب متأخر: طمن العميل من غير وعود فاضية",context:"عميل متصل عشان طلبه متأخر خمس أيام عن الموعد المتفق عليه. دورك كموظف: تتأكد من بيانات الطلب، تقول اللي تعرفه بجد، وتدي خطوة تالية واقعية من غير ما توعد بتاريخ وصول أو فلوس راجعة مش متأكد منهم.",goal:"بعد الدرس ده حتقدر تدير مكالمة عن طلب متأخر: تطلب رقم الطلب، تشرح حالته الحقيقية، وتفتح بلاغ متابعة (incidencia) برقم مرجع.",targets:[{es:"¿Me puede dar el número de su pedido, por favor?",ar:"ممكن حضرتك تديني رقم الطلب، لو سمحت؟",speaker:"luna"},{es:"Sigue en el centro de distribución.",ar:"لسه واقف في مركز التوزيع.",speaker:"luna"},{es:"Lamento mucho la espera, de verdad.",ar:"متأسفة جدًا على الانتظار ده، بجد.",speaker:"luna"},{es:"Voy a abrir una incidencia con el departamento de envíos ahora mismo para que revisen su caso.",ar:"حفتح بلاغ مع قسم الشحن دلوقتي حالًا.",speaker:"luna"},{es:"No quiero prometerle una fecha que no puedo confirmar.",ar:"مش عايزة أعد حضرتك بتاريخ مش قادرة أتأكد منه.",speaker:"luna"}],dialogue:[{speaker:"luna",es:"Buenas tardes, le atiende Luna. ¿En qué puedo ayudarle?",ar:"مساء الخير، مع حضرتك لونا. أقدر أساعد حضرتك في إيه؟"},{speaker:"paco",es:"Hola, llevo cinco días esperando un pedido que tenía que llegar el viernes pasado.",ar:"أهلًا، ليا خمس أيام مستني طلب كان المفروض يوصل يوم الجمعة اللي فاتت."},{speaker:"luna",es:"Lo siento mucho. ¿Me puede dar el número de su pedido, por favor?",ar:"أنا متأسفة جدًا. ممكن حضرتك تديني رقم الطلب، لو سمحت؟"},{speaker:"paco",es:"Sí, es el cuatro, cinco, ocho, dos, tres.",ar:"أيوه، هو ٤٥٨٢٣."},{speaker:"luna",es:"Gracias, un momento… Veo que el pedido salió de nuestro almacén el lunes. Sigue en el centro de distribución.",ar:"شكرًا، لحظة واحدة… شايفة إن الطلب خرج من مخزننا يوم الاتنين، بس لسه واقف في مركز التوزيع."},{speaker:"paco",es:"¿Y cuándo va a llegar? Es que nadie me da una solución.",ar:"وحيوصل إمتى؟ المشكلة إن محدش بيديني حل."},{speaker:"luna",es:"Tiene toda la razón. Lamento mucho la espera, de verdad. Voy a abrir una incidencia con el departamento de envíos ahora mismo para que revisen su caso.",ar:"مع حضرتك كل الحق. متأسفة جدًا على الانتظار ده، بجد. حفتح بلاغ مع قسم الشحن دلوقتي حالًا عشان يراجعوا حالتك."},{speaker:"luna",es:"No quiero prometerle una fecha que no puedo confirmar. En cuanto tengan respuesta le va a llegar un correo con el estado del envío.",ar:"مش عايزة أعد حضرتك بتاريخ مش قادرة أتأكد منه، بس أول ما يجيلنا رد منهم، حيوصلك إيميل بحالة الشحنة."},{speaker:"luna",es:"¿Me confirma su correo para enviarle el número de referencia? Es la incidencia INC setecientos setenta y uno.",ar:"تأكدلي حضرتك الإيميل عشان أبعتلِك رقم المرجع؟ البلاغ رقمه INC-٧٧١."},{speaker:"paco",es:"Sí, es paco punto martin arroba correo punto es. Gracias.",ar:"أيوه، paco نقطة martin آت correo نقطة es. شكرًا."}],questions:[{q:"العميل شاكي من إيه بالظبط؟",options:["طلبه ماوصلش في موعده ولسه مستنيه","الطلب وصل بس جاله غلط","عايز يلغي الطلب ويرجّع فلوسه","الموقع مش بيقبل رقم الطلب"],answer:"طلبه ماوصلش في موعده ولسه مستنيه",rationale:"قال: llevo cinco días esperando un pedido que tenía que llegar el viernes pasado = ليا خمس أيام مستني طلب كان المفروض يوصل الجمعة اللي فاتت. مفيش كلام عن منتج غلط ولا إلغاء."},{q:"العميل سأل «وحيوصل إمتى؟». أنسب رد مهني؟",options:["حيوصل بكرة أكيد، متقلقش","تقوله إن التأخير مش مسؤولية شركتك","تطلب منه يتصل تاني بعد أسبوع","توضح إنك مش هتوعد بتاريخ مش متأكد منه، وتفتح بلاغ للمتابعة"],answer:"توضح إنك مش هتوعد بتاريخ مش متأكد منه، وتفتح بلاغ للمتابعة",rationale:"الوعد بموعد مش مؤكد بيكسر ثقة العميل لما يتكسر، والتنصّل أو الترحيل مش حل. الصح: اعتذار + الحقيقة + خطوة ملموسة (بلاغ + رقم مرجع)."},{q:"كلمة «incidencia» في المكالمة دي معناها إيه؟",options:["خصم على الطلب الجاي","بلاغ رسمي عن مشكلة، بيتم متابعته برقم مرجع","تأكيد إن الفلوس اترجعت","مكالمة من قسم المبيعات"],answer:"بلاغ رسمي عن مشكلة، بيتم متابعته برقم مرجع",rationale:"في خدمة العملاء في إسبانيا، abrir una incidencia = تفتح بلاغ رسمي عند القسم المختص، وليه رقم مرجع بتتابع بيه. مش تعويض ولا استرجاع."}],responseTask:{prompt:"العميل قال: «وحيوصل إمتى؟ محدش بيديني حل». اكتب أو قول ردك بالإسباني: اعتذار قصير + اللي حتعمله دلوقتي، من غير ما توعد بتاريخ.",acceptable:["Lamento mucho la espera. Voy a abrir una incidencia con el departamento de envíos ahora mismo para que revisen su caso.","Tiene toda la razón. No quiero prometerle una fecha que no puedo confirmar, pero voy a abrir una incidencia ahora mismo y le informaremos por correo.","Lo siento mucho. Voy a abrir una incidencia con envíos para que lo revisen, y le llegará un correo con la respuesta.","Entiendo su enfado. Ahora mismo abro una incidencia con el departamento de envíos y le envío el número de referencia por correo."],modelEs:"Lamento mucho la espera. Voy a abrir una incidencia con el departamento de envíos ahora mismo para que revisen su caso.",modelAr:"متأسفة جدًا على الانتظار. حفتح بلاغ مع قسم الشحن دلوقتي حالًا عشان يراجعوا حالتك.",checklistAr:"راجع إجابتك: ١) اعتذار أو تعاطف (Lamento / Lo siento / Entiendo)، ٢) خطوة واقعية (abrir una incidencia + مين حيراجع)، ٣) مفيش وعد بتاريخ وصول أو فلوس. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"صيغة الاحترام للعميل: le وsu. للمستقبل القريب: va a llegar (حيوصل). وle informaremos = حنبلّغ حضرتك (مستقبل بسيط). para que revisen: بعد para que بنستخدم صيغة خاصة للفعل."}},{id:"cc-u05l02",courseId:"call-center",unitId:"cc-u05",sourceLessonId:"cc-u05l02",level:"B1",register:"usted",title:"الخصم معلّق",context:"عميلة لاقت خصم في حسابها مش فاهماه وقلقانة. دورك: تطمنها وتشرح يعني إيه خصم معلّق، من غير ما توعد بموعد أو نتيجة مضمونة.",goal:"بعد الدرس ده حتقدر تشرح الفرق بين الخصم المعلّق والنهائي بكلام بسيط، وتقول للعميل يعمل إيه لو الموضوع متأكدش.",targets:[{es:"Veo un cargo en mi cuenta y no sé qué es.",ar:"شايفة خصم في حسابي ومش عارفة هو إيه.",speaker:"luna"},{es:"Es un cargo pendiente del pedido de ayer.",ar:"ده خصم معلّق بتاع طلب إمبارح.",speaker:"paco"},{es:"El banco lo reserva y luego se confirma o desaparece.",ar:"البنك حاجزه وبعد كده بيتأكد أو بيختفي.",speaker:"paco"},{es:"Normalmente en unos días verá el movimiento definitivo.",ar:"عادي خلال كام يوم حتشوفي الحركة النهائية.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hola. Veo un cargo en mi cuenta y no sé qué es.",ar:"أهلًا، شايفة خصم في حسابي ومش عارفة هو إيه."},{speaker:"paco",es:"Entiendo. ¿Me permite un momento mientras lo reviso? …Vale. Es un cargo pendiente del pedido de ayer.",ar:"فاهم حضرتك. تسمحيلي بلحظة لحد ما أراجعه؟ …تمام، ده خصم معلّق بتاع طلب إمبارح."},{speaker:"luna",es:"¿Pendiente? ¿Eso qué quiere decir?",ar:"معلّق؟ يعني إيه؟"},{speaker:"paco",es:"Que todavía no es definitivo. El banco lo reserva y luego se confirma o desaparece.",ar:"يعني لسه مش نهائي. البنك حاجزه وبعد كده بيتأكد أو بيختفي."},{speaker:"luna",es:"¿Y cuándo sé si se confirmó?",ar:"وأعرف إمتى لو اتأكد؟"},{speaker:"paco",es:"Normalmente en unos días verá el movimiento definitivo. Si no, me llama y lo revisamos.",ar:"عادي خلال كام يوم حتشوفي الحركة النهائية. لو لأ، اتصلي بينا ونراجعها."},{speaker:"luna",es:"Vale, me quedo más tranquila.",ar:"تمام، كده اطمنّيت."},{speaker:"paco",es:"Si quiere apunto una nota en su cuenta por si vuelve a llamar.",ar:"لو تحبي أدون ملاحظة في حساب حضرتك لو اتصلتي تاني."}],questions:[{q:"العميلة شافت إيه في حسابها؟",options:["خصم مش فاهمة هو إيه","رصيد زيادة","رسالة من البنك","تحويل غلط"],answer:"خصم مش فاهمة هو إيه",rationale:"قالت: veo un cargo en mi cuenta y no sé qué es = شايفة خصم ومش عارفة هو إيه. cargo = خصم."},{q:"«cargo pendiente» معناها إيه؟",options:["خصم نهائي","فلوس رجعت","خصم لسه مش نهائي، البنك حاجزه مؤقتًا","فاتورة قديمة"],answer:"خصم لسه مش نهائي، البنك حاجزه مؤقتًا",rationale:"شرحها: todavía no es definitivo. El banco lo reserva y luego se confirma o desaparece. pendiente = معلّق/لسه مش نهائي."},{q:"عميل سأل عن خصم معلّق. أنسب شرح؟",options:["أقوله أكيد الفلوس حترجع","أشرح إنه خصم مؤقت ممكن يتأكد أو يختفي، من غير وعد بموعد مضمون","أقوله كلم البنك، إحنا مش طرف","أتجاهل الموضوع"],answer:"أشرح إنه خصم مؤقت ممكن يتأكد أو يختفي، من غير وعد بموعد مضمون",rationale:"normalmente فيها احتمال مش ضمان. الموظف قال إنه عادي خلال كام يوم وعرض مراجعة لو متأكدش — ده شرح صادق من غير وعد."}],responseTask:{prompt:"عميلة لاقت خصم معلّق في حسابها وقلقانة. اشرح لها بالإسباني إيه هو الخصم المعلّق بهدوء.",acceptable:["Es un cargo pendiente: todavía no es definitivo. El banco lo reserva y luego se confirma o desaparece.","Tranquila, es un cargo pendiente, no definitivo. En unos días se confirma o desaparece.","Es un cargo pendiente del pedido. El banco lo reserva, y si no se confirma, desaparece.","No se preocupe: es un cargo pendiente. Aún no es definitivo."],modelEs:"Es un cargo pendiente: todavía no es definitivo. El banco lo reserva y luego se confirma o desaparece.",modelAr:"ده خصم معلّق: لسه مش نهائي. البنك حاجزه وبعد كده بيتأكد أو بيختفي.",checklistAr:"راجع إجابتك: ١) سمّيت المفهوم (cargo pendiente)، ٢) وضحت إنه مش نهائي، ٣) من غير وعد بمبلغ أو موعد مضمون. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cargo = خصم. pendiente = معلّق. definitivo = نهائي. reservar = يحجز. unos días = كام يوم. tranquila للست وtranquilo للراجل."}},{id:"cc-u05l03",courseId:"call-center",unitId:"cc-u05",sourceLessonId:"cc-u05l03",level:"B1",register:"usted",title:"خصم مرتين؟",context:"عميل متوتر بيقول إنه اتخصم منه مرتين لنفس الطلب. دورك: تراجع الحساب قبل ما تؤكد أو تنفي، وتشرح اللي لقيته بالظبط.",goal:"بعد الدرس ده حتقدر تتعامل مع ادعاء خصم مزدوج: مراجعة أولًا، وبعدين شرح الفرق بين خصم مؤكد وخصم معلّق.",targets:[{es:"¡Me han cobrado dos veces el mismo pedido!",ar:"اتخصم مني مرتين لنفس الطلب",speaker:"paco"},{es:"Lo reviso ahora mismo antes de confirmarle nada.",ar:"حراجعه دلوقتي حالًا قبل ما أأكد لحضرتك أي حاجة",speaker:"luna"},{es:"Veo un solo pedido con un cargo confirmado, y otro cargo pendiente del mismo día.",ar:"خصم مؤكد، وخصم تاني معلّق",speaker:"luna"},{es:"Por lo que veo, no.",ar:"على اللي أنا شايفه، لأ.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¡Hola! ¡Me han cobrado dos veces el mismo pedido!",ar:"أهلًا! اتخصم مني مرتين لنفس الطلب!"},{speaker:"luna",es:"Lo siento mucho. Lo reviso ahora mismo antes de confirmarle nada. ¿Me da el número del pedido?",ar:"أنا متأسفة جدًا. حراجعه دلوقتي حالًا قبل ما أأكد لحضرتك أي حاجة. تديني رقم الطلب؟"},{speaker:"paco",es:"Es el ocho, nueve, uno, dos, cero.",ar:"هو ٨٩١٢٠."},{speaker:"luna",es:"Gracias… Veo un solo pedido con un cargo confirmado, y otro cargo pendiente del mismo día.",ar:"شكرًا… شايفة طلب واحد بس عليه خصم مؤكد، وخصم تاني معلّق من نفس اليوم."},{speaker:"paco",es:"¿Entonces no me cobraron dos veces?",ar:"يبقى ماتخصمش مني مرتين؟"},{speaker:"luna",es:"Por lo que veo, no. El segundo está pendiente y normalmente desaparece. Si en unos días se confirma, me llama y lo gestionamos.",ar:"على اللي أنا شايفه، لأ. التاني معلّق وعادي بيختفي. لو خلال كام يوم اتأكد، اتصل بينا وحنحلّها."},{speaker:"paco",es:"Vale, entendido.",ar:"تمام، فهمت."},{speaker:"luna",es:"Le dejo una nota con lo que hemos visto hoy.",ar:"حسيب لحضرتك ملاحظة باللي شفناه النهارده."}],questions:[{q:"العميل فاكر إيه؟",options:["إن الطلب ماوصلش","إن الفاتورة غالية","إنه اتخصم منه مرتين لنفس الطلب","إن الطلب اتلغى"],answer:"إنه اتخصم منه مرتين لنفس الطلب",rationale:"قال: Me han cobrado dos veces el mismo pedido = اتخصم مني مرتين لنفس الطلب. cobrar = يخصم."},{q:"الحقيقة اللي الموظفة لقتها إيه؟",options:["خصمين مؤكدين","خصم واحد مؤكد وواحد معلّق","مفيش أي خصم","تلت خصومات"],answer:"خصم واحد مؤكد وواحد معلّق",rationale:"قالت: un cargo confirmado, y otro cargo pendiente = خصم مؤكد وخصم معلّق. عشان كده ردها كان على اللي أنا شايفه، لأ."},{q:"ليه الموظفة راجعت الحساب قبل ما ترد؟",options:["عشان النظام بطيء","عشان تضيّع وقت","عشان تلاقي غلط العميل","عشان متأكدش أو تنفي حاجة مش متأكدة منها"],answer:"عشان متأكدش أو تنفي حاجة مش متأكدة منها",rationale:"قالت: Lo reviso ahora mismo antes de confirmarle nada. لو قالت 'مفيش خصم مزدوج' وطلعت غلط، الثقة بتتكسر."}],responseTask:{prompt:"عميل بيقول إنه اتخصم منه مرتين. قول بالإسباني إنك حتراجع قبل ما تؤكد أي حاجة، واطلب رقم الطلب.",acceptable:["Lo siento mucho. Lo reviso ahora mismo antes de confirmarle nada. ¿Me da el número del pedido?","Entiendo. Déjeme revisarlo antes de confirmar nada. ¿El número del pedido, por favor?","Lo reviso ahora. ¿Me dice el número del pedido?","Vamos a verlo. ¿Me da el número del pedido para revisarlo?"],modelEs:"Lo siento mucho. Lo reviso ahora mismo antes de confirmarle nada. ¿Me da el número del pedido?",modelAr:"أنا متأسفة جدًا. حراجعه دلوقتي حالًا قبل ما أأكد لحضرتك أي حاجة. تديني رقم الطلب؟",checklistAr:"راجع إجابتك: ١) مراجعة قبل التأكيد (antes de confirmarle nada)، ٢) طلب رقم الطلب، ٣) مفيش وعد باسترجاع. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"antes de + مصدر = قبل ما. gestionar = يتعامل مع/يحل. una nota = ملاحظة. por lo que veo = على اللي أنا شايفه."}},{id:"cc-u05l04",courseId:"call-center",unitId:"cc-u05",sourceLessonId:null,level:"B1",register:"usted",title:"وصل منتج غلط",context:"عميلة وصلها طلبها بس المنتج غلط. دورك: تعتذر، تسأل إيه اللي طلبته وإيه اللي وصلها بالظبط، وتفتح بلاغ منتج غلط من غير تأكيد مواعيد مش بتاعتك.",goal:"بعد الدرس ده حتقدر تسأل عن المطلوب مقابل الواصل، وتطلب مستندات الشحنة، وتفتح البلاغ المناسب.",targets:[{es:"Me llegó el pedido pero no es lo que pedí.",ar:"الطلب وصلني بس مش اللي أنا طلبته.",speaker:"luna"},{es:"¿Qué pidió y qué le llegó?",ar:"حضرتك طلبت إيه ووصلك إيه؟",speaker:"paco"},{es:"Abro una incidencia por producto incorrecto.",ar:"حفتح بلاغ منتج غلط.",speaker:"paco"},{es:"No le voy a confirmar fechas hasta que envíos revise la incidencia.",ar:"مش حأكد لحضرتك مواعيد لحد ما قسم الشحن يراجع البلاغ.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hola. Me llegó el pedido pero no es lo que pedí.",ar:"أهلًا، الطلب وصلني بس مش اللي أنا طلبته."},{speaker:"paco",es:"Lo siento mucho. ¿Qué pidió y qué le llegó?",ar:"أنا متأسف جدًا. حضرتك طلبت إيه ووصلك إيه؟"},{speaker:"luna",es:"Pedí unos auriculares negros y llegaron unos blancos, de otro modelo.",ar:"طلبت سماعات سودا ووصلتني سماعات بيضا، من موديل تاني."},{speaker:"paco",es:"Entiendo. ¿Tiene la caja y el albarán?",ar:"فاهم. مع حضرتك الكرتونة وبوليصة التوصيل؟"},{speaker:"luna",es:"Sí, todo.",ar:"أيوه، كل حاجة."},{speaker:"paco",es:"Perfecto. Abro una incidencia por producto incorrecto. Le explico la devolución. No le voy a confirmar fechas hasta que envíos revise la incidencia.",ar:"جميل. حفتح بلاغ منتج غلط وحأشرح لحضرتك الإرجاع. مش حأكد لحضرتك مواعيد لحد ما قسم الشحن يراجع البلاغ."},{speaker:"luna",es:"Vale, gracias por la aclaración.",ar:"تمام، شكرًا على التوضيح."},{speaker:"paco",es:"Le llega un correo con la referencia hoy mismo.",ar:"حيوصلك إيميل برقم المرجع النهارده."}],questions:[{q:"مشكلة العميلة إيه؟",options:["الطلب ماوصلش خالص","الطلب اتأخر","المنتج بايظ","وصلها منتج غلط"],answer:"وصلها منتج غلط",rationale:"قالت: me llegó el pedido pero no es lo que pedí = الطلب وصل بس مش اللي طلبته. والتفاصيل: سماعات سودا طلبتها، ووصلت بيضا من موديل تاني."},{q:"الموظف سألها لو معاها إيه؟",options:["الكرتونة وبوليصة التوصيل","الكارت البنكي","الضمان","صورة المنتج"],answer:"الكرتونة وبوليصة التوصيل",rationale:"سأل: ¿Tiene la caja y el albarán? — albarán = بوليصة التوصيل، الورقة اللي بتيجي مع الشحنة."},{q:"ليه الموظف مأكدش مواعيد للإرجاع؟",options:["عشان مش عايز يشتغل","عشان المواعيد بتتأكد من قسم الشحن بعد مراجعة البلاغ","عشان الشركة ممنوعة من الوعود","عشان نسي"],answer:"عشان المواعيد بتتأكد من قسم الشحن بعد مراجعة البلاغ",rationale:"قال بصراحة: No le voy a confirmar fechas hasta que envíos revise la incidencia. الصدق في حدود صلاحيتك أحسن من وعد يتكسر."}],responseTask:{prompt:"عميلة وصلها منتج غلط. رد بالإسباني: اعتذر، واسأل إيه اللي طلبته وإيه اللي وصلها.",acceptable:["Lo siento mucho. ¿Qué pidió y qué le llegó?","Perdone. ¿Me cuenta qué pidió y qué le llegó?","Lo siento. ¿Qué esperaba y qué recibió?","Disculpe. ¿Qué pidió exactamente y qué le llegó?"],modelEs:"Lo siento mucho. ¿Qué pidió y qué le llegó?",modelAr:"أنا متأسف جدًا. حضرتك طلبت إيه ووصلك إيه؟",checklistAr:"راجع إجابتك: ١) اعتذار (Lo siento / Perdone / Disculpe)، ٢) سؤال واضح عن المطلوب مقابل الواصل، ٣) مفيش لوم للعميلة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"pedir = يطلب، وpedí = طلبت. albarán = بوليصة توصيل. devolución = إرجاع. auriculares = سماعات. incorrecto = غلط."}},{id:"cc-u05l05",courseId:"call-center",unitId:"cc-u05",sourceLessonId:null,level:"B2",register:"usted",title:"تالت مكالمة عن نفس الطلب",context:"عميل متصل للمرة التالتة عن نفس المشكلة ووصل لآخره. دورك: تقرا ملاحظات المكالمات السابقة بدل ما تخليه يعيد الشرح، وتقوله بالظبط واقفين فين، وتعمل اللي في حدودك فعلًا.",goal:"بعد الدرس ده حتقدر تتعامل مع عميل متكرر الاتصال: تقرا التاريخ، تلخّص الوضع الحالي، وتوضح اللي تقدر تعمله ومش تقدر تعمله.",targets:[{es:"¡Es la tercera vez que llamo por lo mismo!",ar:"دي تالت مرة بأتصل فيها لنفس الموضوع.",speaker:"paco"},{es:"Siento que tenga que repetirlo.",ar:"متأسفة إنك مضطر تعيد الكلام.",speaker:"luna"},{es:"Le digo exactamente en qué punto está.",ar:"حأقولك بالظبط واقفين فين.",speaker:"luna"},{es:"Lo que sí puedo hacer es marcar la incidencia como urgente y pedir una respuesta.",ar:"اللي أقدر أعمله فعلًا إني أعلّم البلاغ كعاجل.",speaker:"luna"}],dialogue:[{speaker:"paco",es:"¡Es la tercera vez que llamo por lo mismo! ¡Nadie hace nada!",ar:"دي تالت مرة بأتصل فيها لنفس الموضوع! محدش بيعمل حاجة!"},{speaker:"luna",es:"Tiene toda la razón. Siento que tenga que repetirlo. Voy a leer las notas de sus llamadas anteriores para no hacerle repetir todo.",ar:"مع حضرتك كل الحق. متأسفة إنك مضطر تعيد الكلام. حقرا ملاحظات مكالماتك اللي فاتت عشان مخلّيكش تعيد كل حاجة."},{speaker:"paco",es:"Por fin alguien lee las notas.",ar:"أخيرًا حد بيقرا الملاحظات."},{speaker:"luna",es:"Veo que hay una incidencia abierta desde el lunes. Le digo exactamente en qué punto está.",ar:"شايفة إن في بلاغ مفتوح من يوم الاتنين. حأقولك بالظبط واقفين فين."},{speaker:"paco",es:"A ver.",ar:"نشوف."},{speaker:"luna",es:"Está con envíos y aún no hay respuesta. Lo que sí puedo hacer es marcar la incidencia como urgente y pedir una respuesta.",ar:"عند الشحن ولسه مفيش رد. اللي أقدر أعمله فعلًا إني أعلّم البلاغ كعاجل وأطلب رد."},{speaker:"paco",es:"Vale, hágalo, por favor.",ar:"تمام، اعملي كده، لو سمحت."},{speaker:"luna",es:"Hecho. Le doy la referencia: INC setecientos setenta y uno.",ar:"اتعمل. حأديك رقم المرجع: INC-٧٧١."}],questions:[{q:"دي المكالمة رقم كام للعميل عن نفس الموضوع؟",options:["الأولى","التالتة","التانية","الرابعة"],answer:"التالتة",rationale:"قال: Es la tercera vez que llamo por lo mismo = دي تالت مرة بأتصل لنفس الموضوع. por lo mismo = لنفس الموضوع."},{q:"الموظفة عرفت تفاصيل المكالمات السابقة إزاي؟",options:["خمّنت","سألت العميل يعيد الشرح من الأول","قريت الملاحظات المسجلة","اتصلت بزميلها"],answer:"قريت الملاحظات المسجلة",rationale:"قالت: Voy a leer las notas de sus llamadas anteriores = حقرا ملاحظات مكالماتك اللي فاتت. قراءة الملاحظات بتوفر على العميل إعادة الشرح."},{q:"إيه اللي الموظفة قدرت تعمله فعلًا؟",options:["تأكد ميعاد وصول","ترجّع الفلوس فورًا","تلغي الطلب","تعلّم البلاغ كعاجل وتطلب رد"],answer:"تعلّم البلاغ كعاجل وتطلب رد",rationale:"قالت: Lo que sí puedo hacer es marcar la incidencia como urgente = اللي أقدر أعمله فعلًا إني أعلّم البلاغ كعاجل. marcar como urgente = تعلّم كعاجل."}],responseTask:{prompt:"عميل بيقول إنها تالت مكالمة عن نفس المشكلة. رد بالإسباني: اعتذر، ووضح إنك حتقرا الملاحظات بدل ما تخليه يعيد الشرح.",acceptable:["Tiene toda la razón. Siento que tenga que repetirlo. Voy a leer las notas de sus llamadas anteriores para no hacerle repetir todo.","Lamento que tenga que llamar otra vez. Leo las notas ahora para no hacerle repetir todo.","Lo siento mucho. Déjeme leer las notas primero, así no repite todo.","Entiendo su enfado. Voy a leer las notas de las llamadas anteriores."],modelEs:"Tiene toda la razón. Siento que tenga que repetirlo. Voy a leer las notas de sus llamadas anteriores para no hacerle repetir todo.",modelAr:"مع حضرتك كل الحق. متأسفة إنك مضطر تعيد الكلام. حقرا ملاحظات مكالماتك اللي فاتت عشان مخلّيكش تعيد كل حاجة.",checklistAr:"راجع إجابتك: ١) اعتراف بالحق (Tiene toda la razón / Entiendo su enfado)، ٢) اعتذار عن التكرار، ٣) قراءة الملاحظات بدل إعادة الشرح. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"siento que tenga que repetirlo: بعد siento que بنستخدم صيغة خاصة للفعل (tenga). lo que sí puedo hacer = اللي أقدر أعمله فعلًا. urgente = عاجل. aún = لسه."}},{id:"cc-u05l06",courseId:"call-center",unitId:"cc-u05",sourceLessonId:null,level:"B2",register:"usted",title:"طلب إلغاء طلب خرج للشحن",context:"عميلة عايزة تلغي طلب متأخر، بس الطلب خرج من المخزن خلاص. دورك: تتحقق من هويتها، توضح بصدق إن الإلغاء المباشر مش في إيدك، وتفتح طلب إلغاء برقم مرجع وتلخّص.",goal:"درس مراجعة: حتجمع التحقق + توضيح الحدود + خطوة واقعية برقم مرجع + تلخيص، في مكالمة إلغاء واحدة.",targets:[{es:"Quiero cancelar un pedido que no llega.",ar:"عايزة ألغي طلب مبييوصلش.",speaker:"luna"},{es:"Antes de nada, ¿me confirma su nombre y el correo del pedido?",ar:"قبل أي حاجة، تأكديلي اسم حضرتك والإيميل بتاع الطلب؟",speaker:"paco"},{es:"No puedo cancelarlo yo desde aquí.",ar:"مش أقدر ألغيه من عندي.",speaker:"paco"},{es:"Puedo abrir una solicitud de cancelación con envíos, y le llegan los pasos por correo.",ar:"أقدر أفتح طلب إلغاء مع الشحن، وحيوصلك الخطوات على الإيميل.",speaker:"paco"}],dialogue:[{speaker:"luna",es:"Hola. Quiero cancelar un pedido que no llega.",ar:"أهلًا. عايزة ألغي طلب مبييوصلش."},{speaker:"paco",es:"Entiendo. Antes de nada, ¿me confirma su nombre y el correo del pedido?",ar:"فاهم حضرتك. قبل أي حاجة، تأكديلي اسم حضرتك والإيميل بتاع الطلب؟"},{speaker:"luna",es:"Luna García, luna punto garcia arroba correo punto es.",ar:"لونا جارسيا، luna نقطة garcia آت correo نقطة es."},{speaker:"paco",es:"Gracias. Veo el pedido: salió del almacén ayer. Le explico lo que puedo hacer.",ar:"شكرًا. شايف الطلب: خرج من المخزن إمبارح. حأشرح لحضرتك اللي أقدر أعمله."},{speaker:"luna",es:"A ver.",ar:"نشوف."},{speaker:"paco",es:"El pedido ya salió. No puedo cancelarlo yo desde aquí. Puedo abrir una solicitud de cancelación con envíos, y le llegan los pasos por correo.",ar:"الطلب خرج خلاص. مش أقدر ألغيه من عندي. أقدر أفتح طلب إلغاء مع الشحن، وحيوصلك الخطوات على الإيميل."},{speaker:"luna",es:"¿Y si no me contestan?",ar:"ولو مردوش عليا؟"},{speaker:"paco",es:"Tiene la referencia de la solicitud: INC setecientos setenta y dos. Si no le contestan, llama con ella y seguimos el caso.",ar:"مع حضرتك رقم مرجع الطلب: INC-٧٧٢. لو مردوش، اتصلي بيه ونكمل متابعة الحالة."},{speaker:"luna",es:"Vale, así me quedo más tranquila.",ar:"تمام، كده اطمنّيت."},{speaker:"paco",es:"Perfecto. Entonces: solicitud abierta, referencia INC setecientos setenta y dos, y le llegan los pasos por correo. ¿Algo más?",ar:"جميل. يبقى: طلب الإلغاء اتفتح، رقم المرجع INC-٧٧٢، وحيوصلك الخطوات على الإيميل. أي حاجة تانية؟"}],questions:[{q:"ليه الموظف مش قادر يلغي الطلب من عنده؟",options:["عشان الطلب خرج من المخزن خلاص","عشان مش معاه صلاحية أبدًا","عشان النظام مش شغال","عشان العميلة متأخرة في الطلب"],answer:"عشان الطلب خرج من المخزن خلاص",rationale:"قال: El pedido ya salió. No puedo cancelarlo yo desde aquí = الطلب خرج خلاص، مش أقدر ألغيه من عندي. وفي الرد النموذجي حتلاقي Como ya salió… — como هنا = لأن/بما إن."},{q:"إيه اللي الموظف عمله فعلًا؟",options:["لغى الطلب","رجّع الفلوس","حوّلها للمدير","فتح طلب إلغاء مع الشحن ودى رقم مرجع"],answer:"فتح طلب إلغاء مع الشحن ودى رقم مرجع",rationale:"قال: Puedo abrir una solicitud de cancelación con envíos = أقدر أفتح طلب إلغاء مع الشحن. solicitud = طلب رسمي."},{q:"عميل عايز يلغي طلب خرج للشحن. إيه التصرف الصح؟",options:["توعده إن الإلغاء اتعمل","تقوله مفيش أي حل خالص","تقفل المكالمة","توضح حدودك بصدق وتفتح طلب إلغاء بمرجع وتشرح الخطوة اللي بعدها"],answer:"توضح حدودك بصدق وتفتح طلب إلغاء بمرجع وتشرح الخطوة اللي بعدها",rationale:"لا وعد كاذب ولا ترك العميل من غير حل: الحدود + البديل الواقعي + رقم مرجع للمتابعة هو القالب الصح."}],responseTask:{prompt:"عميلة عايزة تلغي طلب خرج من المخزن. وضح لها بالإسباني حدودك، واعرض فتح طلب إلغاء برقم مرجع.",acceptable:["Como ya salió, no puedo cancelarlo yo desde aquí. Puedo abrir una solicitud de cancelación con envíos.","El pedido ya salió, así que no puedo cancelarlo aquí. Puedo abrir una solicitud de cancelación y le doy la referencia.","No puedo cancelarlo desde aquí porque ya salió, pero le abro una solicitud con envíos.","Como el pedido está en camino, abro una solicitud de cancelación y le llegan los pasos por correo."],modelEs:"Como ya salió, no puedo cancelarlo yo desde aquí. Puedo abrir una solicitud de cancelación con envíos.",modelAr:"لأنه خرج خلاص، مش أقدر ألغيه من عندي. أقدر أفتح طلب إلغاء مع الشحن.",checklistAr:"راجع إجابتك: ١) توضيح الحد بصدق (no puedo… porque/como)، ٢) البديل الواقعي (solicitud de cancelación)، ٣) رقم مرجع أو خطوة متابعة. ردك مفتوح: أي صياغة سليمة مقبولة.",explanation:"cancelar = يلغي. solicitud = طلب رسمي. en camino = في الطريق. así me quedo más tranquila = كده اطمنّيت. ¿Algo más? = أي حاجة تانية؟"}}]}];for(const e of JOB_COURSES){const a=t.filter(s=>s.courseId===e.id).sort((s,i)=>s.unit.id.localeCompare(i.unit.id));e.units.splice(0,e.units.length,...a.map(s=>({...s.unit,level:e.title,sectionId:e.id,icon:"◌",tag:s.unit.cefr,lessons:[]})));const l=a.flatMap((s,i)=>s.lessons.map(o=>{const p=o.targets.map((r,d)=>({...r,id:o.id+"w"+d,audioKey:r.speaker+":"+r.es})),n=o.dialogue,c={...o,questions:o.questions.map(r=>({...r,answer:r.options.indexOf(r.answer)})),responseTask:{...o.responseTask,checklistAr:Array.isArray(o.responseTask.checklistAr)?o.responseTask.checklistAr:[o.responseTask.checklistAr]}};return{id:o.id,unit:i,level:e.title,sectionId:e.id,title:o.title,note:o.goal,words:p,scenario167:c,dialog:[n[0].es,n[1].es,n[0].ar,n[1].ar],dialogSpeakers:[n[0].speaker,n[1].speaker]}}));l.forEach((s,i)=>s.index=i),e.lessons.splice(0,e.lessons.length,...l)}ALL_LESSONS.splice(0,ALL_LESSONS.length,...MAIN_LESSONS,...JOB_COURSES.flatMap(e=>e.lessons)),ALL_WORDS.splice(0,ALL_WORDS.length,...ALL_LESSONS.flatMap(e=>e.words));const u=exercises;exercises=e=>e.scenario167?e.words.map(a=>({type:"teach",word:a})).concat(e.words.map(a=>({type:"listen",prompt:"اسمع واختار المعنى",source:a.es,answer:a.ar,options:shuffled([...new Set(e.words.map(l=>l.ar))]),word:a})),[{type:"match",prompt:"وصّل التعبيرات بمعناها",words:e.words}],e.words.map(a=>({type:"speak",prompt:"اسمع وكرّر بصوتك",source:a.es,answer:a.es,meaning:a.ar,word:a}))):u(e)})();
